fn assert_required_test_model(backend_kind: BackendKind, event: &ChatEvent) {
    let observed_model = match event {
        ChatEvent::StreamStart(start) => start.model.as_deref(),
        ChatEvent::StreamEnd(end) => end
            .message
            .model_info
            .as_ref()
            .map(|model| model.model.as_str()),
        ChatEvent::MessageAdded(message) => message
            .model_info
            .as_ref()
            .map(|model| model.model.as_str()),
        ChatEvent::MessageMetadataUpdated(update) => {
            update.model_info.as_ref().map(|model| model.model.as_str())
        }
        _ => None,
    };
    let Some(model) = observed_model else {
        return;
    };
    eprintln!("TYDE MODEL AUDIT backend={backend_kind:?} event={event:?} model={model}");
    match backend_kind {
        BackendKind::Codex => assert_eq!(
            model, REQUIRED_CODEX_TEST_MODEL,
            "real Codex test attempted to use a non-Luna model"
        ),
        BackendKind::Claude => assert!(
            matches!(
                model,
                UNIVERSAL_CLAUDE_MODEL | REQUIRED_CLAUDE_REPORTED_MODEL
            ),
            "real Claude test attempted to use a model other than the mandatory Haiku pin: {model}"
        ),
        _ => {}
    }
}

fn event_reports_required_test_model(backend_kind: BackendKind, event: &ChatEvent) -> bool {
    let model = match event {
        ChatEvent::StreamStart(start) => start.model.as_deref(),
        ChatEvent::StreamEnd(end) => end
            .message
            .model_info
            .as_ref()
            .map(|info| info.model.as_str()),
        ChatEvent::MessageAdded(message) => {
            message.model_info.as_ref().map(|info| info.model.as_str())
        }
        ChatEvent::MessageMetadataUpdated(update) => {
            update.model_info.as_ref().map(|info| info.model.as_str())
        }
        _ => None,
    };
    match backend_kind {
        BackendKind::Codex => model == Some(REQUIRED_CODEX_TEST_MODEL),
        BackendKind::Claude => {
            matches!(
                model,
                Some(UNIVERSAL_CLAUDE_MODEL | REQUIRED_CLAUDE_REPORTED_MODEL)
            )
        }
        _ => true,
    }
}

