#[test]
fn conformance_suite_structure_is_complete() {
    let source = include_str!("backend.rs");
    let paid_ignores = source
        .lines()
        .filter(|line| line.contains("#[ignore") && line.contains(&["paid", "backend"].join(" ")))
        .count();
    assert_eq!(paid_ignores, 2);
    assert!(source.contains("fn real_universal_backend_qualification_suite()"));
    assert!(source.contains("macro_rules! live_certification_tests"));

    let discovered_filters: HashSet<_> = source
        .split(|character: char| {
            !(character.is_ascii_uppercase() || character.is_ascii_digit() || character == '_')
        })
        .filter(|token| token.starts_with("TYDE_CONFORMANCE_") && *token != "TYDE_CONFORMANCE_")
        .collect();
    let cleared_filters: HashSet<_> = TARGETED_CONFORMANCE_FILTER_ENVS
        .iter()
        .copied()
        .filter(|token| token.starts_with("TYDE_CONFORMANCE_"))
        .collect();
    assert_eq!(cleared_filters, discovered_filters);
}

fn binary_available(name: &str) -> bool {
    std::process::Command::new("which")
        .arg(name)
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
}

fn backend_binary_available(backend_kind: BackendKind) -> bool {
    match backend_kind {
        BackendKind::Claude => binary_available("claude"),
        BackendKind::Codex => binary_available("codex"),
        BackendKind::Antigravity => binary_available("agy"),
        BackendKind::Tycode => std::env::var_os("HOME").is_some_and(|home| {
            PathBuf::from(home)
                .join(".tyde/tycode/0.10.0/tycode-subprocess")
                .is_file()
        }),
        BackendKind::Acp => binary_available("kiro-cli-chat") || binary_available("kiro-cli"),
        BackendKind::Hermes => {
            std::env::var("HERMES_PYTHON").is_ok()
                || binary_available("python3")
                || binary_available("python")
        }
    }
}

fn home_is_writable() -> bool {
    let Ok(home) = std::env::var("HOME") else {
        return false;
    };
    let probe = PathBuf::from(home).join(format!(
        ".tyde-backend-probe-{}-{}",
        std::process::id(),
        std::thread::current().name().unwrap_or("thread")
    ));

    let created = std::fs::OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(&probe)
        .is_ok();
    if created {
        let _ = std::fs::remove_file(&probe);
    }
    created
}

