#[tokio::test]
async fn antigravity_empty_workspace_spawn_is_accepted() {
    init_tracing();

    let mut fixture = Fixture::new().await;
    fixture
        .client
        .spawn_agent(SpawnAgentPayload {
            name: Some("Antigravity".to_string()),
            custom_agent_id: None,
            parent_agent_id: None,
            project_id: None,
            params: SpawnAgentParams::New {
                workspace_roots: Vec::new(),
                prompt: "hello antigravity".to_string(),
                images: None,
                backend_kind: BackendKind::Antigravity,
                launch_profile_id: None,
                cost_hint: None,
                access_mode: Default::default(),
                session_settings: None,
            },
        })
        .await
        .expect("send Antigravity spawn");

    let new_agent = loop {
        let env = expect_fixture_event(&mut fixture.client, "Antigravity NewAgent").await;
        if fixture::is_builtin_team_custom_agent_notify(&env) {
            continue;
        }
        match env.kind {
            FrameKind::NewAgent => {
                break env
                    .parse_payload::<NewAgentPayload>()
                    .expect("parse NewAgent");
            }
            FrameKind::HostSettings
            | FrameKind::SessionSchemas
            | FrameKind::LaunchProfileCatalogNotify
            | FrameKind::BackendSetup
            | FrameKind::BackendCapacity
            | FrameKind::TeamPresetCatalogNotify => continue,
            FrameKind::CommandError => {
                let error = env
                    .parse_payload::<CommandErrorPayload>()
                    .expect("parse unexpected CommandError");
                panic!("empty-root Antigravity spawn must not be rejected: {error:?}");
            }
            other => panic!("unexpected event while waiting for Antigravity NewAgent: {other}"),
        }
    };
    assert_eq!(new_agent.backend_kind, BackendKind::Antigravity);

    let start = expect_fixture_agent_start(
        &mut fixture.client,
        &new_agent.instance_stream,
        "Antigravity AgentStart",
    )
    .await;
    assert_eq!(start.backend_kind, BackendKind::Antigravity);
    assert!(
        start.workspace_roots.is_empty(),
        "empty-root spawn must keep protocol workspace_roots empty"
    );
}

#[tokio::test]
async fn empty_workspace_spawn_is_accepted_for_all_backends() {
    init_tracing();

    let mut fixture = Fixture::new().await;
    let host = fixture.host_for_test();
    host.set_session_schema_ready_for_test(BackendKind::Codex)
        .await;
    host.set_session_schema_ready_for_test(BackendKind::Acp)
        .await;
    host.set_session_schema_ready_for_test(BackendKind::Hermes)
        .await;
    let backends = [
        BackendKind::Claude,
        BackendKind::Codex,
        BackendKind::Acp,
        BackendKind::Tycode,
        BackendKind::Antigravity,
        BackendKind::Hermes,
    ];
    let mut session_ids = Vec::new();
    for backend_kind in backends {
        fixture
            .client
            .spawn_agent(SpawnAgentPayload {
                name: Some(format!("{backend_kind:?} empty root")),
                custom_agent_id: None,
                parent_agent_id: None,
                project_id: None,
                params: SpawnAgentParams::New {
                    workspace_roots: Vec::new(),
                    prompt: format!("hello {backend_kind:?}"),
                    launch_profile_id: None,
                    images: None,
                    backend_kind,
                    cost_hint: None,
                    access_mode: Default::default(),
                    session_settings: None,
                },
            })
            .await
            .unwrap_or_else(|err| panic!("send {backend_kind:?} empty-root spawn: {err:?}"));

        let new_agent = loop {
            let env = expect_fixture_event(&mut fixture.client, "empty-root NewAgent").await;
            if fixture::is_builtin_team_custom_agent_notify(&env) {
                continue;
            }
            match env.kind {
                FrameKind::NewAgent => {
                    let payload: NewAgentPayload =
                        env.parse_payload().expect("parse empty-root NewAgent");
                    if payload.backend_kind == backend_kind {
                        break payload;
                    }
                }
                FrameKind::CommandError => {
                    let error = env
                        .parse_payload::<CommandErrorPayload>()
                        .expect("parse unexpected empty-root CommandError");
                    panic!("{backend_kind:?} empty-root spawn must not be rejected: {error:?}");
                }
                _ => {}
            }
        };

        let (start, bootstrap_chat_events) = expect_fixture_agent_start_with_chat_events(
            &mut fixture.client,
            &new_agent.instance_stream,
            "empty-root AgentStart",
        )
        .await;
        assert_eq!(start.backend_kind, backend_kind);
        assert!(
            start.workspace_roots.is_empty(),
            "{backend_kind:?} empty-root spawn must keep AgentStart workspace_roots empty"
        );
        let session_id = start
            .session_id
            .clone()
            .unwrap_or_else(|| panic!("{backend_kind:?} empty-root AgentStart missing session_id"));
        session_ids.push((backend_kind, session_id));

        expect_fixture_initial_turn_completion(
            &mut fixture.client,
            &new_agent.instance_stream,
            bootstrap_chat_events,
            "empty-root ChatEvent",
        )
        .await;
    }

    fixture
        .client
        .list_sessions(ListSessionsPayload::default())
        .await
        .expect("list sessions after all empty-root spawns");
    let session_list = loop {
        let env = expect_fixture_event(&mut fixture.client, "empty-root SessionList").await;
        if env.kind == FrameKind::SessionList {
            break env
                .parse_payload::<SessionListPayload>()
                .expect("parse empty-root SessionList");
        }
    };
    for (backend_kind, session_id) in session_ids {
        let session = session_list
            .sessions
            .iter()
            .find(|session| session.id == session_id)
            .unwrap_or_else(|| panic!("missing {backend_kind:?} empty-root session"));
        assert_eq!(session.backend_kind, backend_kind);
        assert!(
            session.workspace_roots.is_empty(),
            "{backend_kind:?} empty-root session summary must keep workspace_roots empty"
        );
    }
}

#[tokio::test]
async fn compact_turn_emits_typed_marker_and_stream_end_without_legacy_notice() {
    init_tracing();

    let mut fixture = Fixture::new().await;
    fixture
        .client
        .spawn_agent(SpawnAgentPayload {
            name: Some("Compact".to_string()),
            custom_agent_id: None,
            parent_agent_id: None,
            project_id: None,
            params: SpawnAgentParams::New {
                workspace_roots: vec!["/tmp/test".to_string()],
                prompt: "/compact".to_string(),
                images: None,
                backend_kind: BackendKind::Claude,
                launch_profile_id: None,
                cost_hint: None,
                access_mode: Default::default(),
                session_settings: None,
            },
        })
        .await
        .expect("spawn compact test agent");

    let new_agent = loop {
        let env = expect_fixture_event(&mut fixture.client, "compact NewAgent").await;
        if env.kind == FrameKind::NewAgent {
            break env
                .parse_payload::<NewAgentPayload>()
                .expect("parse compact NewAgent");
        }
    };
    let agent_stream = new_agent.instance_stream.clone();

    expect_fixture_agent_start(&mut fixture.client, &agent_stream, "compact AgentStart").await;

    let mut saw_marker = false;
    let mut saw_legacy_notice = false;
    let mut saw_stream_end = false;
    let mut saw_typing_false = false;

    while !saw_typing_false {
        let env = expect_fixture_event(&mut fixture.client, "compact ChatEvent").await;
        if env.stream != agent_stream {
            continue;
        }
        assert_ne!(
            env.kind,
            FrameKind::AgentError,
            "compact turn should not emit AgentError"
        );
        if env.kind != FrameKind::ChatEvent {
            continue;
        }

        let event: ChatEvent = env.parse_payload().expect("parse compact ChatEvent");
        match event {
            ChatEvent::MessageAdded(message) => {
                if message.content == "Conversation compacted." {
                    saw_legacy_notice = true;
                }
            }
            ChatEvent::ContextCompaction(marker) => {
                assert_eq!(marker.trigger, protocol::CompactionTrigger::UserTyped);
                assert_eq!(marker.method, protocol::CompactionMethod::NativeTextCommand);
                saw_marker = true;
            }
            ChatEvent::StreamEnd(data) => {
                assert!(
                    data.message.content.is_empty(),
                    "compact turn should not fabricate assistant text"
                );
                saw_stream_end = true;
            }
            ChatEvent::TypingStatusChanged(false) => {
                saw_typing_false = true;
            }
            _ => {}
        }
    }

    assert!(saw_marker, "compact turn should emit one typed marker");
    assert!(
        !saw_legacy_notice,
        "compact turn must not emit the superseded system-message notice"
    );
    assert!(saw_stream_end, "compact turn should emit StreamEnd");
}

struct RealBackendFixture {
    client: ValidatedConnection,
    host: server::HostHandle,
    cleanup_guard: RealBackendCleanupGuard,
    #[allow(dead_code)]
    session_store_dir: tempfile::TempDir,
    workspace_dir: tempfile::TempDir,
}

struct RealBackendCleanupGuard {
    host: server::HostHandle,
}

static REAL_BACKEND_CLEANUPS_IN_FLIGHT: AtomicUsize = AtomicUsize::new(0);
static REAL_BACKEND_CLEANUP_FAILURES: AtomicUsize = AtomicUsize::new(0);
static REAL_BACKEND_CLEANUP_NOTIFY: std::sync::LazyLock<tokio::sync::Notify> =
    std::sync::LazyLock::new(tokio::sync::Notify::new);

async fn await_real_backend_cleanup() {
    loop {
        let notified = REAL_BACKEND_CLEANUP_NOTIFY.notified();
        if REAL_BACKEND_CLEANUPS_IN_FLIGHT.load(AtomicOrdering::SeqCst) == 0 {
            assert_eq!(
                REAL_BACKEND_CLEANUP_FAILURES.swap(0, AtomicOrdering::SeqCst),
                0,
                "real-backend fixture cleanup timed out"
            );
            return;
        }
        notified.await;
    }
}

impl Drop for RealBackendCleanupGuard {
    fn drop(&mut self) {
        REAL_BACKEND_CLEANUPS_IN_FLIGHT.fetch_add(1, AtomicOrdering::SeqCst);
        let host = self.host.clone();
        tokio::spawn(async move {
            if tokio::time::timeout(
                Duration::from_secs(30),
                host.shutdown_agents_for_conformance(),
            )
            .await
            .is_err()
            {
                REAL_BACKEND_CLEANUP_FAILURES.fetch_add(1, AtomicOrdering::SeqCst);
            }
            REAL_BACKEND_CLEANUPS_IN_FLIGHT.fetch_sub(1, AtomicOrdering::SeqCst);
            REAL_BACKEND_CLEANUP_NOTIFY.notify_waiters();
        });
    }
}

struct ValidatedConnection {
    inner: client::Connection,
    required_backend: BackendKind,
    validator: ProtocolValidator,
    pending_bootstrap_events: VecDeque<Envelope>,
    restored_events: VecDeque<Envelope>,
    progress_families: HashMap<(StreamPath, String), ProgressFamily>,
    terminal_progress: HashSet<(StreamPath, String, ProgressFamily)>,
    running_progress: HashSet<(StreamPath, String, ProgressFamily)>,
    open_tools: HashSet<(StreamPath, String)>,
    terminal_tools: HashSet<(StreamPath, String)>,
    running_background_tasks: HashSet<(StreamPath, String)>,
    ambient_work_kinds: HashMap<(StreamPath, String), ObservedAmbientWorkKind>,
    agent_streams: HashMap<protocol::AgentId, StreamPath>,
    closed_streams: HashSet<StreamPath>,
    pending_inputs: HashMap<StreamPath, VecDeque<String>>,
    queued_input_ids: HashMap<(StreamPath, QueuedMessageId), String>,
    agent_control_input_tools: HashMap<(StreamPath, String), (StreamPath, String)>,
    pending_spawn_inputs: VecDeque<SpawnInputAdmission>,
    pending_startup_inputs: HashMap<StreamPath, SpawnInputAdmission>,
    bootstrap_may_consume_input: HashSet<StreamPath>,
    implicit_initial_input_streams: HashSet<StreamPath>,
    bootstrap_agent_streams: HashMap<protocol::AgentId, StreamPath>,
    replayed_agent_events: HashMap<StreamPath, Vec<ChatEvent>>,
    typing_streams: HashSet<StreamPath>,
    quiescent_streams: HashSet<StreamPath>,
    cancelled_turns: HashSet<StreamPath>,
}

#[derive(Clone)]
struct SpawnInputAdmission {
    prompt: String,
    bootstrap_may_consume: bool,
}

#[derive(Default)]
struct ReplayTraceAudit {
    open_tools: HashSet<String>,
    terminal_tools: HashSet<String>,
    progress_families: HashMap<String, ProgressFamily>,
    terminal_progress: HashSet<(String, ProgressFamily)>,
    running_progress: HashSet<(String, ProgressFamily)>,
    running_background_tasks: HashSet<String>,
}

impl ReplayTraceAudit {
    fn observe(&mut self, backend_kind: BackendKind, event: &ChatEvent) {
        assert_required_test_model(backend_kind, event);
        match event {
            ChatEvent::ToolRequest(request) => {
                assert!(
                    !self.terminal_tools.contains(&request.tool_call_id)
                        && self.open_tools.insert(request.tool_call_id.clone()),
                    "replayed tool request identity was reused: {}",
                    request.tool_call_id
                );
            }
            ChatEvent::ToolExecutionCompleted(completion) => {
                assert!(
                    self.terminal_tools.insert(completion.tool_call_id.clone()),
                    "replayed tool completed more than once: {}",
                    completion.tool_call_id
                );
                assert!(
                    self.open_tools.remove(&completion.tool_call_id),
                    "replayed tool completed without one correlated request: {}",
                    completion.tool_call_id
                );
                if let Some(family) = self
                    .progress_families
                    .get(&completion.tool_call_id)
                    .copied()
                {
                    let progress_key = (completion.tool_call_id.clone(), family);
                    assert!(
                        self.terminal_progress.insert(progress_key.clone()),
                        "replayed progress completed more than once: {progress_key:?}"
                    );
                    self.running_progress.remove(&progress_key);
                }
                self.running_background_tasks
                    .remove(&completion.tool_call_id);
            }
            ChatEvent::ToolProgress(progress) => {
                let family = progress_family(&progress.update);
                if let Some(previous) = self
                    .progress_families
                    .insert(progress.tool_call_id.clone(), family)
                {
                    assert_eq!(
                        previous, family,
                        "replayed progress identity changed family: {}",
                        progress.tool_call_id
                    );
                }
                let progress_key = (progress.tool_call_id.clone(), family);
                assert!(
                    !self.terminal_progress.contains(&progress_key),
                    "replayed progress arrived after completion: {progress_key:?}"
                );
                self.running_progress.insert(progress_key);
                if progress.execution_mode == protocol::ToolExecutionMode::Background {
                    self.running_background_tasks
                        .insert(progress.tool_call_id.clone());
                }
            }
            _ => {}
        }
    }
}

impl ValidatedConnection {
    fn inherit_live_trace_from(&mut self, previous: &Self) {
        self.progress_families = previous.progress_families.clone();
        self.terminal_progress = previous.terminal_progress.clone();
        self.running_progress = previous.running_progress.clone();
        self.open_tools = previous.open_tools.clone();
        self.terminal_tools = previous.terminal_tools.clone();
        self.running_background_tasks = previous.running_background_tasks.clone();
        self.ambient_work_kinds = previous.ambient_work_kinds.clone();
        self.agent_streams = previous.agent_streams.clone();
        self.closed_streams = previous.closed_streams.clone();
        self.pending_inputs = previous.pending_inputs.clone();
        self.queued_input_ids = previous.queued_input_ids.clone();
        self.agent_control_input_tools = previous.agent_control_input_tools.clone();
        self.pending_spawn_inputs = previous.pending_spawn_inputs.clone();
        self.pending_startup_inputs = previous.pending_startup_inputs.clone();
        self.bootstrap_may_consume_input = previous.bootstrap_may_consume_input.clone();
        self.implicit_initial_input_streams = previous.implicit_initial_input_streams.clone();
        self.bootstrap_agent_streams = previous.bootstrap_agent_streams.clone();
        self.replayed_agent_events = previous.replayed_agent_events.clone();
        self.typing_streams = previous.typing_streams.clone();
        self.quiescent_streams = previous.quiescent_streams.clone();
        self.cancelled_turns = previous.cancelled_turns.clone();
    }

    fn enforced_trace_invariants() -> [TraceInvariant; 11] {
        TraceInvariant::ALL.map(|invariant| match invariant {
            TraceInvariant::ValidLifecycleOrder => invariant,
            TraceInvariant::StableStreamIdentity => invariant,
            TraceInvariant::UniqueTerminalEvents => invariant,
            TraceInvariant::NoEventsAfterQuiescence => invariant,
            TraceInvariant::InputConsumedExactlyOnce => invariant,
            TraceInvariant::ToolCompletedExactlyOnce => invariant,
            TraceInvariant::BackgroundTaskTerminalExactlyOnce => invariant,
            TraceInvariant::NoTerminalToRunningRegression => invariant,
            TraceInvariant::NoPendingInputAtShutdown => invariant,
            TraceInvariant::NoOpenToolAtShutdown => invariant,
            TraceInvariant::NoOrphanedProcessAtShutdown => invariant,
        })
    }

    fn restore_events(&mut self, events: Vec<Envelope>) {
        for event in events.into_iter().rev() {
            self.restored_events.push_front(event);
        }
    }

    async fn spawn_agent(
        &mut self,
        mut payload: SpawnAgentPayload,
    ) -> Result<(), protocol::FrameError> {
        enforce_required_live_test_model(&mut payload);
        let admission = match &payload.params {
            SpawnAgentParams::New { prompt, .. } => Some(SpawnInputAdmission {
                prompt: prompt.clone(),
                bootstrap_may_consume: true,
            }),
            SpawnAgentParams::Fork { prompt, .. } => Some(SpawnInputAdmission {
                prompt: prompt.clone(),
                bootstrap_may_consume: false,
            }),
            SpawnAgentParams::Resume { prompt, .. } => {
                prompt.clone().map(|prompt| SpawnInputAdmission {
                    prompt,
                    bootstrap_may_consume: false,
                })
            }
        };
        let result = self.inner.spawn_agent(payload).await;
        if result.is_ok()
            && let Some(admission) = admission
            && !admission.prompt.is_empty()
        {
            self.pending_spawn_inputs.push_back(admission);
        }
        result
    }

    async fn list_sessions(
        &mut self,
        payload: ListSessionsPayload,
    ) -> Result<(), protocol::FrameError> {
        self.inner.list_sessions(payload).await
    }

    async fn delete_session(
        &mut self,
        payload: DeleteSessionPayload,
    ) -> Result<(), protocol::FrameError> {
        self.inner.delete_session(payload).await
    }

    async fn backend_settings_refresh(
        &mut self,
        backend: BackendKind,
    ) -> Result<(), protocol::FrameError> {
        self.inner
            .backend_settings_refresh(BackendSettingsRefreshPayload { backend })
            .await
    }

    async fn set_session_settings(
        &mut self,
        stream: &StreamPath,
        payload: SetSessionSettingsPayload,
    ) -> Result<(), protocol::FrameError> {
        self.inner.set_session_settings(stream, payload).await
    }

    async fn close_agent(&mut self, stream: &StreamPath) -> Result<(), protocol::FrameError> {
        self.pending_startup_inputs.remove(stream);
        let cancelled = self
            .queued_input_ids
            .iter()
            .filter_map(|((queued_stream, _), message)| {
                (queued_stream == stream).then_some(message.clone())
            })
            .collect::<Vec<_>>();
        if let Some(pending) = self.pending_inputs.get_mut(stream) {
            for message in cancelled {
                if let Some(position) = pending.iter().position(|candidate| candidate == &message) {
                    pending.remove(position);
                }
            }
            if pending.is_empty() {
                self.pending_inputs.remove(stream);
            }
        }
        self.queued_input_ids
            .retain(|(queued_stream, _), _| queued_stream != stream);
        self.inner.close_agent(stream).await
    }

    async fn next_event(&mut self) -> Result<Option<Envelope>, protocol::FrameError> {
        let (envelope, replayed_bootstrap, already_validated) =
            if let Some(envelope) = self.restored_events.pop_front() {
                (envelope, false, true)
            } else if let Some(envelope) = self.pending_bootstrap_events.pop_front() {
                (envelope, true, false)
            } else {
                let Some(envelope) = self.inner.next_event().await? else {
                    return Ok(None);
                };
                if let Err(error) = self.validator.validate_envelope(&envelope) {
                    panic!("protocol violation while reading backend events: {error}");
                }
                self.record_bootstrap_state(&envelope);
                self.queue_agent_bootstrap_chat_events(&envelope);
                (envelope, false, false)
            };
        if !already_validated && envelope.kind == FrameKind::QueuedMessages {
            let queued: QueuedMessagesPayload = envelope
                .parse_payload()
                .expect("parse queued inputs for admission trace");
            self.queued_input_ids
                .retain(|(stream, _), _| stream != &envelope.stream);
            for message in queued.messages {
                self.queued_input_ids
                    .insert((envelope.stream.clone(), message.id), message.message);
            }
        }
        if !already_validated && !(replayed_bootstrap && envelope.kind == FrameKind::ChatEvent) {
            self.validate_trace_invariants(&envelope);
        }

        Ok(Some(envelope))
    }

    fn record_bootstrap_state(&mut self, envelope: &Envelope) {
        if envelope.kind == FrameKind::HostBootstrap {
            let payload: HostBootstrapPayload = envelope
                .parse_payload()
                .expect("parse HostBootstrap for replay lookup");
            self.bootstrap_agent_streams.extend(
                payload
                    .agents
                    .into_iter()
                    .map(|agent| (agent.agent_id, agent.instance_stream)),
            );
        } else if envelope.kind == FrameKind::AgentBootstrap {
            let payload: AgentBootstrapPayload = envelope
                .parse_payload()
                .expect("parse AgentBootstrap for replay lookup");
            self.replayed_agent_events.insert(
                envelope.stream.clone(),
                payload
                    .events
                    .into_iter()
                    .filter_map(|event| match event {
                        AgentBootstrapEvent::ChatEvent(event) => Some(event),
                        _ => None,
                    })
                    .collect(),
            );
        }
    }

    fn validate_trace_invariants(&mut self, envelope: &Envelope) {
        if envelope.kind == FrameKind::CommandError {
            let error: CommandErrorPayload = envelope
                .parse_payload()
                .expect("parse audited CommandError");
            match error.request_kind {
                FrameKind::SpawnAgent => {
                    self.pending_spawn_inputs.pop_front();
                }
                FrameKind::SendMessage => {
                    if let Some(pending) = self.pending_inputs.get_mut(&error.stream) {
                        pending.pop_back();
                        if pending.is_empty() {
                            self.pending_inputs.remove(&error.stream);
                        }
                    }
                }
                _ => {}
            }
            return;
        }
        if envelope.kind == FrameKind::NewAgent {
            let new_agent: NewAgentPayload =
                envelope.parse_payload().expect("parse audited NewAgent");
            if let Some(admission) = self.pending_spawn_inputs.pop_front() {
                eprintln!(
                    "CONFORMANCE NEW AGENT agent={} stream={} admission={:?}",
                    new_agent.agent_id, new_agent.instance_stream, admission.prompt
                );
                self.pending_startup_inputs
                    .insert(new_agent.instance_stream.clone(), admission);
            }
            self.agent_streams
                .insert(new_agent.agent_id, new_agent.instance_stream);
            return;
        }
        if envelope.kind == FrameKind::AgentStart {
            let start: AgentStartPayload =
                envelope.parse_payload().expect("parse audited AgentStart");
            self.observe_agent_start(&envelope.stream, start);
            return;
        }
        if envelope.kind == FrameKind::ChatEvent {
            let event: ChatEvent = envelope
                .parse_payload()
                .expect("parse model-audited ChatEvent");
            assert_required_test_model(self.required_backend, &event);
        }
        if envelope.kind == FrameKind::AgentError {
            let error: protocol::AgentErrorPayload =
                envelope.parse_payload().expect("parse audited AgentError");
            if error.fatal {
                assert!(
                    self.open_tools
                        .iter()
                        .all(|(stream, _)| stream != &envelope.stream),
                    "fatal agent error left an open tool on {}",
                    envelope.stream
                );
                assert!(
                    self.running_background_tasks
                        .iter()
                        .all(|(stream, _)| stream != &envelope.stream),
                    "fatal agent error left orphaned background work on {}",
                    envelope.stream
                );
                assert!(
                    self.running_progress
                        .iter()
                        .all(|(stream, _, _)| stream != &envelope.stream),
                    "fatal agent error left nonterminal progress on {}",
                    envelope.stream
                );
                self.pending_inputs.remove(&envelope.stream);
                self.pending_startup_inputs.remove(&envelope.stream);
                self.implicit_initial_input_streams.remove(&envelope.stream);
                self.queued_input_ids
                    .retain(|(stream, _), _| stream != &envelope.stream);
                self.closed_streams.insert(envelope.stream.clone());
            }
            return;
        }
        if envelope.kind == FrameKind::AgentClosed {
            let closed: protocol::AgentClosedPayload =
                envelope.parse_payload().expect("parse audited AgentClosed");
            let stream = self
                .agent_streams
                .get(&closed.agent_id)
                .cloned()
                .unwrap_or_else(|| envelope.stream.clone());
            let abandoned_agent_messages = self
                .agent_control_input_tools
                .iter()
                .filter_map(
                    |((source_stream, tool_call_id), (target_stream, message))| {
                        (source_stream == &stream || target_stream == &stream).then_some((
                            (source_stream.clone(), tool_call_id.clone()),
                            target_stream.clone(),
                            message.clone(),
                        ))
                    },
                )
                .collect::<Vec<_>>();
            for (key, target_stream, message) in abandoned_agent_messages {
                self.agent_control_input_tools.remove(&key);
                let pending = self.pending_inputs.get_mut(&target_stream).unwrap_or_else(|| {
                    panic!(
                        "closed source lost its undelivered agent-message admission for {target_stream}: {message:?}"
                    )
                });
                let position = pending
                    .iter()
                    .position(|candidate| candidate == &message)
                    .expect("closed source agent-message admission disappeared");
                pending.remove(position);
                if pending.is_empty() {
                    self.pending_inputs.remove(&target_stream);
                }
            }
            assert!(
                self.open_tools
                    .iter()
                    .all(|(candidate, _)| candidate != &stream),
                "agent closed with an open tool on {stream}"
            );
            assert!(
                self.running_background_tasks
                    .iter()
                    .all(|(candidate, _)| candidate != &stream),
                "agent closed with an orphaned background process on {stream}"
            );
            assert!(
                self.running_progress
                    .iter()
                    .all(|(candidate, _, _)| candidate != &stream),
                "agent closed with nonterminal progress on {stream}: {:?}",
                self.running_progress
                    .iter()
                    .filter(|(candidate, _, _)| candidate == &stream)
                    .collect::<Vec<_>>()
            );
            assert!(
                self.pending_inputs
                    .get(&stream)
                    .is_none_or(VecDeque::is_empty),
                "agent closed with unconsumed input on {stream}"
            );
            assert!(
                !self.implicit_initial_input_streams.contains(&stream),
                "agent closed before consuming its internally admitted initial input on {stream}"
            );
            self.closed_streams.insert(stream);
            return;
        }
        if envelope.kind != FrameKind::ChatEvent {
            return;
        }
        assert!(
            !self.closed_streams.contains(&envelope.stream),
            "event arrived after the definitive AgentClosed boundary on {}",
            envelope.stream
        );
        match envelope
            .parse_payload::<ChatEvent>()
            .expect("parse audited ChatEvent")
        {
            ChatEvent::MessageAdded(ChatMessage {
                sender: MessageSender::User,
                content,
                ..
            }) => {
                self.quiescent_streams.remove(&envelope.stream);
                self.cancelled_turns.remove(&envelope.stream);
                eprintln!(
                    "CONFORMANCE USER ECHO stream={} content={:?} pending={:?}",
                    envelope.stream,
                    content,
                    self.pending_inputs.get(&envelope.stream)
                );
                if self.implicit_initial_input_streams.remove(&envelope.stream) {
                    return;
                }
                if !self.pending_inputs.contains_key(&envelope.stream) {
                    let reconnect_agent_id =
                        self.agent_streams
                            .iter()
                            .find_map(|(agent_id, active_stream)| {
                                (active_stream == &envelope.stream).then_some(agent_id.clone())
                            });
                    if let Some(agent_id) = reconnect_agent_id {
                        let prefix = format!("/agent/{}/", agent_id.0);
                        let prior_streams = self
                            .pending_inputs
                            .keys()
                            .filter(|stream| stream.0.starts_with(&prefix))
                            .cloned()
                            .collect::<Vec<_>>();
                        assert!(
                            prior_streams.len() <= 1,
                            "multiple prior instance streams held admitted input for {agent_id:?}: {prior_streams:?}"
                        );
                        if let Some(prior_stream) = prior_streams.into_iter().next()
                            && let Some(pending) = self.pending_inputs.remove(&prior_stream)
                        {
                            self.pending_inputs.insert(envelope.stream.clone(), pending);
                            for (target_stream, _) in self.agent_control_input_tools.values_mut() {
                                if *target_stream == prior_stream {
                                    *target_stream = envelope.stream.clone();
                                }
                            }
                        }
                    }
                }
                if !self.pending_inputs.contains_key(&envelope.stream) {
                    panic!(
                        "input was echoed without a live admission on {}: {content:?}; pending={:?}; agent_streams={:?}; agent_control_inputs={:?}",
                        envelope.stream,
                        self.pending_inputs,
                        self.agent_streams,
                        self.agent_control_input_tools,
                    )
                }
                let pending = self
                    .pending_inputs
                    .get_mut(&envelope.stream)
                    .expect("checked pending input stream disappeared");
                let expected = pending.pop_front().expect("pending input queue was empty");
                assert_eq!(
                    content, expected,
                    "input echoes violated per-stream admission FIFO on {}",
                    envelope.stream
                );
                if pending.is_empty() {
                    self.pending_inputs.remove(&envelope.stream);
                }
                self.bootstrap_may_consume_input.remove(&envelope.stream);
            }
            ChatEvent::MessageAdded(ChatMessage {
                sender: MessageSender::Assistant { .. },
                ..
            }) => {
                assert!(
                    !self.quiescent_streams.contains(&envelope.stream),
                    "assistant message arrived after foreground quiescence without a new turn on {}",
                    envelope.stream
                );
            }
            ChatEvent::ToolRequest(request) => {
                assert!(
                    !self.quiescent_streams.contains(&envelope.stream),
                    "tool request arrived after foreground quiescence without a new turn on {}: {:?}",
                    envelope.stream,
                    request
                );
                let key = (envelope.stream.clone(), request.tool_call_id);
                if let protocol::ToolRequestType::TydeSendAgentMessage { agent_id, message } =
                    &request.tool_type
                    && let Some(target_stream) = self.agent_streams.get(agent_id).cloned()
                {
                    self.pending_inputs
                        .entry(target_stream.clone())
                        .or_default()
                        .push_back(message.clone());
                    self.agent_control_input_tools
                        .insert(key.clone(), (target_stream, message.clone()));
                }
                assert!(
                    !self.terminal_tools.contains(&key) && self.open_tools.insert(key.clone()),
                    "tool request identity was reused: {key:?}"
                );
            }
            ChatEvent::ToolExecutionCompleted(completion) => {
                let key = (envelope.stream.clone(), completion.tool_call_id.clone());
                if let Some((target_stream, message)) = self.agent_control_input_tools.remove(&key)
                    && !completion.success()
                {
                    let pending = self.pending_inputs.get_mut(&target_stream).unwrap_or_else(|| {
                        panic!(
                            "failed agent-control message was consumed by {target_stream}: {message:?}"
                        )
                    });
                    let position = pending
                        .iter()
                        .position(|candidate| candidate == &message)
                        .expect("failed agent-control message admission disappeared");
                    pending.remove(position);
                    if pending.is_empty() {
                        self.pending_inputs.remove(&target_stream);
                    }
                }
                assert!(
                    self.terminal_tools.insert(key.clone()),
                    "tool completed more than once: {key:?}"
                );
                assert!(
                    self.open_tools.remove(&key),
                    "tool completed without one live correlated request: {key:?}"
                );
                if let Some(family) = self.progress_families.get(&key).copied() {
                    let progress_key = (key.0.clone(), key.1.clone(), family);
                    assert!(
                        self.terminal_progress.insert(progress_key.clone()),
                        "progress completed more than once: {progress_key:?}"
                    );
                    self.running_progress.remove(&progress_key);
                }
                self.running_background_tasks.remove(&key);
            }
            ChatEvent::ToolProgress(progress) => {
                let key = (envelope.stream.clone(), progress.tool_call_id.clone());
                assert!(
                    self.open_tools.contains(&key) || self.terminal_tools.contains(&key),
                    "tool progress preceded its request: {key:?}"
                );
                assert_progress_payload_contract(&progress, "common progress auditor");
                let family = progress_family(&progress.update);
                if let Some(previous) = self.progress_families.insert(key.clone(), family) {
                    assert_eq!(
                        previous, family,
                        "tool progress identity changed family: {key:?}"
                    );
                }
                let progress_key = (key.0.clone(), key.1.clone(), family);
                assert!(
                    !self.terminal_progress.contains(&progress_key),
                    "progress arrived after completion: {progress_key:?}"
                );
                self.running_progress.insert(progress_key);
                let observed_kind = match &progress.update {
                    protocol::ToolProgressUpdate::SubAgent(_) => {
                        Some(ObservedAmbientWorkKind::Subagent)
                    }
                    _ if progress.execution_mode == protocol::ToolExecutionMode::Background => {
                        Some(ObservedAmbientWorkKind::Command)
                    }
                    _ => None,
                };
                if let Some(observed_kind) = observed_kind
                    && let Some(previous) =
                        self.ambient_work_kinds.insert(key.clone(), observed_kind)
                {
                    assert_eq!(
                        previous, observed_kind,
                        "ambient work identity changed observable kind: {key:?}"
                    );
                }
                if progress.execution_mode == protocol::ToolExecutionMode::Background {
                    self.running_background_tasks.insert(key);
                }
            }
            ChatEvent::TypingStatusChanged(true) => {
                assert!(
                    self.typing_streams.insert(envelope.stream.clone()),
                    "typing started twice without an intervening idle boundary on {}",
                    envelope.stream
                );
                self.quiescent_streams.remove(&envelope.stream);
                self.cancelled_turns.remove(&envelope.stream);
            }
            ChatEvent::TypingStatusChanged(false) => {
                self.typing_streams.remove(&envelope.stream);
                self.quiescent_streams.insert(envelope.stream.clone());
            }
            ChatEvent::OperationCancelled(_) => {
                assert!(
                    self.cancelled_turns.insert(envelope.stream.clone()),
                    "foreground turn emitted duplicate cancellation on {}",
                    envelope.stream
                );
            }
            ChatEvent::StreamStart(_) | ChatEvent::StreamDelta(_) | ChatEvent::StreamEnd(_) => {
                assert!(
                    !self.quiescent_streams.contains(&envelope.stream),
                    "assistant stream event arrived after foreground quiescence without a new turn on {}",
                    envelope.stream
                );
            }
            _ => {}
        }
    }

    fn observe_agent_start(&mut self, stream: &StreamPath, start: AgentStartPayload) {
        eprintln!(
            "CONFORMANCE AGENT START agent={} stream={} prior_stream={:?} startup_inputs={:?}",
            start.agent_id,
            stream,
            self.agent_streams.get(&start.agent_id),
            self.pending_startup_inputs.keys().collect::<Vec<_>>()
        );
        if let Some(previous_stream) = self.agent_streams.get(&start.agent_id).cloned()
            && previous_stream != *stream
        {
            self.progress_families = self
                .progress_families
                .drain()
                .map(|((candidate, id), family)| {
                    (
                        (
                            if candidate == previous_stream {
                                stream.clone()
                            } else {
                                candidate
                            },
                            id,
                        ),
                        family,
                    )
                })
                .collect();
            self.terminal_progress = self
                .terminal_progress
                .drain()
                .map(|(candidate, id, family)| {
                    (
                        if candidate == previous_stream {
                            stream.clone()
                        } else {
                            candidate
                        },
                        id,
                        family,
                    )
                })
                .collect();
            self.running_progress = self
                .running_progress
                .drain()
                .map(|(candidate, id, family)| {
                    (
                        if candidate == previous_stream {
                            stream.clone()
                        } else {
                            candidate
                        },
                        id,
                        family,
                    )
                })
                .collect();
            self.open_tools = self
                .open_tools
                .drain()
                .map(|(candidate, id)| {
                    (
                        if candidate == previous_stream {
                            stream.clone()
                        } else {
                            candidate
                        },
                        id,
                    )
                })
                .collect();
            self.terminal_tools = self
                .terminal_tools
                .drain()
                .map(|(candidate, id)| {
                    (
                        if candidate == previous_stream {
                            stream.clone()
                        } else {
                            candidate
                        },
                        id,
                    )
                })
                .collect();
            self.running_background_tasks = self
                .running_background_tasks
                .drain()
                .map(|(candidate, id)| {
                    (
                        if candidate == previous_stream {
                            stream.clone()
                        } else {
                            candidate
                        },
                        id,
                    )
                })
                .collect();
            self.ambient_work_kinds = self
                .ambient_work_kinds
                .drain()
                .map(|((candidate, id), kind)| {
                    (
                        (
                            if candidate == previous_stream {
                                stream.clone()
                            } else {
                                candidate
                            },
                            id,
                        ),
                        kind,
                    )
                })
                .collect();
            if self.typing_streams.remove(&previous_stream) {
                self.typing_streams.insert(stream.clone());
            }
            if self.quiescent_streams.remove(&previous_stream) {
                self.quiescent_streams.insert(stream.clone());
            }
            if self.cancelled_turns.remove(&previous_stream) {
                self.cancelled_turns.insert(stream.clone());
            }
            if self.bootstrap_may_consume_input.remove(&previous_stream) {
                self.bootstrap_may_consume_input.insert(stream.clone());
            }
            if self.implicit_initial_input_streams.remove(&previous_stream) {
                self.implicit_initial_input_streams.insert(stream.clone());
            }
            if let Some(pending) = self.pending_inputs.remove(&previous_stream) {
                self.pending_inputs.insert(stream.clone(), pending);
            }
            if let Some(admission) = self.pending_startup_inputs.remove(&previous_stream) {
                self.pending_startup_inputs
                    .insert(stream.clone(), admission);
            }
            self.queued_input_ids = self
                .queued_input_ids
                .drain()
                .map(|((candidate, id), message)| {
                    (
                        (
                            if candidate == previous_stream {
                                stream.clone()
                            } else {
                                candidate
                            },
                            id,
                        ),
                        message,
                    )
                })
                .collect();
            self.agent_control_input_tools = self
                .agent_control_input_tools
                .drain()
                .map(
                    |((source_stream, tool_call_id), (target_stream, message))| {
                        (
                            (
                                if source_stream == previous_stream {
                                    stream.clone()
                                } else {
                                    source_stream
                                },
                                tool_call_id,
                            ),
                            (
                                if target_stream == previous_stream {
                                    stream.clone()
                                } else {
                                    target_stream
                                },
                                message,
                            ),
                        )
                    },
                )
                .collect();
        }
        self.agent_streams.insert(start.agent_id, stream.clone());
        self.register_started_stream(stream, start.origin);
    }

    fn queue_agent_bootstrap_chat_events(&mut self, envelope: &Envelope) {
        if envelope.kind != FrameKind::AgentBootstrap {
            return;
        }

        let payload: AgentBootstrapPayload = envelope
            .parse_payload()
            .expect("parse AgentBootstrap for replayed ChatEvents");
        let mut replay_audit = ReplayTraceAudit::default();
        for event in &payload.events {
            if let AgentBootstrapEvent::ChatEvent(ChatEvent::ToolRequest(request)) = event {
                replay_audit.observe(
                    self.required_backend,
                    &ChatEvent::ToolRequest(request.clone()),
                );
            }
        }
        for event in payload.events {
            match event {
                AgentBootstrapEvent::AgentStart(start) => {
                    self.observe_agent_start(&envelope.stream, start);
                }
                AgentBootstrapEvent::ChatEvent(chat_event) => {
                    if !matches!(chat_event, ChatEvent::ToolRequest(_)) {
                        replay_audit.observe(self.required_backend, &chat_event);
                    }
                    if let ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::User,
                        content,
                        ..
                    }) = &chat_event
                    {
                        if self.implicit_initial_input_streams.remove(&envelope.stream) {
                            // The bootstrap captured the internally admitted child prompt.
                        } else if self.bootstrap_may_consume_input.contains(&envelope.stream)
                            && self
                                .pending_inputs
                                .get(&envelope.stream)
                                .and_then(|pending| pending.front())
                                == Some(content)
                        {
                            let pending = self
                                .pending_inputs
                                .get_mut(&envelope.stream)
                                .expect("new-agent bootstrap admission disappeared");
                            pending.pop_front();
                            if pending.is_empty() {
                                self.pending_inputs.remove(&envelope.stream);
                            }
                            self.bootstrap_may_consume_input.remove(&envelope.stream);
                        }
                    }
                    self.pending_bootstrap_events.push_back(Envelope {
                        stream: envelope.stream.clone(),
                        kind: FrameKind::ChatEvent,
                        seq: envelope.seq,
                        payload: serde_json::to_value(chat_event)
                            .expect("serialize replayed bootstrap ChatEvent"),
                    });
                }
                AgentBootstrapEvent::AgentError(error) => {
                    self.pending_bootstrap_events.push_back(Envelope {
                        stream: envelope.stream.clone(),
                        kind: FrameKind::AgentError,
                        seq: envelope.seq,
                        payload: serde_json::to_value(error)
                            .expect("serialize replayed bootstrap AgentError"),
                    });
                }
                AgentBootstrapEvent::QueuedMessages(queued) => {
                    self.queued_input_ids
                        .retain(|(stream, _), _| stream != &envelope.stream);
                    for message in &queued.messages {
                        if !self
                            .pending_inputs
                            .get(&envelope.stream)
                            .is_some_and(|pending| pending.contains(&message.message))
                        {
                            let prior_stream =
                                self.pending_inputs.iter().find_map(|(stream, pending)| {
                                    (stream != &envelope.stream
                                        && pending.contains(&message.message))
                                    .then(|| stream.clone())
                                });
                            if let Some(prior_stream) = prior_stream {
                                let prior = self
                                    .pending_inputs
                                    .get_mut(&prior_stream)
                                    .expect("persisted queue admission source disappeared");
                                let position = prior
                                    .iter()
                                    .position(|candidate| candidate == &message.message)
                                    .expect("persisted queue admission content disappeared");
                                prior.remove(position);
                                if prior.is_empty() {
                                    self.pending_inputs.remove(&prior_stream);
                                }
                                self.pending_inputs
                                    .entry(envelope.stream.clone())
                                    .or_default()
                                    .push_back(message.message.clone());
                            }
                        }
                        self.queued_input_ids.insert(
                            (envelope.stream.clone(), message.id.clone()),
                            message.message.clone(),
                        );
                    }
                    self.pending_bootstrap_events.push_back(Envelope {
                        stream: envelope.stream.clone(),
                        kind: FrameKind::QueuedMessages,
                        seq: envelope.seq,
                        payload: serde_json::to_value(queued)
                            .expect("serialize replayed bootstrap QueuedMessages"),
                    });
                }
                _ => {}
            }
        }
        self.open_tools.extend(
            replay_audit
                .open_tools
                .into_iter()
                .map(|id| (envelope.stream.clone(), id)),
        );
        self.terminal_tools.extend(
            replay_audit
                .terminal_tools
                .into_iter()
                .map(|id| (envelope.stream.clone(), id)),
        );
        self.progress_families.extend(
            replay_audit
                .progress_families
                .into_iter()
                .map(|(id, family)| ((envelope.stream.clone(), id), family)),
        );
        self.terminal_progress.extend(
            replay_audit
                .terminal_progress
                .into_iter()
                .map(|(id, family)| (envelope.stream.clone(), id, family)),
        );
        self.running_progress.extend(
            replay_audit
                .running_progress
                .into_iter()
                .map(|(id, family)| (envelope.stream.clone(), id, family)),
        );
        self.running_background_tasks.extend(
            replay_audit
                .running_background_tasks
                .into_iter()
                .map(|id| (envelope.stream.clone(), id)),
        );
    }

    fn register_started_stream(&mut self, stream: &StreamPath, origin: protocol::AgentOrigin) {
        if let Some(admission) = self.pending_startup_inputs.remove(stream) {
            eprintln!(
                "CONFORMANCE START stream={stream} origin={origin:?} admission={:?} bootstrap_may_consume={}",
                admission.prompt, admission.bootstrap_may_consume,
            );
            if admission.bootstrap_may_consume {
                self.bootstrap_may_consume_input.insert(stream.clone());
            }
            self.pending_inputs
                .entry(stream.clone())
                .or_default()
                .push_front(admission.prompt);
        } else if origin != protocol::AgentOrigin::User {
            self.implicit_initial_input_streams.insert(stream.clone());
        } else {
            eprintln!("CONFORMANCE START stream={stream} no pending spawn admission");
        }
    }

    async fn interrupt(&mut self, stream: &StreamPath) -> Result<(), protocol::FrameError> {
        self.inner.interrupt(stream).await
    }

    async fn compact_agent(
        &mut self,
        stream: &StreamPath,
        payload: protocol::AgentCompactPayload,
    ) -> Result<(), protocol::FrameError> {
        self.inner.compact_agent(stream, payload).await
    }

    async fn send_queued_message_now(
        &mut self,
        stream: &StreamPath,
        payload: SendQueuedMessageNowPayload,
    ) -> Result<(), protocol::FrameError> {
        self.inner.send_queued_message_now(stream, payload).await
    }

    async fn edit_queued_message(
        &mut self,
        stream: &StreamPath,
        payload: EditQueuedMessagePayload,
    ) -> Result<(), protocol::FrameError> {
        let key = (stream.clone(), payload.id.clone());
        let prior = self
            .queued_input_ids
            .get_mut(&key)
            .unwrap_or_else(|| panic!("edit targeted an unobserved queued message: {key:?}"));
        let pending = self.pending_inputs.get_mut(stream).unwrap();
        let position = pending
            .iter()
            .position(|message| message == prior)
            .expect("queued edit target disappeared from input admission trace");
        pending[position] = payload.message.clone();
        *prior = payload.message.clone();
        self.inner.edit_queued_message(stream, payload).await
    }

    async fn cancel_queued_message(
        &mut self,
        stream: &StreamPath,
        payload: CancelQueuedMessagePayload,
    ) -> Result<(), protocol::FrameError> {
        let key = (stream.clone(), payload.id.clone());
        let prior = self
            .queued_input_ids
            .remove(&key)
            .unwrap_or_else(|| panic!("cancel targeted an unobserved queued message: {key:?}"));
        let pending = self.pending_inputs.get_mut(stream).unwrap();
        let position = pending
            .iter()
            .position(|message| message == &prior)
            .expect("queued cancel target disappeared from input admission trace");
        pending.remove(position);
        if pending.is_empty() {
            self.pending_inputs.remove(stream);
        }
        self.inner.cancel_queued_message(stream, payload).await
    }

    async fn send_message(
        &mut self,
        stream: &StreamPath,
        message: String,
    ) -> Result<(), protocol::FrameError> {
        let result = self.inner.send_message(stream, message.clone()).await;
        if result.is_ok() && !message.is_empty() {
            self.pending_inputs
                .entry(stream.clone())
                .or_default()
                .push_back(message);
        }
        result
    }

    async fn send_message_payload(
        &mut self,
        stream: &StreamPath,
        payload: SendMessagePayload,
    ) -> Result<(), protocol::FrameError> {
        let message = payload.message.clone();
        let is_interaction_response = payload.tool_response.is_some();
        let result = self.inner.send_message_payload(stream, payload).await;
        if result.is_ok() && !message.is_empty() {
            let pending = self.pending_inputs.entry(stream.clone()).or_default();
            if is_interaction_response {
                pending.push_front(message);
            } else {
                pending.push_back(message);
            }
        }
        result
    }
}

fn enforce_required_live_test_model(payload: &mut SpawnAgentPayload) {
    let SpawnAgentParams::New {
        backend_kind,
        cost_hint,
        session_settings,
        ..
    } = &mut payload.params
    else {
        return;
    };
    *cost_hint = Some(SpawnCostHint::Low);
    let settings = session_settings.get_or_insert_default();
    if *backend_kind == BackendKind::Tycode {
        settings.0.insert(
            "tyde_conformance_model".to_owned(),
            SessionSettingValue::String(UNIVERSAL_TYCODE_MODEL.to_owned()),
        );
        settings
            .0
            .entry("default_agent".to_owned())
            .or_insert_with(|| SessionSettingValue::String("one_shot".to_owned()));
        return;
    }
    let (model, effort_key, effort) = match backend_kind {
        BackendKind::Claude => (UNIVERSAL_CLAUDE_MODEL, "effort", UNIVERSAL_CLAUDE_EFFORT),
        BackendKind::Codex => (
            REQUIRED_CODEX_TEST_MODEL,
            "reasoning_effort",
            REQUIRED_CODEX_TEST_REASONING_EFFORT,
        ),
        _ => return,
    };
    for (key, required) in [("model", model), (effort_key, effort)] {
        if let Some(existing) = settings.0.get(key) {
            assert_eq!(
                existing,
                &SessionSettingValue::String(required.to_owned()),
                "real {backend_kind:?} conformance attempted to override mandatory {key}={required}"
            );
        }
        settings.0.insert(
            key.to_owned(),
            SessionSettingValue::String(required.to_owned()),
        );
    }
}

