fn invalid_image_cases(
    supported: &[ImageData],
) -> Vec<(&'static str, ImageAttachmentCell, Vec<ImageData>)> {
    vec![
        (
            "empty-media-type",
            ImageAttachmentCell::InvalidEmptyMediaType,
            vec![ImageData {
                media_type: String::new(),
                data: SOLID_RED_PNG_BASE64.to_owned(),
            }],
        ),
        (
            "whitespace-media-type",
            ImageAttachmentCell::InvalidWhitespaceMediaType,
            vec![ImageData {
                media_type: " \t".to_owned(),
                data: SOLID_RED_PNG_BASE64.to_owned(),
            }],
        ),
        (
            "non-image-media-type",
            ImageAttachmentCell::InvalidNonImageMediaType,
            vec![ImageData {
                media_type: "text/plain".to_owned(),
                data: SOLID_RED_PNG_BASE64.to_owned(),
            }],
        ),
        (
            "unsupported-image-media-type",
            ImageAttachmentCell::InvalidUnsupportedMediaType,
            vec![ImageData {
                media_type: "image/bmp".to_owned(),
                data: SOLID_RED_PNG_BASE64.to_owned(),
            }],
        ),
        (
            "empty-data",
            ImageAttachmentCell::InvalidEmptyData,
            vec![ImageData {
                media_type: "image/png".to_owned(),
                data: String::new(),
            }],
        ),
        (
            "whitespace-data",
            ImageAttachmentCell::InvalidWhitespaceData,
            vec![ImageData {
                media_type: "image/png".to_owned(),
                data: " \n".to_owned(),
            }],
        ),
        (
            "surrounding-whitespace",
            ImageAttachmentCell::InvalidSurroundingWhitespace,
            vec![ImageData {
                media_type: "image/png".to_owned(),
                data: format!(" {SOLID_RED_PNG_BASE64}\n"),
            }],
        ),
        (
            "malformed-base64",
            ImageAttachmentCell::InvalidMalformedBase64,
            vec![ImageData {
                media_type: "image/png".to_owned(),
                data: "not/base64%%%".to_owned(),
            }],
        ),
        (
            "non-image-bytes",
            ImageAttachmentCell::InvalidNonImageBytes,
            vec![ImageData {
                media_type: "image/png".to_owned(),
                data: "bm90IGFuIGltYWdl".to_owned(),
            }],
        ),
        (
            "truncated-image-bytes",
            ImageAttachmentCell::InvalidTruncatedBytes,
            vec![ImageData {
                media_type: "image/png".to_owned(),
                data: "iVBORw0KGgo=".to_owned(),
            }],
        ),
        (
            "data-url-instead-of-base64",
            ImageAttachmentCell::InvalidDataUrl,
            vec![ImageData {
                media_type: "image/png".to_owned(),
                data: format!("data:image/png;base64,{SOLID_RED_PNG_BASE64}"),
            }],
        ),
        (
            "media-content-mismatch",
            ImageAttachmentCell::InvalidMediaTypeContentMismatch,
            vec![ImageData {
                media_type: "image/jpeg".to_owned(),
                data: SOLID_RED_PNG_BASE64.to_owned(),
            }],
        ),
        (
            "mixed-valid-invalid",
            ImageAttachmentCell::InvalidMixedPayloadAtomicity,
            vec![
                supported[0].clone(),
                ImageData {
                    media_type: "image/png".to_owned(),
                    data: "invalid%%%".to_owned(),
                },
                supported[2].clone(),
            ],
        ),
    ]
}

