fn schedule_image_ambient_during_stimulus(
    fixture: &RealBackendFixture,
    activity: ActivityCondition,
    stimulus: ContractStimulus,
) -> Option<tokio::task::JoinHandle<()>> {
    if !background_terminal_during_stimulus(activity)
        || matches!(
            stimulus,
            ContractStimulus::Close
                | ContractStimulus::HostRestartResume
                | ContractStimulus::TransportClosed
        )
    {
        return None;
    }
    let workspace = fixture.workspace_dir.path().to_path_buf();
    let count = ambient_work_count(activity);
    Some(tokio::spawn(async move {
        tokio::time::sleep(Duration::from_millis(50)).await;
        release_question_background_work_for_path(&workspace, count);
    }))
}

async fn finish_image_ambient_during_stimulus(
    release: Option<tokio::task::JoinHandle<()>>,
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    ids: &HashSet<String>,
    activity: ActivityCondition,
    stimulus: ContractStimulus,
    context: &str,
) {
    let boundary_terminalizes = matches!(
        stimulus,
        ContractStimulus::Close
            | ContractStimulus::HostRestartResume
            | ContractStimulus::TransportClosed
    );
    let must_observe_boundary = boundary_terminalizes
        && activity != ActivityCondition::ForegroundOnly
        && !background_terminal_before_stimulus(activity);
    if release.is_none() && !must_observe_boundary {
        return;
    }
    if let Some(release) = release {
        release.await.expect("image ambient release task failed");
    }
    let expected = if must_observe_boundary {
        match stimulus {
            ContractStimulus::Close | ContractStimulus::HostRestartResume => {
                ExpectedBackgroundOutcome::Cancelled
            }
            ContractStimulus::TransportClosed => ExpectedBackgroundOutcome::Failed,
            _ => unreachable!(),
        }
    } else {
        expected_background_outcome(activity)
            .expect("during-stimulus activity must have a terminal outcome")
    };
    wait_for_background_terminal_lifecycle(fixture, stream, ids, expected, context).await;
}

