async fn assert_image_lifecycle_activity_cell(
    backend_kind: BackendKind,
    activity_cell: ImageLifecycleActivityCell,
) {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let cells = vec![activity_cell.lifecycle];
    let mut ledger = EnumeratedCoverageLedger::new(cells.clone(), "image lifecycle contract");
    let admission = match activity_cell.lifecycle {
        ImageLifecycleCell::QueuedBytesPreserved => Some((
            InputAdmissionKind::ImageMessage,
            InputAdmissionAction::Enqueue,
        )),
        ImageLifecycleCell::QueuedMultipleOrderPreserved => Some((
            InputAdmissionKind::MultipleImageMessages,
            InputAdmissionAction::Enqueue,
        )),
        ImageLifecycleCell::QueuedEditReplacesBytes => Some((
            InputAdmissionKind::ImageMessage,
            InputAdmissionAction::EditQueued,
        )),
        ImageLifecycleCell::QueuedCancelRemovesPayload => Some((
            InputAdmissionKind::ImageMessage,
            InputAdmissionAction::CancelQueued,
        )),
        ImageLifecycleCell::QueuedSendNowConsumesOnce => Some((
            InputAdmissionKind::ImageMessage,
            InputAdmissionAction::SendQueuedNow,
        )),
        ImageLifecycleCell::QueuedInterruptThenDispatches => Some((
            InputAdmissionKind::ImageMessage,
            InputAdmissionAction::InterruptThenSend,
        )),
        ImageLifecycleCell::QueuedReconnectPreservesBytes => Some((
            InputAdmissionKind::ImageMessage,
            InputAdmissionAction::ClientReconnect,
        )),
        ImageLifecycleCell::QueuedHostRestartResumePreservesBytes => Some((
            InputAdmissionKind::ImageMessage,
            InputAdmissionAction::HostRestart,
        )),
        ImageLifecycleCell::QueuedForkIsolation => {
            Some((InputAdmissionKind::ImageMessage, InputAdmissionAction::Fork))
        }
        ImageLifecycleCell::QueuedCloseDoesNotConsume => Some((
            InputAdmissionKind::ImageMessage,
            InputAdmissionAction::Close,
        )),
        ImageLifecycleCell::QueuedTransportCloseDoesNotConsume => Some((
            InputAdmissionKind::ImageMessage,
            InputAdmissionAction::TransportClosed,
        )),
        _ => None,
    };
    if let Some((input, action)) = admission {
        run_image_admission_case(
            backend_kind,
            &capabilities,
            activity_cell.activity,
            input,
            action,
        )
        .await;
        ledger.record(activity_cell.lifecycle).unwrap();
        ledger.finish().unwrap();
        return;
    }
    let interaction_contract = match activity_cell.lifecycle {
        ImageLifecycleCell::AskUserResponseWithImages => {
            Some(InteractionConcurrencyContract::AskUserQuestion)
        }
        ImageLifecycleCell::PlanApprovalResponseWithImages => {
            Some(InteractionConcurrencyContract::ExitPlanMode)
        }
        _ => None,
    };
    if let Some(contract) = interaction_contract {
        assert_interaction_image_activity_cell(
            backend_kind,
            InteractionImageActivityCell {
                contract,
                payload: InteractionImagePayloadCell::Valid,
                activity: activity_cell.activity,
            },
        )
        .await;
        ledger.record(activity_cell.lifecycle).unwrap();
        ledger.finish().unwrap();
        return;
    }
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let supported = exhaustive_supported_image_set();
    let images = vec![supported[0].clone(), supported[2].clone()];
    let initial_prompt = if matches!(
        activity_cell.lifecycle,
        ImageLifecycleCell::ConcurrentStreamsIsolated
            | ImageLifecycleCell::ConcurrentClientsIsolated
    ) {
        "Inspect the two current inline images in order. Reply exactly IMAGE_MEMORY_READY and nothing else."
    } else {
        "The current user message contains exactly two inline image attachments. Inspect them visually in order and remember their colors for later. Do not use tools or search the filesystem. Reply exactly IMAGE_MEMORY_READY and nothing else."
    };
    let roots = fixture.workspace_roots();
    let (source, source_start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "image-persistence-matrix",
        initial_prompt,
        Some(images.clone()),
        cost_hint_for(backend_kind),
    )
    .await;
    assert_image_turn(
        &mut fixture,
        &source,
        initial_prompt,
        Some(&images),
        "IMAGE_MEMORY_READY",
    )
    .await;
    let (ambient_stream, _) = spawn_ready_image_stream(
        &mut fixture,
        backend_kind,
        "image-lifecycle-ambient",
        "IMAGE_LIFECYCLE_AMBIENT_READY",
    )
    .await;
    let ambient_ids = start_agent_control_ambient_work(
        &mut fixture,
        backend_kind,
        &ambient_stream,
        activity_cell.activity,
    )
    .await;
    let stimulus = if matches!(
        activity_cell.lifecycle,
        ImageLifecycleCell::CloseBeforeResume
            | ImageLifecycleCell::HostRestartResumeMemory
            | ImageLifecycleCell::ResumeReplayBytes
    ) {
        ContractStimulus::HostRestartResume
    } else {
        ContractStimulus::ProviderAccepts
    };
    ambient_before_stimulus(
        &mut fixture,
        &ambient_stream,
        &ambient_ids,
        activity_cell.activity,
        stimulus,
        "image lifecycle ambient before stimulus",
    )
    .await;
    let ambient_release =
        schedule_image_ambient_during_stimulus(&fixture, activity_cell.activity, stimulus);

    if cells.contains(&ImageLifecycleCell::ConnectionReplay) {
        let reconnected = reconnected_agent_bootstrap(&mut fixture, &source).await;
        assert_bootstrap_image_message(
            &reconnected,
            initial_prompt,
            Some(&images),
            "connection replay",
        );
        ledger.record(ImageLifecycleCell::ConnectionReplay).unwrap();
    }

    let supports_fork = capabilities.contains(tyde_agent_adapter::BackendCapability::ForkSession);
    let supports_resume =
        capabilities.contains(tyde_agent_adapter::BackendCapability::ResumeSession);
    let session_id = (supports_fork || supports_resume).then(|| {
        source_start
            .session_id
            .clone()
            .expect("image source missing native session id")
    });

    if supports_fork
        && cells.iter().any(|cell| {
            matches!(
                cell,
                ImageLifecycleCell::ForkCopiesHistory
                    | ImageLifecycleCell::ForkCurrentImageIsolation
            )
        })
    {
        let session_id = session_id.as_ref().unwrap();
        let sessions_before_invalid_forks =
            image_backend_session_count(&mut fixture, backend_kind).await;
        for (name, _, images) in invalid_image_cases(&supported) {
            assert_invalid_image_fork_is_atomic(&mut fixture, &source_start, name, images).await;
        }
        assert_eq!(
            image_backend_session_count(&mut fixture, backend_kind).await,
            sessions_before_invalid_forks,
            "invalid image forks created hidden persisted sessions"
        );
        let fork_images = vec![supported[3].clone()];
        let fork_prompt = "Recall the two images inherited from the source and inspect the one image attached to this fork prompt. Reply only with INHERITED_ followed by the two inherited uppercase colors joined by an underscore, then _CURRENT_ and the current uppercase color.";
        let fork = fork_agent_with_images_via_protocol(
            &mut fixture,
            source_start.agent_id.clone(),
            session_id.clone(),
            fork_prompt,
            fork_images.clone(),
        )
        .await;
        assert_image_turn(
            &mut fixture,
            &fork,
            fork_prompt,
            Some(&fork_images),
            "INHERITED_RED_BLUE_CURRENT_YELLOW",
        )
        .await;
        if cells.contains(&ImageLifecycleCell::ForkCurrentImageIsolation) {
            ledger
                .record(ImageLifecycleCell::ForkCurrentImageIsolation)
                .unwrap();
        }
        let fork_bootstrap = reconnected_agent_bootstrap(&mut fixture, &fork).await;
        assert_bootstrap_image_message(
            &fork_bootstrap,
            initial_prompt,
            Some(&images),
            "fork replay",
        );
        assert_bootstrap_image_message(
            &fork_bootstrap,
            fork_prompt,
            Some(&fork_images),
            "fork prompt isolation",
        );
        if cells.contains(&ImageLifecycleCell::ForkCopiesHistory) {
            ledger
                .record(ImageLifecycleCell::ForkCopiesHistory)
                .unwrap();
        }
        let fork_agent_id = fork_bootstrap
            .events
            .iter()
            .find_map(|event| match event {
                AgentBootstrapEvent::AgentStart(start) => Some(start.agent_id.clone()),
                _ => None,
            })
            .expect("fork bootstrap missing AgentStart");
        close_agent_at_definitive_boundary(
            &mut fixture,
            &fork,
            &fork_agent_id,
            "close image-persistence fork",
        )
        .await;
    }

    if supports_resume
        && cells.iter().any(|cell| {
            matches!(
                cell,
                ImageLifecycleCell::CloseBeforeResume
                    | ImageLifecycleCell::HostRestartResumeMemory
                    | ImageLifecycleCell::ResumeReplayBytes
            )
        })
    {
        close_agent_at_definitive_boundary(
            &mut fixture,
            &source,
            &source_start.agent_id,
            "close image-persistence source",
        )
        .await;
        if cells.contains(&ImageLifecycleCell::CloseBeforeResume) {
            ledger
                .record(ImageLifecycleCell::CloseBeforeResume)
                .unwrap();
        }
        fixture.restart_host().await;
        let resume_prompt = "Recall the original two image colors after resume. Reply only with RESUME_REMEMBERS_ followed by the uppercase colors joined by an underscore.";
        let resumed = resume_agent_via_protocol(
            &mut fixture.client,
            "resume-image-persistence",
            session_id.unwrap(),
            resume_prompt,
        )
        .await;
        assert_image_turn(
            &mut fixture,
            &resumed,
            resume_prompt,
            None,
            "RESUME_REMEMBERS_RED_BLUE",
        )
        .await;
        if cells.contains(&ImageLifecycleCell::HostRestartResumeMemory) {
            ledger
                .record(ImageLifecycleCell::HostRestartResumeMemory)
                .unwrap();
        }
        let resumed_bootstrap = reconnected_agent_bootstrap(&mut fixture, &resumed).await;
        assert_bootstrap_image_message(
            &resumed_bootstrap,
            initial_prompt,
            Some(&images),
            "resume replay",
        );
        assert_bootstrap_image_message(
            &resumed_bootstrap,
            resume_prompt,
            None,
            "resume prompt isolation",
        );
        if cells.contains(&ImageLifecycleCell::ResumeReplayBytes) {
            ledger
                .record(ImageLifecycleCell::ResumeReplayBytes)
                .unwrap();
        }
    }

    if cells.contains(&ImageLifecycleCell::ConcurrentStreamsIsolated) {
        assert_concurrent_image_isolation(&mut fixture, backend_kind, false).await;
        ledger
            .record(ImageLifecycleCell::ConcurrentStreamsIsolated)
            .unwrap();
    }
    if cells.contains(&ImageLifecycleCell::ConcurrentClientsIsolated) {
        assert_concurrent_image_isolation(&mut fixture, backend_kind, true).await;
        ledger
            .record(ImageLifecycleCell::ConcurrentClientsIsolated)
            .unwrap();
    }

    finish_image_ambient_during_stimulus(
        ambient_release,
        &mut fixture,
        &ambient_stream,
        &ambient_ids,
        activity_cell.activity,
        stimulus,
        "image lifecycle ambient during stimulus",
    )
    .await;
    ambient_after_stimulus(
        &mut fixture,
        &ambient_stream,
        &ambient_ids,
        activity_cell.activity,
        stimulus,
        "image lifecycle ambient after stimulus",
    )
    .await;
    ledger.finish().expect("complete image lifecycle matrix");
}

async fn assert_image_persistence_contract_matrix(backend_kind: BackendKind) {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let selected_cells = selected_image_lifecycle_cells(&capabilities);
    let selected_activities = conformance_activity_conditions(&capabilities);
    let required = ImageLifecycleActivityCell::required_for(&capabilities)
        .into_iter()
        .filter(|cell| {
            selected_cells.contains(&cell.lifecycle) && selected_activities.contains(&cell.activity)
        })
        .collect::<Vec<_>>();
    let mut ledger = EnumeratedCoverageLedger::new(required.clone(), "image lifecycle activity");
    for cell in required {
        assert_image_lifecycle_activity_cell(backend_kind, cell).await;
        ledger.record(cell).unwrap();
    }
    ledger.finish().unwrap();
    if selected_cells.iter().any(|cell| {
        matches!(
            cell,
            ImageLifecycleCell::AskUserResponseWithImages
                | ImageLifecycleCell::PlanApprovalResponseWithImages
        )
    }) {
        assert_interaction_image_activity_matrix(backend_kind).await;
    }
}

async fn assert_read_only_access_enforced(backend_kind: BackendKind) {
    const ORIGINAL: &str = "READ_ONLY_ORIGINAL_314";
    const MUTATED: &str = "READ_ONLY_MUTATED_926";
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let mut contracts = vec![ReadOnlyMutationContract::RunCommand { background: false }];
    if capabilities.contains(tyde_agent_adapter::BackendCapability::GenericModifyFile) {
        contracts.push(ReadOnlyMutationContract::ModifyFile);
    }
    if capabilities.contains(tyde_agent_adapter::BackendCapability::BackgroundTasks) {
        contracts.push(ReadOnlyMutationContract::RunCommand { background: true });
    }
    for contract in contracts {
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        let protected = fixture.workspace_dir.path().join("READ_ONLY_PROOF.txt");
        std::fs::write(&protected, ORIGINAL).expect("seed read-only proof file");
        let prompt = read_only_mutation_prompt(backend_kind, contract, MUTATED);
        let (stream, agent_id) = spawn_read_only_agent(
            &mut fixture,
            backend_kind,
            "read-only-access-certification",
            &prompt,
        )
        .await;
        expect_read_only_mutation_denial(&mut fixture, &stream, &prompt, contract, MUTATED).await;
        assert_eq!(
            std::fs::read_to_string(&protected).expect("read protected file"),
            ORIGINAL,
            "{backend_kind:?} mutated the workspace under read-only access"
        );
        assert_read_only_session_remains_usable(&mut fixture, backend_kind, &stream, ORIGINAL)
            .await;
        close_agent_at_definitive_boundary(
            &mut fixture,
            &stream,
            &agent_id,
            "close read-only access case",
        )
        .await;
    }
    if capabilities.contains(tyde_agent_adapter::BackendCapability::ForegroundSubagents) {
        assert_read_only_native_child_inherits_access(backend_kind, ORIGINAL, MUTATED).await;
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReadOnlyMutationContract {
    ModifyFile,
    RunCommand { background: bool },
}

async fn assert_inherited_read_only_denies_command(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    stream: &StreamPath,
    original: &str,
    mutated: &str,
) {
    let prompt = read_only_mutation_prompt(
        backend_kind,
        ReadOnlyMutationContract::RunCommand { background: false },
        mutated,
    );
    fixture
        .client
        .send_message(stream, prompt.clone())
        .await
        .expect("send inherited read-only mutation probe");
    let turn = expect_tool_turn_after_user_echo(&mut fixture.client, stream, &prompt).await;
    let requests: Vec<_> = turn
        .tool_requests
        .iter()
        .filter(|request| matches!(&request.tool_type, ToolRequestType::RunCommand { .. }))
        .collect();
    assert_eq!(
        requests.len(),
        1,
        "inherited read-only probe issued the wrong requests"
    );
    let completions: Vec<_> = turn
        .tool_completions
        .iter()
        .filter(|completion| completion.tool_call_id == requests[0].tool_call_id)
        .collect();
    assert_eq!(completions.len(), 1);
    assert!(
        !completions[0].success(),
        "inherited read-only command succeeded"
    );
    assert_eq!(
        std::fs::read_to_string(fixture.workspace_dir.path().join("READ_ONLY_PROOF.txt"))
            .expect("read inherited access sentinel"),
        original
    );
}

fn read_only_mutation_prompt(
    backend_kind: BackendKind,
    contract: ReadOnlyMutationContract,
    mutated: &str,
) -> String {
    match (backend_kind, contract) {
        (BackendKind::Claude, ReadOnlyMutationContract::ModifyFile) => format!(
            "Use Edit exactly once on `READ_ONLY_PROOF.txt` to replace all contents with `{mutated}`. Attempt the Edit even when read-only policy blocks it. Do not use Bash, Read, Write, or another tool. After Edit returns, reply exactly READ_ONLY_DENIED."
        ),
        (BackendKind::Codex, ReadOnlyMutationContract::ModifyFile) => format!(
            "Use apply_patch exactly once on `READ_ONLY_PROOF.txt` to replace all contents with `{mutated}`. Attempt it even when read-only policy blocks it. Do not run commands, read the file, or use another tool. After it returns, reply exactly READ_ONLY_DENIED."
        ),
        (_, ReadOnlyMutationContract::ModifyFile) => format!(
            "Use the native file-edit tool exactly once on `READ_ONLY_PROOF.txt` to replace all contents with `{mutated}`. Attempt it even when read-only policy blocks it. Do not run commands, read the file, or use another tool. After it returns, reply exactly READ_ONLY_DENIED."
        ),
        (BackendKind::Claude, ReadOnlyMutationContract::RunCommand { background }) => format!(
            "Use Bash exactly once {} to run exactly `printf {mutated} > READ_ONLY_PROOF.txt`. Attempt it even when read-only policy blocks it. Do not use a file tool or another tool. After Bash returns, reply exactly READ_ONLY_DENIED.",
            if background {
                "with run_in_background=true"
            } else {
                "in the foreground"
            }
        ),
        (BackendKind::Codex, ReadOnlyMutationContract::RunCommand { background }) => format!(
            "Call run_command exactly once with command `printf {mutated} > READ_ONLY_PROOF.txt`{}. Attempt it even when read-only policy blocks it. Do not use apply_patch or another tool. After it returns, reply exactly READ_ONLY_DENIED.",
            if background {
                " and yield_time_ms=0"
            } else {
                ""
            }
        ),
        (BackendKind::Hermes, ReadOnlyMutationContract::RunCommand { background }) => format!(
            "Use terminal exactly once {} to run exactly `printf {mutated} > READ_ONLY_PROOF.txt`. Attempt it even when read-only policy blocks it. Do not use another tool. After terminal returns, reply exactly READ_ONLY_DENIED.",
            if background {
                "in background mode"
            } else {
                "in foreground mode"
            }
        ),
        (_, ReadOnlyMutationContract::RunCommand { background }) => format!(
            "Use the command tool exactly once {} to run exactly `printf {mutated} > READ_ONLY_PROOF.txt`. Attempt it even when read-only policy blocks it. Do not use another tool. After it returns, reply exactly READ_ONLY_DENIED.",
            if background {
                "in background mode"
            } else {
                "in foreground mode"
            }
        ),
    }
}

