async fn expect_read_only_mutation_denial(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    prompt: &str,
    contract: ReadOnlyMutationContract,
    mutated: &str,
) {
    let mut saw_user = false;
    let mut request_id = None;
    let mut completion_count = 0usize;
    let mut saw_failed_completion = false;
    let mut saw_idle = false;
    let mut trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(180), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, "read-only mutation denial").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            let event = envelope.parse_payload::<ChatEvent>().expect("parse read-only event");
            trace.push(format!("{event:?}"));
            match event {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == prompt => saw_user = true,
                ChatEvent::ToolRequest(request) if saw_user => {
                    let matches = match (&request.tool_type, contract) {
                        (ToolRequestType::ModifyFile { file_path, after, .. }, ReadOnlyMutationContract::ModifyFile) => {
                            file_path.ends_with("READ_ONLY_PROOF.txt") && after.contains(mutated)
                        }
                        (ToolRequestType::RunCommand { command, .. }, ReadOnlyMutationContract::RunCommand { .. }) => {
                            command.contains("READ_ONLY_PROOF.txt") && command.contains(mutated)
                        }
                        _ => false,
                    };
                    assert!(matches, "backend made the wrong read-only mutation request: {request:?}");
                    assert!(request_id.replace(request.tool_call_id).is_none(), "read-only mutation request was emitted more than once");
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if request_id.as_ref() == Some(&completion.tool_call_id) =>
                {
                    completion_count += 1;
                    assert_eq!(completion_count, 1, "read-only denial completed more than once");
                    assert!(!completion.success(), "read-only mutation reported success: {completion:?}");
                    assert!(
                        completion.error().as_ref().is_some_and(|error| !error.trim().is_empty())
                            || matches!(&completion.outcome, ToolExecutionOutcome::Failed { .. }),
                        "read-only denial had no visible error: {completion:?}"
                    );
                    saw_failed_completion = true;
                }
                ChatEvent::TypingStatusChanged(false) if saw_failed_completion => {
                    saw_idle = true;
                    break;
                }
                ChatEvent::TypingStatusChanged(false) if saw_user => {
                    panic!("read-only turn became idle without its exact failed mutation completion")
                }
                ChatEvent::MessageAdded(ChatMessage { sender: MessageSender::Error, content, .. })
                    if request_id.is_none() => panic!("read-only backend failed before emitting the normalized mutation request: {content}"),
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("read-only mutation contract timed out; trace:\n{}", trace.join("\n")));
    assert!(request_id.is_some());
    assert_eq!(completion_count, 1);
    assert!(saw_idle);
}

async fn assert_read_only_session_remains_usable(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    stream: &StreamPath,
    original: &str,
) {
    let read_prompt = match backend_kind {
        BackendKind::Claude => {
            "Use Bash exactly once in the foreground to run `cat READ_ONLY_PROOF.txt`. Do not use another tool. Then reply exactly READ_ONLY_READ_OK."
        }
        BackendKind::Codex => {
            "Call run_command exactly once with command `cat READ_ONLY_PROOF.txt`. Do not use another tool. Then reply exactly READ_ONLY_READ_OK."
        }
        BackendKind::Hermes => {
            "Use terminal exactly once in foreground mode to run `cat READ_ONLY_PROOF.txt`. Do not use another tool. Then reply exactly READ_ONLY_READ_OK."
        }
        _ => {
            "Use the command tool exactly once in the foreground to run `cat READ_ONLY_PROOF.txt`. Do not use another tool. Then reply exactly READ_ONLY_READ_OK."
        }
    };
    fixture
        .client
        .send_message(stream, read_prompt.to_owned())
        .await
        .expect("send read-only read probe");
    let turn = expect_tool_turn_after_user_echo(&mut fixture.client, stream, read_prompt).await;
    let requests = turn.tool_requests.iter().filter(|request| matches!(&request.tool_type, ToolRequestType::RunCommand { command, .. } if command.contains("cat READ_ONLY_PROOF.txt"))).collect::<Vec<_>>();
    assert_eq!(
        requests.len(),
        1,
        "read-only session did not issue one exact read command: {turn:?}"
    );
    let completions = turn
        .tool_completions
        .iter()
        .filter(|completion| completion.tool_call_id == requests[0].tool_call_id)
        .collect::<Vec<_>>();
    assert_eq!(completions.len(), 1);
    assert!(
        completions[0].success(),
        "read-only read failed after denied mutation: {:?}",
        completions[0]
    );
    let ToolExecutionResult::RunCommand { stdout, .. } = &completions[0].tool_result() else {
        panic!(
            "read-only read completion was not normalized RunCommand: {:?}",
            completions[0]
        )
    };
    assert!(stdout.contains(original));
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, "read-only read idle").await;
            if envelope.kind == FrameKind::ChatEvent
                && envelope.stream == *stream
                && matches!(
                    envelope
                        .parse_payload::<ChatEvent>()
                        .expect("parse read-only idle"),
                    ChatEvent::TypingStatusChanged(false)
                )
            {
                break;
            }
        }
    })
    .await
    .expect("read-only session did not become idle after successful read");
    let follow_up = "Do not use tools. Reply exactly READ_ONLY_FOLLOW_UP_OK.";
    fixture
        .client
        .send_message(stream, follow_up.to_owned())
        .await
        .expect("send read-only follow-up");
    let response =
        expect_assistant_turn_after_user_echo(&mut fixture.client, stream, follow_up).await;
    assert!(response.final_text.contains("READ_ONLY_FOLLOW_UP_OK"));
}

async fn assert_read_only_native_child_inherits_access(
    backend_kind: BackendKind,
    original: &str,
    mutated: &str,
) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let protected = fixture.workspace_dir.path().join("READ_ONLY_PROOF.txt");
    std::fs::write(&protected, original).expect("seed inherited read-only proof");
    let child_job = format!(
        "run exactly `printf {mutated} > READ_ONLY_PROOF.txt` with the command tool, even if read-only policy blocks it; use no other tool; report the denial"
    );
    let prompt = match backend_kind {
        BackendKind::Claude => format!(
            "Use the Agent tool exactly once in foreground mode. Tell the child to {child_job}. Wait for it, then reply exactly READ_ONLY_CHILD_DONE."
        ),
        BackendKind::Hermes => format!(
            "Delegate exactly once to one native child and tell it to {child_job}. Wait for it, then reply exactly READ_ONLY_CHILD_DONE."
        ),
        _ => format!(
            "Use one native foreground subagent exactly once and tell it to {child_job}. Wait for it, then reply exactly READ_ONLY_CHILD_DONE."
        ),
    };
    let (parent_stream, parent_id) = spawn_read_only_agent(
        &mut fixture,
        backend_kind,
        "read-only-native-child",
        &prompt,
    )
    .await;
    let mut child_stream = None;
    let mut child_request_id = None;
    let mut child_completion_count = 0usize;
    let mut child_failed = false;
    tokio::time::timeout(Duration::from_secs(240), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "read-only native child denial").await;
            if envelope.kind == FrameKind::NewAgent {
                let child: NewAgentPayload = envelope
                    .parse_payload()
                    .expect("parse projected read-only child");
                if child.parent_agent_id.as_ref() == Some(&parent_id) {
                    child_stream = Some(child.instance_stream);
                }
                continue;
            }
            let Some(expected_child_stream) = child_stream.as_ref() else {
                continue;
            };
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *expected_child_stream {
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .expect("parse read-only child event")
            {
                ChatEvent::ToolRequest(request) => {
                    let ToolRequestType::RunCommand { command, .. } = &request.tool_type else {
                        continue;
                    };
                    assert!(command.contains("READ_ONLY_PROOF.txt") && command.contains(mutated));
                    assert!(child_request_id.replace(request.tool_call_id).is_none());
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if child_request_id.as_ref() == Some(&completion.tool_call_id) =>
                {
                    child_completion_count += 1;
                    assert_eq!(child_completion_count, 1);
                    assert!(
                        !completion.success(),
                        "inherited read-only child mutation succeeded: {completion:?}"
                    );
                    child_failed = true;
                }
                ChatEvent::TypingStatusChanged(false) if child_failed => break,
                _ => {}
            }
        }
    })
    .await
    .expect(
        "native child did not expose an exact failed mutation under inherited read-only access",
    );
    assert_eq!(std::fs::read_to_string(&protected).unwrap(), original);
    assert_eq!(child_completion_count, 1);
    close_agent_at_definitive_boundary(
        &mut fixture,
        &parent_stream,
        &parent_id,
        "close inherited read-only parent",
    )
    .await;
}
async fn expect_tool_turn_after_user_echo(
    client: &mut ValidatedConnection,
    agent_stream: &StreamPath,
    prompt: &str,
) -> ToolTurn {
    let mut got_user_message_echo = false;
    let mut final_text: Option<String> = None;
    let mut saw_stream_end = false;
    let mut saw_idle = false;
    let mut streamed_text = String::new();
    let mut tool_requests: HashMap<String, ToolRequest> = HashMap::new();
    let mut tool_completions: HashMap<String, ToolExecutionCompletedData> = HashMap::new();
    let mut tool_names = HashMap::new();

    loop {
        let env = expect_next_event(client, "tool-assisted ChatEvent").await;
        if env.kind != FrameKind::ChatEvent || env.stream != *agent_stream {
            continue;
        }
        let event: ChatEvent = env.parse_payload().expect("parse ChatEvent");
        eprintln!("TOOL-ASSISTED TURN EVENT {event:?}");
        match event {
            ChatEvent::MessageAdded(message) => {
                if matches!(message.sender, MessageSender::User) && message.content == prompt {
                    got_user_message_echo = true;
                }
            }
            ChatEvent::StreamEnd(data) => {
                if !got_user_message_echo {
                    continue;
                }
                saw_stream_end = true;
                for tool in &data.message.tool_calls {
                    tool_names.insert(tool.tool_call_id.clone(), tool.name.clone());
                }
                final_text = Some(if data.message.content.trim().is_empty() {
                    streamed_text.clone()
                } else {
                    data.message.content
                });
            }
            ChatEvent::StreamDelta(delta) => {
                if got_user_message_echo {
                    streamed_text.push_str(&delta.text);
                }
            }
            ChatEvent::ToolRequest(request) => {
                if got_user_message_echo {
                    tool_requests.insert(request.tool_call_id.clone(), request);
                }
            }
            ChatEvent::ToolExecutionCompleted(completion) if got_user_message_echo => {
                tool_completions.insert(completion.tool_call_id.clone(), completion);
            }
            ChatEvent::TypingStatusChanged(false) if got_user_message_echo => saw_idle = true,
            _ => {}
        }

        if saw_stream_end
            && saw_idle
            && !tool_requests.is_empty()
            && tool_requests
                .keys()
                .all(|call_id| tool_completions.contains_key(call_id))
        {
            return ToolTurn {
                final_text: final_text.unwrap_or_default(),
                tool_requests: tool_requests.into_values().collect(),
                tool_completions: tool_completions.into_values().collect(),
                tool_names,
            };
        }
    }
}

async fn expect_named_tool_turn_after_user_echo(
    client: &mut ValidatedConnection,
    agent_stream: &StreamPath,
    prompt: &str,
    required_tool_name: &str,
) -> ToolTurn {
    let mut got_user_message_echo = false;
    let mut final_text = String::new();
    let mut streamed_text = String::new();
    let mut target_completed = false;
    let mut saw_stream_end_after_target = false;
    let mut tool_requests: HashMap<String, ToolRequest> = HashMap::new();
    let mut tool_completions: HashMap<String, ToolExecutionCompletedData> = HashMap::new();
    let mut tool_names = HashMap::new();

    loop {
        let env = expect_next_event(client, "named tool-assisted ChatEvent").await;
        if env.kind != FrameKind::ChatEvent || env.stream != *agent_stream {
            continue;
        }
        let event: ChatEvent = env.parse_payload().expect("parse ChatEvent");
        eprintln!("NAMED TOOL-ASSISTED TURN EVENT {event:?}");
        match event {
            ChatEvent::MessageAdded(message) => {
                if matches!(message.sender, MessageSender::User) && message.content == prompt {
                    got_user_message_echo = true;
                }
            }
            ChatEvent::StreamDelta(delta) if got_user_message_echo => {
                streamed_text.push_str(&delta.text);
            }
            ChatEvent::StreamEnd(data) if got_user_message_echo => {
                for tool in &data.message.tool_calls {
                    tool_names.insert(tool.tool_call_id.clone(), tool.name.clone());
                }
                final_text = if data.message.content.trim().is_empty() {
                    streamed_text.clone()
                } else {
                    data.message.content
                };
                streamed_text.clear();
                if target_completed {
                    saw_stream_end_after_target = true;
                }
            }
            ChatEvent::ToolRequest(request) if got_user_message_echo => {
                tool_requests.insert(request.tool_call_id.clone(), request);
            }
            ChatEvent::ToolExecutionCompleted(completion) if got_user_message_echo => {
                if tool_requests.contains_key(&completion.tool_call_id)
                    && tool_names
                        .get(&completion.tool_call_id)
                        .is_some_and(|name| name.contains(required_tool_name))
                {
                    target_completed = true;
                }
                tool_completions.insert(completion.tool_call_id.clone(), completion);
            }
            ChatEvent::TypingStatusChanged(false) if got_user_message_echo && !target_completed => {
                panic!(
                    "backend became idle without calling required tool {required_tool_name}; requests={:?}",
                    tool_requests.values().collect::<Vec<_>>()
                );
            }
            _ => {}
        }

        if target_completed && saw_stream_end_after_target {
            return ToolTurn {
                final_text,
                tool_requests: tool_requests.into_values().collect(),
                tool_completions: tool_completions.into_values().collect(),
                tool_names,
            };
        }
    }
}

async fn expect_tool_turn_until_output_exists(
    client: &mut ValidatedConnection,
    agent_stream: &StreamPath,
    prompt: &str,
    output_path: &std::path::Path,
) -> ToolTurn {
    let mut turn = expect_tool_turn_after_user_echo(client, agent_stream, prompt).await;
    if output_path.exists() {
        return turn;
    }

    loop {
        let maybe_env = tokio::time::timeout(Duration::from_secs(5), client.next_event()).await;
        let env = match maybe_env {
            Ok(Ok(Some(env))) => env,
            Ok(Ok(None)) => break,
            Ok(Err(err)) => panic!("next_event failed while waiting for file output: {err:?}"),
            Err(_) => break,
        };

        if env.kind != FrameKind::ChatEvent || env.stream != *agent_stream {
            continue;
        }

        let event: ChatEvent = env.parse_payload().expect("parse ChatEvent");
        match event {
            ChatEvent::StreamEnd(data) => {
                turn.final_text = data.message.content;
            }
            ChatEvent::ToolRequest(request) => {
                if !turn
                    .tool_requests
                    .iter()
                    .any(|existing| existing.tool_call_id == request.tool_call_id)
                {
                    turn.tool_requests.push(request);
                }
            }
            ChatEvent::ToolExecutionCompleted(completion) => {
                if let Some(existing) = turn
                    .tool_completions
                    .iter_mut()
                    .find(|existing| existing.tool_call_id == completion.tool_call_id)
                {
                    *existing = completion;
                } else {
                    turn.tool_completions.push(completion);
                }
            }
            _ => {}
        }

        if output_path.exists()
            && !turn.tool_requests.is_empty()
            && turn.tool_requests.iter().all(|request| {
                turn.tool_completions
                    .iter()
                    .any(|completion| completion.tool_call_id == request.tool_call_id)
            })
        {
            break;
        }
    }

    turn
}

async fn assert_backend_emits_tool_events_for_file_copy(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
) {
    let input_contents = format!("TOOL-COPY-CONTENT-{}", unique_secret());
    let input_path = fixture.workspace_dir.path().join("INPUT.txt");
    let output_path = fixture.workspace_dir.path().join("OUTPUT.txt");
    let workspace_roots = fixture.workspace_roots();
    std::fs::write(&input_path, &input_contents).expect("seed input file");
    let _ = std::fs::remove_file(&output_path);

    let prompt = match backend_kind {
        BackendKind::Claude => {
            "Use Bash exactly once to run `cp INPUT.txt OUTPUT.txt` in the foreground. Do not use another tool. After it succeeds, reply briefly."
        }
        BackendKind::Codex => {
            "Call run_command exactly once with command `cp INPUT.txt OUTPUT.txt`. Do not use another tool. After it succeeds, reply briefly."
        }
        BackendKind::Hermes => {
            "Use the terminal tool exactly once in the foreground to run `cp INPUT.txt OUTPUT.txt`. Do not use another tool. After it succeeds, reply briefly."
        }
        _ => {
            "Use the command execution tool exactly once in the foreground to run `cp INPUT.txt OUTPUT.txt`. Do not use another tool. After it succeeds, reply briefly."
        }
    };
    let agent_stream = spawn_agent_via_protocol(
        &mut fixture.client,
        workspace_roots,
        backend_kind,
        "tool-file-copy",
        prompt,
    )
    .await;
    let turn = expect_tool_turn_until_output_exists(
        &mut fixture.client,
        &agent_stream,
        prompt,
        &output_path,
    )
    .await;
    let mut turn = turn;

    for follow_up_prompt in [
        "You inspected INPUT.txt. Now actually create OUTPUT.txt in the workspace with exactly the same contents before you reply.",
        "Finish the task now: write OUTPUT.txt with the same contents as INPUT.txt, then confirm briefly.",
    ] {
        if output_path.exists() {
            break;
        }
        fixture
            .client
            .send_message(&agent_stream, follow_up_prompt.to_string())
            .await
            .expect("send tool follow-up message");
        let next_turn = expect_tool_turn_until_output_exists(
            &mut fixture.client,
            &agent_stream,
            follow_up_prompt,
            &output_path,
        )
        .await;
        turn.tool_requests.extend(next_turn.tool_requests);
        turn.tool_completions.extend(next_turn.tool_completions);
        if !next_turn.final_text.trim().is_empty() {
            turn.final_text = next_turn.final_text;
        }
    }

    assert!(
        !turn.tool_requests.is_empty(),
        "expected at least one ToolRequest for {backend_kind:?}"
    );
    assert_eq!(
        turn.tool_requests.len(),
        turn.tool_completions.len(),
        "expected a matching ToolExecutionCompleted for every ToolRequest for {backend_kind:?}"
    );
    assert!(
        turn.tool_completions
            .iter()
            .any(|completion| completion.success()),
        "expected at least one successful ToolExecutionCompleted for {backend_kind:?}; requests={:?} completions={:?} final_text={:?}",
        turn.tool_requests,
        turn.tool_completions,
        turn.final_text
    );
    assert_eq!(
        turn.tool_requests.len(),
        1,
        "agent-message turn issued an unexpected extra tool request: {:?}",
        turn.tool_requests
    );
    assert!(
        output_path.exists(),
        "expected OUTPUT.txt to exist after tool-assisted turn for {backend_kind:?}; requests={:?} completions={:?} final_text={:?}",
        turn.tool_requests,
        turn.tool_completions,
        turn.final_text
    );
    let output_contents = std::fs::read_to_string(&output_path).expect("read OUTPUT.txt");
    assert!(
        output_contents == input_contents || output_contents == format!("{input_contents}\n"),
        "expected OUTPUT.txt to match INPUT.txt for {backend_kind:?} (allowing one trailing newline); requests={:?} completions={:?} final_text={:?} output={:?} input={:?}",
        turn.tool_requests,
        turn.tool_completions,
        turn.final_text,
        output_contents,
        input_contents
    );
    // Live Codex may finish a tool-only turn without a final text message.
    // This test's contract is the tool lifecycle and file-copy result above.
}

async fn assert_tool_response_ownership(backend_kind: BackendKind) {
    const FINAL_MARKER: &str = "BUG001_TOOL_RESPONSE_DONE";
    const TOOL_OUTPUT: &str = "BUG001_TOOL_OUTPUT";

    let mut fixture = RealBackendFixture::new(backend_kind).await;
    fixture
        .client
        .inner
        .mcp_server_upsert(protocol::McpServerUpsertPayload {
            mcp_server: protocol::McpServerConfig {
                id: protocol::McpServerId("bug001-failed-startup".to_owned()),
                name: "bug001-failed-startup".to_owned(),
                supports_parallel_tool_calls: false,
                transport: protocol::McpTransportConfig::Stdio {
                    command: "/definitely/missing/bug001-mcp-server".to_owned(),
                    args: Vec::new(),
                    env: HashMap::new(),
                },
            },
        })
        .await
        .expect("install BUG-001 failed startup MCP server");
    let prompt = match backend_kind {
        BackendKind::Claude => {
            "Use Bash exactly once in the foreground to run `printf BUG001_TOOL_OUTPUT`. Do not use another tool. After the tool succeeds, continue with a new response that says exactly BUG001_TOOL_RESPONSE_DONE."
        }
        BackendKind::Codex => {
            "Call exec_command exactly once with cmd `printf BUG001_TOOL_OUTPUT`. Do not use another tool. After the tool succeeds, continue with a new response that says exactly BUG001_TOOL_RESPONSE_DONE."
        }
        BackendKind::Acp => {
            "Use command execution exactly once in the foreground to run `printf BUG001_TOOL_OUTPUT`. Do not use another tool. After the tool succeeds, continue with a new response that says exactly BUG001_TOOL_RESPONSE_DONE."
        }
        BackendKind::Hermes => {
            "Use terminal exactly once in the foreground to run `printf BUG001_TOOL_OUTPUT`. Do not use another tool. After the tool succeeds, continue with a new response that says exactly BUG001_TOOL_RESPONSE_DONE."
        }
        BackendKind::Tycode => {
            "Use command execution exactly once in the foreground to run `printf BUG001_TOOL_OUTPUT`. Do not use another tool. After the tool succeeds, continue with a new response that says exactly BUG001_TOOL_RESPONSE_DONE."
        }
        BackendKind::Antigravity => {
            unreachable!("Antigravity is not in ALL_SUPPORTED_REAL_BACKENDS")
        }
    };
    let workspace_roots = fixture.workspace_roots();
    let stream = spawn_agent_via_protocol(
        &mut fixture.client,
        workspace_roots,
        backend_kind,
        "bug001-tool-response-ownership",
        prompt,
    )
    .await;

    let mut saw_user_echo = false;
    let mut response_open = false;
    let mut response_ordinal = 0usize;
    let mut message_ids = Vec::<(usize, &'static str, String)>::new();
    let mut declarations = HashMap::<String, Vec<(usize, usize)>>::new();
    let mut requests = Vec::<(usize, ToolRequest)>::new();
    let mut completions = HashMap::<String, (usize, ToolExecutionCompletedData)>::new();
    let mut next_streams = Vec::<(usize, usize)>::new();
    let mut saw_terminal_response = false;
    let mut saw_idle_after_terminal = false;
    let mut event_index = 0usize;

    tokio::time::timeout(Duration::from_secs(180), async {
        loop {
            let envelope = fixture
                .client
                .next_event()
                .await
                .expect("read BUG-001 ownership event")
                .expect("BUG-001 ownership stream closed");
            if envelope.stream != stream {
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                let error: protocol::AgentErrorPayload = envelope
                    .parse_payload()
                    .expect("parse BUG-001 AgentError");
                panic!(
                    "{backend_kind:?} BUG-001 successful turn emitted AgentError: {}",
                    error.message
                );
            }
            if envelope.kind != FrameKind::ChatEvent {
                continue;
            }
            let event: ChatEvent = envelope
                .parse_payload()
                .expect("parse BUG-001 ChatEvent");
            eprintln!("BUG001 EVENT backend={backend_kind:?} index={event_index} {event:?}");

            match &event {
                ChatEvent::MessageAdded(message) => {
                    if matches!(message.sender, MessageSender::User) && message.content == prompt {
                        saw_user_echo = true;
                    }
                    if saw_user_echo && matches!(message.sender, MessageSender::Error) {
                        panic!(
                            "{backend_kind:?} BUG-001 successful turn emitted Error: {}",
                            message.content
                        );
                    }
                    if let Some(message_id) = &message.message_id {
                        message_ids.push((event_index, "MessageAdded", message_id.0.clone()));
                    }
                }
                ChatEvent::StreamStart(_) if saw_user_echo => {
                    assert!(
                        !response_open,
                        "{backend_kind:?} BUG-001 next assistant stream started while another stream was active"
                    );
                    response_open = true;
                    response_ordinal += 1;
                    if !completions.is_empty() {
                        next_streams.push((event_index, response_ordinal));
                    }
                }
                ChatEvent::StreamDelta(delta) | ChatEvent::StreamReasoningDelta(delta)
                    if saw_user_echo =>
                {
                    let _ = delta;
                    assert!(
                        response_open,
                        "{backend_kind:?} BUG-001 stream delta arrived outside a response"
                    );
                }
                ChatEvent::StreamEnd(end) if saw_user_echo => {
                    assert!(
                        response_open,
                        "{backend_kind:?} BUG-001 StreamEnd did not close its own assistant stream"
                    );
                    response_open = false;
                    if let Some(message_id) = &end.message.message_id {
                        message_ids.push((event_index, "StreamEnd", message_id.0.clone()));
                    }
                    for tool_call in &end.message.tool_calls {
                        declarations
                            .entry(tool_call.tool_call_id.clone())
                            .or_default()
                            .push((event_index, response_ordinal));
                    }
                    if !completions.is_empty() && end.message.content.contains(FINAL_MARKER) {
                        saw_terminal_response = true;
                    }
                }
                ChatEvent::MessageMetadataUpdated(update) if saw_user_echo => {
                    message_ids.push((
                        event_index,
                        "MessageMetadataUpdated",
                        update.message_id.0.clone(),
                    ));
                }
                ChatEvent::ToolRequest(request) if saw_user_echo => {
                    requests.push((event_index, request.clone()));
                }
                ChatEvent::ToolExecutionCompleted(completion) if saw_user_echo => {
                    assert!(
                        completion.success(),
                        "{backend_kind:?} BUG-001 tool failed: {completion:?}"
                    );
                    if let ToolExecutionResult::RunCommand { stdout, .. } = &completion.tool_result() {
                        assert!(
                            stdout.contains(TOOL_OUTPUT),
                            "{backend_kind:?} BUG-001 command returned unexpected output: {completion:?}"
                        );
                    }
                    assert!(
                        completions
                            .insert(completion.tool_call_id.clone(), (event_index, completion.clone()))
                            .is_none(),
                        "{backend_kind:?} BUG-001 tool completed more than once"
                    );
                }
                ChatEvent::OperationCancelled(cancelled) if saw_user_echo => {
                    panic!(
                        "{backend_kind:?} BUG-001 successful turn emitted OperationCancelled: {}",
                        cancelled.message
                    );
                }
                ChatEvent::TypingStatusChanged(false) if saw_terminal_response => {
                    saw_idle_after_terminal = true;
                }
                _ => {}
            }
            event_index += 1;

            if saw_idle_after_terminal {
                break;
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "{backend_kind:?} BUG-001 tool turn did not complete: requests={requests:?} completions={completions:?} declarations={declarations:?} next_streams={next_streams:?}"
        )
    });

    assert_eq!(
        requests.len(),
        1,
        "{backend_kind:?} BUG-001 prompt must produce exactly one ToolRequest"
    );
    let (request_index, request) = &requests[0];
    let owners = declarations.get(&request.tool_call_id).unwrap_or_else(|| {
        panic!(
            "{backend_kind:?} BUG-001 ToolRequest was not declared by any provider response: {request:?}"
        )
    });
    assert_eq!(
        owners.len(),
        1,
        "{backend_kind:?} BUG-001 ToolRequest was declared by multiple provider responses: {owners:?}"
    );
    let (owner_end_index, owner_response_ordinal) = &owners[0];
    let (completion_index, _) = completions.get(&request.tool_call_id).unwrap_or_else(|| {
        panic!(
            "{backend_kind:?} BUG-001 ToolRequest had no matching successful completion: {request:?}"
        )
    });
    assert!(
        request_index < completion_index,
        "{backend_kind:?} BUG-001 tool completed before its request"
    );
    assert!(
        message_ids
            .iter()
            .all(|(_, _, message_id)| message_id != &request.tool_call_id),
        "{backend_kind:?} BUG-001 emitted a message id equal to tool call id {}: {message_ids:?}",
        request.tool_call_id
    );
    let (next_start_index, next_response_ordinal) = next_streams
        .iter()
        .find(|(index, _)| index > completion_index)
        .unwrap_or_else(|| {
            panic!(
                "{backend_kind:?} BUG-001 tool completion was not followed by a clean assistant stream: {next_streams:?}"
            )
        });
    assert!(next_start_index > completion_index);
    assert!(
        owner_end_index < next_start_index,
        "{backend_kind:?} BUG-001 next provider response started before the tool owner declared its request"
    );
    assert_ne!(next_response_ordinal, owner_response_ordinal);
    assert!(saw_terminal_response);
    assert!(saw_idle_after_terminal);

    fixture
        .client
        .close_agent(&stream)
        .await
        .expect("close BUG-001 ownership agent");
}

async fn assert_backend_interrupts_long_running_command(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
) {
    let workspace_roots = fixture.workspace_roots();
    let script_path = fixture.workspace_dir.path().join("interrupt_test.sh");
    let output_path = fixture.workspace_dir.path().join("INTERRUPT_PROOF.txt");
    let _ = std::fs::remove_file(&output_path);
    std::fs::write(
        &script_path,
        "#!/bin/sh\nsleep 60\nprintf cancelled-proof > INTERRUPT_PROOF.txt\n",
    )
    .expect("write interrupt_test.sh");
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;

        let mut permissions = std::fs::metadata(&script_path)
            .expect("stat interrupt_test.sh")
            .permissions();
        permissions.set_mode(0o755);
        std::fs::set_permissions(&script_path, permissions).expect("chmod interrupt_test.sh");
    }

    let prompt = match backend_kind {
        BackendKind::Claude => {
            "Use the Bash tool exactly once to execute exactly `./interrupt_test.sh` in the current working directory. Start the command immediately. Do not use any other tools."
        }
        BackendKind::Codex => {
            "Immediately run the test harness `./interrupt_test.sh` in the current working directory using your command execution capability. Start it before any explanation, do not ask for confirmation, and do not use any other tools."
        }
        BackendKind::Antigravity => {
            "Execute exactly `./interrupt_test.sh` in the current working directory. Start the command immediately. Do not use any other tools."
        }
        BackendKind::Acp => {
            "Use the available tools to run the test harness `./interrupt_test.sh` in the current working directory immediately. Do not ask for clarification, and do not only describe a plan."
        }
        BackendKind::Tycode => {
            "Use the run_build_test tool exactly once to run the test harness `./interrupt_test.sh` in the current working directory. Start the test immediately. Do not use any other tools."
        }
        BackendKind::Hermes => {
            "Run the test harness `./interrupt_test.sh` in the current working directory immediately. Do not ask for clarification, and do not only describe a plan."
        }
    };
    let agent_stream = spawn_agent_via_protocol(
        &mut fixture.client,
        workspace_roots,
        backend_kind,
        "interrupt-long-command",
        prompt,
    )
    .await;

    let started_at = Instant::now();
    let mut got_user_message_echo = false;
    let tool_call_id = loop {
        let context = format!("{backend_kind:?} long-running ToolRequest");
        let env = expect_next_event(&mut fixture.client, &context).await;
        if env.kind != FrameKind::ChatEvent || env.stream != agent_stream {
            continue;
        }
        let event: ChatEvent = env.parse_payload().expect("parse ChatEvent");
        match event {
            ChatEvent::MessageAdded(message) => {
                if matches!(message.sender, MessageSender::User) && message.content == prompt {
                    got_user_message_echo = true;
                }
            }
            ChatEvent::ToolRequest(request) if got_user_message_echo => {
                let ToolRequestType::RunCommand { command, .. } = &request.tool_type else {
                    continue;
                };
                if command.contains("interrupt_test.sh") {
                    break request.tool_call_id;
                }
            }
            _ => {}
        }
    };
    tokio::time::sleep(Duration::from_secs(1)).await;
    fixture
        .client
        .interrupt(&agent_stream)
        .await
        .expect("interrupt failed");

    let mut saw_operation_cancelled = false;
    let mut saw_typing_stopped = false;
    let mut saw_matching_tool_completion = false;
    let cancel_deadline = Instant::now() + Duration::from_secs(20);
    while Instant::now() < cancel_deadline {
        let context = format!("{backend_kind:?} interrupt outcome");
        let env = expect_next_event(&mut fixture.client, &context).await;
        if env.kind != FrameKind::ChatEvent || env.stream != agent_stream {
            continue;
        }
        let event: ChatEvent = env.parse_payload().expect("parse ChatEvent");
        match event {
            ChatEvent::OperationCancelled(_) => {
                saw_operation_cancelled = true;
                if saw_typing_stopped {
                    break;
                }
            }
            ChatEvent::TypingStatusChanged(false) => {
                saw_typing_stopped = true;
                if saw_operation_cancelled {
                    break;
                }
            }
            ChatEvent::ToolExecutionCompleted(completion)
                if completion.tool_call_id == tool_call_id =>
            {
                saw_matching_tool_completion = true;
            }
            _ => {}
        }
    }

    assert!(
        saw_operation_cancelled,
        "expected OperationCancelled for {backend_kind:?} interrupt test"
    );
    assert!(
        saw_typing_stopped,
        "expected TypingStatusChanged(false) for {backend_kind:?} interrupt test"
    );
    assert!(
        started_at.elapsed() < Duration::from_secs(20),
        "interrupt test for {backend_kind:?} took too long: {:?}",
        started_at.elapsed()
    );
    tokio::time::sleep(Duration::from_secs(2)).await;
    assert!(
        !output_path.exists(),
        "expected interrupted command to avoid writing {:?} for {:?}; saw_tool_completion={}",
        output_path,
        backend_kind,
        saw_matching_tool_completion
    );

    let follow_up_prompt = "After the cancelled turn, reply with a short acknowledgement that you are ready for the next task.";
    fixture
        .client
        .send_message(&agent_stream, follow_up_prompt.to_string())
        .await
        .expect("send follow-up message after interrupt");
    let follow_up_turn =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &agent_stream, follow_up_prompt)
            .await;
    assert!(
        !follow_up_turn.final_text.trim().is_empty(),
        "expected non-empty follow-up response after interrupt for {backend_kind:?}"
    );
}

async fn expect_stream_idle_after_interrupt(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    context: &str,
) {
    let mut cancellations = 0;
    let mut idle = 0;
    let mut trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(30), async {
        while cancellations == 0 || idle == 0 {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind == FrameKind::AgentError && envelope.stream == *stream {
                let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                panic!("{context}: {}", error.message);
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            let event = envelope.parse_payload::<ChatEvent>().unwrap();
            trace.push(format!("{event:?}"));
            match event {
                ChatEvent::OperationCancelled(_) => cancellations += 1,
                ChatEvent::TypingStatusChanged(false) => idle += 1,
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context} did not terminate; trace={trace:#?}"));
    assert_eq!(cancellations, 1, "{context}: duplicate cancellation");
    assert_eq!(idle, 1, "{context}: duplicate idle");
}

async fn wait_for_interrupt_phase_idle(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    context: &str,
) {
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind == FrameKind::AgentError && envelope.stream == *stream {
                let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                panic!("{context}: {}", error.message);
            }
            if envelope.kind == FrameKind::ChatEvent
                && envelope.stream == *stream
                && matches!(
                    envelope.parse_payload::<ChatEvent>().unwrap(),
                    ChatEvent::TypingStatusChanged(false)
                )
            {
                break;
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context} did not reach idle"));
}

async fn interrupt_during_model_stream(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    prompt: &str,
    context: &str,
) {
    fixture
        .client
        .send_message(stream, prompt.to_owned())
        .await
        .unwrap();
    let mut echoed = false;
    let mut started = false;
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind == FrameKind::AgentError && envelope.stream == *stream {
                let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                panic!("{context}: {}", error.message);
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            let event = envelope.parse_payload::<ChatEvent>().unwrap();
            eprintln!("MODEL STREAM INTERRUPT EVENT {context} {event:?}");
            match event {
                ChatEvent::MessageAdded(message)
                    if matches!(message.sender, MessageSender::User)
                        && message.content == prompt =>
                {
                    echoed = true
                }
                ChatEvent::StreamStart(_) if echoed => started = true,
                ChatEvent::StreamDelta(delta) if started && !delta.text.is_empty() => break,
                ChatEvent::TypingStatusChanged(false) => {
                    panic!("{context} completed before a visible model delta")
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context} did not produce a model delta"));
    fixture.client.interrupt(stream).await.unwrap();
    fixture.client.interrupt(stream).await.unwrap();
    expect_stream_idle_after_interrupt(fixture, stream, context).await;
}

async fn assert_interrupt_phase_contract_matrix(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let ready_prompt = "Reply exactly INTERRUPT_PHASE_READY.";
    let roots = fixture.workspace_roots();
    let (stream, start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "interrupt-phase-contract",
        ready_prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let ready =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, ready_prompt).await;
    assert!(ready.final_text.contains("INTERRUPT_PHASE_READY"));
    wait_for_interrupt_phase_idle(&mut fixture, &stream, "interrupt readiness").await;

    let pre_acceptance = "Write a very long explanation of interrupt semantics. Do not use tools.";
    fixture
        .client
        .send_message(&stream, pre_acceptance.to_owned())
        .await
        .unwrap();
    fixture.client.interrupt(&stream).await.unwrap();
    expect_stream_idle_after_interrupt(&mut fixture, &stream, "pre-acceptance interrupt").await;

    interrupt_during_model_stream(
        &mut fixture,
        &stream,
        "Without using tools, write at least 1000 words, beginning exactly MODEL_STREAM_STARTED.",
        "model-stream interrupt",
    )
    .await;

    let terminal_prompt = "Reply exactly INTERRUPT_TERMINAL_COMPLETE.";
    fixture
        .client
        .send_message(&stream, terminal_prompt.to_owned())
        .await
        .unwrap();
    let terminal =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, terminal_prompt).await;
    assert!(terminal.final_text.contains("INTERRUPT_TERMINAL_COMPLETE"));
    fixture.client.interrupt(&stream).await.unwrap();
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind == FrameKind::AgentError && envelope.stream == stream {
                let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                panic!("post-terminal interrupt: {}", error.message);
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::OperationCancelled(cancelled) => panic!(
                    "interrupt after terminal cancelled an already completed turn: {}",
                    cancelled.message
                ),
                ChatEvent::TypingStatusChanged(false) => break,
                _ => {}
            }
        }
    })
    .await
    .expect("post-terminal interrupt did not preserve the normal idle boundary");
    let quiet = tokio::time::timeout(Duration::from_secs(3), async {
        loop {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::OperationCancelled(_) | ChatEvent::TypingStatusChanged(true) => {
                    return true;
                }
                _ => {}
            }
        }
    })
    .await;
    assert!(
        quiet.is_err(),
        "idle interrupt emitted a new terminal lifecycle"
    );

    let mut reconnected = fixture.connect().await;
    reconnected.inherit_live_trace_from(&fixture.client);
    std::mem::swap(&mut fixture.client, &mut reconnected);
    drop(reconnected);
    let reconnected_stream = tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind != FrameKind::HostBootstrap {
                continue;
            }
            let bootstrap: HostBootstrapPayload = envelope.parse_payload().unwrap();
            break bootstrap
                .agents
                .into_iter()
                .find(|agent| agent.session_id.as_ref() == start.session_id.as_ref())
                .expect("reconnect omitted interrupted session")
                .instance_stream;
        }
    })
    .await
    .expect("interrupt reconnect timed out");
    let follow_up = "Reply exactly INTERRUPT_RECONNECT_OK.";
    fixture
        .client
        .send_message(&reconnected_stream, follow_up.to_owned())
        .await
        .unwrap();
    let response =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &reconnected_stream, follow_up)
            .await;
    assert!(response.final_text.contains("INTERRUPT_RECONNECT_OK"));
}

