async fn assert_interrupt_follow_up_survives_request_timeout(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
) {
    let script_path = fixture
        .workspace_dir
        .path()
        .join("interrupt_timeout_test.sh");
    std::fs::write(&script_path, "#!/bin/sh\nsleep 60\n").expect("write interrupt_timeout_test.sh");
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;

        let mut permissions = std::fs::metadata(&script_path)
            .expect("stat interrupt_timeout_test.sh")
            .permissions();
        permissions.set_mode(0o755);
        std::fs::set_permissions(&script_path, permissions)
            .expect("chmod interrupt_timeout_test.sh");
    }

    let initial_prompt = match backend_kind {
        BackendKind::Claude => {
            "Use the Bash tool exactly once to execute exactly `./interrupt_timeout_test.sh`. Start immediately and do not use another tool."
        }
        BackendKind::Codex => {
            "Immediately execute exactly `./interrupt_timeout_test.sh` in the current working directory. Do not explain first and do not use another tool."
        }
        BackendKind::Antigravity => {
            "Execute exactly `./interrupt_timeout_test.sh` in the current working directory. Start the command immediately. Do not use any other tools."
        }
        BackendKind::Acp => {
            "Immediately run exactly `./interrupt_timeout_test.sh` using the available command tool. Do not only describe it."
        }
        BackendKind::Tycode => {
            "Use the bash tool exactly once to run `./interrupt_timeout_test.sh` in the current working directory. Start the command immediately. Do not use any other tools."
        }
        BackendKind::Hermes => {
            "Immediately run exactly `./interrupt_timeout_test.sh` in the current working directory. Do not only describe it."
        }
    };
    let workspace_roots = fixture.workspace_roots();
    let mut started_stream = None;
    let mut failed_attempts = Vec::new();
    for attempt in 1..=3 {
        let candidate = spawn_agent_via_protocol(
            &mut fixture.client,
            workspace_roots.clone(),
            backend_kind,
            &format!("interrupt-request-timeout-{attempt}"),
            "Reply exactly INTERRUPT_TEST_READY.",
        )
        .await;
        let readiness_prompt = "Reply exactly INTERRUPT_TEST_READY.";
        let readiness = expect_assistant_turn_after_user_echo(
            &mut fixture.client,
            &candidate,
            readiness_prompt,
        )
        .await;
        assert!(
            readiness.final_text.contains("INTERRUPT_TEST_READY"),
            "{backend_kind:?} did not complete interrupt test readiness: {:?}",
            readiness.final_text
        );
        loop {
            let envelope = expect_next_event(&mut fixture.client, "interrupt readiness idle").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != candidate {
                continue;
            }
            let event: ChatEvent = envelope
                .parse_payload()
                .expect("parse interrupt readiness idle event");
            if matches!(event, ChatEvent::TypingStatusChanged(false)) {
                break;
            }
        }
        fixture
            .client
            .send_message(&candidate, initial_prompt.to_owned())
            .await
            .expect("send long-running interrupt prompt");
        let mut pre_interrupt_text = String::new();
        let mut attempt_trace = Vec::new();
        loop {
            let envelope = expect_next_event(&mut fixture.client, "long-running ToolRequest").await;
            if envelope.kind == FrameKind::AgentError && envelope.stream == candidate {
                let error: protocol::AgentErrorPayload = envelope
                    .parse_payload()
                    .expect("parse pre-interrupt AgentError");
                panic!("backend failed before interrupt: {}", error.message);
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != candidate {
                continue;
            }
            let event: ChatEvent = envelope
                .parse_payload()
                .expect("parse pre-interrupt ChatEvent");
            attempt_trace.push(format!("{event:?}"));
            match event {
                ChatEvent::ToolRequest(ToolRequest {
                    tool_type: ToolRequestType::RunCommand { ref command, .. },
                    ..
                }) if command.contains("interrupt_timeout_test.sh") => {
                    started_stream = Some(candidate);
                    break;
                }
                ChatEvent::StreamDelta(delta) => pre_interrupt_text.push_str(&delta.text),
                ChatEvent::StreamEnd(end) if !end.message.content.trim().is_empty() => {
                    pre_interrupt_text = end.message.content;
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("backend failed before starting interrupt command: {content}"),
                ChatEvent::TypingStatusChanged(false) => {
                    failed_attempts.push((pre_interrupt_text, attempt_trace));
                    break;
                }
                _ => {}
            }
        }
        if started_stream.is_some() {
            break;
        }
    }
    let stream = started_stream.unwrap_or_else(|| {
        panic!(
            "backend became idle before starting interrupt command for {backend_kind:?} in three attempts: {failed_attempts:?}"
        )
    });

    let queued_prompt = "The running command is cancelled. Reply exactly INTERRUPT_FOLLOW_UP_OK.";
    fixture
        .client
        .send_message(&stream, queued_prompt.to_owned())
        .await
        .expect("queue follow-up during long-running command");
    let queued_id = loop {
        let envelope =
            expect_next_unfiltered_event(&mut fixture.client, "queued follow-up snapshot").await;
        if envelope.kind == FrameKind::AgentError && envelope.stream == stream {
            let error: protocol::AgentErrorPayload = envelope
                .parse_payload()
                .expect("parse queued follow-up AgentError");
            panic!(
                "backend failed while queueing interrupt follow-up: {}",
                error.message
            );
        }
        if envelope.kind != FrameKind::QueuedMessages || envelope.stream != stream {
            continue;
        }
        let queued: QueuedMessagesPayload = envelope
            .parse_payload()
            .expect("parse QueuedMessages after follow-up");
        if let Some(message) = queued
            .messages
            .into_iter()
            .find(|message| message.message == queued_prompt)
        {
            break message.id;
        }
    };
    fixture
        .client
        .send_queued_message_now(&stream, SendQueuedMessageNowPayload { id: queued_id })
        .await
        .expect("interrupt with queued follow-up");
    fixture
        .client
        .interrupt(&stream)
        .await
        .expect("repeat interrupt while cancellation is in flight");

    let quiet_result = tokio::time::timeout(Duration::from_secs(50), async {
        loop {
            let envelope = fixture
                .client
                .next_event()
                .await
                .expect("read backend events after interrupt")
                .expect("backend connection closed after interrupt");
            if envelope.stream != stream {
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                let error: protocol::AgentErrorPayload = envelope
                    .parse_payload()
                    .expect("parse delayed interrupt AgentError");
                panic!(
                    "backend failed after an apparently successful interrupt: {}",
                    error.message
                );
            }
            assert_ne!(
                envelope.kind,
                FrameKind::AgentClosed,
                "backend closed after an apparently successful interrupt"
            );
        }
    })
    .await;
    assert!(
        quiet_result.is_err(),
        "post-interrupt health observation ended unexpectedly"
    );

    let health_prompt = "Reply exactly INTERRUPT_SESSION_STILL_HEALTHY.";
    fixture
        .client
        .send_message(&stream, health_prompt.to_owned())
        .await
        .expect("send health check after interrupt timeout horizon");
    let health_turn =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, health_prompt).await;
    assert!(
        health_turn
            .final_text
            .contains("INTERRUPT_SESSION_STILL_HEALTHY"),
        "backend stopped accepting work after interrupt for {backend_kind:?}: {:?}",
        health_turn.final_text
    );
}

async fn assert_interrupt_allows_follow_up_during_background_work(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
) {
    let proof_path = fixture
        .workspace_dir
        .path()
        .join("BACKGROUND_INTERRUPT_PROOF.txt");
    let workspace_roots = fixture.workspace_roots();
    let prompt = match backend_kind {
        BackendKind::Claude => {
            "Use the Bash tool exactly once to run `sleep 120; printf SHOULD_NOT_EXIST > BACKGROUND_INTERRUPT_PROOF.txt` with run_in_background=true. Do not call TaskOutput, TaskStop, or any other tool. After Bash reports that the command is running in the background, end the foreground turn by replying exactly BACKGROUND_INTERRUPT_READY; do not wait for its result."
        }
        BackendKind::Codex => {
            "Use command execution exactly once to run `sleep 120; printf SHOULD_NOT_EXIST > BACKGROUND_INTERRUPT_PROOF.txt`, setting the tool's `yield_time_ms` argument to `1000`. Do not add `&`, and do not call write_stdin, wait, poll, or any other tool afterward. As soon as the tool reports a running session, end the foreground turn by replying exactly BACKGROUND_INTERRUPT_READY; do not wait for its result."
        }
        BackendKind::Hermes => {
            "Use the terminal tool exactly once with background=true to run `sleep 120; printf SHOULD_NOT_EXIST > BACKGROUND_INTERRUPT_PROOF.txt`. Do not call process, wait, poll, or any other tool afterward. As soon as the tool reports a background process, end the foreground turn by replying exactly BACKGROUND_INTERRUPT_READY; do not wait for its result."
        }
        BackendKind::Acp => {
            "Run `sleep 120; printf SHOULD_NOT_EXIST > BACKGROUND_INTERRUPT_PROOF.txt` as background work using the command tool exactly once. Do not wait or poll. End the foreground turn by replying exactly BACKGROUND_INTERRUPT_READY."
        }
        BackendKind::Tycode => {
            "Run `sleep 120; printf SHOULD_NOT_EXIST > BACKGROUND_INTERRUPT_PROOF.txt` as background work using the build/test tool exactly once. Do not wait or poll. End the foreground turn by replying exactly BACKGROUND_INTERRUPT_READY."
        }
        BackendKind::Antigravity => {
            "Run `sleep 120; printf SHOULD_NOT_EXIST > BACKGROUND_INTERRUPT_PROOF.txt` as background work using the command tool exactly once. Do not wait or poll. End the foreground turn by replying exactly BACKGROUND_INTERRUPT_READY."
        }
    };
    let stream = spawn_agent_via_protocol_with_options(
        &mut fixture.client,
        workspace_roots,
        backend_kind,
        "interrupt-detached-background-command",
        prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;

    let mut background_tool_call_id = None;
    let mut foreground_ended = false;
    let mut setup_trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = fixture
                .client
                .next_event()
                .await
                .expect("read detached background setup")
                .expect("detached background setup stream closed");
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            let event: ChatEvent = envelope
                .parse_payload()
                .expect("parse detached background setup event");
            setup_trace.push(event.clone());
            match event {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{backend_kind:?} detached background setup failed: {content}"),
                ChatEvent::ToolProgress(progress) => {
                    if background_task_progress(&progress.update).is_some() {
                        background_tool_call_id = Some(progress.tool_call_id);
                    }
                }
                ChatEvent::StreamEnd(end)
                    if background_tool_call_id.is_some()
                        && end.message.tool_calls.is_empty()
                        && end.message.content.contains("BACKGROUND_INTERRUPT_READY") =>
                {
                    foreground_ended = true;
                }
                ChatEvent::TypingStatusChanged(false)
                    if background_tool_call_id.is_some() && !foreground_ended =>
                {
                    panic!("{backend_kind:?} became idle before ending its foreground turn")
                }
                _ => {}
            }
            if background_tool_call_id.is_some() && foreground_ended {
                break;
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "{backend_kind:?} did not enter detached-background-only activity; trace={setup_trace:#?}"
        )
    });

    fixture
        .client
        .interrupt(&stream)
        .await
        .expect("interrupt detached Claude background command");

    let background_tool_call_id = background_tool_call_id.expect("background tool call id");
    let mut saw_idle = false;
    tokio::time::timeout(Duration::from_secs(10), async {
        loop {
            let envelope = fixture
                .client
                .next_event()
                .await
                .expect("read detached background cancellation")
                .expect("backend stream closed during detached background cancellation");
            if envelope.kind == FrameKind::AgentError && envelope.stream == stream {
                let error: protocol::AgentErrorPayload =
                    envelope.parse_payload().expect("parse cancellation AgentError");
                panic!(
                    "{backend_kind:?} detached background cancellation failed: {}",
                    error.message
                );
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            let event: ChatEvent = envelope
                .parse_payload()
                .expect("parse detached background cancellation event");
            match event {
                ChatEvent::ToolProgress(progress)
                    if progress.tool_call_id == background_tool_call_id =>
                {
                    assert!(
                        background_task_progress(&progress.update).is_some(),
                        "conversation interrupt changed detached {backend_kind:?} background progress family"
                    );
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == background_tool_call_id =>
                {
                    panic!(
                        "conversation interrupt terminated detached {backend_kind:?} background work: {completion:?}"
                    );
                }
                ChatEvent::TypingStatusChanged(false) => saw_idle = true,
                _ => {}
            }
            if saw_idle {
                break;
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "{backend_kind:?} did not make the conversation interactive within 10 seconds while detached background work remained active: idle={saw_idle}"
        )
    });

    tokio::time::sleep(Duration::from_secs(2)).await;
    assert!(
        !proof_path.exists(),
        "detached {backend_kind:?} background command completed before the follow-up"
    );

    let foreground_prompt = match backend_kind {
        BackendKind::Claude => {
            "Use Bash exactly once in the foreground to run `until test -f FOREGROUND_INTERRUPT_RELEASE; do sleep 2; done`. Do not set run_in_background and do not use another tool."
        }
        BackendKind::Codex => {
            "Use command execution exactly once in the foreground to run `sleep 120`. Do not set yield_time_ms, do not background it, and do not use another tool."
        }
        BackendKind::Hermes => {
            "Use the terminal tool exactly once in the foreground to run `sleep 120`. Do not set background=true and do not use another tool."
        }
        BackendKind::Acp | BackendKind::Tycode | BackendKind::Antigravity => {
            "Use the command tool exactly once in the foreground to run `sleep 120`. Do not background it and do not use another tool."
        }
    };
    fixture
        .client
        .send_message(&stream, foreground_prompt.to_owned())
        .await
        .expect("start foreground turn over detached background work");
    let foreground_tool_call_id = tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(
                &mut fixture.client,
                "foreground command over detached background work",
            )
            .await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolRequest(ToolRequest {
                    tool_call_id,
                    tool_type: ToolRequestType::RunCommand { command, .. },
                    ..
                }) if command.contains("FOREGROUND_INTERRUPT_RELEASE")
                    || command.contains("sleep 120") =>
                {
                    break tool_call_id;
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{backend_kind:?} foreground-over-background setup failed: {content}"),
                _ => {}
            }
        }
    })
    .await
    .expect("foreground command did not start while detached background work remained");
    fixture
        .client
        .interrupt(&stream)
        .await
        .expect("interrupt active foreground turn over detached background work");
    expect_exact_cancelled_tool_request(
        fixture,
        &stream,
        &foreground_tool_call_id,
        "active foreground interrupt over detached background work",
    )
    .await;
    assert_background_remains_running(
        fixture,
        &stream,
        &HashSet::from([background_tool_call_id.clone()]),
        "foreground interrupt terminated detached background work",
    )
    .await;

    let follow_up = "Reply exactly BACKGROUND_INTERRUPT_FOLLOW_UP_OK.";
    fixture
        .client
        .send_message(&stream, follow_up.to_owned())
        .await
        .expect("send follow-up after detached background cancellation");
    let response =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, follow_up).await;
    assert!(
        response
            .final_text
            .contains("BACKGROUND_INTERRUPT_FOLLOW_UP_OK"),
        "{backend_kind:?} did not recover after detached background cancellation: {:?}",
        response.final_text
    );
}

async fn assert_user_question_answer_during_background_work(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
) {
    let prompt = match backend_kind {
        BackendKind::Claude => {
            "Use Bash exactly once with run_in_background=true to run `sleep 600`. Do not wait for or stop that background command. Once Bash reports it is running, use AskUserQuestion exactly once to ask `What verification token should I use?` with the options BLUE and GREEN. Wait for my answer. After I answer, reply exactly ASK_BACKGROUND_ANSWER_OK_<answer>, replacing <answer> with my answer, and do not use another tool."
        }
        BackendKind::Codex => {
            "Start `sleep 600` as background command work, without polling it. Then use the native user-question tool exactly once to ask `What verification token should I use?` with options BLUE and GREEN. Wait for my answer, then reply exactly ASK_BACKGROUND_ANSWER_OK_<answer>."
        }
        BackendKind::Acp => {
            "Start `sleep 600` as background command work, without polling it. Then use the native user-question tool exactly once to ask `What verification token should I use?` with options BLUE and GREEN. Wait for my answer, then reply exactly ASK_BACKGROUND_ANSWER_OK_<answer>."
        }
        BackendKind::Hermes => {
            "Start `sleep 600` as background command work, without polling it. Then use the native user-question tool exactly once to ask `What verification token should I use?` with options BLUE and GREEN. Wait for my answer, then reply exactly ASK_BACKGROUND_ANSWER_OK_<answer>."
        }
        BackendKind::Tycode => {
            "Start `sleep 600` as background command work, without polling it. Then use the native user-question tool exactly once to ask `What verification token should I use?` with options BLUE and GREEN. Wait for my answer, then reply exactly ASK_BACKGROUND_ANSWER_OK_<answer>."
        }
        BackendKind::Antigravity => {
            "Start `sleep 600` as background command work, without polling it. Then use the native user-question tool exactly once to ask `What verification token should I use?` with options BLUE and GREEN. Wait for my answer, then reply exactly ASK_BACKGROUND_ANSWER_OK_<answer>."
        }
    };
    let workspace_roots = fixture.workspace_roots();
    let stream = spawn_agent_via_protocol_with_options(
        &mut fixture.client,
        workspace_roots,
        backend_kind,
        "question-during-background-work",
        prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;

    let mut background_tool_call_id = None;
    let mut question_tool_call_id = None;
    let mut question_waiting = false;
    let mut setup_trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        while !question_waiting {
            let envelope = fixture
                .client
                .next_event()
                .await
                .expect("read question setup events")
                .expect("question setup connection closed");
            if envelope.stream != stream {
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                let error: protocol::AgentErrorPayload =
                    envelope.parse_payload().expect("parse question AgentError");
                panic!("{backend_kind:?} question setup failed: {}", error.message);
            }
            if envelope.kind != FrameKind::ChatEvent {
                continue;
            }
            let event: ChatEvent = envelope.parse_payload().expect("parse question setup event");
            setup_trace.push(format!("{event:?}"));
            match event {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{backend_kind:?} question setup failed: {content}"),
                ChatEvent::ToolProgress(progress) => {
                    if background_task_progress(&progress.update).is_some() {
                        background_tool_call_id = Some(progress.tool_call_id);
                    }
                }
                ChatEvent::ToolRequest(request)
                    if matches!(request.tool_type, ToolRequestType::AskUserQuestion { .. }) =>
                {
                    assert!(
                        question_tool_call_id.replace(request.tool_call_id).is_none(),
                        "{backend_kind:?} emitted duplicate AskUserQuestion requests"
                    );
                }
                ChatEvent::TypingStatusChanged(false)
                    if background_tool_call_id.is_some()
                        && question_tool_call_id.is_some() =>
                {
                    question_waiting = true;
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "{backend_kind:?} did not reach a user-question rendezvous while background work was running; trace:\n{}",
            setup_trace.join("\n")
        )
    });

    let question_tool_call_id = question_tool_call_id.expect("question tool call id");
    let background_tool_call_id = background_tool_call_id.expect("background tool call id");
    let answer = "BLUE";
    send_user_question_answer(fixture, &stream, &question_tool_call_id, answer).await;
    let mut answer_echoes = 0usize;
    let mut answer_completions = 0usize;
    let mut saw_continuation = false;
    let mut saw_idle_after_answer = false;
    let mut answer_trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        while !(saw_continuation && saw_idle_after_answer) {
            let envelope = fixture
                .client
                .next_event()
                .await
                .expect("read question answer events")
                .expect("question answer connection closed");
            if envelope.stream != stream {
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                let error: protocol::AgentErrorPayload =
                    envelope.parse_payload().expect("parse answer AgentError");
                panic!("{backend_kind:?} rejected question answer: {}", error.message);
            }
            if envelope.kind != FrameKind::ChatEvent {
                continue;
            }
            let event: ChatEvent = envelope.parse_payload().expect("parse question answer event");
            answer_trace.push(format!("{event:?}"));
            match event {
                ChatEvent::MessageAdded(message)
                    if matches!(message.sender, MessageSender::User)
                        && message.content == answer =>
                {
                    answer_echoes += 1;
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{backend_kind:?} question answer failed: {content}"),
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == question_tool_call_id =>
                {
                    assert!(completion.success(), "question completion failed: {completion:?}");
                    let ToolExecutionResult::Other { result: normalized } =
                        &completion.tool_result()
                    else {
                        panic!(
                            "question answer did not carry its normalized result: {completion:?}"
                        )
                    };
                    assert_eq!(
                        normalized.get("answer").and_then(Value::as_str),
                        Some(answer),
                        "question completion did not preserve the admitted answer"
                    );
                    answer_completions += 1;
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == background_tool_call_id =>
                {
                    panic!(
                        "{backend_kind:?} background task ended while delivering the question answer: {completion:?}"
                    );
                }
                ChatEvent::ToolProgress(progress)
                    if progress.tool_call_id == background_tool_call_id =>
                {
                    assert!(
                        background_task_progress(&progress.update).is_some(),
                        "background task changed progress family while the foreground question was answered"
                    );
                }
                ChatEvent::StreamEnd(end)
                    if end.message.content.contains("ASK_BACKGROUND_ANSWER_OK_BLUE") =>
                {
                    saw_continuation = true;
                }
                ChatEvent::TypingStatusChanged(false) if answer_completions == 1 => {
                    saw_idle_after_answer = true;
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "{backend_kind:?} did not consume and continue from the question answer while background work remained active; trace:\n{}",
            answer_trace.join("\n")
        )
    });
    assert_eq!(
        answer_echoes, 1,
        "question answer was not echoed exactly once"
    );
    assert_eq!(
        answer_completions, 1,
        "question request did not complete exactly once"
    );
}

async fn reach_user_question_wait(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
    input: ToolInputVariant,
) -> (
    StreamPath,
    SessionId,
    protocol::AgentId,
    String,
    HashSet<String>,
) {
    let activity_prompt = ambient_setup_instruction(backend_kind, activity, "QUESTION_BACKGROUND");
    let question_prompt = match (backend_kind, input) {
        (BackendKind::Claude, ToolInputVariant::AskSingleChoice) => {
            "Use AskUserQuestion exactly once to ask one single-select question with the options BLUE and GREEN"
        }
        (BackendKind::Claude, ToolInputVariant::AskMultipleChoice) => {
            "Use AskUserQuestion exactly once to ask one multi-select question with header Verification and the options BLUE and GREEN"
        }
        (BackendKind::Claude, ToolInputVariant::AskFreeText) => {
            "Use AskUserQuestion exactly once to ask one question with exactly two options whose labels are TYDE_FREE_TEXT and Other, in that order. This sentinel pair presents as free text to the user"
        }
        (BackendKind::Claude, ToolInputVariant::AskMultipleQuestions) => {
            "Use AskUserQuestion exactly once to ask two questions in that one call: first a single-select question with options BLUE and GREEN, then a question with exactly two options whose labels are TYDE_FREE_TEXT and Other, in that order. This sentinel pair presents as free text to the user"
        }
        (_, ToolInputVariant::AskSingleChoice) => {
            "Use the native user-question tool exactly once to ask one single-select question with the options BLUE and GREEN"
        }
        (_, ToolInputVariant::AskMultipleChoice) => {
            "Use the native user-question tool exactly once to ask one multi-select question with header Verification and the options BLUE and GREEN"
        }
        (_, ToolInputVariant::AskFreeText) => {
            "Use the native user-question tool exactly once to ask one free-text question with no options"
        }
        (_, ToolInputVariant::AskMultipleQuestions) => {
            "Use the native user-question tool exactly once to ask two questions in that one call: first a single-select question with options BLUE and GREEN, then a free-text question with no options"
        }
        _ => panic!("non-question input passed to question runner: {input:?}"),
    };
    let sequence_prompt = if activity == ActivityCondition::ForegroundOnly {
        format!("{question_prompt} immediately")
    } else if backend_kind == BackendKind::Claude {
        format!(
            "Each Agent or Bash tool's successful background dispatch result means that item is Running. Immediately after every required background dispatch returns successfully, in this same foreground turn, {question_prompt}. Do not end the turn between the background dispatches and AskUserQuestion"
        )
    } else {
        format!("After every required background item reports Running, {question_prompt}")
    };
    let question_text = if input == ToolInputVariant::AskMultipleQuestions {
        "Use `What verification token should I use?` as the first question and `What second token should I use?` as the second question."
    } else {
        "Ask only `What verification token should I use?`; do not add another question."
    };
    let continuation = if input == ToolInputVariant::AskMultipleChoice {
        "After I answer, if my response includes an image, inspect it visually and reply exactly USER_QUESTION_ANSWER_OK_BLUE_RED_IMAGE when it is solid red. Otherwise reply exactly USER_QUESTION_MULTISELECT_OK if the answer contains both BLUE and GREEN, or USER_QUESTION_ANSWER_OK_BLUE for any other answer."
    } else {
        "After I answer, if my response includes an image, inspect it visually and reply exactly USER_QUESTION_ANSWER_OK_BLUE_RED_IMAGE when it is solid red. If it has no image, reply exactly USER_QUESTION_ANSWER_OK_BLUE."
    };
    let prompt = format!(
        "{activity_prompt} {sequence_prompt}. {question_text} Wait for my answer. {continuation}"
    );
    let roots = fixture.workspace_roots();
    let (stream, start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "user-question-lifecycle",
        &prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let mut setup_trace = Vec::new();
    let (tool_call_id, running_background_ids) = tokio::time::timeout(Duration::from_secs(120), async {
        let mut tool_call_id = None;
        let mut ambient = AmbientWorkObservation::default();
        let mut provider_idle = false;
        loop {
            let envelope = fixture
                .client
                .next_event()
                .await
                .expect("read user-question lifecycle")
                .expect("user-question lifecycle connection closed");
            if envelope.stream != stream {
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                let error: protocol::AgentErrorPayload = envelope
                    .parse_payload()
                    .expect("parse user-question AgentError");
                panic!(
                    "{backend_kind:?} user-question setup failed: {}",
                    error.message
                );
            }
            if envelope.kind != FrameKind::ChatEvent {
                continue;
            }
            let event = envelope
                .clone()
                .parse_payload::<ChatEvent>()
                .expect("parse user-question event");
            setup_trace.push(format!("{event:?}"));
            match event {
                ChatEvent::ToolRequest(request) => {
                    let ToolRequestType::AskUserQuestion { questions } = request.tool_type else {
                        continue;
                    };
                    assert_user_question_request_shape(&questions, input);
                    assert!(tool_call_id.replace(request.tool_call_id).is_none());
                }
                ChatEvent::ToolProgress(progress) => ambient.observe_running(&progress),
                ChatEvent::ToolExecutionCompleted(completion)
                    if tool_call_id.as_deref() == Some(completion.tool_call_id.as_str()) =>
                {
                    panic!(
                        "{backend_kind:?} completed AskUserQuestion before receiving an answer: {completion:?}"
                    )
                }
                ChatEvent::TypingStatusChanged(false) if tool_call_id.is_some() => {
                    provider_idle = true;
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{backend_kind:?} user-question setup failed: {content}"),
                _ => {}
            }
            if provider_idle
                && let Some(tool_call_id) = tool_call_id.clone()
                && ambient.matches(activity)
            {
                ambient.assert_exact(activity, "user question provider acceptance");
                break (tool_call_id, ambient.ids());
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "{backend_kind:?} did not wait for a user-question answer; trace:\n{}",
            setup_trace.join("\n")
        )
    });
    (
        stream,
        start.session_id.expect("user-question session id"),
        start.agent_id,
        tool_call_id,
        running_background_ids,
    )
}

async fn assert_user_question_waits_for_answer(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
    input: ToolInputVariant,
) -> Vec<ConformanceCoverageCell> {
    let (stream, _, _, _, background_ids) =
        reach_user_question_wait(fixture, backend_kind, activity, input).await;
    let stimulus = ContractStimulus::TimeoutExpires;
    ambient_before_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "question timeout before",
    )
    .await;
    if background_terminal_during_stimulus(activity) {
        tokio::time::sleep(Duration::from_secs(2)).await;
        ambient_during_stimulus(
            fixture,
            &stream,
            &background_ids,
            activity,
            stimulus,
            "question timeout during",
        )
        .await;
    }
    let unexpected = tokio::time::timeout(Duration::from_secs(5), async {
        loop {
            let envelope = fixture
                .client
                .next_event()
                .await
                .expect("observe pending user question")
                .expect("connection closed while awaiting user answer");
            if envelope.stream == stream
                && matches!(
                    envelope.kind,
                    FrameKind::AgentClosed | FrameKind::AgentError
                )
            {
                break envelope;
            }
            if envelope.kind == FrameKind::ChatEvent && envelope.stream == stream {
                match envelope
                    .parse_payload::<ChatEvent>()
                    .expect("parse pending question")
                {
                    ChatEvent::ToolExecutionCompleted(_)
                    | ChatEvent::TypingStatusChanged(true)
                    | ChatEvent::StreamStart(_) => break envelope,
                    _ => {}
                }
            }
        }
    })
    .await;
    assert!(
        unexpected.is_err(),
        "{backend_kind:?} advanced a user question without an answer: {unexpected:?}"
    );
    ambient_after_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "question timeout after",
    )
    .await;
    fixture
        .client
        .close_agent(&stream)
        .await
        .expect("close waiting user-question agent");
    vec![
        observed_cell(
            SpecialToolContract::AskUserQuestion,
            input,
            ToolResultVariant::Pending,
            activity,
            ContractState::Requested,
            ContractStimulus::ProviderAccepts,
            ContractOutcome::WaitingForUser,
        ),
        observed_cell(
            SpecialToolContract::AskUserQuestion,
            input,
            ToolResultVariant::Pending,
            activity,
            ContractState::WaitingForUser,
            ContractStimulus::TimeoutExpires,
            ContractOutcome::RemainsWaiting,
        ),
    ]
}

