async fn assert_user_question_fails_on_backend_transport_close(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
    input: ToolInputVariant,
) -> Vec<ConformanceCoverageCell> {
    let (stream, _, agent_id, tool_call_id, background_ids) =
        reach_user_question_wait(fixture, backend_kind, activity, input).await;
    let stimulus = ContractStimulus::TransportClosed;
    ambient_before_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "question transport ambient work before stimulus",
    )
    .await;
    assert!(
        fixture
            .host
            .force_agent_backend_shutdown_for_conformance(&agent_id)
            .await,
        "{backend_kind:?} backend shutdown injection was not admitted"
    );
    ambient_during_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "question transport ambient work during boundary",
    )
    .await;
    let mut completion_count = 0usize;
    let mut visible_error = false;
    tokio::time::timeout(Duration::from_secs(30), async {
        while !(visible_error && completion_count == 1) {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.stream != stream {
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                assert_eq!(error.code, AgentErrorCode::BackendFailed);
                visible_error = true;
                continue;
            }
            if envelope.kind != FrameKind::ChatEvent {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    assert!(!completion.success());
                    completion_count += 1;
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    ..
                }) => visible_error = true,
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "{backend_kind:?} did not visibly fail a pending question after backend transport close: error={visible_error}, completions={completion_count}"
        )
    });
    vec![observed_cell(
        SpecialToolContract::AskUserQuestion,
        input,
        ToolResultVariant::Pending,
        activity,
        ContractState::WaitingForUser,
        ContractStimulus::TransportClosed,
        ContractOutcome::FailedVisibly,
    )]
}

fn release_question_background_work(fixture: &RealBackendFixture, count: usize) {
    release_question_background_work_for_path(fixture.workspace_dir.path(), count);
}

fn release_question_background_work_for_path(workspace_dir: &Path, count: usize) {
    for index in 1..=count {
        std::fs::write(
            workspace_dir.join(format!("QUESTION_RELEASE_{index}")),
            "release",
        )
        .expect("release question background work");
    }
}

fn background_terminal_before_stimulus(activity: ActivityCondition) -> bool {
    matches!(
        activity,
        ActivityCondition::BackgroundCompletesBeforeStimulus
            | ActivityCondition::BackgroundFailsBeforeStimulus
            | ActivityCondition::BackgroundSubagentCompletesBeforeStimulus
            | ActivityCondition::BackgroundSubagentFailsBeforeStimulus
            | ActivityCondition::MixedBackgroundWorkCompletesBeforeStimulus
            | ActivityCondition::MixedBackgroundWorkFailsBeforeStimulus
    )
}

fn background_terminal_during_stimulus(activity: ActivityCondition) -> bool {
    matches!(
        activity,
        ActivityCondition::BackgroundCompletesDuringStimulus
            | ActivityCondition::BackgroundFailsDuringStimulus
            | ActivityCondition::BackgroundSubagentCompletesDuringStimulus
            | ActivityCondition::BackgroundSubagentFailsDuringStimulus
            | ActivityCondition::MixedBackgroundWorkCompletesDuringStimulus
            | ActivityCondition::MixedBackgroundWorkFailsDuringStimulus
    )
}

fn background_terminal_after_stimulus(activity: ActivityCondition) -> bool {
    matches!(
        activity,
        ActivityCondition::BackgroundCompletesAfterStimulus
            | ActivityCondition::BackgroundFailsAfterStimulus
            | ActivityCondition::BackgroundSubagentCompletesAfterStimulus
            | ActivityCondition::BackgroundSubagentFailsAfterStimulus
            | ActivityCondition::MixedBackgroundWorkCompletesAfterStimulus
            | ActivityCondition::MixedBackgroundWorkFailsAfterStimulus
    )
}

fn expected_background_outcome(activity: ActivityCondition) -> Option<ExpectedBackgroundOutcome> {
    match activity {
        ActivityCondition::BackgroundCompletesBeforeStimulus
        | ActivityCondition::BackgroundCompletesDuringStimulus
        | ActivityCondition::BackgroundCompletesAfterStimulus
        | ActivityCondition::BackgroundSubagentCompletesBeforeStimulus
        | ActivityCondition::BackgroundSubagentCompletesDuringStimulus
        | ActivityCondition::BackgroundSubagentCompletesAfterStimulus
        | ActivityCondition::MixedBackgroundWorkCompletesBeforeStimulus
        | ActivityCondition::MixedBackgroundWorkCompletesDuringStimulus
        | ActivityCondition::MixedBackgroundWorkCompletesAfterStimulus => {
            Some(ExpectedBackgroundOutcome::Succeeded)
        }
        ActivityCondition::BackgroundFailsBeforeStimulus
        | ActivityCondition::BackgroundFailsDuringStimulus
        | ActivityCondition::BackgroundFailsAfterStimulus
        | ActivityCondition::BackgroundSubagentFailsBeforeStimulus
        | ActivityCondition::BackgroundSubagentFailsDuringStimulus
        | ActivityCondition::BackgroundSubagentFailsAfterStimulus
        | ActivityCondition::MixedBackgroundWorkFailsBeforeStimulus
        | ActivityCondition::MixedBackgroundWorkFailsDuringStimulus
        | ActivityCondition::MixedBackgroundWorkFailsAfterStimulus => {
            Some(ExpectedBackgroundOutcome::Failed)
        }
        ActivityCondition::ForegroundOnly
        | ActivityCondition::OneBackgroundTaskRunning
        | ActivityCondition::MultipleBackgroundTasksRunning
        | ActivityCondition::OneBackgroundSubagentRunning
        | ActivityCondition::MultipleBackgroundSubagentsRunning
        | ActivityCondition::MixedBackgroundWorkRunning => None,
    }
}

fn ambient_work_count(activity: ActivityCondition) -> usize {
    match activity {
        ActivityCondition::ForegroundOnly => 0,
        ActivityCondition::MultipleBackgroundTasksRunning
        | ActivityCondition::MultipleBackgroundSubagentsRunning
        | ActivityCondition::MixedBackgroundWorkRunning
        | ActivityCondition::MixedBackgroundWorkCompletesBeforeStimulus
        | ActivityCondition::MixedBackgroundWorkCompletesDuringStimulus
        | ActivityCondition::MixedBackgroundWorkCompletesAfterStimulus
        | ActivityCondition::MixedBackgroundWorkFailsBeforeStimulus
        | ActivityCondition::MixedBackgroundWorkFailsDuringStimulus
        | ActivityCondition::MixedBackgroundWorkFailsAfterStimulus => 2,
        _ => 1,
    }
}

fn ambient_work_fails(activity: ActivityCondition) -> bool {
    matches!(
        activity,
        ActivityCondition::BackgroundFailsBeforeStimulus
            | ActivityCondition::BackgroundFailsDuringStimulus
            | ActivityCondition::BackgroundFailsAfterStimulus
            | ActivityCondition::BackgroundSubagentFailsBeforeStimulus
            | ActivityCondition::BackgroundSubagentFailsDuringStimulus
            | ActivityCondition::BackgroundSubagentFailsAfterStimulus
            | ActivityCondition::MixedBackgroundWorkFailsBeforeStimulus
            | ActivityCondition::MixedBackgroundWorkFailsDuringStimulus
            | ActivityCondition::MixedBackgroundWorkFailsAfterStimulus
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ObservedAmbientWorkKind {
    Command,
    Subagent,
}

#[derive(Default)]
struct AmbientWorkObservation {
    running: HashMap<(String, String), ObservedAmbientWorkKind>,
}

impl AmbientWorkObservation {
    fn observe_running(&mut self, progress: &protocol::ToolProgressData) {
        let observed = match &progress.update {
            protocol::ToolProgressUpdate::SubAgent(subagent) if !subagent.completed => Some((
                ObservedAmbientWorkKind::Subagent,
                subagent.agent_id.0.clone(),
            )),
            // A completed SubAgent snapshot keeps the background execution
            // mode of the running snapshot; it is not a command observation.
            protocol::ToolProgressUpdate::SubAgent(_) => None,
            _ if progress.execution_mode == protocol::ToolExecutionMode::Background => {
                // Codex can yield several command sessions from one model
                // tool invocation, so the session id—not only the enclosing
                // tool-call id—is the observable background-work identity.
                let task_id = match &progress.update {
                    protocol::ToolProgressUpdate::Other { payload } => payload
                        .get("task_id")
                        .and_then(|task_id| {
                            task_id
                                .as_str()
                                .map(str::to_owned)
                                .or_else(|| task_id.as_u64().map(|task_id| task_id.to_string()))
                        })
                        .unwrap_or_else(|| progress.tool_call_id.clone()),
                    _ => progress.tool_call_id.clone(),
                };
                Some((ObservedAmbientWorkKind::Command, task_id))
            }
            _ => None,
        };
        let Some((kind, item_id)) = observed else {
            return;
        };
        let identity = (progress.tool_call_id.clone(), item_id);
        if let Some(previous) = self.running.insert(identity.clone(), kind) {
            assert_eq!(
                previous, kind,
                "ambient work identity changed observable kind: {identity:?}",
            );
        }
    }

    fn assert_exact(&self, activity: ActivityCondition, context: &str) {
        let total = ambient_work_count(activity);
        let (expected_commands, expected_subagents) = match activity.ambient_work_kind() {
            AmbientWorkKind::None => (0, 0),
            AmbientWorkKind::Commands => (total, 0),
            AmbientWorkKind::Subagents => (0, total),
            AmbientWorkKind::Mixed => (1, 1),
        };
        let commands = self
            .running
            .values()
            .filter(|kind| **kind == ObservedAmbientWorkKind::Command)
            .count();
        let subagents = self
            .running
            .values()
            .filter(|kind| **kind == ObservedAmbientWorkKind::Subagent)
            .count();
        assert_eq!(
            (commands, subagents),
            (expected_commands, expected_subagents),
            "{context}: observed the wrong ambient work-kind mix"
        );
        assert_eq!(
            self.running.len(),
            total,
            "{context}: observed the wrong number of distinct ambient items"
        );
    }

    fn matches(&self, activity: ActivityCondition) -> bool {
        let total = ambient_work_count(activity);
        let commands = self
            .running
            .values()
            .filter(|kind| **kind == ObservedAmbientWorkKind::Command)
            .count();
        let subagents = self
            .running
            .values()
            .filter(|kind| **kind == ObservedAmbientWorkKind::Subagent)
            .count();
        let expected = match activity.ambient_work_kind() {
            AmbientWorkKind::None => (0, 0),
            AmbientWorkKind::Commands => (total, 0),
            AmbientWorkKind::Subagents => (0, total),
            AmbientWorkKind::Mixed => (1, 1),
        };
        (commands, subagents) == expected && self.running.len() == total
    }

    fn ids(self) -> HashSet<String> {
        self.running
            .into_keys()
            .map(|(tool_call_id, _)| tool_call_id)
            .collect()
    }
}

struct BufferedEventCollector<'a> {
    connection: &'a mut ValidatedConnection,
    deferred: Vec<Envelope>,
}

impl<'a> BufferedEventCollector<'a> {
    fn new(connection: &'a mut ValidatedConnection) -> Self {
        Self {
            connection,
            deferred: Vec::new(),
        }
    }

    async fn next(&mut self, context: &str) -> Envelope {
        self.connection
            .next_event()
            .await
            .unwrap_or_else(|error| panic!("{context}: read failed: {error:?}"))
            .unwrap_or_else(|| panic!("{context}: connection closed"))
    }

    fn defer(&mut self, envelope: Envelope) {
        self.deferred.push(envelope);
    }

    fn restore(self) {
        self.connection.restore_events(self.deferred);
    }
}

#[derive(Default)]
struct BackgroundTerminalObservation {
    completion_count: usize,
}

async fn wait_for_background_terminal_lifecycle(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    background_ids: &HashSet<String>,
    expected_outcome: ExpectedBackgroundOutcome,
    context: &str,
) {
    if background_ids.is_empty() {
        return;
    }
    let mut observations = background_ids
        .iter()
        .cloned()
        .map(|tool_call_id| (tool_call_id, BackgroundTerminalObservation::default()))
        .collect::<HashMap<_, _>>();
    let mut collector = BufferedEventCollector::new(&mut fixture.client);
    let mut trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(30), async {
        while observations
            .values()
            .any(|observation| observation.completion_count != 1)
        {
            let envelope = collector.next(context).await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                collector.defer(envelope);
                continue;
            }
            let event = envelope
                .parse_payload::<ChatEvent>()
                .unwrap_or_else(|error| panic!("{context}: parse failed: {error:?}"));
            trace.push(event.clone());
            match event {
                ChatEvent::ToolProgress(progress)
                    if background_ids.contains(&progress.tool_call_id) =>
                {
                    assert_eq!(
                        progress.execution_mode,
                        protocol::ToolExecutionMode::Background,
                        "{context}: ambient work changed execution mode"
                    );
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if background_ids.contains(&completion.tool_call_id) =>
                {
                    let observation = observations
                        .get_mut(&completion.tool_call_id)
                        .expect("tracked background task");
                    observation.completion_count += 1;
                    assert_eq!(
                        observation.completion_count, 1,
                        "{context}: duplicate correlated completion"
                    );
                    assert!(
                        expected_outcome.matches(&completion.outcome),
                        "{context}: correlated completion had the wrong outcome: {completion:?}"
                    );
                }
                _ => collector.defer(envelope),
            }
        }
        let quiet_until = Instant::now() + Duration::from_millis(250);
        while Instant::now() < quiet_until {
            let remaining = quiet_until.saturating_duration_since(Instant::now());
            let Ok(envelope) = tokio::time::timeout(remaining, collector.next(context)).await
            else {
                break;
            };
            if envelope.kind == FrameKind::ChatEvent && envelope.stream == *stream {
                match envelope
                    .parse_payload::<ChatEvent>()
                    .unwrap_or_else(|error| panic!("{context}: parse failed: {error:?}"))
                {
                    ChatEvent::ToolProgress(progress)
                        if background_ids.contains(&progress.tool_call_id) =>
                    {
                        panic!(
                            "{context}: progress arrived after completion for {}",
                            progress.tool_call_id
                        );
                    }
                    ChatEvent::ToolExecutionCompleted(completion)
                        if background_ids.contains(&completion.tool_call_id) =>
                    {
                        panic!(
                            "{context}: duplicate correlated completion for {}",
                            completion.tool_call_id
                        );
                    }
                    _ => collector.defer(envelope),
                }
            } else {
                collector.defer(envelope);
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!("{context}: background lifecycle did not terminalize; trace={trace:#?}")
    });
    collector.restore();
}

async fn assert_background_remains_running(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    background_ids: &HashSet<String>,
    context: &str,
) {
    if background_ids.is_empty() {
        return;
    }
    let mut collector = BufferedEventCollector::new(&mut fixture.client);
    let deadline = Instant::now() + Duration::from_millis(500);
    while Instant::now() < deadline {
        let remaining = deadline.saturating_duration_since(Instant::now());
        let Ok(envelope) = tokio::time::timeout(remaining, collector.next(context)).await else {
            break;
        };
        if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
            collector.defer(envelope);
            continue;
        }
        match envelope
            .parse_payload::<ChatEvent>()
            .unwrap_or_else(|error| panic!("{context}: parse failed: {error:?}"))
        {
            ChatEvent::ToolProgress(progress)
                if background_ids.contains(&progress.tool_call_id) =>
            {
                match progress.update {
                    protocol::ToolProgressUpdate::SubAgent(subagent) => assert!(
                        !subagent.completed,
                        "{context}: independent background subagent did not remain running"
                    ),
                    update if background_task_progress(&update).is_some() => assert_eq!(
                        progress.execution_mode,
                        protocol::ToolExecutionMode::Background,
                        "{context}: independent background command changed execution mode"
                    ),
                    _ => collector.defer(envelope),
                }
            }
            ChatEvent::ToolExecutionCompleted(completion)
                if background_ids.contains(&completion.tool_call_id) =>
            {
                panic!(
                    "{context}: independent background work completed unexpectedly: {completion:?}"
                );
            }
            _ => collector.defer(envelope),
        }
    }
    collector.restore();
}

async fn release_and_wait_for_background_terminal(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    background_ids: &HashSet<String>,
    activity: ActivityCondition,
    stimulus: ContractStimulus,
    context: &str,
) {
    let boundary_controls_terminal = !background_terminal_before_stimulus(activity);
    let expected = match stimulus {
        ContractStimulus::Close if boundary_controls_terminal => {
            Some(ExpectedBackgroundOutcome::Cancelled)
        }
        ContractStimulus::HostRestartResume if boundary_controls_terminal => {
            Some(ExpectedBackgroundOutcome::Cancelled)
        }
        ContractStimulus::TransportClosed if boundary_controls_terminal => {
            Some(ExpectedBackgroundOutcome::Failed)
        }
        _ => expected_background_outcome(activity),
    }
    .unwrap_or_else(|| panic!("{context}: activity has no terminal background outcome"));
    if !boundary_controls_terminal
        || !matches!(
            stimulus,
            ContractStimulus::Close
                | ContractStimulus::HostRestartResume
                | ContractStimulus::TransportClosed
        )
    {
        release_question_background_work(fixture, background_ids.len());
    }
    wait_for_background_terminal_lifecycle(fixture, stream, background_ids, expected, context)
        .await;
}

async fn ambient_before_stimulus(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    ids: &HashSet<String>,
    activity: ActivityCondition,
    stimulus: ContractStimulus,
    context: &str,
) {
    if background_terminal_before_stimulus(activity) {
        release_and_wait_for_background_terminal(fixture, stream, ids, activity, stimulus, context)
            .await;
    }
}

async fn ambient_during_stimulus(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    ids: &HashSet<String>,
    activity: ActivityCondition,
    stimulus: ContractStimulus,
    context: &str,
) {
    let boundary_terminalizes = matches!(
        stimulus,
        ContractStimulus::Close
            | ContractStimulus::HostRestartResume
            | ContractStimulus::TransportClosed
    );
    if background_terminal_during_stimulus(activity)
        || (boundary_terminalizes
            && activity != ActivityCondition::ForegroundOnly
            && !background_terminal_before_stimulus(activity))
    {
        release_and_wait_for_background_terminal(fixture, stream, ids, activity, stimulus, context)
            .await;
    }
}

async fn ambient_after_stimulus(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    ids: &HashSet<String>,
    activity: ActivityCondition,
    stimulus: ContractStimulus,
    context: &str,
) {
    let boundary_terminalizes = matches!(
        stimulus,
        ContractStimulus::Close
            | ContractStimulus::HostRestartResume
            | ContractStimulus::TransportClosed
    );
    if matches!(
        activity,
        ActivityCondition::OneBackgroundTaskRunning
            | ActivityCondition::MultipleBackgroundTasksRunning
            | ActivityCondition::OneBackgroundSubagentRunning
            | ActivityCondition::MultipleBackgroundSubagentsRunning
            | ActivityCondition::MixedBackgroundWorkRunning
    ) && !boundary_terminalizes
    {
        assert_background_remains_running(fixture, stream, ids, context).await;
    } else if background_terminal_after_stimulus(activity) && !boundary_terminalizes {
        release_and_wait_for_background_terminal(fixture, stream, ids, activity, stimulus, context)
            .await;
    }
}

fn assert_user_question_request_shape(
    questions: &[protocol::AskUserQuestion],
    input: ToolInputVariant,
) {
    for question in questions {
        assert_normalized_optional_text("AskUserQuestion id", question.id.as_deref());
        assert_normalized_optional_text("AskUserQuestion header", question.header.as_deref());
        assert!(
            !question.question.trim().is_empty(),
            "AskUserQuestion emitted an empty question"
        );
        for option in &question.options {
            assert!(
                !option.label.trim().is_empty(),
                "AskUserQuestion emitted an empty option label"
            );
            assert_normalized_optional_text(
                "AskUserQuestion option description",
                option.description.as_deref(),
            );
        }
    }

    fn assert_choice_question(
        question: &protocol::AskUserQuestion,
        expected_text: &str,
        multi_select: bool,
    ) {
        assert_eq!(question.question, expected_text);
        assert_eq!(question.multi_select, multi_select);
        let labels = question
            .options
            .iter()
            .map(|option| option.label.as_str())
            .collect::<Vec<_>>();
        assert_eq!(labels, ["BLUE", "GREEN"]);
    }

    fn assert_free_text_question(question: &protocol::AskUserQuestion, expected_text: &str) {
        assert_eq!(question.question, expected_text);
        assert!(!question.multi_select);
        assert!(
            question.options.is_empty(),
            "free-text question unexpectedly carried choice options: {:?}",
            question.options
        );
    }

    match input {
        ToolInputVariant::AskSingleChoice => {
            assert_eq!(questions.len(), 1);
            assert_choice_question(
                &questions[0],
                "What verification token should I use?",
                false,
            );
        }
        ToolInputVariant::AskMultipleChoice => {
            assert_eq!(questions.len(), 1);
            assert_choice_question(&questions[0], "What verification token should I use?", true);
            assert_eq!(questions[0].header.as_deref(), Some("Verification"));
        }
        ToolInputVariant::AskFreeText => {
            assert_eq!(questions.len(), 1);
            assert_free_text_question(&questions[0], "What verification token should I use?");
        }
        ToolInputVariant::AskMultipleQuestions => {
            assert_eq!(questions.len(), 2);
            assert_choice_question(
                &questions[0],
                "What verification token should I use?",
                false,
            );
            assert_free_text_question(&questions[1], "What second token should I use?");
        }
        _ => panic!("non-question input passed to question shape oracle: {input:?}"),
    }
}

fn assert_plan_approval_request_shape(
    fixture: &RealBackendFixture,
    plan: Option<String>,
    plan_path: Option<String>,
) {
    assert_normalized_optional_text("ExitPlanMode plan", plan.as_deref());
    assert_normalized_optional_text("ExitPlanMode plan_path", plan_path.as_deref());
    let plan = plan.filter(|value| !value.trim().is_empty());
    let plan_path = plan_path.filter(|value| !value.trim().is_empty());
    assert!(
        plan.is_some() || plan_path.is_some(),
        "ExitPlanMode request omitted both plan content and plan path"
    );
    let plan_text = plan.or_else(|| {
        let path = PathBuf::from(plan_path.expect("non-empty plan path"));
        let path = if path.is_absolute() {
            path
        } else {
            fixture.workspace_dir.path().join(path)
        };
        Some(
            std::fs::read_to_string(&path)
                .unwrap_or_else(|error| panic!("read ExitPlanMode plan {path:?}: {error}")),
        )
    });
    let plan_text = plan_text.expect("ExitPlanMode plan text");
    assert!(
        plan_text.contains("README.txt"),
        "ExitPlanMode plan did not contain the requested README.txt step: {plan_text:?}"
    );
}

fn assert_normalized_optional_text(field: &str, value: Option<&str>) {
    if let Some(value) = value {
        assert!(
            !value.trim().is_empty(),
            "{field} used Some(empty/whitespace) instead of None"
        );
    }
}

fn assert_run_command_request_shape(command: &str, working_directory: &str) {
    assert!(
        !command.trim().is_empty(),
        "RunCommand normalized an absent/empty command as a request"
    );
    assert!(
        working_directory.is_empty() || !working_directory.trim().is_empty(),
        "RunCommand working_directory used a whitespace sentinel instead of the empty/default shape"
    );
}

fn assert_agent_spawn_request_shape(
    prompt: Option<&str>,
    name: Option<&str>,
    execution_mode: protocol::AgentExecutionMode,
) {
    assert_normalized_optional_text("AgentSpawn prompt", prompt);
    assert_normalized_optional_text("AgentSpawn name", name);
    assert!(
        prompt.is_some(),
        "a live provider emitted AgentSpawn without the child instruction required to execute it"
    );
    assert_ne!(
        execution_mode,
        protocol::AgentExecutionMode::Unknown,
        "a live provider emitted AgentSpawn with legacy/unknown execution mode"
    );
}

struct InputAdmissionRun {
    stream: StreamPath,
    agent_id: protocol::AgentId,
    session_id: SessionId,
    state: InputAdmissionState,
    interaction_tool_call_id: Option<String>,
    release_paths: Vec<PathBuf>,
    background_tool_ids: HashSet<String>,
}

async fn expect_queued_messages_exact(
    client: &mut ValidatedConnection,
    stream: &StreamPath,
    expected: &[&str],
) -> Vec<QueuedMessageId> {
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope =
                expect_next_unfiltered_event(client, "authoritative queued messages").await;
            if envelope.kind != FrameKind::QueuedMessages || envelope.stream != *stream {
                continue;
            }
            let queued: QueuedMessagesPayload = envelope.parse_payload().unwrap();
            let actual = queued
                .messages
                .iter()
                .map(|message| message.message.as_str())
                .collect::<Vec<_>>();
            if actual == expected {
                break queued
                    .messages
                    .into_iter()
                    .map(|message| message.id)
                    .collect();
            }
        }
    })
    .await
    .expect("queued-message snapshot did not reach the exact expected order")
}

async fn expect_queued_image_exact(
    client: &mut ValidatedConnection,
    stream: &StreamPath,
    message: &str,
    images: &[ImageData],
) -> QueuedMessageId {
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope = expect_next_unfiltered_event(client, "authoritative queued image").await;
            if envelope.kind != FrameKind::QueuedMessages || envelope.stream != *stream {
                continue;
            }
            let queued: QueuedMessagesPayload = envelope.parse_payload().unwrap();
            if queued.messages.len() == 1
                && queued.messages[0].message == message
                && queued.messages[0].images == images
            {
                break queued.messages[0].id.clone();
            }
        }
    })
    .await
    .expect("queued image snapshot did not preserve exact text and bytes")
}

async fn expect_queued_payloads_exact(
    client: &mut ValidatedConnection,
    stream: &StreamPath,
    expected: &[(&str, &[ImageData])],
) -> Vec<QueuedMessageId> {
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope =
                expect_next_unfiltered_event(client, "authoritative queued payloads").await;
            if envelope.kind != FrameKind::QueuedMessages || envelope.stream != *stream {
                continue;
            }
            let queued: QueuedMessagesPayload = envelope.parse_payload().unwrap();
            if queued.messages.len() == expected.len()
                && queued
                    .messages
                    .iter()
                    .zip(expected)
                    .all(|(actual, (message, images))| {
                        actual.message == *message && actual.images.as_slice() == *images
                    })
            {
                break queued
                    .messages
                    .into_iter()
                    .map(|message| message.id)
                    .collect();
            }
        }
    })
    .await
    .expect("queued payload snapshot did not preserve exact text, order, and image bytes")
}

fn admission_prompt(
    backend_kind: BackendKind,
    state: InputAdmissionState,
    release: &Path,
) -> String {
    match state {
        InputAdmissionState::ModelStreaming =>
            "Without using tools, write at least 2000 words beginning exactly ADMISSION_STREAM_ACTIVE.".to_owned(),
        InputAdmissionState::ForegroundToolPending => match backend_kind {
            BackendKind::Claude => format!("Use Bash exactly once in the foreground to run `while [ ! -f {} ]; do sleep 0.1; done; printf ADMISSION_TOOL_RELEASED`. Do not use another tool.", release.display()),
            BackendKind::Codex => format!("Call exec_command exactly once with command `while [ ! -f {} ]; do sleep 0.1; done; printf ADMISSION_TOOL_RELEASED`. Do not use another tool.", release.display()),
            BackendKind::Hermes => format!("Use terminal exactly once in the foreground to run `while [ ! -f {} ]; do sleep 0.1; done; printf ADMISSION_TOOL_RELEASED`. Do not use another tool.", release.display()),
            _ => format!("Use command execution exactly once in the foreground to run `while [ ! -f {} ]; do sleep 0.1; done; printf ADMISSION_TOOL_RELEASED`. Do not use another tool.", release.display()),
        },
        InputAdmissionState::BackgroundOnlyIdle | InputAdmissionState::AgentInitiatedTurn => match backend_kind {
            BackendKind::Claude => format!("This is an IDE background-task lifecycle integration test in a temporary workspace. Use Bash exactly once with run_in_background=true to run `while [ ! -f {} ]; do sleep 0.1; done; printf ADMISSION_BACKGROUND_DONE`. Do not poll it. After Bash reports Running, reply exactly ADMISSION_BACKGROUND_IDLE. If its normal completion later wakes the turn, begin your status report with ADMISSION_AGENT_INITIATED and continue until interrupted.", release.display()),
            BackendKind::Codex => format!("This is an IDE background-task lifecycle integration test in a temporary workspace. Use command execution exactly once with yield_time_ms=1000 to run `while [ ! -f {} ]; do sleep 0.1; done; printf ADMISSION_BACKGROUND_DONE`. Do not poll it. After it reports Running, reply exactly ADMISSION_BACKGROUND_IDLE. If its normal completion later wakes the turn, begin your status report with ADMISSION_AGENT_INITIATED and continue until interrupted.", release.display()),
            BackendKind::Hermes => format!("This is an IDE background-task lifecycle integration test in a temporary workspace. Use terminal exactly once with background=true to run `while [ ! -f {} ]; do sleep 0.1; done; printf ADMISSION_BACKGROUND_DONE`. Do not poll it. After it reports Running, reply exactly ADMISSION_BACKGROUND_IDLE. If its normal completion later wakes the turn, begin your status report with ADMISSION_AGENT_INITIATED and continue until interrupted.", release.display()),
            _ => unreachable!(),
        },
        _ => unreachable!(),
    }
}

async fn reach_pending_compaction_admission(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
) -> InputAdmissionRun {
    let release = fixture.workspace_dir.path().join(format!(
        "ADMISSION_COMPACTION_RELEASE_{}",
        Uuid::new_v4().simple()
    ));
    let roots = fixture.workspace_roots();
    let ready_prompt = "Do not use tools. Reply exactly ADMISSION_COMPACTION_READY.";
    let (stream, start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "input-admission-compaction",
        ready_prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let ready =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, ready_prompt).await;
    assert!(ready.final_text.contains("ADMISSION_COMPACTION_READY"));
    let background_tool_ids =
        start_agent_control_ambient_work(fixture, backend_kind, &stream, activity).await;
    let prompt = admission_prompt(
        backend_kind,
        InputAdmissionState::ForegroundToolPending,
        &release,
    );
    fixture.client.send_message(&stream, prompt).await.unwrap();
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "compaction admission tool").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            if let ChatEvent::ToolRequest(ToolRequest {
                tool_type: ToolRequestType::RunCommand { command, .. },
                ..
            }) = envelope.parse_payload::<ChatEvent>().unwrap()
                && command.contains("ADMISSION_COMPACTION_RELEASE_")
            {
                break;
            }
        }
    })
    .await
    .expect("compaction admission command never became pending");
    fixture
        .client
        .compact_agent(&stream, protocol::AgentCompactPayload::default())
        .await
        .unwrap();
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "pending compaction admission").await;
            if envelope.kind != FrameKind::ContextCompactionNotify || envelope.stream != stream {
                continue;
            }
            let notify: protocol::ContextCompactionNotifyPayload =
                envelope.parse_payload().unwrap();
            assert!(
                !notify.status.is_terminal(),
                "compaction did not remain pending: {notify:?}"
            );
            break;
        }
    })
    .await
    .expect("compaction never exposed a pending admission state");
    InputAdmissionRun {
        stream,
        agent_id: start.agent_id,
        session_id: start.session_id.expect("compaction admission session id"),
        state: InputAdmissionState::CompactionPending,
        interaction_tool_call_id: None,
        release_paths: vec![release],
        background_tool_ids,
    }
}

async fn reach_input_admission_state(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    cell: InputAdmissionCoverageCell,
) -> InputAdmissionRun {
    let state = cell.state;
    if state == InputAdmissionState::UserQuestionWaiting {
        let activity = cell.activity;
        let (stream, session_id, agent_id, tool_call_id, background_tool_ids) =
            reach_user_question_wait(
                fixture,
                backend_kind,
                activity,
                ToolInputVariant::AskSingleChoice,
            )
            .await;
        let release_paths = (1..=background_tool_ids.len())
            .map(|index| {
                fixture
                    .workspace_dir
                    .path()
                    .join(format!("QUESTION_RELEASE_{index}"))
            })
            .collect();
        return InputAdmissionRun {
            stream,
            agent_id,
            session_id,
            state,
            interaction_tool_call_id: Some(tool_call_id),
            release_paths,
            background_tool_ids,
        };
    }
    if state == InputAdmissionState::PlanApprovalWaiting {
        let activity = cell.activity;
        let (stream, session_id, agent_id, tool_call_id, background_tool_ids) =
            reach_plan_approval_wait(fixture, backend_kind, activity).await;
        let release_paths = (1..=background_tool_ids.len())
            .map(|index| {
                fixture
                    .workspace_dir
                    .path()
                    .join(format!("QUESTION_RELEASE_{index}"))
            })
            .collect();
        return InputAdmissionRun {
            stream,
            agent_id,
            session_id,
            state,
            interaction_tool_call_id: Some(tool_call_id),
            release_paths,
            background_tool_ids,
        };
    }
    if state == InputAdmissionState::McpToolPending {
        install_adversarial_mcp(fixture, "pending_wait").await;
        let sentinel = format!("ADMISSION_MCP_{}", Uuid::new_v4().simple());
        let prompt = adversarial_mcp_prompt(backend_kind, &sentinel, true);
        let ready_prompt = "Do not use tools. Reply exactly ADMISSION_MCP_READY.";
        let roots = fixture.workspace_roots();
        let (stream, start) = spawn_agent_via_protocol_with_start(
            &mut fixture.client,
            roots,
            backend_kind,
            "input-admission-mcp-pending",
            ready_prompt,
            None,
            cost_hint_for(backend_kind),
        )
        .await;
        let ready =
            expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, ready_prompt).await;
        assert!(ready.final_text.contains("ADMISSION_MCP_READY"));
        let background_tool_ids =
            start_agent_control_ambient_work(fixture, backend_kind, &stream, cell.activity).await;
        fixture
            .client
            .send_message(&stream, prompt.clone())
            .await
            .unwrap();
        let request = tokio::time::timeout(Duration::from_secs(120), async {
            loop {
                let envelope =
                    expect_next_event(&mut fixture.client, "input-admission MCP request").await;
                if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                    continue;
                }
                if let ChatEvent::ToolRequest(request) =
                    envelope.parse_payload::<ChatEvent>().unwrap()
                    && matches!(
                        &request.tool_type,
                        ToolRequestType::Other { args }
                            if args.get("value") == Some(&Value::String(sentinel.clone()))
                    )
                {
                    break request;
                }
            }
        })
        .await
        .expect("input-admission MCP tool was not invoked");
        return InputAdmissionRun {
            stream,
            agent_id: start.agent_id,
            session_id: start.session_id.expect("MCP admission session id"),
            state,
            interaction_tool_call_id: Some(request.tool_call_id),
            release_paths: Vec::new(),
            background_tool_ids,
        };
    }
    if state == InputAdmissionState::GenericOtherPending {
        install_pending_generic_other_mcp(fixture).await;
        let nonce = Uuid::new_v4().simple().to_string();
        let sentinel = format!("GENERIC_OTHER_PENDING_VALUE_{}", &nonce[..8]);
        let prompt = match backend_kind {
            BackendKind::Codex => format!(
                "Invoke tool `generic_other_pending` from MCP server `generic_other_pending_live` exactly once. Pass exactly this JSON arguments object without changing any character: {{\"value\":\"{sentinel}\"}}. Do not call another tool and do not respond before it returns."
            ),
            _ => format!(
                "Use the MCP tool `generic_other_pending` exactly once with value `{sentinel}`. Do not call another tool and do not respond before it returns."
            ),
        };
        let ready_prompt = "Do not use tools. Reply exactly ADMISSION_OTHER_READY.";
        let roots = fixture.workspace_roots();
        let (stream, start) = spawn_agent_via_protocol_with_start(
            &mut fixture.client,
            roots,
            backend_kind,
            "input-admission-generic-other",
            ready_prompt,
            None,
            cost_hint_for(backend_kind),
        )
        .await;
        let ready =
            expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, ready_prompt).await;
        assert!(ready.final_text.contains("ADMISSION_OTHER_READY"));
        let background_tool_ids =
            start_agent_control_ambient_work(fixture, backend_kind, &stream, cell.activity).await;
        fixture.client.send_message(&stream, prompt).await.unwrap();
        let tool_call_id = tokio::time::timeout(Duration::from_secs(120), async {
            loop {
                let envelope =
                    expect_next_event(&mut fixture.client, "input-admission generic Other request")
                        .await;
                if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                    continue;
                }
                if let ChatEvent::ToolRequest(request) =
                    envelope.parse_payload::<ChatEvent>().unwrap()
                    && let ToolRequestType::Other { args } = request.tool_type
                {
                    let serialized = serde_json::to_string(&args).unwrap();
                    if serialized.contains(&sentinel) {
                        break request.tool_call_id;
                    }
                }
            }
        })
        .await
        .expect("input-admission generic Other tool was not invoked");
        return InputAdmissionRun {
            stream,
            agent_id: start.agent_id,
            session_id: start
                .session_id
                .expect("generic Other admission session id"),
            state,
            interaction_tool_call_id: Some(tool_call_id),
            release_paths: Vec::new(),
            background_tool_ids,
        };
    }
    if state == InputAdmissionState::NativeSpawnPending {
        let pending = reach_native_spawn_wait(
            fixture,
            backend_kind,
            SpecialToolContract::AgentSpawn,
            ToolResultVariant::Succeeds,
            cell.activity,
        )
        .await;
        return InputAdmissionRun {
            stream: pending.parent_stream,
            agent_id: pending.parent_id,
            session_id: pending.parent_session_id,
            state,
            interaction_tool_call_id: Some(pending.tool_call_id),
            release_paths: vec![pending.release],
            background_tool_ids: pending.ambient_ids,
        };
    }
    if state == InputAdmissionState::AgentAwaitPending {
        let (pair, tool_call_id, background_tool_ids) = reach_agent_await(
            fixture,
            backend_kind,
            cell.activity,
            ContractStimulus::UserResponds,
        )
        .await;
        return InputAdmissionRun {
            stream: pair.parent_stream,
            agent_id: pair.parent_id,
            session_id: pair.parent_session_id,
            state,
            interaction_tool_call_id: Some(tool_call_id),
            release_paths: vec![pair.child_release],
            background_tool_ids,
        };
    }
    if state == InputAdmissionState::CompactionPending {
        return reach_pending_compaction_admission(fixture, backend_kind, cell.activity).await;
    }
    let roots = fixture.workspace_roots();
    let release = fixture
        .workspace_dir
        .path()
        .join(format!("ADMISSION_RELEASE_{}", Uuid::new_v4().simple()));
    let ready_prompt = "Do not use tools. Reply exactly ADMISSION_IDLE_READY.";
    let background_state = matches!(
        state,
        InputAdmissionState::BackgroundOnlyIdle | InputAdmissionState::AgentInitiatedTurn
    );
    let prompt = if background_state {
        admission_prompt(backend_kind, state, &release)
    } else {
        ready_prompt.to_owned()
    };
    let (stream, start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "input-admission-matrix",
        &prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let mut background_tool_ids = HashSet::new();
    if !background_state {
        let ready =
            expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, &prompt).await;
        assert!(ready.final_text.contains("ADMISSION_IDLE_READY"));
        background_tool_ids =
            start_agent_control_ambient_work(fixture, backend_kind, &stream, cell.activity).await;
        if state != InputAdmissionState::Idle {
            let state_prompt = admission_prompt(backend_kind, state, &release);
            fixture
                .client
                .send_message(&stream, state_prompt)
                .await
                .unwrap();
        }
    }
    let mut focal_tool_call_id = None;
    match state {
        InputAdmissionState::Idle => {}
        InputAdmissionState::ModelStreaming => {
            tokio::time::timeout(Duration::from_secs(120), async {
                loop {
                    let envelope =
                        expect_next_event(&mut fixture.client, "active model stream").await;
                    if envelope.kind == FrameKind::ChatEvent
                        && envelope.stream == stream
                        && matches!(
                            envelope.parse_payload::<ChatEvent>().unwrap(),
                            ChatEvent::StreamDelta(_)
                        )
                    {
                        break;
                    }
                }
            })
            .await
            .expect("model never reached streaming admission state");
        }
        InputAdmissionState::ForegroundToolPending => {
            focal_tool_call_id = Some(
                tokio::time::timeout(Duration::from_secs(120), async {
                    loop {
                        let envelope =
                            expect_next_event(&mut fixture.client, "pending foreground tool").await;
                        if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                            continue;
                        }
                        if let ChatEvent::ToolRequest(ToolRequest {
                            tool_call_id,
                            tool_type: ToolRequestType::RunCommand { command, .. },
                            ..
                        }) = envelope.parse_payload::<ChatEvent>().unwrap()
                            && command.contains("ADMISSION_RELEASE_")
                        {
                            break tool_call_id;
                        }
                    }
                })
                .await
                .expect("command never reached foreground pending state"),
            );
        }
        InputAdmissionState::BackgroundOnlyIdle | InputAdmissionState::AgentInitiatedTurn => {
            let mut running = false;
            let mut idle = false;
            tokio::time::timeout(Duration::from_secs(120), async {
                while !running || !idle {
                    let envelope =
                        expect_next_event(&mut fixture.client, "background-only admission state")
                            .await;
                    if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                        continue;
                    }
                    match envelope.parse_payload::<ChatEvent>().unwrap() {
                        ChatEvent::ToolProgress(progress)
                            if background_task_progress(&progress.update).is_some() =>
                        {
                            background_tool_ids.insert(progress.tool_call_id);
                            running = true
                        }
                        ChatEvent::TypingStatusChanged(false) if running => idle = true,
                        _ => {}
                    }
                }
            })
            .await
            .expect("background work never reached foreground idle");
            background_tool_ids.extend(
                start_agent_control_ambient_work(fixture, backend_kind, &stream, cell.activity)
                    .await,
            );
            if state == InputAdmissionState::AgentInitiatedTurn {
                std::fs::write(&release, b"release").unwrap();
                tokio::time::timeout(Duration::from_secs(120), async {
                    loop {
                        let envelope = expect_next_event(
                            &mut fixture.client,
                            "agent-initiated admission turn",
                        )
                        .await;
                        if envelope.kind == FrameKind::ChatEvent
                            && envelope.stream == stream
                            && matches!(
                                envelope.parse_payload::<ChatEvent>().unwrap(),
                                ChatEvent::TypingStatusChanged(true)
                            )
                        {
                            break;
                        }
                    }
                })
                .await
                .expect("background completion did not begin an agent-initiated turn");
            }
        }
        _ => unreachable!(),
    }
    InputAdmissionRun {
        stream,
        agent_id: start.agent_id,
        session_id: start.session_id.expect("input-admission session id"),
        state,
        interaction_tool_call_id: focal_tool_call_id,
        release_paths: matches!(
            state,
            InputAdmissionState::BackgroundOnlyIdle
                | InputAdmissionState::AgentInitiatedTurn
                | InputAdmissionState::ForegroundToolPending
        )
        .then_some(release)
        .into_iter()
        .collect(),
        background_tool_ids,
    }
}

async fn finish_active_admission_state(fixture: &mut RealBackendFixture, run: &InputAdmissionRun) {
    if matches!(
        run.state,
        InputAdmissionState::Idle | InputAdmissionState::BackgroundOnlyIdle
    ) {
        return;
    }
    fixture
        .client
        .interrupt(&run.stream)
        .await
        .expect("interrupt input-admission state");
}

