#[derive(Debug)]
struct PendingInteractionProbe {
    stream: StreamPath,
    session_id: SessionId,
    agent_id: protocol::AgentId,
    tool_call_id: String,
    ambient_ids: HashSet<String>,
}

async fn reach_interaction_probe(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    contract: InteractionConcurrencyContract,
) -> PendingInteractionProbe {
    reach_interaction_probe_with_activity(
        fixture,
        backend_kind,
        contract,
        ActivityCondition::ForegroundOnly,
    )
    .await
}

async fn reach_interaction_probe_with_activity(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    contract: InteractionConcurrencyContract,
    activity: ActivityCondition,
) -> PendingInteractionProbe {
    match contract {
        InteractionConcurrencyContract::AskUserQuestion => {
            let (stream, session_id, agent_id, tool_call_id, ambient_ids) =
                reach_user_question_wait(
                    fixture,
                    backend_kind,
                    activity,
                    ToolInputVariant::AskSingleChoice,
                )
                .await;
            PendingInteractionProbe {
                stream,
                session_id,
                agent_id,
                tool_call_id,
                ambient_ids,
            }
        }
        InteractionConcurrencyContract::ExitPlanMode => {
            let (stream, session_id, agent_id, tool_call_id, ambient_ids) =
                reach_plan_approval_wait(fixture, backend_kind, activity).await;
            PendingInteractionProbe {
                stream,
                session_id,
                agent_id,
                tool_call_id,
                ambient_ids,
            }
        }
        InteractionConcurrencyContract::AskAndPlan => {
            panic!("mixed interaction probe requires one probe of each concrete contract")
        }
    }
}

async fn send_interaction_probe_response(
    client: &mut ValidatedConnection,
    probe: &PendingInteractionProbe,
    contract: InteractionConcurrencyContract,
    stream: &StreamPath,
    message: &str,
    images: Option<Vec<ImageData>>,
) -> Result<(), protocol::FrameError> {
    client
        .send_message_payload(
            stream,
            interaction_probe_response_payload(probe, contract, message, images, false),
        )
        .await
}

fn interaction_probe_response_payload(
    probe: &PendingInteractionProbe,
    contract: InteractionConcurrencyContract,
    message: &str,
    images: Option<Vec<ImageData>>,
    alternate: bool,
) -> SendMessagePayload {
    let tool_response = match contract {
        InteractionConcurrencyContract::AskUserQuestion => {
            SendMessageToolResponse::AskUserQuestion {
                tool_call_id: probe.tool_call_id.clone(),
                answer: if alternate { "GREEN" } else { "BLUE" }.to_owned(),
            }
        }
        InteractionConcurrencyContract::ExitPlanMode => SendMessageToolResponse::ExitPlanMode {
            tool_call_id: probe.tool_call_id.clone(),
            decision: if alternate {
                protocol::ExitPlanModeDecision::Reject
            } else {
                protocol::ExitPlanModeDecision::Approve
            },
            feedback: alternate.then(|| "Use the alternate approach.".to_owned()),
        },
        InteractionConcurrencyContract::AskAndPlan => unreachable!(),
    };
    SendMessagePayload {
        message: message.to_owned(),
        images,
        origin: None,
        tool_response: Some(tool_response),
    }
}

async fn expect_interaction_probe_completion(
    client: &mut ValidatedConnection,
    probe: &PendingInteractionProbe,
) {
    let completion = expect_tool_completion_for_id(
        client,
        &probe.stream,
        &probe.tool_call_id,
        "interaction concurrency completion",
    )
    .await;
    assert!(
        completion.success(),
        "interaction response failed: {completion:?}"
    );
}

async fn expect_interaction_probe_completion_with_images(
    client: &mut ValidatedConnection,
    probe: &PendingInteractionProbe,
    contract: InteractionConcurrencyContract,
    message: &str,
    images: &[ImageData],
) {
    let mut echoes = 0usize;
    let mut completions = 0usize;
    let expected_continuation = match contract {
        InteractionConcurrencyContract::AskUserQuestion => "USER_QUESTION_ANSWER_OK_BLUE_RED_IMAGE",
        InteractionConcurrencyContract::ExitPlanMode => "PLAN_APPROVAL_OK_RED_IMAGE",
        InteractionConcurrencyContract::AskAndPlan => unreachable!(),
    };
    let mut continuation = String::new();
    let mut saw_continuation = false;
    tokio::time::timeout(Duration::from_secs(120), async {
        while echoes != 1 || completions != 1 || !saw_continuation {
            let envelope = expect_next_event(client, "image-bearing interaction response").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != probe.stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::MessageAdded(message_added)
                    if matches!(message_added.sender, MessageSender::User)
                        && message_added.content == message =>
                {
                    assert_eq!(
                        message_added.images.as_deref(),
                        Some(images),
                        "typed interaction response changed image count, order, media type, or bytes"
                    );
                    echoes += 1;
                    assert_eq!(echoes, 1, "typed interaction response was echoed twice");
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == probe.tool_call_id =>
                {
                    assert!(completion.success(), "interaction response failed: {completion:?}");
                    completions += 1;
                    assert_eq!(completions, 1, "typed interaction completed twice");
                }
                ChatEvent::StreamDelta(delta) => {
                    continuation.push_str(&delta.text);
                    saw_continuation |= continuation.contains(expected_continuation);
                }
                ChatEvent::StreamEnd(end) => {
                    continuation.push_str(&end.message.content);
                    saw_continuation |= continuation.contains(expected_continuation);
                }
                _ => {}
            }
        }
    })
    .await
    .expect("image-bearing interaction response did not echo and complete exactly once");
}

async fn expect_two_interaction_probe_completions(
    client: &mut ValidatedConnection,
    first: &PendingInteractionProbe,
    second: &PendingInteractionProbe,
) {
    let expected = HashSet::from([
        (first.stream.clone(), first.tool_call_id.clone()),
        (second.stream.clone(), second.tool_call_id.clone()),
    ]);
    let mut completed = HashSet::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        while completed.len() < expected.len() {
            let envelope = expect_next_event(client, "two interaction completions").await;
            if envelope.kind != FrameKind::ChatEvent {
                continue;
            }
            let stream = envelope.stream.clone();
            let ChatEvent::ToolExecutionCompleted(completion) =
                envelope.parse_payload::<ChatEvent>().unwrap()
            else {
                continue;
            };
            let key = (stream, completion.tool_call_id.clone());
            if expected.contains(&key) {
                assert!(
                    completion.success(),
                    "interaction response failed: {completion:?}"
                );
                assert!(
                    completed.insert(key),
                    "interaction completed more than once"
                );
            }
        }
    })
    .await
    .expect("two interaction responses did not both complete");
}

async fn reach_two_interaction_probes(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    first: InteractionConcurrencyContract,
    second: InteractionConcurrencyContract,
) -> (PendingInteractionProbe, PendingInteractionProbe) {
    let first = reach_interaction_probe(fixture, backend_kind, first).await;
    let second = reach_interaction_probe(fixture, backend_kind, second).await;
    assert_ne!(first.stream, second.stream);
    (first, second)
}

async fn run_interaction_pair_order(
    backend_kind: BackendKind,
    first_contract: InteractionConcurrencyContract,
    second_contract: InteractionConcurrencyContract,
    scenario: InteractionConcurrencyScenario,
) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let (first, second) =
        reach_two_interaction_probes(&mut fixture, backend_kind, first_contract, second_contract)
            .await;
    let reverse = scenario == InteractionConcurrencyScenario::TwoAgentsReverseResponseOrder;
    let (left, left_contract, right, right_contract) = if reverse {
        (&second, second_contract, &first, first_contract)
    } else {
        (&first, first_contract, &second, second_contract)
    };
    send_interaction_probe_response(
        &mut fixture.client,
        left,
        left_contract,
        &left.stream,
        "Typed response for the first selected interaction.",
        None,
    )
    .await
    .unwrap();
    send_interaction_probe_response(
        &mut fixture.client,
        right,
        right_contract,
        &right.stream,
        "Typed response for the second selected interaction.",
        None,
    )
    .await
    .unwrap();
    expect_two_interaction_probe_completions(&mut fixture.client, left, right).await;
}

async fn run_interaction_single_envelope(
    backend_kind: BackendKind,
    contract: InteractionConcurrencyContract,
    scenario: InteractionConcurrencyScenario,
) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let probe = reach_interaction_probe(&mut fixture, backend_kind, contract).await;
    let images = (scenario == InteractionConcurrencyScenario::ResponseWithImages).then(|| {
        vec![ImageData {
            media_type: "image/png".to_owned(),
            data: SOLID_RED_PNG_BASE64.to_owned(),
        }]
    });
    let message = "Human prose accompanying the authoritative typed response.";
    send_interaction_probe_response(
        &mut fixture.client,
        &probe,
        contract,
        &probe.stream,
        message,
        images.clone(),
    )
    .await
    .unwrap();
    if let Some(images) = images {
        expect_interaction_probe_completion_with_images(
            &mut fixture.client,
            &probe,
            contract,
            message,
            &images,
        )
        .await;
    } else {
        expect_interaction_probe_completion(&mut fixture.client, &probe).await;
    }
}

async fn expect_atomic_interaction_image_rejection(
    fixture: &mut RealBackendFixture,
    probe: &PendingInteractionProbe,
    message: &str,
) {
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope = expect_next_unfiltered_event(
                &mut fixture.client,
                "atomic interaction image rejection",
            )
            .await;
            if envelope.kind == FrameKind::CommandError {
                let error: CommandErrorPayload = envelope.parse_payload().unwrap();
                if error.request_kind == FrameKind::SendMessage && error.stream == probe.stream {
                    assert_eq!(error.code, CommandErrorCode::InvalidInput);
                    assert!(!error.fatal);
                    assert!(!error.message.trim().is_empty());
                    break;
                }
            }
            if envelope.kind == FrameKind::ChatEvent && envelope.stream == probe.stream {
                match envelope.parse_payload::<ChatEvent>().unwrap() {
                    ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::User,
                        content,
                        ..
                    }) if content == message => {
                        panic!("invalid typed-response image was echoed to the provider")
                    }
                    ChatEvent::ToolExecutionCompleted(completion)
                        if completion.tool_call_id == probe.tool_call_id =>
                    {
                        panic!("invalid typed-response image consumed the pending interaction")
                    }
                    _ => {}
                }
            }
        }
    })
    .await
    .expect("invalid typed-response image was not rejected atomically");
    let bootstrap = reconnected_agent_bootstrap(fixture, &probe.stream).await;
    assert!(
        bootstrap.events.iter().any(|event| matches!(event,
            AgentBootstrapEvent::ChatEvent(ChatEvent::ToolRequest(request))
                if request.tool_call_id == probe.tool_call_id
        )),
        "atomic image rejection removed the pending interaction"
    );
}

async fn expect_provider_rejected_interaction_image(
    fixture: &mut RealBackendFixture,
    probe: &PendingInteractionProbe,
    message: &str,
    images: &[ImageData],
) {
    let mut echoes = 0;
    let mut completions = 0;
    let mut rejected = false;
    tokio::time::timeout(Duration::from_secs(180), async {
        loop {
            let envelope = expect_next_unfiltered_event(
                &mut fixture.client,
                "provider-rejected interaction image",
            )
            .await;
            if envelope.stream != probe.stream {
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                rejected = true;
                break;
            }
            if envelope.kind != FrameKind::ChatEvent {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    images: observed,
                    ..
                }) if content == message => {
                    assert_eq!(observed.as_deref(), Some(images));
                    echoes += 1;
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == probe.tool_call_id =>
                {
                    assert!(completion.success());
                    completions += 1;
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => {
                    assert!(!content.trim().is_empty());
                    rejected = true;
                    break;
                }
                ChatEvent::TypingStatusChanged(false) if completions == 1 => break,
                _ => {}
            }
        }
    })
    .await
    .expect("provider did not settle corrupt typed-response image");
    assert_eq!(echoes, 1);
    assert_eq!(completions, 1);
    assert!(rejected, "provider accepted header-valid corrupt image");
}

async fn assert_interaction_image_activity_cell(
    backend_kind: BackendKind,
    cell: InteractionImageActivityCell,
) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let probe = reach_interaction_probe_with_activity(
        &mut fixture,
        backend_kind,
        cell.contract,
        cell.activity,
    )
    .await;
    ambient_before_stimulus(
        &mut fixture,
        &probe.stream,
        &probe.ambient_ids,
        cell.activity,
        ContractStimulus::UserResponds,
        "interaction image before response",
    )
    .await;
    let message = format!(
        "Typed image response for {:?} {:?}.",
        cell.payload, cell.activity
    );
    let valid = ImageData {
        media_type: "image/png".to_owned(),
        data: SOLID_RED_PNG_BASE64.to_owned(),
    };
    let images = match cell.payload {
        InteractionImagePayloadCell::Valid => vec![valid.clone()],
        InteractionImagePayloadCell::Invalid => vec![ImageData {
            media_type: "image/png".to_owned(),
            data: "invalid%%%".to_owned(),
        }],
        InteractionImagePayloadCell::MixedValidInvalid => vec![
            valid.clone(),
            ImageData {
                media_type: "image/png".to_owned(),
                data: "invalid%%%".to_owned(),
            },
        ],
        InteractionImagePayloadCell::ProviderRejected => vec![header_valid_corrupt_png()],
    };
    send_interaction_probe_response(
        &mut fixture.client,
        &probe,
        cell.contract,
        &probe.stream,
        &message,
        Some(images.clone()),
    )
    .await
    .unwrap();
    ambient_during_stimulus(
        &mut fixture,
        &probe.stream,
        &probe.ambient_ids,
        cell.activity,
        ContractStimulus::UserResponds,
        "interaction image during response",
    )
    .await;
    match cell.payload {
        InteractionImagePayloadCell::Invalid | InteractionImagePayloadCell::MixedValidInvalid => {
            expect_atomic_interaction_image_rejection(&mut fixture, &probe, &message).await;
            send_interaction_probe_response(
                &mut fixture.client,
                &probe,
                cell.contract,
                &probe.stream,
                &message,
                Some(vec![valid.clone()]),
            )
            .await
            .unwrap();
            expect_interaction_probe_completion_with_images(
                &mut fixture.client,
                &probe,
                cell.contract,
                &message,
                &[valid],
            )
            .await;
        }
        InteractionImagePayloadCell::Valid => {
            expect_interaction_probe_completion_with_images(
                &mut fixture.client,
                &probe,
                cell.contract,
                &message,
                &images,
            )
            .await;
        }
        InteractionImagePayloadCell::ProviderRejected => {
            expect_provider_rejected_interaction_image(&mut fixture, &probe, &message, &images)
                .await;
        }
    }
    ambient_after_stimulus(
        &mut fixture,
        &probe.stream,
        &probe.ambient_ids,
        cell.activity,
        ContractStimulus::UserResponds,
        "interaction image after response",
    )
    .await;
}

async fn assert_interaction_image_activity_matrix(backend_kind: BackendKind) {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let selected_activities = conformance_activity_conditions(&capabilities);
    let required = InteractionImageActivityCell::required_for(&capabilities)
        .into_iter()
        .filter(|cell| selected_activities.contains(&cell.activity))
        .collect::<Vec<_>>();
    let mut ledger = EnumeratedCoverageLedger::new(required.clone(), "interaction image activity");
    for cell in required {
        assert_interaction_image_activity_cell(backend_kind, cell).await;
        ledger.record(cell).unwrap();
    }
    ledger.finish().unwrap();
}
async fn run_interaction_concurrent_distinct(
    backend_kind: BackendKind,
    first_contract: InteractionConcurrencyContract,
    second_contract: InteractionConcurrencyContract,
) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let (first, second) =
        reach_two_interaction_probes(&mut fixture, backend_kind, first_contract, second_contract)
            .await;
    let mut observer = fixture.connect().await;
    observer.inherit_live_trace_from(&fixture.client);
    let mut observed_streams = HashSet::new();
    tokio::time::timeout(Duration::from_secs(30), async {
        while observed_streams.len() < 2 {
            let envelope =
                expect_next_unfiltered_event(&mut observer, "second-client bootstrap").await;
            if envelope.kind != FrameKind::HostBootstrap {
                continue;
            }
            let bootstrap: HostBootstrapPayload = envelope.parse_payload().unwrap();
            for agent in bootstrap.agents {
                if agent.agent_id == first.agent_id || agent.agent_id == second.agent_id {
                    observed_streams.insert(agent.instance_stream);
                }
            }
        }
    })
    .await
    .expect("second client did not discover both pending interactions");
    assert!(observed_streams.contains(&first.stream));
    assert!(observed_streams.contains(&second.stream));
    let (first_result, second_result) = tokio::join!(
        send_interaction_probe_response(
            &mut fixture.client,
            &first,
            first_contract,
            &first.stream,
            "First client response.",
            None,
        ),
        send_interaction_probe_response(
            &mut observer,
            &second,
            second_contract,
            &second.stream,
            "Second client response.",
            None,
        ),
    );
    first_result.unwrap();
    second_result.unwrap();
    expect_two_interaction_probe_completions(&mut fixture.client, &first, &second).await;
}

async fn run_interaction_two_clients_conflicting(
    backend_kind: BackendKind,
    contract: InteractionConcurrencyContract,
) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let probe = reach_interaction_probe(&mut fixture, backend_kind, contract).await;
    let mut observer = fixture.connect().await;
    observer.inherit_live_trace_from(&fixture.client);
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope =
                expect_next_unfiltered_event(&mut observer, "conflicting-client bootstrap").await;
            if envelope.kind != FrameKind::HostBootstrap {
                continue;
            }
            let bootstrap: HostBootstrapPayload = envelope.parse_payload().unwrap();
            if bootstrap.agents.iter().any(|agent| {
                agent.agent_id == probe.agent_id && agent.instance_stream == probe.stream
            }) {
                break;
            }
        }
    })
    .await
    .expect("second client did not discover the pending interaction");

    let primary = interaction_probe_response_payload(
        &probe,
        contract,
        "Primary client's typed response.",
        None,
        false,
    );
    let conflicting = interaction_probe_response_payload(
        &probe,
        contract,
        "Second client's conflicting typed response.",
        None,
        true,
    );
    let (primary_result, conflicting_result) = tokio::join!(
        fixture.client.send_message_payload(&probe.stream, primary),
        observer.send_message_payload(&probe.stream, conflicting),
    );
    primary_result.unwrap();
    conflicting_result.unwrap();

    let mut completion_count = 0usize;
    let mut rejection_count = 0usize;
    let mut consumed_user_responses = 0usize;
    tokio::time::timeout(Duration::from_secs(120), async {
        while completion_count != 1 || rejection_count != 1 || consumed_user_responses != 1 {
            let envelope = expect_next_event(
                &mut fixture.client,
                "two-client conflicting interaction responses",
            )
            .await;
            if envelope.stream != probe.stream {
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                assert!(!error.message.trim().is_empty());
                rejection_count += 1;
                assert_eq!(
                    rejection_count, 1,
                    "conflicting response rejected repeatedly"
                );
                continue;
            }
            if envelope.kind != FrameKind::ChatEvent {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == probe.tool_call_id =>
                {
                    assert!(
                        completion.success(),
                        "winning response failed: {completion:?}"
                    );
                    let ToolExecutionResult::Other { result } = &completion.tool_result() else {
                        panic!("winning typed response was not normalized: {completion:?}")
                    };
                    match contract {
                        InteractionConcurrencyContract::AskUserQuestion => assert!(matches!(
                            result.get("answer").and_then(Value::as_str),
                            Some("BLUE") | Some("GREEN")
                        )),
                        InteractionConcurrencyContract::ExitPlanMode => assert!(matches!(
                            result.get("decision").and_then(Value::as_str),
                            Some("approved") | Some("rejected")
                        )),
                        InteractionConcurrencyContract::AskAndPlan => unreachable!(),
                    }
                    completion_count += 1;
                    assert_eq!(completion_count, 1, "conflicting responses completed twice");
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == "Primary client's typed response."
                    || content == "Second client's conflicting typed response." =>
                {
                    consumed_user_responses += 1;
                    assert_eq!(
                        consumed_user_responses, 1,
                        "both conflicting responses were consumed"
                    );
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => {
                    assert!(!content.trim().is_empty());
                    rejection_count += 1;
                    assert_eq!(
                        rejection_count, 1,
                        "conflicting response rejected repeatedly"
                    );
                }
                _ => {}
            }
        }
    })
    .await
    .expect("conflicting client responses did not settle one winner and one rejection");

    let quiet_until = Instant::now() + Duration::from_millis(250);
    while Instant::now() < quiet_until {
        let remaining = quiet_until.saturating_duration_since(Instant::now());
        let Ok(envelope) = tokio::time::timeout(
            remaining,
            expect_next_event(&mut fixture.client, "conflicting response quiet period"),
        )
        .await
        else {
            break;
        };
        if envelope.kind == FrameKind::ChatEvent && envelope.stream == probe.stream {
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == probe.tool_call_id =>
                {
                    panic!("conflicting responses produced a duplicate completion: {completion:?}")
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == "Primary client's typed response."
                    || content == "Second client's conflicting typed response." =>
                {
                    panic!("conflicting responses were both consumed")
                }
                _ => {}
            }
        }
    }
}

#[derive(Clone, Copy, Debug)]
enum QuestionInterruptRaceOrder {
    ResponseThenInterrupt,
    InterruptThenResponse,
    Concurrent,
}

async fn assert_no_typing_resurrection_after_question_interrupt(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    question_tool_call_id: &str,
    background_tool_ids: &HashSet<String>,
    context: &str,
) {
    let quiet = tokio::time::timeout(Duration::from_secs(3), async {
        loop {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::TypingStatusChanged(true) => {
                    panic!("{context}: typing resurrected after cancellation reached idle")
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == question_tool_call_id =>
                {
                    panic!("{context}: question terminalized twice: {completion:?}")
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if background_tool_ids.contains(&completion.tool_call_id) =>
                {
                    panic!(
                        "{context}: interrupt stopped independent background work: {completion:?}"
                    )
                }
                ChatEvent::ToolProgress(progress)
                    if background_tool_ids.contains(&progress.tool_call_id) =>
                {
                    assert!(
                        background_task_progress(&progress.update).is_some(),
                        "{context}: interrupt changed independent background progress family"
                    );
                }
                _ => {}
            }
        }
    })
    .await;
    assert!(
        quiet.is_err(),
        "{context}: quiet observation ended unexpectedly"
    );
}

async fn run_user_question_interrupt_race_with_background(
    backend_kind: BackendKind,
    order: QuestionInterruptRaceOrder,
) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let (stream, _, agent_id, tool_call_id, background_tool_ids) = reach_user_question_wait(
        &mut fixture,
        backend_kind,
        ActivityCondition::OneBackgroundTaskRunning,
        ToolInputVariant::AskSingleChoice,
    )
    .await;
    assert_eq!(
        background_tool_ids.len(),
        1,
        "question/interrupt race did not establish exactly one background task"
    );

    let response = SendMessagePayload {
        message: "BLUE".to_owned(),
        images: None,
        origin: None,
        tool_response: Some(SendMessageToolResponse::AskUserQuestion {
            tool_call_id: tool_call_id.clone(),
            answer: "BLUE".to_owned(),
        }),
    };
    let mut observer = None;
    match order {
        QuestionInterruptRaceOrder::ResponseThenInterrupt => {
            fixture
                .client
                .send_message_payload(&stream, response.clone())
                .await
                .expect("send answer before interrupt");
            fixture
                .client
                .interrupt(&stream)
                .await
                .expect("interrupt after answer");
        }
        QuestionInterruptRaceOrder::InterruptThenResponse => {
            fixture
                .client
                .interrupt(&stream)
                .await
                .expect("interrupt before stale answer");
        }
        QuestionInterruptRaceOrder::Concurrent => {
            let mut second = fixture.connect().await;
            second.inherit_live_trace_from(&fixture.client);
            let second_stream = tokio::time::timeout(Duration::from_secs(30), async {
                loop {
                    let envelope = expect_next_unfiltered_event(
                        &mut second,
                        "question race second-client bootstrap",
                    )
                    .await;
                    if envelope.kind != FrameKind::HostBootstrap {
                        continue;
                    }
                    let bootstrap: HostBootstrapPayload = envelope.parse_payload().unwrap();
                    if let Some(agent) = bootstrap
                        .agents
                        .into_iter()
                        .find(|agent| agent.agent_id == agent_id)
                    {
                        break agent.instance_stream;
                    }
                }
            })
            .await
            .expect("question race second client did not discover the pending interaction");
            let (answered, interrupted) = tokio::join!(
                fixture
                    .client
                    .send_message_payload(&stream, response.clone()),
                second.interrupt(&second_stream),
            );
            answered.expect("send concurrent question answer");
            interrupted.expect("send concurrent interrupt");
            observer = Some(second);
        }
    }

    let context = format!("{backend_kind:?} question/interrupt {order:?}");
    let mut completion = None;
    let mut cancellation_count = 0usize;
    let mut idle_count = 0usize;
    let mut rejection_count = 0usize;
    let mut trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, &context).await;
            if envelope.stream != stream {
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                assert!(
                    !error.message.trim().is_empty(),
                    "{context}: empty rejection"
                );
                rejection_count += 1;
                continue;
            }
            if envelope.kind != FrameKind::ChatEvent {
                continue;
            }
            let event = envelope.parse_payload::<ChatEvent>().unwrap();
            trace.push(format!("{event:?}"));
            match event {
                ChatEvent::ToolExecutionCompleted(candidate)
                    if candidate.tool_call_id == tool_call_id =>
                {
                    assert!(
                        completion.replace(candidate).is_none(),
                        "{context}: duplicate terminal"
                    )
                }
                ChatEvent::OperationCancelled(_) => cancellation_count += 1,
                ChatEvent::TypingStatusChanged(false) if cancellation_count == 1 => idle_count += 1,
                ChatEvent::TypingStatusChanged(true)
                    if cancellation_count != 0 || idle_count != 0 =>
                {
                    panic!("{context}: typing resurrected after cancellation began")
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => {
                    assert!(
                        !content.trim().is_empty(),
                        "{context}: empty visible rejection"
                    );
                    rejection_count += 1;
                }
                _ => {}
            }
            let cancelled = completion
                .as_ref()
                .is_some_and(|completion| !completion.success());
            let needs_rejection =
                matches!(order, QuestionInterruptRaceOrder::Concurrent) && cancelled;
            if completion.is_some()
                && cancellation_count == 1
                && idle_count == 1
                && (!needs_rejection || rejection_count >= 1)
            {
                break;
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context}: race did not settle; trace={trace:#?}"));

    let completion = completion.expect("question/interrupt race omitted tool terminal");
    assert_eq!(cancellation_count, 1, "{context}: wrong cancellation count");
    assert_eq!(idle_count, 1, "{context}: wrong post-cancel idle count");
    match order {
        QuestionInterruptRaceOrder::ResponseThenInterrupt => {
            assert!(
                completion.success(),
                "{context}: admitted answer lost: {completion:?}"
            );
        }
        QuestionInterruptRaceOrder::InterruptThenResponse => {
            assert!(
                !completion.success(),
                "{context}: interrupted question succeeded"
            );
            fixture
                .client
                .send_message_payload(&stream, response)
                .await
                .expect("send stale answer after interrupt");
            expect_typed_response_rejection(
                &mut fixture,
                &stream,
                &tool_call_id,
                "answer after question interrupt",
            )
            .await;
        }
        QuestionInterruptRaceOrder::Concurrent => {
            if !completion.success() {
                assert!(
                    rejection_count >= 1,
                    "{context}: losing answer was not visibly rejected"
                );
            }
        }
    }
    assert_background_remains_running(&mut fixture, &stream, &background_tool_ids, &context).await;
    assert_no_typing_resurrection_after_question_interrupt(
        &mut fixture,
        &stream,
        &tool_call_id,
        &background_tool_ids,
        &context,
    )
    .await;
    drop(observer);
}

async fn run_interaction_duplicate_after_reconnect(
    backend_kind: BackendKind,
    contract: InteractionConcurrencyContract,
) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let probe = reach_interaction_probe(&mut fixture, backend_kind, contract).await;
    let mut reconnected = fixture.connect().await;
    reconnected.inherit_live_trace_from(&fixture.client);
    std::mem::swap(&mut fixture.client, &mut reconnected);
    drop(reconnected);
    send_interaction_probe_response(
        &mut fixture.client,
        &probe,
        contract,
        &probe.stream,
        "Accepted response after reconnect.",
        None,
    )
    .await
    .unwrap();
    expect_interaction_probe_completion(&mut fixture.client, &probe).await;
    send_interaction_probe_response(
        &mut fixture.client,
        &probe,
        contract,
        &probe.stream,
        "Duplicate response after reconnect.",
        None,
    )
    .await
    .unwrap();
    expect_typed_response_rejection(
        &mut fixture,
        &probe.stream,
        &probe.tool_call_id,
        "duplicate response after reconnect",
    )
    .await;
}

async fn run_interaction_sequential_stale_ids(
    backend_kind: BackendKind,
    contract: InteractionConcurrencyContract,
) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let first = reach_interaction_probe(&mut fixture, backend_kind, contract).await;
    send_interaction_probe_response(
        &mut fixture.client,
        &first,
        contract,
        &first.stream,
        "Complete the older interaction.",
        None,
    )
    .await
    .unwrap();
    expect_interaction_probe_completion(&mut fixture.client, &first).await;
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, "first interaction idle").await;
            if envelope.kind == FrameKind::ChatEvent
                && envelope.stream == first.stream
                && matches!(
                    envelope.parse_payload::<ChatEvent>().unwrap(),
                    ChatEvent::TypingStatusChanged(false)
                )
            {
                break;
            }
        }
    })
    .await
    .expect("first interaction did not return idle");
    let prompt = interaction_followup_prompt(backend_kind, contract);
    fixture
        .client
        .send_message(&first.stream, prompt.to_owned())
        .await
        .unwrap();
    let second_tool_call_id = tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "second interaction request").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != first.stream {
                continue;
            }
            if let ChatEvent::ToolRequest(request) = envelope.parse_payload::<ChatEvent>().unwrap()
                && match contract {
                    InteractionConcurrencyContract::AskUserQuestion => {
                        matches!(request.tool_type, ToolRequestType::AskUserQuestion { .. })
                    }
                    InteractionConcurrencyContract::ExitPlanMode => {
                        matches!(request.tool_type, ToolRequestType::ExitPlanMode { .. })
                    }
                    InteractionConcurrencyContract::AskAndPlan => unreachable!(),
                }
            {
                break request.tool_call_id;
            }
        }
    })
    .await
    .expect("same stream did not emit a second interaction");
    assert_ne!(first.tool_call_id, second_tool_call_id);
    let second = PendingInteractionProbe {
        stream: first.stream.clone(),
        session_id: first.session_id.clone(),
        agent_id: first.agent_id.clone(),
        tool_call_id: second_tool_call_id,
        ambient_ids: first.ambient_ids.clone(),
    };
    send_interaction_probe_response(
        &mut fixture.client,
        &first,
        contract,
        &second.stream,
        "Stale identifier while a newer interaction is pending.",
        None,
    )
    .await
    .unwrap();
    expect_typed_response_rejection(
        &mut fixture,
        &second.stream,
        &second.tool_call_id,
        "sequential stale interaction id",
    )
    .await;
    send_interaction_probe_response(
        &mut fixture.client,
        &second,
        contract,
        &second.stream,
        "Complete the newer interaction.",
        None,
    )
    .await
    .unwrap();
    expect_interaction_probe_completion(&mut fixture.client, &second).await;
}

fn interaction_followup_prompt(
    backend_kind: BackendKind,
    contract: InteractionConcurrencyContract,
) -> &'static str {
    match (backend_kind, contract) {
        (_, InteractionConcurrencyContract::AskUserQuestion) => {
            "Use the native user-question tool exactly once to ask `What verification token should I use?` with options BLUE and GREEN. Wait for my answer."
        }
        (BackendKind::Hermes, InteractionConcurrencyContract::ExitPlanMode) => {
            "Use the terminal exactly once to run `printf '\nHERMES_SECOND_APPROVAL\n' >> README.txt`. Wait for the native approval request before the command runs."
        }
        (_, InteractionConcurrencyContract::ExitPlanMode) => {
            "Enter native plan mode, make a one-step plan to inspect README.txt, and use the native exit-plan tool exactly once. Wait for my decision."
        }
        (_, InteractionConcurrencyContract::AskAndPlan) => unreachable!(),
    }
}

async fn run_interaction_wrong_stream(
    backend_kind: BackendKind,
    first_contract: InteractionConcurrencyContract,
    second_contract: InteractionConcurrencyContract,
) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let (first, second) =
        reach_two_interaction_probes(&mut fixture, backend_kind, first_contract, second_contract)
            .await;
    send_interaction_probe_response(
        &mut fixture.client,
        &first,
        first_contract,
        &second.stream,
        "This response deliberately targets the wrong stream.",
        None,
    )
    .await
    .unwrap();
    expect_typed_response_rejection(
        &mut fixture,
        &second.stream,
        &second.tool_call_id,
        "cross-stream typed response",
    )
    .await;
    for (probe, contract) in [(&first, first_contract), (&second, second_contract)] {
        send_interaction_probe_response(
            &mut fixture.client,
            probe,
            contract,
            &probe.stream,
            "Correctly routed typed response.",
            None,
        )
        .await
        .unwrap();
        expect_interaction_probe_completion(&mut fixture.client, probe).await;
    }
}

fn interaction_admission_state(contract: InteractionConcurrencyContract) -> InputAdmissionState {
    match contract {
        InteractionConcurrencyContract::AskUserQuestion => InputAdmissionState::UserQuestionWaiting,
        InteractionConcurrencyContract::ExitPlanMode => InputAdmissionState::PlanApprovalWaiting,
        InteractionConcurrencyContract::AskAndPlan => unreachable!(),
    }
}

fn interaction_concurrency_scenario_id(scenario: InteractionConcurrencyScenario) -> &'static str {
    use InteractionConcurrencyScenario as Scenario;
    match scenario {
        Scenario::TwoAgentsForwardResponseOrder => "two_agents_forward",
        Scenario::TwoAgentsReverseResponseOrder => "two_agents_reverse",
        Scenario::TwoAgentsConcurrentResponses => "two_agents_concurrent",
        Scenario::TwoConcurrentClients => "two_clients_same_interaction",
        Scenario::WrongStreamResponse => "wrong_stream",
        Scenario::DuplicateResponseAfterReconnect => "duplicate_after_reconnect",
        Scenario::SequentialStaleToolIds => "sequential_stale_ids",
        Scenario::ResponseWithProse => "response_with_prose",
        Scenario::ResponseWithImages => "response_with_images",
        Scenario::ResponseWhileInputQueued => "response_while_input_queued",
        Scenario::ResponseRacesInterrupt => "response_races_interrupt",
        Scenario::ResponseRacesClose => "response_races_close",
        Scenario::ResponseRacesTransportClose => "response_races_transport_close",
        Scenario::ResponseRacesReconnect => "response_races_reconnect",
        Scenario::ResponseRacesHostRestart => "response_races_host_restart",
        Scenario::NaturalSameToolIdCrossStream => "natural_same_id_cross_stream",
    }
}

async fn run_interaction_concurrency_matrix(
    backend_kind: BackendKind,
    contract: InteractionConcurrencyContract,
) {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let concrete = match contract {
        InteractionConcurrencyContract::AskAndPlan => vec![
            InteractionConcurrencyContract::AskUserQuestion,
            InteractionConcurrencyContract::ExitPlanMode,
        ],
        contract => vec![contract],
    };
    let pair = [concrete[0], *concrete.get(1).unwrap_or(&concrete[0])];
    let selected = std::env::var("TYDE_CONFORMANCE_INTERACTION_CELL")
        .ok()
        .filter(|value| !value.trim().is_empty());
    if let Some(selected) = selected.as_deref() {
        assert!(
            InteractionConcurrencyScenario::ALL
                .into_iter()
                .any(|scenario| interaction_concurrency_scenario_id(scenario) == selected),
            "unknown TYDE_CONFORMANCE_INTERACTION_CELL {selected:?}"
        );
    }
    let cells = InteractionConcurrencyCell::required_for(contract, &capabilities)
        .into_iter()
        .filter(|cell| {
            selected.as_deref().is_none_or(|selected| {
                interaction_concurrency_scenario_id(cell.scenario) == selected
            })
        })
        .collect::<Vec<_>>();
    assert!(
        !cells.is_empty(),
        "interaction matrix has no applicable cells"
    );
    let mut ledger = EnumeratedCoverageLedger::new(cells.clone(), "interaction concurrency/race");
    for cell in cells {
        eprintln!("INTERACTION CONCURRENCY CELL {backend_kind:?} {cell:?}");
        use InteractionConcurrencyScenario as Scenario;
        match cell.scenario {
            Scenario::TwoAgentsForwardResponseOrder | Scenario::TwoAgentsReverseResponseOrder => {
                run_interaction_pair_order(backend_kind, pair[0], pair[1], cell.scenario).await;
            }
            Scenario::TwoAgentsConcurrentResponses => {
                run_interaction_concurrent_distinct(backend_kind, pair[0], pair[1]).await;
            }
            Scenario::WrongStreamResponse => {
                run_interaction_wrong_stream(backend_kind, pair[0], pair[1]).await;
            }
            Scenario::TwoConcurrentClients => {
                assert_ne!(
                    contract,
                    InteractionConcurrencyContract::AskAndPlan,
                    "mixed-kind two-client conflict is explicitly not applicable"
                );
                run_interaction_two_clients_conflicting(backend_kind, contract).await;
            }
            Scenario::ResponseWhileInputQueued => {
                for &concrete_contract in &concrete {
                    run_input_admission_cell(
                        backend_kind,
                        InputAdmissionCoverageCell {
                            activity: ActivityCondition::ForegroundOnly,
                            state: interaction_admission_state(concrete_contract),
                            input: InputAdmissionKind::InteractionResponse,
                            action: InputAdmissionAction::Enqueue,
                        },
                        false,
                    )
                    .await;
                }
            }
            Scenario::ResponseRacesInterrupt => {
                for &concrete_contract in &concrete {
                    run_input_admission_cell(
                        backend_kind,
                        InputAdmissionCoverageCell {
                            activity: ActivityCondition::ForegroundOnly,
                            state: interaction_admission_state(concrete_contract),
                            input: InputAdmissionKind::InteractionResponse,
                            action: InputAdmissionAction::InterruptThenSend,
                        },
                        false,
                    )
                    .await;
                }
                if contract == InteractionConcurrencyContract::AskUserQuestion
                    && capabilities.contains(BackendCapability::BackgroundTasks)
                {
                    for order in [
                        QuestionInterruptRaceOrder::ResponseThenInterrupt,
                        QuestionInterruptRaceOrder::InterruptThenResponse,
                        QuestionInterruptRaceOrder::Concurrent,
                    ] {
                        run_user_question_interrupt_race_with_background(backend_kind, order).await;
                    }
                }
            }
            Scenario::ResponseRacesClose => {
                for &concrete_contract in &concrete {
                    run_input_admission_cell(
                        backend_kind,
                        InputAdmissionCoverageCell {
                            activity: ActivityCondition::ForegroundOnly,
                            state: interaction_admission_state(concrete_contract),
                            input: InputAdmissionKind::InteractionResponse,
                            action: InputAdmissionAction::Close,
                        },
                        false,
                    )
                    .await;
                }
            }
            Scenario::ResponseRacesTransportClose => {
                for &concrete_contract in &concrete {
                    run_input_admission_cell(
                        backend_kind,
                        InputAdmissionCoverageCell {
                            activity: ActivityCondition::ForegroundOnly,
                            state: interaction_admission_state(concrete_contract),
                            input: InputAdmissionKind::InteractionResponse,
                            action: InputAdmissionAction::TransportClosed,
                        },
                        false,
                    )
                    .await;
                }
            }
            Scenario::ResponseRacesReconnect => {
                for &concrete_contract in &concrete {
                    run_input_admission_cell(
                        backend_kind,
                        InputAdmissionCoverageCell {
                            activity: ActivityCondition::ForegroundOnly,
                            state: interaction_admission_state(concrete_contract),
                            input: InputAdmissionKind::InteractionResponse,
                            action: InputAdmissionAction::ClientReconnect,
                        },
                        false,
                    )
                    .await;
                }
            }
            Scenario::ResponseRacesHostRestart => {
                for &concrete_contract in &concrete {
                    run_input_admission_cell(
                        backend_kind,
                        InputAdmissionCoverageCell {
                            activity: ActivityCondition::ForegroundOnly,
                            state: interaction_admission_state(concrete_contract),
                            input: InputAdmissionKind::InteractionResponse,
                            action: InputAdmissionAction::HostRestart,
                        },
                        false,
                    )
                    .await;
                }
            }
            Scenario::ResponseWithProse | Scenario::ResponseWithImages => {
                for &concrete_contract in &concrete {
                    run_interaction_single_envelope(backend_kind, concrete_contract, cell.scenario)
                        .await;
                }
            }
            Scenario::DuplicateResponseAfterReconnect => {
                for &concrete_contract in &concrete {
                    run_interaction_duplicate_after_reconnect(backend_kind, concrete_contract)
                        .await;
                }
            }
            Scenario::SequentialStaleToolIds => {
                for &concrete_contract in &concrete {
                    run_interaction_sequential_stale_ids(backend_kind, concrete_contract).await;
                }
            }
            Scenario::NaturalSameToolIdCrossStream => {
                unreachable!("provider-generated same-id collision is explicitly not applicable")
            }
        }
        ledger.record(cell).unwrap();
    }
    ledger.finish().unwrap();
}

async fn expect_typed_response_rejection(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    pending_tool_call_id: &str,
    context: &str,
) {
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope = fixture
                .client
                .next_event()
                .await
                .unwrap_or_else(|error| panic!("{context}: read rejection: {error}"))
                .unwrap_or_else(|| panic!("{context}: connection closed before rejection"));
            if envelope.stream != *stream {
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                let error: protocol::AgentErrorPayload = envelope
                    .parse_payload()
                    .unwrap_or_else(|error| panic!("{context}: parse AgentError: {error}"));
                assert!(
                    !error.message.trim().is_empty(),
                    "{context}: empty rejection"
                );
                break;
            }
            if envelope.kind != FrameKind::ChatEvent {
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .unwrap_or_else(|error| panic!("{context}: parse rejection event: {error}"))
            {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => {
                    assert!(!content.trim().is_empty(), "{context}: empty rejection");
                    break;
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) => panic!("{context}: invalid typed response was consumed: {content:?}"),
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == pending_tool_call_id =>
                {
                    panic!("{context}: invalid typed response completed the pending tool")
                }
                ChatEvent::TypingStatusChanged(true) => {
                    panic!("{context}: invalid typed response resurrected typing")
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context}: typed response was not visibly rejected"));
}

async fn complete_pending_question_for_probe(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    tool_call_id: &str,
    answer: &str,
) {
    send_user_question_answer(fixture, stream, tool_call_id, answer).await;
    tokio::time::timeout(Duration::from_secs(120), async {
        let mut completed = false;
        loop {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    assert!(
                        completion.success(),
                        "question probe failed: {completion:?}"
                    );
                    assert!(!completed, "question probe completed more than once");
                    let ToolExecutionResult::Other { result } = &completion.tool_result() else {
                        panic!("question probe result was not normalized: {completion:?}")
                    };
                    assert_eq!(
                        result.get("answer").and_then(Value::as_str),
                        Some(answer),
                        "question probe did not preserve the exact answer encoding"
                    );
                    completed = true;
                }
                ChatEvent::TypingStatusChanged(false) if completed => break,
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("question probe failed: {content}"),
                _ => {}
            }
        }
    })
    .await
    .expect("question probe did not reach terminal idle");
}

async fn expect_interaction_with_background_terminal(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    interaction_tool_call_id: &str,
    background_tool_ids: &HashSet<String>,
    expected_outcome: ExpectedBackgroundOutcome,
) -> ToolExecutionCompletedData {
    let mut interaction = None;
    let mut terminal_completions = HashSet::new();
    let mut collector = BufferedEventCollector::new(&mut fixture.client);
    tokio::time::timeout(Duration::from_secs(120), async {
        while interaction.is_none() || terminal_completions.len() != background_tool_ids.len() {
            let envelope = collector
                .next("interaction response with background terminal")
                .await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                collector.defer(envelope);
                continue;
            }
            let event = envelope
                .clone()
                .parse_payload::<ChatEvent>()
                .expect("parse interaction/background race event");
            match event {
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == interaction_tool_call_id =>
                {
                    assert!(interaction.replace(completion).is_none());
                }
                ChatEvent::ToolProgress(progress)
                    if background_tool_ids.contains(&progress.tool_call_id) =>
                {
                    assert_eq!(
                        progress.execution_mode,
                        protocol::ToolExecutionMode::Background
                    );
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if background_tool_ids.contains(&completion.tool_call_id) =>
                {
                    assert!(
                        expected_outcome.matches(&completion.outcome),
                        "background work completed with the wrong outcome: {completion:?}"
                    );
                    assert!(terminal_completions.insert(completion.tool_call_id));
                }
                _ => collector.defer(envelope),
            }
        }
    })
    .await
    .expect("interaction/background terminal race did not settle exactly once");
    collector.restore();
    interaction.expect("interaction completion")
}

async fn reconnect_input_admission_agent_through_all_cardinalities(
    mut fixture: RealBackendFixture,
    agent_id: &protocol::AgentId,
) -> (RealBackendFixture, StreamPath) {
    assert_eq!(
        fixture.host.connection_count_for_test().await,
        1,
        "input-admission cardinality matrix did not begin with one client"
    );
    let mut observer = fixture.connect().await;
    tokio::time::timeout(Duration::from_secs(5), async {
        while fixture.host.connection_count_for_test().await < 2 {
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
    })
    .await
    .expect("input-admission cardinality never reached two clients");
    let observer_bootstrap = loop {
        let envelope = expect_next_unfiltered_event(&mut observer, "two-client bootstrap").await;
        if envelope.kind == FrameKind::HostBootstrap {
            break envelope.parse_payload::<HostBootstrapPayload>().unwrap();
        }
    };
    assert_eq!(
        observer_bootstrap
            .agents
            .iter()
            .filter(|agent| &agent.agent_id == agent_id)
            .count(),
        1,
        "two-client bootstrap duplicated or omitted the active agent"
    );
    drop(observer);
    tokio::time::timeout(Duration::from_secs(5), async {
        while fixture.host.connection_count_for_test().await != 1 {
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
    })
    .await
    .expect("input-admission cardinality did not return to one client");

    fixture = fixture.reconnect_after_zero_clients().await;
    tokio::time::timeout(Duration::from_secs(5), async {
        while fixture.host.connection_count_for_test().await != 1 {
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
    })
    .await
    .expect("input-admission cardinality did not recover from zero to one client");
    let stream = loop {
        let envelope =
            expect_next_event(&mut fixture.client, "zero-client reconnect bootstrap").await;
        if envelope.kind != FrameKind::HostBootstrap {
            continue;
        }
        let bootstrap: HostBootstrapPayload = envelope.parse_payload().unwrap();
        let matching = bootstrap
            .agents
            .into_iter()
            .filter(|agent| &agent.agent_id == agent_id)
            .map(|agent| agent.instance_stream)
            .collect::<Vec<_>>();
        assert_eq!(
            matching.len(),
            1,
            "zero-client bootstrap duplicated or omitted {agent_id}"
        );
        break matching.into_iter().next().unwrap();
    };
    (fixture, stream)
}

async fn resume_input_admission_agent(
    fixture: &mut RealBackendFixture,
    run: &InputAdmissionRun,
) -> (
    StreamPath,
    Vec<protocol::QueuedMessageEntry>,
    Vec<AgentBootstrapEvent>,
) {
    fixture.restart_host().await;
    fixture
        .client
        .spawn_agent(SpawnAgentPayload {
            name: Some("input-admission-resume".to_owned()),
            custom_agent_id: None,
            parent_agent_id: None,
            project_id: None,
            params: SpawnAgentParams::Resume {
                session_id: run.session_id.clone(),
                prompt: None,
            },
        })
        .await
        .unwrap();
    let resumed_new: NewAgentPayload = loop {
        let envelope =
            expect_next_unfiltered_event(&mut fixture.client, "queued-input resume NewAgent").await;
        if envelope.kind == FrameKind::NewAgent {
            let candidate: NewAgentPayload = envelope.parse_payload().unwrap();
            if candidate.session_id.as_ref() == Some(&run.session_id) {
                break candidate;
            }
        }
    };
    let resumed = resumed_new.instance_stream;
    let ids = loop {
        let envelope =
            expect_next_unfiltered_event(&mut fixture.client, "queued-input resume bootstrap")
                .await;
        if envelope.kind != FrameKind::AgentBootstrap || envelope.stream != resumed {
            continue;
        }
        let bootstrap: AgentBootstrapPayload = envelope.parse_payload().unwrap();
        let queued = bootstrap
            .events
            .iter()
            .find_map(|event| match event {
                AgentBootstrapEvent::QueuedMessages(queued) => Some(queued.clone()),
                _ => None,
            })
            .expect("resume bootstrap omitted queued input snapshot");
        break (queued.messages, bootstrap.events);
    };
    (resumed, ids.0, ids.1)
}

fn input_admission_stimulus(action: InputAdmissionAction) -> ContractStimulus {
    match action {
        InputAdmissionAction::InterruptThenSend => ContractStimulus::Interrupt,
        InputAdmissionAction::ClientReconnect => ContractStimulus::DisconnectReconnect,
        InputAdmissionAction::HostRestart => ContractStimulus::HostRestartResume,
        InputAdmissionAction::Fork => ContractStimulus::Fork,
        InputAdmissionAction::TransportClosed => ContractStimulus::TransportClosed,
        InputAdmissionAction::Close => ContractStimulus::Close,
        InputAdmissionAction::BackgroundFailureTerminal => ContractStimulus::ToolFails,
        InputAdmissionAction::BackgroundTerminal => ContractStimulus::ToolCompletes,
        InputAdmissionAction::Admit
        | InputAdmissionAction::Enqueue
        | InputAdmissionAction::EditQueued
        | InputAdmissionAction::CancelQueued
        | InputAdmissionAction::SendQueuedNow => ContractStimulus::UserResponds,
    }
}

async fn settle_input_admission_ambient(
    fixture: &mut RealBackendFixture,
    run: &InputAdmissionRun,
    activity: ActivityCondition,
    stimulus: ContractStimulus,
    context: &str,
) {
    ambient_during_stimulus(
        fixture,
        &run.stream,
        &run.background_tool_ids,
        activity,
        stimulus,
        context,
    )
    .await;
    ambient_after_stimulus(
        fixture,
        &run.stream,
        &run.background_tool_ids,
        activity,
        stimulus,
        context,
    )
    .await;
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TypedAdmissionResponseKind {
    Ask,
    Plan,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TypedAdmissionTarget {
    Current,
    Stale,
    WrongKind,
    ForeignStream,
}

fn typed_admission_axes(
    input: InputAdmissionKind,
) -> Option<(TypedAdmissionResponseKind, TypedAdmissionTarget)> {
    use InputAdmissionKind as Input;
    use TypedAdmissionResponseKind as Kind;
    use TypedAdmissionTarget as Target;
    match input {
        Input::AskResponseCurrent => Some((Kind::Ask, Target::Current)),
        Input::AskResponseStale => Some((Kind::Ask, Target::Stale)),
        Input::AskResponseWrongKind => Some((Kind::Ask, Target::WrongKind)),
        Input::AskResponseForeignStream => Some((Kind::Ask, Target::ForeignStream)),
        Input::PlanResponseCurrent => Some((Kind::Plan, Target::Current)),
        Input::PlanResponseStale => Some((Kind::Plan, Target::Stale)),
        Input::PlanResponseWrongKind => Some((Kind::Plan, Target::WrongKind)),
        Input::PlanResponseForeignStream => Some((Kind::Plan, Target::ForeignStream)),
        _ => None,
    }
}

fn typed_admission_contract(kind: TypedAdmissionResponseKind) -> InteractionConcurrencyContract {
    match kind {
        TypedAdmissionResponseKind::Ask => InteractionConcurrencyContract::AskUserQuestion,
        TypedAdmissionResponseKind::Plan => InteractionConcurrencyContract::ExitPlanMode,
    }
}

fn opposite_typed_admission_kind(kind: TypedAdmissionResponseKind) -> TypedAdmissionResponseKind {
    match kind {
        TypedAdmissionResponseKind::Ask => TypedAdmissionResponseKind::Plan,
        TypedAdmissionResponseKind::Plan => TypedAdmissionResponseKind::Ask,
    }
}

fn typed_admission_payload(
    kind: TypedAdmissionResponseKind,
    tool_call_id: String,
    marker: String,
) -> SendMessagePayload {
    let tool_response = match kind {
        TypedAdmissionResponseKind::Ask => SendMessageToolResponse::AskUserQuestion {
            tool_call_id,
            answer: "BLUE".to_owned(),
        },
        TypedAdmissionResponseKind::Plan => SendMessageToolResponse::ExitPlanMode {
            tool_call_id,
            decision: protocol::ExitPlanModeDecision::Approve,
            feedback: None,
        },
    };
    SendMessagePayload {
        message: marker,
        images: None,
        origin: None,
        tool_response: Some(tool_response),
    }
}

async fn expect_exact_invalid_typed_admission_rejection(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    marker: &str,
    forbidden_tool_call_ids: &HashSet<String>,
    context: &str,
) {
    let mut rejection_count = 0usize;
    let deadline = tokio::time::Instant::now() + Duration::from_secs(30);
    while rejection_count == 0 {
        let remaining = deadline
            .checked_duration_since(tokio::time::Instant::now())
            .unwrap_or_default();
        let envelope =
            tokio::time::timeout(remaining, expect_next_event(&mut fixture.client, context))
                .await
                .unwrap_or_else(|_| panic!("{context}: typed response was not visibly rejected"));
        if envelope.stream != *stream {
            continue;
        }
        if envelope.kind == FrameKind::AgentError {
            let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
            assert!(
                !error.message.trim().is_empty(),
                "{context}: empty rejection"
            );
            rejection_count += 1;
            continue;
        }
        if envelope.kind == FrameKind::CommandError {
            let error: CommandErrorPayload = envelope.parse_payload().unwrap();
            assert_eq!(error.request_kind, FrameKind::SendMessage);
            assert!(
                !error.message.trim().is_empty(),
                "{context}: empty rejection"
            );
            rejection_count += 1;
            continue;
        }
        if envelope.kind != FrameKind::ChatEvent {
            continue;
        }
        match envelope.parse_payload::<ChatEvent>().unwrap() {
            ChatEvent::MessageAdded(ChatMessage {
                sender: MessageSender::Error,
                content,
                ..
            }) => {
                assert!(!content.trim().is_empty(), "{context}: empty rejection");
                rejection_count += 1;
            }
            ChatEvent::MessageAdded(ChatMessage {
                sender: MessageSender::User,
                content,
                ..
            }) if content == marker => {
                panic!("{context}: invalid typed response was echoed as user input")
            }
            ChatEvent::ToolExecutionCompleted(completion)
                if forbidden_tool_call_ids.contains(&completion.tool_call_id) =>
            {
                panic!("{context}: invalid typed response completed a focal interaction")
            }
            ChatEvent::StreamDelta(delta) if delta.text.contains(marker) => {
                panic!("{context}: invalid typed response reached the model")
            }
            ChatEvent::StreamEnd(end) if end.message.content.contains(marker) => {
                panic!("{context}: invalid typed response produced a model turn")
            }
            _ => {}
        }
    }

    let quiet = tokio::time::sleep(Duration::from_millis(750));
    tokio::pin!(quiet);
    loop {
        tokio::select! {
            () = &mut quiet => break,
            event = fixture.client.next_event() => {
                let envelope = event
                    .unwrap_or_else(|error| panic!("{context}: read post-rejection event: {error}"))
                    .unwrap_or_else(|| panic!("{context}: connection closed after rejection"));
                if envelope.stream != *stream {
                    continue;
                }
                if envelope.kind == FrameKind::AgentError {
                    let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                    assert!(!error.message.trim().is_empty(), "{context}: empty duplicate rejection");
                    rejection_count += 1;
                } else if envelope.kind == FrameKind::CommandError {
                    let error: CommandErrorPayload = envelope.parse_payload().unwrap();
                    assert_eq!(error.request_kind, FrameKind::SendMessage);
                    assert!(!error.message.trim().is_empty(), "{context}: empty duplicate rejection");
                    rejection_count += 1;
                } else if envelope.kind == FrameKind::ChatEvent {
                    match envelope.parse_payload::<ChatEvent>().unwrap() {
                        ChatEvent::MessageAdded(ChatMessage {
                            sender: MessageSender::Error,
                            content,
                            ..
                        }) => {
                            assert!(!content.trim().is_empty(), "{context}: empty duplicate rejection");
                            rejection_count += 1;
                        }
                        ChatEvent::MessageAdded(ChatMessage {
                            sender: MessageSender::User,
                            content,
                            ..
                        }) if content == marker => {
                            panic!("{context}: invalid typed response was echoed after rejection")
                        }
                        ChatEvent::ToolExecutionCompleted(completion)
                            if forbidden_tool_call_ids.contains(&completion.tool_call_id) =>
                        {
                            panic!("{context}: invalid typed response completed a focal interaction")
                        }
                        ChatEvent::StreamDelta(delta) if delta.text.contains(marker) => {
                            panic!("{context}: invalid typed response reached the model")
                        }
                        ChatEvent::StreamEnd(end) if end.message.content.contains(marker) => {
                            panic!("{context}: invalid typed response produced a model turn")
                        }
                        ChatEvent::TypingStatusChanged(true) => {
                            panic!("{context}: invalid typed response started a model turn")
                        }
                        _ => {}
                    }
                }
            }
        }
    }
    assert_eq!(
        rejection_count, 1,
        "{context}: rejection was not emitted exactly once"
    );
}

async fn complete_typed_admission_probe(
    fixture: &mut RealBackendFixture,
    probe: &PendingInteractionProbe,
    kind: TypedAdmissionResponseKind,
    context: &str,
) {
    fixture
        .client
        .send_message_payload(
            &probe.stream,
            typed_admission_payload(kind, probe.tool_call_id.clone(), format!("{context}_VALID")),
        )
        .await
        .unwrap_or_else(|error| panic!("{context}: send valid response: {error}"));
    let completion = expect_tool_completion_for_id(
        &mut fixture.client,
        &probe.stream,
        &probe.tool_call_id,
        context,
    )
    .await;
    assert!(
        completion.success(),
        "{context}: valid response failed: {completion:?}"
    );
}

async fn recover_focal_input_admission_state(
    fixture: &mut RealBackendFixture,
    run: &InputAdmissionRun,
    context: &str,
) {
    let valid_interaction = match run.state {
        InputAdmissionState::UserQuestionWaiting => Some(TypedAdmissionResponseKind::Ask),
        InputAdmissionState::PlanApprovalWaiting => Some(TypedAdmissionResponseKind::Plan),
        _ => None,
    };
    if let Some(kind) = valid_interaction {
        let tool_call_id = run
            .interaction_tool_call_id
            .clone()
            .expect("interaction admission state omitted its tool id");
        fixture
            .client
            .send_message_payload(
                &run.stream,
                typed_admission_payload(kind, tool_call_id.clone(), format!("{context}_VALID")),
            )
            .await
            .unwrap_or_else(|error| panic!("{context}: send focal valid response: {error}"));
        let completion = expect_tool_completion_for_id(
            &mut fixture.client,
            &run.stream,
            &tool_call_id,
            "valid focal interaction after rejected typed response",
        )
        .await;
        assert!(
            completion.success(),
            "{context}: focal interaction failed: {completion:?}"
        );
        return;
    }

    finish_active_admission_state(fixture, run).await;
    let marker = format!("TYPED_ADMISSION_RECOVERY_{}", Uuid::new_v4().simple());
    let prompt = format!("Do not use tools. Reply exactly {marker} and nothing else.");
    fixture
        .client
        .send_message(&run.stream, prompt.clone())
        .await
        .unwrap_or_else(|error| panic!("{context}: send recovery input: {error}"));
    expect_admitted_turn(fixture, &run.stream, &prompt, &marker).await;
}

async fn run_typed_interaction_admission_cell(
    backend_kind: BackendKind,
    cell: InputAdmissionCoverageCell,
    kind: TypedAdmissionResponseKind,
    target: TypedAdmissionTarget,
) {
    assert_eq!(cell.action, InputAdmissionAction::Admit);
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let response_contract = typed_admission_contract(kind);
    let target_kind = if target == TypedAdmissionTarget::WrongKind {
        opposite_typed_admission_kind(kind)
    } else {
        kind
    };
    let wrong_kind_uses_focal = target == TypedAdmissionTarget::WrongKind
        && cell.state == interaction_admission_state(typed_admission_contract(target_kind));
    let auxiliary = if target == TypedAdmissionTarget::Current || wrong_kind_uses_focal {
        None
    } else {
        Some(
            reach_interaction_probe(
                &mut fixture,
                backend_kind,
                typed_admission_contract(target_kind),
            )
            .await,
        )
    };
    if target == TypedAdmissionTarget::Stale {
        complete_typed_admission_probe(
            &mut fixture,
            auxiliary.as_ref().unwrap(),
            target_kind,
            "make typed-admission identifier stale",
        )
        .await;
    }

    let run = reach_input_admission_state(&mut fixture, backend_kind, cell).await;
    let stimulus = ContractStimulus::UserResponds;
    ambient_before_stimulus(
        &mut fixture,
        &run.stream,
        &run.background_tool_ids,
        cell.activity,
        stimulus,
        "typed-admission ambient work before response",
    )
    .await;

    let matching_current = target == TypedAdmissionTarget::Current
        && run.state == interaction_admission_state(response_contract);
    assert_eq!(
        wrong_kind_uses_focal,
        target == TypedAdmissionTarget::WrongKind
            && run.state == interaction_admission_state(typed_admission_contract(target_kind)),
        "input-admission setup reached a different state than its selected cell"
    );
    let target_tool_call_id = if matching_current || wrong_kind_uses_focal {
        run.interaction_tool_call_id
            .clone()
            .expect("current interaction response omitted focal tool id")
    } else if target == TypedAdmissionTarget::Current {
        run.interaction_tool_call_id
            .clone()
            .unwrap_or_else(|| format!("CURRENT_NON_INTERACTION_{}", Uuid::new_v4().simple()))
    } else {
        auxiliary
            .as_ref()
            .expect("non-current interaction target omitted auxiliary probe")
            .tool_call_id
            .clone()
    };
    let marker = format!("INVALID_TYPED_ADMISSION_{}", Uuid::new_v4().simple());
    fixture
        .client
        .send_message_payload(
            &run.stream,
            typed_admission_payload(kind, target_tool_call_id.clone(), marker.clone()),
        )
        .await
        .expect("send typed admission response");
    ambient_during_stimulus(
        &mut fixture,
        &run.stream,
        &run.background_tool_ids,
        cell.activity,
        stimulus,
        "typed-admission ambient work during response",
    )
    .await;

    if matching_current {
        let completion = expect_tool_completion_for_id(
            &mut fixture.client,
            &run.stream,
            &target_tool_call_id,
            "matching current typed admission response",
        )
        .await;
        assert!(
            completion.success(),
            "matching current response failed: {completion:?}"
        );
    } else {
        let mut forbidden = HashSet::from([target_tool_call_id.clone()]);
        if let Some(focal) = &run.interaction_tool_call_id {
            forbidden.insert(focal.clone());
        }
        expect_exact_invalid_typed_admission_rejection(
            &mut fixture,
            &run.stream,
            &marker,
            &forbidden,
            "invalid typed input-admission response",
        )
        .await;
        recover_focal_input_admission_state(&mut fixture, &run, "typed admission focal recovery")
            .await;
    }

    if let Some(probe) = auxiliary
        && target != TypedAdmissionTarget::Stale
    {
        complete_typed_admission_probe(
            &mut fixture,
            &probe,
            target_kind,
            "typed admission auxiliary recovery",
        )
        .await;
    }
    ambient_after_stimulus(
        &mut fixture,
        &run.stream,
        &run.background_tool_ids,
        cell.activity,
        stimulus,
        "typed-admission ambient work after response",
    )
    .await;
}

async fn run_input_admission_cell(
    backend_kind: BackendKind,
    cell: InputAdmissionCoverageCell,
    cardinality_matrix: bool,
) {
    eprintln!("INPUT ADMISSION CELL {backend_kind:?} {cell:?}");
    if let Some((kind, target)) = typed_admission_axes(cell.input) {
        assert!(
            !cardinality_matrix,
            "typed response admission cells are not connection-cardinality cells"
        );
        run_typed_interaction_admission_cell(backend_kind, cell, kind, target).await;
        return;
    }
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let run = reach_input_admission_state(&mut fixture, backend_kind, cell).await;
    let stimulus = input_admission_stimulus(cell.action);
    ambient_before_stimulus(
        &mut fixture,
        &run.stream,
        &run.background_tool_ids,
        cell.activity,
        stimulus,
        "input-admission ambient work before action",
    )
    .await;
    if cell.input == InputAdmissionKind::InteractionResponse {
        let tool_call_id = run.interaction_tool_call_id.clone().unwrap();
        let queued = "Without using tools, reply exactly 42.".to_owned();
        let edited = "Without using tools, reply exactly 44.".to_owned();
        let mut queued_id = None;
        if cell.action != InputAdmissionAction::Admit {
            fixture
                .client
                .send_message(&run.stream, queued.clone())
                .await
                .unwrap();
            queued_id =
                expect_queued_messages_exact(&mut fixture.client, &run.stream, &[queued.as_str()])
                    .await
                    .into_iter()
                    .next();
        }
        let mut response_stream = run.stream.clone();
        match cell.action {
            InputAdmissionAction::Admit | InputAdmissionAction::Enqueue => {}
            InputAdmissionAction::EditQueued => {
                fixture
                    .client
                    .edit_queued_message(
                        &run.stream,
                        EditQueuedMessagePayload {
                            id: queued_id.clone().unwrap(),
                            message: edited.clone(),
                            images: Vec::new(),
                        },
                    )
                    .await
                    .unwrap();
                expect_queued_messages_exact(&mut fixture.client, &run.stream, &[edited.as_str()])
                    .await;
            }
            InputAdmissionAction::CancelQueued => {
                fixture
                    .client
                    .cancel_queued_message(
                        &run.stream,
                        CancelQueuedMessagePayload {
                            id: queued_id.clone().unwrap(),
                        },
                    )
                    .await
                    .unwrap();
                expect_queued_messages_exact(&mut fixture.client, &run.stream, &[]).await;
            }
            InputAdmissionAction::ClientReconnect => {
                let reconnected = reconnect_input_admission_agent_through_all_cardinalities(
                    fixture,
                    &run.agent_id,
                )
                .await;
                fixture = reconnected.0;
                response_stream = reconnected.1;
                expect_queued_messages_exact(
                    &mut fixture.client,
                    &response_stream,
                    &[queued.as_str()],
                )
                .await;
            }
            InputAdmissionAction::HostRestart => {
                // The response is admitted first below, then host teardown races
                // its backend continuation while the separately queued input
                // must survive for resume.
            }
            InputAdmissionAction::BackgroundTerminal
            | InputAdmissionAction::BackgroundFailureTerminal => {}
            InputAdmissionAction::SendQueuedNow
            | InputAdmissionAction::Fork
            | InputAdmissionAction::TransportClosed
            | InputAdmissionAction::Close
            | InputAdmissionAction::InterruptThenSend => {}
        }
        send_input_admission_interaction_response(&mut fixture, &run, &response_stream).await;
        if cell.action == InputAdmissionAction::InterruptThenSend {
            fixture.client.interrupt(&response_stream).await.unwrap();
            ambient_during_stimulus(
                &mut fixture,
                &response_stream,
                &run.background_tool_ids,
                cell.activity,
                stimulus,
                "input-admission ambient work during interaction interrupt",
            )
            .await;
        }
        if !matches!(
            cell.action,
            InputAdmissionAction::HostRestart
                | InputAdmissionAction::Fork
                | InputAdmissionAction::TransportClosed
                | InputAdmissionAction::Close
                | InputAdmissionAction::InterruptThenSend
                | InputAdmissionAction::BackgroundTerminal
                | InputAdmissionAction::BackgroundFailureTerminal
        ) {
            ambient_during_stimulus(
                &mut fixture,
                &response_stream,
                &run.background_tool_ids,
                cell.activity,
                stimulus,
                "input-admission ambient work during interaction response",
            )
            .await;
        }
        if cell.action == InputAdmissionAction::HostRestart {
            let completion = expect_correlated_tool_completion(
                &mut fixture,
                &response_stream,
                &tool_call_id,
                "admitted interaction response before host restart",
            )
            .await;
            assert!(completion.success());
        }
        if cell.action == InputAdmissionAction::Close {
            fixture
                .client
                .close_agent(&response_stream)
                .await
                .expect("close racing admitted interaction response");
            ambient_during_stimulus(
                &mut fixture,
                &response_stream,
                &run.background_tool_ids,
                cell.activity,
                stimulus,
                "input-admission ambient work during close",
            )
            .await;
            let mut completed = 0usize;
            tokio::time::timeout(Duration::from_secs(120), async {
                loop {
                    let envelope =
                        expect_next_event(&mut fixture.client, "interaction response close race")
                            .await;
                    if envelope.kind == FrameKind::ChatEvent
                        && envelope.stream == response_stream
                        && let ChatEvent::ToolExecutionCompleted(completion) =
                            envelope.parse_payload::<ChatEvent>().unwrap()
                        && completion.tool_call_id == tool_call_id
                    {
                        assert!(completion.success());
                        completed += 1;
                        assert_eq!(completed, 1);
                    }
                    if envelope.kind == FrameKind::AgentClosed {
                        let closed: protocol::AgentClosedPayload =
                            envelope.parse_payload().unwrap();
                        if closed.agent_id == run.agent_id {
                            assert_eq!(
                                completed, 1,
                                "close overtook the admitted interaction response"
                            );
                            break;
                        }
                    }
                }
            })
            .await
            .expect("interaction response/close race never reached AgentClosed");
            return;
        }
        if cell.action == InputAdmissionAction::Fork {
            let fork_stream = fork_agent_via_protocol(
                &mut fixture.client,
                "fork-input-admission",
                run.agent_id.clone(),
                run.session_id.clone(),
                "Do not use tools. Reply exactly FORK_INPUT_ADMISSION_OK.",
            )
            .await;
            ambient_during_stimulus(
                &mut fixture,
                &response_stream,
                &run.background_tool_ids,
                cell.activity,
                stimulus,
                "input-admission ambient work during fork",
            )
            .await;
            let fork_turn = expect_assistant_turn_after_user_echo(
                &mut fixture.client,
                &fork_stream,
                "Do not use tools. Reply exactly FORK_INPUT_ADMISSION_OK.",
            )
            .await;
            assert!(fork_turn.final_text.contains("FORK_INPUT_ADMISSION_OK"));
            expect_queued_messages_exact(&mut fixture.client, &response_stream, &[queued.as_str()])
                .await;
            fixture.client.close_agent(&fork_stream).await.unwrap();
        }
        if cell.action == InputAdmissionAction::TransportClosed {
            assert!(
                fixture
                    .host
                    .force_agent_backend_shutdown_for_conformance(&run.agent_id)
                    .await
            );
            ambient_during_stimulus(
                &mut fixture,
                &response_stream,
                &run.background_tool_ids,
                cell.activity,
                stimulus,
                "input-admission ambient work during transport close",
            )
            .await;
        }
        if cell.action == InputAdmissionAction::HostRestart {
            fixture.host.shutdown_agents_for_conformance().await;
            ambient_during_stimulus(
                &mut fixture,
                &response_stream,
                &run.background_tool_ids,
                cell.activity,
                stimulus,
                "input-admission ambient work during host restart",
            )
            .await;
            let (resumed, resumed_messages, bootstrap_events) =
                resume_input_admission_agent(&mut fixture, &run).await;
            eprintln!("INPUT ADMISSION RESTART BOOTSTRAP {bootstrap_events:#?}");
            assert_eq!(
                resumed_messages.len(),
                1,
                "restart lost or duplicated queued input"
            );
            assert_eq!(resumed_messages[0].message, queued);
            assert!(resumed_messages[0].images.is_empty());
            let completed = bootstrap_events.iter().any(|event| {
                matches!(
                    event,
                    AgentBootstrapEvent::ChatEvent(ChatEvent::ToolExecutionCompleted(completion))
                        if completion.tool_call_id == tool_call_id && completion.success()
                )
            });
            let continued = bootstrap_events.iter().any(|event| {
                matches!(
                    event,
                    AgentBootstrapEvent::ChatEvent(ChatEvent::StreamEnd(end))
                        if end.message.content.contains("USER_QUESTION_ANSWER_OK_BLUE")
                            || end.message.content.contains("PLAN_APPROVAL_OK")
                )
            });
            assert!(
                completed || continued,
                "restart lost every durable effect of the admitted interaction response"
            );
            response_stream = resumed;
        }
        if cell.action == InputAdmissionAction::SendQueuedNow {
            fixture
                .client
                .send_queued_message_now(
                    &response_stream,
                    SendQueuedMessageNowPayload {
                        id: queued_id.clone().unwrap(),
                    },
                )
                .await
                .unwrap();
        }
        let completion = if cell.action == InputAdmissionAction::HostRestart {
            None
        } else if matches!(
            cell.action,
            InputAdmissionAction::BackgroundTerminal
                | InputAdmissionAction::BackgroundFailureTerminal
        ) {
            release_question_background_work(&fixture, run.background_tool_ids.len());
            Some(
                expect_interaction_with_background_terminal(
                    &mut fixture,
                    &response_stream,
                    &tool_call_id,
                    &run.background_tool_ids,
                    if cell.action == InputAdmissionAction::BackgroundTerminal {
                        ExpectedBackgroundOutcome::Succeeded
                    } else {
                        ExpectedBackgroundOutcome::Failed
                    },
                )
                .await,
            )
        } else {
            Some(
                expect_correlated_tool_completion(
                    &mut fixture,
                    &response_stream,
                    &tool_call_id,
                    "input-admission interaction response",
                )
                .await,
            )
        };
        if let Some(completion) = completion {
            assert!(
                completion.success(),
                "interaction response was not consumed: {completion:?}"
            );
        }
        ambient_after_stimulus(
            &mut fixture,
            &response_stream,
            &run.background_tool_ids,
            cell.activity,
            stimulus,
            "input-admission ambient work after interaction response",
        )
        .await;
        if !matches!(
            cell.action,
            InputAdmissionAction::Admit
                | InputAdmissionAction::CancelQueued
                | InputAdmissionAction::TransportClosed
        ) {
            let (prompt, marker) = if cell.action == InputAdmissionAction::EditQueued {
                (&edited, "44")
            } else {
                (&queued, "42")
            };
            expect_admitted_turn(&mut fixture, &response_stream, prompt, marker).await;
        }
        return;
    }
    let first_marker = "42".to_owned();
    let mut first = "Without using tools, reply exactly 42.".to_owned();
    let mut second_marker = "43".to_owned();
    let mut second = "Without using tools, reply exactly 43.".to_owned();
    let image_input = matches!(
        cell.input,
        InputAdmissionKind::ImageMessage | InputAdmissionKind::MultipleImageMessages
    );
    let multiple = matches!(
        cell.input,
        InputAdmissionKind::MultipleMessages | InputAdmissionKind::MultipleImageMessages
    );
    let red_image = ImageData {
        media_type: "image/png".to_owned(),
        data: SOLID_RED_PNG_BASE64.to_owned(),
    };
    let green_image = ImageData {
        media_type: "image/jpeg".to_owned(),
        data: SOLID_GREEN_JPEG_BASE64.to_owned(),
    };
    let initial_images = if cell.input == InputAdmissionKind::MultipleImageMessages {
        vec![red_image.clone(), red_image]
    } else if image_input {
        vec![red_image]
    } else {
        Vec::new()
    };
    let second_images = if cell.input == InputAdmissionKind::MultipleImageMessages {
        vec![green_image.clone()]
    } else {
        Vec::new()
    };
    if image_input {
        first = "Inspect the attached solid-color image or images. They are all the same color. Without tools or explanation, reply with only that color in uppercase.".to_owned();
    }
    if cell.input == InputAdmissionKind::MultipleImageMessages {
        second = "Inspect the attached solid-color image. Without tools or explanation, reply with only its color in uppercase.".to_owned();
        second_marker = "GREEN".to_owned();
    }
    let active = !matches!(
        run.state,
        InputAdmissionState::Idle | InputAdmissionState::BackgroundOnlyIdle
    );
    if image_input {
        fixture
            .client
            .send_message_payload(
                &run.stream,
                SendMessagePayload {
                    message: first.clone(),
                    images: Some(initial_images.clone()),
                    origin: None,
                    tool_response: None,
                },
            )
            .await
            .unwrap();
    } else {
        fixture
            .client
            .send_message(&run.stream, first.clone())
            .await
            .unwrap();
    }
    if !active {
        if multiple {
            if second_images.is_empty() {
                fixture
                    .client
                    .send_message(&run.stream, second.clone())
                    .await
                    .unwrap();
            } else {
                fixture
                    .client
                    .send_message_payload(
                        &run.stream,
                        SendMessagePayload {
                            message: second.clone(),
                            images: Some(second_images.clone()),
                            origin: None,
                            tool_response: None,
                        },
                    )
                    .await
                    .unwrap();
            }
        }
        ambient_during_stimulus(
            &mut fixture,
            &run.stream,
            &run.background_tool_ids,
            cell.activity,
            stimulus,
            "input-admission idle ambient work during admit",
        )
        .await;
        let expected = if image_input { "RED" } else { &first_marker };
        expect_admitted_payload_turn(&mut fixture, &run.stream, &first, expected, &initial_images)
            .await;
        if multiple {
            expect_admitted_payload_turn(
                &mut fixture,
                &run.stream,
                &second,
                &second_marker,
                &second_images,
            )
            .await;
        }
        ambient_after_stimulus(
            &mut fixture,
            &run.stream,
            &run.background_tool_ids,
            cell.activity,
            stimulus,
            "input-admission idle ambient work after admit",
        )
        .await;
        for release in &run.release_paths {
            let _ = std::fs::write(release, b"release");
        }
        return;
    }
    let mut ids = if image_input {
        vec![
            expect_queued_image_exact(&mut fixture.client, &run.stream, &first, &initial_images)
                .await,
        ]
    } else {
        expect_queued_messages_exact(&mut fixture.client, &run.stream, &[&first]).await
    };
    if multiple {
        if second_images.is_empty() {
            fixture
                .client
                .send_message(&run.stream, second.clone())
                .await
                .unwrap();
        } else {
            fixture
                .client
                .send_message_payload(
                    &run.stream,
                    SendMessagePayload {
                        message: second.clone(),
                        images: Some(second_images.clone()),
                        origin: None,
                        tool_response: None,
                    },
                )
                .await
                .unwrap();
        }
        ids = expect_queued_payloads_exact(
            &mut fixture.client,
            &run.stream,
            &[
                (first.as_str(), initial_images.as_slice()),
                (second.as_str(), second_images.as_slice()),
            ],
        )
        .await;
    }
    match cell.action {
        InputAdmissionAction::EditQueued => {
            let edited_marker = if image_input { "GREEN" } else { "44" }.to_owned();
            let edited = if image_input {
                first.clone()
            } else {
                "Without using tools, reply exactly 44.".to_owned()
            };
            let edited_images = if image_input {
                vec![ImageData {
                    media_type: "image/jpeg".to_owned(),
                    data: SOLID_GREEN_JPEG_BASE64.to_owned(),
                }]
            } else {
                Vec::new()
            };
            fixture
                .client
                .edit_queued_message(
                    &run.stream,
                    EditQueuedMessagePayload {
                        id: ids[0].clone(),
                        message: edited.clone(),
                        images: edited_images.clone(),
                    },
                )
                .await
                .unwrap();
            if image_input && multiple {
                expect_queued_payloads_exact(
                    &mut fixture.client,
                    &run.stream,
                    &[
                        (edited.as_str(), edited_images.as_slice()),
                        (second.as_str(), second_images.as_slice()),
                    ],
                )
                .await;
            } else if image_input {
                expect_queued_image_exact(
                    &mut fixture.client,
                    &run.stream,
                    &edited,
                    &edited_images,
                )
                .await;
            } else if multiple {
                expect_queued_messages_exact(&mut fixture.client, &run.stream, &[&edited, &second])
                    .await;
            } else {
                expect_queued_messages_exact(&mut fixture.client, &run.stream, &[&edited]).await;
            }
            settle_input_admission_ambient(
                &mut fixture,
                &run,
                cell.activity,
                stimulus,
                "input-admission edit queued",
            )
            .await;
            finish_active_admission_state(&mut fixture, &run).await;
            expect_admitted_payload_turn(
                &mut fixture,
                &run.stream,
                &edited,
                &edited_marker,
                &edited_images,
            )
            .await;
            if multiple {
                expect_admitted_payload_turn(
                    &mut fixture,
                    &run.stream,
                    &second,
                    &second_marker,
                    &second_images,
                )
                .await;
            }
        }
        InputAdmissionAction::CancelQueued => {
            fixture
                .client
                .cancel_queued_message(
                    &run.stream,
                    CancelQueuedMessagePayload { id: ids[0].clone() },
                )
                .await
                .unwrap();
            if multiple {
                expect_queued_payloads_exact(
                    &mut fixture.client,
                    &run.stream,
                    &[(second.as_str(), second_images.as_slice())],
                )
                .await;
            } else {
                expect_queued_messages_exact(&mut fixture.client, &run.stream, &[]).await;
            }
            settle_input_admission_ambient(
                &mut fixture,
                &run,
                cell.activity,
                stimulus,
                "input-admission cancel queued",
            )
            .await;
            finish_active_admission_state(&mut fixture, &run).await;
            if multiple {
                expect_admitted_payload_turn(
                    &mut fixture,
                    &run.stream,
                    &second,
                    &second_marker,
                    &second_images,
                )
                .await;
            }
        }
        InputAdmissionAction::SendQueuedNow => {
            fixture
                .client
                .send_queued_message_now(
                    &run.stream,
                    SendQueuedMessageNowPayload { id: ids[0].clone() },
                )
                .await
                .unwrap();
            settle_input_admission_ambient(
                &mut fixture,
                &run,
                cell.activity,
                stimulus,
                "input-admission send queued now",
            )
            .await;
            let expected = if image_input { "RED" } else { &first_marker };
            expect_admitted_payload_turn(
                &mut fixture,
                &run.stream,
                &first,
                expected,
                &initial_images,
            )
            .await;
            if multiple {
                expect_admitted_payload_turn(
                    &mut fixture,
                    &run.stream,
                    &second,
                    &second_marker,
                    &second_images,
                )
                .await;
            }
        }
        InputAdmissionAction::InterruptThenSend => {
            finish_active_admission_state(&mut fixture, &run).await;
            settle_input_admission_ambient(
                &mut fixture,
                &run,
                cell.activity,
                stimulus,
                "input-admission interrupt",
            )
            .await;
            let expected = if image_input { "RED" } else { &first_marker };
            expect_admitted_payload_turn(
                &mut fixture,
                &run.stream,
                &first,
                expected,
                &initial_images,
            )
            .await;
            if multiple {
                expect_admitted_payload_turn(
                    &mut fixture,
                    &run.stream,
                    &second,
                    &second_marker,
                    &second_images,
                )
                .await;
            }
        }
        InputAdmissionAction::ClientReconnect => {
            let reconnected =
                reconnect_input_admission_agent_through_all_cardinalities(fixture, &run.agent_id)
                    .await;
            fixture = reconnected.0;
            let reconnected_stream = reconnected.1;
            ambient_during_stimulus(
                &mut fixture,
                &reconnected_stream,
                &run.background_tool_ids,
                cell.activity,
                stimulus,
                "input-admission reconnect",
            )
            .await;
            ambient_after_stimulus(
                &mut fixture,
                &reconnected_stream,
                &run.background_tool_ids,
                cell.activity,
                stimulus,
                "input-admission reconnect",
            )
            .await;
            if multiple {
                expect_queued_payloads_exact(
                    &mut fixture.client,
                    &reconnected_stream,
                    &[
                        (first.as_str(), initial_images.as_slice()),
                        (second.as_str(), second_images.as_slice()),
                    ],
                )
                .await;
            } else if image_input {
                expect_queued_image_exact(
                    &mut fixture.client,
                    &reconnected_stream,
                    &first,
                    &initial_images,
                )
                .await;
            } else {
                expect_queued_messages_exact(&mut fixture.client, &reconnected_stream, &[&first])
                    .await;
            }
            fixture.client.interrupt(&reconnected_stream).await.unwrap();
            let expected = if image_input { "RED" } else { &first_marker };
            expect_admitted_payload_turn(
                &mut fixture,
                &reconnected_stream,
                &first,
                expected,
                &initial_images,
            )
            .await;
            if multiple {
                expect_admitted_payload_turn(
                    &mut fixture,
                    &reconnected_stream,
                    &second,
                    &second_marker,
                    &second_images,
                )
                .await;
            }
        }
        InputAdmissionAction::HostRestart => {
            fixture.host.shutdown_agents_for_conformance().await;
            ambient_during_stimulus(
                &mut fixture,
                &run.stream,
                &run.background_tool_ids,
                cell.activity,
                stimulus,
                "input-admission ambient work during host restart",
            )
            .await;
            let (resumed, resumed_messages, _) =
                resume_input_admission_agent(&mut fixture, &run).await;
            let expected = if multiple {
                vec![first.as_str(), second.as_str()]
            } else {
                vec![first.as_str()]
            };
            assert_eq!(
                resumed_messages
                    .iter()
                    .map(|message| message.message.as_str())
                    .collect::<Vec<_>>(),
                expected
            );
            if image_input {
                assert_eq!(resumed_messages[0].images, initial_images);
            }
            if multiple {
                assert_eq!(resumed_messages[1].images, second_images);
            }
            fixture
                .client
                .send_queued_message_now(
                    &resumed,
                    SendQueuedMessageNowPayload {
                        id: resumed_messages[0].id.clone(),
                    },
                )
                .await
                .unwrap();
            let expected = if image_input { "RED" } else { &first_marker };
            expect_admitted_payload_turn(&mut fixture, &resumed, &first, expected, &initial_images)
                .await;
            if multiple {
                expect_admitted_payload_turn(
                    &mut fixture,
                    &resumed,
                    &second,
                    &second_marker,
                    &second_images,
                )
                .await;
            }
        }
        InputAdmissionAction::Fork => {
            let fork_stream = fork_agent_via_protocol(
                &mut fixture.client,
                "fork-queued-input-admission",
                run.agent_id.clone(),
                run.session_id.clone(),
                "Do not use tools. Reply exactly FORK_INPUT_ADMISSION_OK.",
            )
            .await;
            settle_input_admission_ambient(
                &mut fixture,
                &run,
                cell.activity,
                stimulus,
                "input-admission fork",
            )
            .await;
            let fork_turn = expect_assistant_turn_after_user_echo(
                &mut fixture.client,
                &fork_stream,
                "Do not use tools. Reply exactly FORK_INPUT_ADMISSION_OK.",
            )
            .await;
            assert!(fork_turn.final_text.contains("FORK_INPUT_ADMISSION_OK"));
            if multiple {
                expect_queued_payloads_exact(
                    &mut fixture.client,
                    &run.stream,
                    &[
                        (first.as_str(), initial_images.as_slice()),
                        (second.as_str(), second_images.as_slice()),
                    ],
                )
                .await;
            } else if image_input {
                expect_queued_image_exact(
                    &mut fixture.client,
                    &run.stream,
                    &first,
                    &initial_images,
                )
                .await;
            } else {
                expect_queued_messages_exact(&mut fixture.client, &run.stream, &[&first]).await;
            }
            fixture.client.close_agent(&fork_stream).await.unwrap();
            finish_active_admission_state(&mut fixture, &run).await;
            let expected = if image_input { "RED" } else { &first_marker };
            expect_admitted_payload_turn(
                &mut fixture,
                &run.stream,
                &first,
                expected,
                &initial_images,
            )
            .await;
            if multiple {
                expect_admitted_payload_turn(
                    &mut fixture,
                    &run.stream,
                    &second,
                    &second_marker,
                    &second_images,
                )
                .await;
            }
        }
        InputAdmissionAction::TransportClosed => {
            let active_stream = if cardinality_matrix {
                let reconnected = reconnect_input_admission_agent_through_all_cardinalities(
                    fixture,
                    &run.agent_id,
                )
                .await;
                fixture = reconnected.0;
                reconnected.1
            } else {
                run.stream.clone()
            };
            assert!(
                fixture
                    .host
                    .force_agent_backend_shutdown_for_conformance(&run.agent_id)
                    .await
            );
            ambient_during_stimulus(
                &mut fixture,
                &active_stream,
                &run.background_tool_ids,
                cell.activity,
                stimulus,
                "input-admission ambient work during transport close",
            )
            .await;
            tokio::time::timeout(Duration::from_secs(120), async {
                loop {
                    let envelope =
                        expect_next_event(&mut fixture.client, "queued input transport close")
                            .await;
                    if envelope.stream != active_stream {
                        continue;
                    }
                    match envelope.kind {
                        FrameKind::AgentError | FrameKind::AgentClosed => break,
                        FrameKind::ChatEvent => {
                            match envelope.parse_payload::<ChatEvent>().unwrap() {
                                ChatEvent::MessageAdded(ChatMessage {
                                    sender: MessageSender::Error,
                                    ..
                                }) => break,
                                ChatEvent::MessageAdded(ChatMessage {
                                    sender: MessageSender::User,
                                    content,
                                    ..
                                }) if content == first || content == second => panic!(
                                    "queued input was consumed after backend transport closed"
                                ),
                                _ => {}
                            }
                        }
                        _ => {}
                    }
                }
            })
            .await
            .expect("backend transport close was not visible");
        }
        InputAdmissionAction::Close => {
            fixture
                .client
                .close_agent(&run.stream)
                .await
                .expect("close queued input admission");
            settle_input_admission_ambient(
                &mut fixture,
                &run,
                cell.activity,
                stimulus,
                "input-admission close",
            )
            .await;
            tokio::time::timeout(Duration::from_secs(120), async {
                loop {
                    let envelope =
                        expect_next_event(&mut fixture.client, "close queued input admission")
                            .await;
                    if envelope.kind == FrameKind::ChatEvent && envelope.stream == run.stream {
                        if matches!(
                            envelope.parse_payload::<ChatEvent>().unwrap(),
                            ChatEvent::MessageAdded(ChatMessage {
                                sender: MessageSender::User,
                                ref content,
                                ..
                            }) if content == &first || content == &second
                        ) {
                            panic!("close consumed queued input before AgentClosed");
                        }
                        continue;
                    }
                    if envelope.kind == FrameKind::AgentClosed {
                        let closed: protocol::AgentClosedPayload =
                            envelope.parse_payload().unwrap();
                        if closed.agent_id == run.agent_id {
                            break;
                        }
                    }
                }
            })
            .await
            .expect("close queued input admission did not reach AgentClosed");
        }
        InputAdmissionAction::Admit | InputAdmissionAction::Enqueue => {
            settle_input_admission_ambient(
                &mut fixture,
                &run,
                cell.activity,
                stimulus,
                "input-admission admit or enqueue",
            )
            .await;
            finish_active_admission_state(&mut fixture, &run).await;
            let expected = if image_input { "RED" } else { &first_marker };
            expect_admitted_payload_turn(
                &mut fixture,
                &run.stream,
                &first,
                expected,
                &initial_images,
            )
            .await;
            if multiple {
                expect_admitted_payload_turn(
                    &mut fixture,
                    &run.stream,
                    &second,
                    &second_marker,
                    &second_images,
                )
                .await;
            }
        }
        InputAdmissionAction::BackgroundTerminal
        | InputAdmissionAction::BackgroundFailureTerminal => {
            panic!("background-terminal admission action is only valid for interaction responses")
        }
    }
}

async fn assert_input_admission_queue_matrix(backend_kind: BackendKind) {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let mut cells = InputAdmissionCoverageCell::required_for(&capabilities);
    let activity_filter = std::env::var("TYDE_CONFORMANCE_ADMISSION_ACTIVITY").ok();
    let state_filter = std::env::var("TYDE_CONFORMANCE_ADMISSION_STATE").ok();
    let input_filter = std::env::var("TYDE_CONFORMANCE_ADMISSION_INPUT").ok();
    let action_filter = std::env::var("TYDE_CONFORMANCE_ADMISSION_ACTION").ok();
    if activity_filter.is_some()
        || state_filter.is_some()
        || input_filter.is_some()
        || action_filter.is_some()
    {
        cells.retain(|cell| {
            activity_filter
                .as_ref()
                .is_none_or(|value| format!("{:?}", cell.activity).eq_ignore_ascii_case(value))
                && state_filter
                    .as_ref()
                    .is_none_or(|value| format!("{:?}", cell.state).eq_ignore_ascii_case(value))
                && input_filter
                    .as_ref()
                    .is_none_or(|value| format!("{:?}", cell.input).eq_ignore_ascii_case(value))
                && action_filter
                    .as_ref()
                    .is_none_or(|value| format!("{:?}", cell.action).eq_ignore_ascii_case(value))
        });
        assert!(
            !cells.is_empty(),
            "input-admission filter selected no cells"
        );
        for cell in cells {
            run_input_admission_cell(backend_kind, cell, false).await;
        }
        return;
    }
    let mut ledger = InputAdmissionCoverageLedger::for_capabilities(&capabilities);
    for cell in cells {
        run_input_admission_cell(backend_kind, cell, false).await;
        ledger.record(cell).unwrap();
    }
    ledger.finish().unwrap();
}

async fn assert_connection_cardinality_lifecycle_matrix(backend_kind: BackendKind) {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let state_filter = std::env::var("TYDE_CONFORMANCE_ADMISSION_STATE").ok();
    let activity_filter = std::env::var("TYDE_CONFORMANCE_ADMISSION_ACTIVITY").ok();
    let input_filter = std::env::var("TYDE_CONFORMANCE_ADMISSION_INPUT").ok();
    let action_filter = std::env::var("TYDE_CONFORMANCE_ADMISSION_ACTION").ok();
    let cells = InputAdmissionCoverageCell::required_for(&capabilities)
        .into_iter()
        .filter(|cell| {
            matches!(
                cell.action,
                InputAdmissionAction::ClientReconnect | InputAdmissionAction::TransportClosed
            )
        })
        .filter(|cell| {
            state_filter
                .as_ref()
                .is_none_or(|value| format!("{:?}", cell.state).eq_ignore_ascii_case(value))
                && activity_filter
                    .as_ref()
                    .is_none_or(|value| format!("{:?}", cell.activity).eq_ignore_ascii_case(value))
                && input_filter
                    .as_ref()
                    .is_none_or(|value| format!("{:?}", cell.input).eq_ignore_ascii_case(value))
                && action_filter
                    .as_ref()
                    .is_none_or(|value| format!("{:?}", cell.action).eq_ignore_ascii_case(value))
        })
        .collect::<Vec<_>>();
    assert!(
        !cells.is_empty(),
        "connection-cardinality filter selected no applicable lifecycle cells"
    );
    let execution = cells.clone();
    let mut ledger = EnumeratedCoverageLedger::new(cells, "connection-cardinality lifecycle");
    for cell in execution {
        run_input_admission_cell(backend_kind, cell, true).await;
        ledger.record(cell).unwrap();
    }
    ledger.finish().unwrap();
    if capabilities.contains(BackendCapability::BackgroundTasks) {
        assert_fixture_drop_reaps_real_background_process(backend_kind).await;
    }
}

async fn assert_fixture_drop_reaps_real_background_process(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let cell = InputAdmissionCoverageCell {
        activity: ActivityCondition::ForegroundOnly,
        state: InputAdmissionState::BackgroundOnlyIdle,
        input: InputAdmissionKind::PlainMessage,
        action: InputAdmissionAction::ClientReconnect,
    };
    let run = reach_input_admission_state(&mut fixture, backend_kind, cell).await;
    let marker = run
        .release_paths
        .first()
        .expect("background-only cleanup probe omitted its unique process marker")
        .to_string_lossy()
        .into_owned();
    let process_table = std::process::Command::new("ps")
        .args(["-axo", "command"])
        .output()
        .expect("inspect cleanup probe process table");
    assert!(
        String::from_utf8_lossy(&process_table.stdout).contains(&marker),
        "real background cleanup probe was not present in the process table: {marker}"
    );
    drop(fixture);
    await_real_backend_cleanup().await;
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let process_table = std::process::Command::new("ps")
                .args(["-axo", "command"])
                .output()
                .expect("inspect post-cleanup process table");
            if !String::from_utf8_lossy(&process_table.stdout).contains(&marker) {
                break;
            }
            tokio::time::sleep(Duration::from_millis(50)).await;
        }
    })
    .await
    .unwrap_or_else(|_| panic!("fixture cleanup left a real orphan process: {marker}"));
}

async fn expect_exact_cancelled_tool_request(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    tool_call_id: &str,
    context: &str,
) {
    let mut completion_count = 0usize;
    let mut cancellation_count = 0usize;
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, context).await;
            if envelope.kind == FrameKind::AgentError && envelope.stream == *stream {
                let error: protocol::AgentErrorPayload = envelope
                    .parse_payload()
                    .unwrap_or_else(|error| panic!("{context}: parse AgentError: {error:?}"));
                panic!(
                    "{context}: agent failed during interrupt: {}",
                    error.message
                );
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .unwrap_or_else(|error| panic!("{context}: parse ChatEvent: {error:?}"))
            {
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    completion_count += 1;
                    assert_eq!(
                        completion_count, 1,
                        "{context}: interrupted tool completed more than once"
                    );
                    assert!(
                        !completion.success(),
                        "{context}: interrupted tool succeeded"
                    );
                    assert!(
                        matches!(&completion.outcome, ToolExecutionOutcome::Cancelled { .. }),
                        "{context}: interrupted tool did not return Cancelled: {completion:?}"
                    );
                }
                ChatEvent::OperationCancelled(_) => {
                    assert_eq!(
                        completion_count, 1,
                        "{context}: OperationCancelled preceded tool cancellation"
                    );
                    cancellation_count += 1;
                    assert_eq!(
                        cancellation_count, 1,
                        "{context}: OperationCancelled was emitted more than once"
                    );
                }
                ChatEvent::TypingStatusChanged(false) => {
                    assert_eq!(
                        cancellation_count, 1,
                        "{context}: backend became idle before exact cancellation"
                    );
                    break;
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{context}: backend returned an error: {content}"),
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context}: exact cancellation sequence did not arrive"));
    assert_eq!(completion_count, 1);
    assert_eq!(cancellation_count, 1);
}

async fn reach_plan_approval_wait(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
) -> (
    StreamPath,
    SessionId,
    protocol::AgentId,
    String,
    HashSet<String>,
) {
    let activity_prompt = ambient_setup_instruction(backend_kind, activity, "PLAN_BACKGROUND");
    let plan_prompt = match backend_kind {
        BackendKind::Claude => {
            "Enter plan mode, write a one-step plan to inspect README.txt, then use ExitPlanMode exactly once to request approval"
        }
        BackendKind::Hermes => {
            "Use the terminal exactly once to run `printf '\\nHERMES_APPROVAL_PROBE\\n' >> README.txt`. Wait for the native approval request before the command runs"
        }
        _ => {
            "Enter the backend's native plan mode, write a one-step plan to inspect README.txt, then use the native exit-plan tool exactly once to request approval"
        }
    };
    let sequence = if activity == ActivityCondition::ForegroundOnly {
        format!("{plan_prompt} immediately.")
    } else {
        format!("After every background item reports Running, {plan_prompt}.")
    };
    let decision_prompt = match backend_kind {
        BackendKind::Claude => {
            "Wait for my decision. The ExitPlanMode tool result is the authoritative human decision. If the approving response includes an image, inspect it visually and reply exactly PLAN_APPROVAL_OK_RED_IMAGE when it is solid red. If there is no image, reply exactly PLAN_APPROVAL_OK. Do not use another tool, even if an automated background-task reminder says that reminder itself is not a user message."
        }
        _ => {
            "Wait for my decision. If the approving response includes an image, inspect it visually and reply exactly PLAN_APPROVAL_OK_RED_IMAGE when it is solid red. If approved without an image, reply exactly PLAN_APPROVAL_OK. Do not use another tool."
        }
    };
    let prompt = format!("{activity_prompt} {sequence} {decision_prompt}");
    let roots = fixture.workspace_roots();
    let (stream, start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "plan-approval-lifecycle",
        &prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let mut setup_trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        let mut tool_call_id = None;
        let mut ambient = AmbientWorkObservation::default();
        loop {
            let envelope = fixture
                .client
                .next_event()
                .await
                .expect("read plan approval lifecycle")
                .expect("plan approval connection closed");
            if envelope.kind == FrameKind::AgentError && envelope.stream == stream {
                let error: protocol::AgentErrorPayload =
                    envelope.parse_payload().expect("parse plan approval error");
                panic!(
                    "{backend_kind:?} plan approval setup failed: {}",
                    error.message
                );
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            let event = envelope
                .parse_payload::<ChatEvent>()
                .expect("parse plan approval event");
            setup_trace.push(format!("{event:?}"));
            match event {
                ChatEvent::ToolRequest(request) => {
                    let ToolRequestType::ExitPlanMode { plan, plan_path } = request.tool_type else {
                        continue;
                    };
                    ambient.assert_exact(activity, "plan approval provider acceptance");
                    assert_plan_approval_request_shape(fixture, plan, plan_path);
                    assert!(tool_call_id.replace(request.tool_call_id).is_none());
                }
                ChatEvent::ToolProgress(progress) => ambient.observe_running(&progress),
                ChatEvent::ToolExecutionCompleted(completion)
                    if tool_call_id.as_deref() == Some(completion.tool_call_id.as_str()) =>
                {
                    panic!(
                        "{backend_kind:?} completed ExitPlanMode before receiving a decision: {completion:?}"
                    )
                }
                ChatEvent::TypingStatusChanged(false) if tool_call_id.is_some() => {
                    break (
                        tool_call_id.expect("ExitPlanMode tool id"),
                        ambient.ids(),
                    );
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{backend_kind:?} plan approval setup failed: {content}"),
                _ => {}
            }
        }
    })
    .await
    .map(|(tool_call_id, background_ids)| {
        (
            stream,
            start.session_id.expect("plan approval session id"),
            start.agent_id,
            tool_call_id,
            background_ids,
        )
    })
    .unwrap_or_else(|_| {
        panic!(
            "{backend_kind:?} did not wait for plan approval under {activity:?}; trace:\n{}",
            setup_trace.join("\n")
        )
    })
}

async fn assert_plan_approval_answer_contract(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
    result: ToolResultVariant,
) -> Vec<ConformanceCoverageCell> {
    let (stream, _, _, tool_call_id, background_ids) =
        reach_plan_approval_wait(fixture, backend_kind, activity).await;
    let stimulus = ContractStimulus::UserResponds;
    ambient_before_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "plan decision ambient work before stimulus",
    )
    .await;

    let (message, decision, feedback, expected_decision) = match result {
        ToolResultVariant::PlanApprove => (
            "Approve the plan.",
            protocol::ExitPlanModeDecision::Approve,
            None,
            "approved",
        ),
        ToolResultVariant::PlanReject => (
            "Reject the plan.",
            protocol::ExitPlanModeDecision::Reject,
            None,
            "rejected",
        ),
        ToolResultVariant::PlanRejectWithFeedback => (
            "Reject the plan with feedback.",
            protocol::ExitPlanModeDecision::Reject,
            Some("Add a rollback step.".to_owned()),
            "rejected",
        ),
        _ => panic!("non-decision result passed to plan answer runner: {result:?}"),
    };
    fixture
        .client
        .send_message_payload(
            &stream,
            SendMessagePayload {
                message: message.to_owned(),
                images: None,
                origin: None,
                tool_response: Some(SendMessageToolResponse::ExitPlanMode {
                    tool_call_id: tool_call_id.clone(),
                    decision,
                    feedback: feedback.clone(),
                }),
            },
        )
        .await
        .expect("approve plan");
    let mut decision_echoes = 0usize;
    if background_terminal_during_stimulus(activity) {
        let mut collector = BufferedEventCollector::new(&mut fixture.client);
        tokio::time::timeout(Duration::from_secs(30), async {
            while decision_echoes == 0 {
                let envelope = collector.next("plan decision admission").await;
                if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                    collector.defer(envelope);
                    continue;
                }
                match envelope.parse_payload::<ChatEvent>().unwrap() {
                    ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::User,
                        content,
                        ..
                    }) if content == message => decision_echoes += 1,
                    ChatEvent::ToolExecutionCompleted(completion)
                        if completion.tool_call_id == tool_call_id =>
                    {
                        panic!("{backend_kind:?} completed plan approval before decision admission")
                    }
                    _ => collector.defer(envelope),
                }
            }
        })
        .await
        .expect("plan decision was not admitted before background release");
        collector.restore();
        ambient_during_stimulus(
            fixture,
            &stream,
            &background_ids,
            activity,
            stimulus,
            "plan decision ambient work during stimulus",
        )
        .await;
    }

    let mut completion_count = 0usize;
    let mut saw_result = false;
    let mut saw_idle = false;
    let mut result_trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        while !(saw_result && saw_idle) {
            let envelope = fixture
                .client
                .next_event()
                .await
                .expect("read plan approval result")
                .expect("plan approval result connection closed");
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            let event = envelope
                .parse_payload::<ChatEvent>()
                .expect("parse plan approval result");
            result_trace.push(format!("{event:?}"));
            match event {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == message => decision_echoes += 1,
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    assert!(completion.success(), "plan approval failed: {completion:?}");
                    let ToolExecutionResult::Other { result: normalized } =
                        &completion.tool_result()
                    else {
                        panic!("plan response did not carry its normalized result: {completion:?}")
                    };
                    assert_eq!(
                        normalized
                            .get("decision")
                            .and_then(serde_json::Value::as_str),
                        Some(expected_decision)
                    );
                    assert_plan_approval_request_shape(
                        fixture,
                        normalized
                            .get("plan")
                            .and_then(Value::as_str)
                            .map(str::to_owned),
                        normalized
                            .get("plan_path")
                            .and_then(Value::as_str)
                            .map(str::to_owned),
                    );
                    if let Some(feedback) = feedback.as_deref() {
                        assert_eq!(
                            normalized
                                .get("feedback")
                                .and_then(serde_json::Value::as_str),
                            Some(feedback)
                        );
                    }
                    completion_count += 1;
                    assert_eq!(
                        completion_count, 1,
                        "plan approval completed more than once"
                    );
                }
                ChatEvent::StreamDelta(delta) => {
                    saw_result |= delta.text.contains("PLAN_APPROVAL_OK")
                        || result != ToolResultVariant::PlanApprove;
                }
                ChatEvent::StreamEnd(end) => {
                    saw_result |= end.message.content.contains("PLAN_APPROVAL_OK")
                        || result != ToolResultVariant::PlanApprove;
                }
                ChatEvent::TypingStatusChanged(false) if completion_count == 1 => saw_idle = true,
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{backend_kind:?} plan approval failed: {content}"),
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "{backend_kind:?} did not consume plan approval under {activity:?}; trace:\n{}",
            result_trace.join("\n")
        )
    });
    assert_eq!(decision_echoes, 1, "plan decision was not consumed once");
    assert_eq!(completion_count, 1);

    ambient_after_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "plan decision ambient work after stimulus",
    )
    .await;

    fixture
        .client
        .close_agent(&stream)
        .await
        .expect("close plan approval agent");
    {
        let mut cells = vec![observed_cell(
            SpecialToolContract::ExitPlanMode,
            ToolInputVariant::PlanApproval,
            result,
            activity,
            ContractState::WaitingForUser,
            ContractStimulus::UserResponds,
            ContractOutcome::Completed,
        )];
        if result == ToolResultVariant::PlanApprove {
            cells.push(observed_cell(
                SpecialToolContract::ExitPlanMode,
                ToolInputVariant::PlanApproval,
                ToolResultVariant::Pending,
                activity,
                ContractState::Requested,
                ContractStimulus::ProviderAccepts,
                ContractOutcome::WaitingForUser,
            ));
        }
        cells
    }
}

async fn complete_pending_plan_for_probe(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    tool_call_id: &str,
) {
    fixture
        .client
        .send_message_payload(
            stream,
            SendMessagePayload {
                message: "Approve the plan.".to_owned(),
                images: None,
                origin: None,
                tool_response: Some(SendMessageToolResponse::ExitPlanMode {
                    tool_call_id: tool_call_id.to_owned(),
                    decision: protocol::ExitPlanModeDecision::Approve,
                    feedback: None,
                }),
            },
        )
        .await
        .expect("approve plan while arranging response probe");
    tokio::time::timeout(Duration::from_secs(120), async {
        let mut completed = false;
        let mut continued = false;
        loop {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    assert!(completion.success());
                    assert!(!completed, "plan probe completed more than once");
                    let ToolExecutionResult::Other { result: normalized } =
                        &completion.tool_result()
                    else {
                        panic!("plan probe completion was not normalized: {completion:?}")
                    };
                    assert_eq!(
                        normalized.get("decision").and_then(Value::as_str),
                        Some("approved")
                    );
                    assert_plan_approval_request_shape(
                        fixture,
                        normalized
                            .get("plan")
                            .and_then(Value::as_str)
                            .map(str::to_owned),
                        normalized
                            .get("plan_path")
                            .and_then(Value::as_str)
                            .map(str::to_owned),
                    );
                    completed = true;
                }
                ChatEvent::StreamDelta(delta) => {
                    continued |= delta.text.contains("PLAN_APPROVAL_OK");
                }
                ChatEvent::StreamEnd(end) => {
                    continued |= end.message.content.contains("PLAN_APPROVAL_OK");
                }
                ChatEvent::TypingStatusChanged(false) if completed && continued => break,
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("plan probe setup failed: {content}"),
                _ => {}
            }
        }
    })
    .await
    .expect("plan probe setup did not complete the pending request");
}

async fn assert_plan_approval_wrong_id_contract(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
) -> Vec<ConformanceCoverageCell> {
    let (stream, _, _, tool_call_id, background_ids) =
        reach_plan_approval_wait(fixture, backend_kind, activity).await;
    let stimulus = ContractStimulus::UserResponds;
    ambient_before_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "wrong-id plan response ambient work before stimulus",
    )
    .await;
    fixture
        .client
        .send_message_payload(
            &stream,
            SendMessagePayload {
                message: String::new(),
                images: None,
                origin: None,
                tool_response: Some(SendMessageToolResponse::ExitPlanMode {
                    tool_call_id: format!("{tool_call_id}-wrong"),
                    decision: protocol::ExitPlanModeDecision::Approve,
                    feedback: None,
                }),
            },
        )
        .await
        .expect("send wrong-id plan response");
    ambient_during_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "wrong-id plan response ambient work during stimulus",
    )
    .await;
    let mut collector = BufferedEventCollector::new(&mut fixture.client);
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope = collector.next("wrong-id plan response rejection").await;
            if envelope.stream != stream {
                collector.defer(envelope);
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                let error: protocol::AgentErrorPayload = envelope
                    .parse_payload()
                    .expect("parse wrong-id plan response AgentError");
                assert!(
                    error.message.to_ascii_lowercase().contains("stale")
                        || error.message.contains("No matching pending tool request"),
                    "wrong-id plan response produced the wrong rejection: {}",
                    error.message
                );
                break;
            }
            if envelope.kind == FrameKind::ChatEvent {
                match envelope
                    .parse_payload::<ChatEvent>()
                    .expect("parse wrong-id plan response event")
                {
                    ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::Error,
                        content,
                        ..
                    }) => {
                        assert!(
                            content.to_ascii_lowercase().contains("stale")
                                || content.contains("No matching pending tool request"),
                            "wrong-id plan response produced the wrong rejection: {content}"
                        );
                        break;
                    }
                    ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::User,
                        content,
                        ..
                    }) => panic!("wrong-id plan response was consumed as user input: {content:?}"),
                    ChatEvent::ToolExecutionCompleted(completion)
                        if completion.tool_call_id == tool_call_id =>
                    {
                        panic!("wrong-id plan response completed the pending request")
                    }
                    _ => collector.defer(envelope),
                }
            } else {
                collector.defer(envelope);
            }
        }
    })
    .await
    .expect("wrong-id plan response was not visibly rejected");
    collector.restore();
    ambient_after_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "wrong-id plan response ambient work after stimulus",
    )
    .await;
    complete_pending_plan_for_probe(fixture, &stream, &tool_call_id).await;
    fixture.client.close_agent(&stream).await.unwrap();
    vec![observed_cell(
        SpecialToolContract::ExitPlanMode,
        ToolInputVariant::PlanApproval,
        ToolResultVariant::PlanWrongToolIdResponse,
        activity,
        ContractState::WaitingForUser,
        ContractStimulus::UserResponds,
        ContractOutcome::RejectedVisiblyAndRemainsWaiting,
    )]
}

