async fn assert_plan_approval_stale_response_contract(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
) -> Vec<ConformanceCoverageCell> {
    let (stream, _, _, tool_call_id, background_ids) =
        reach_plan_approval_wait(fixture, backend_kind, activity).await;
    complete_pending_plan_for_probe(fixture, &stream, &tool_call_id).await;
    let stimulus = ContractStimulus::UserRespondsAgain;
    ambient_before_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "stale plan response ambient work before stimulus",
    )
    .await;
    fixture
        .client
        .send_message_payload(
            &stream,
            SendMessagePayload {
                message: String::new(),
                images: None,
                origin: None,
                tool_response: Some(SendMessageToolResponse::ExitPlanMode {
                    tool_call_id: tool_call_id.clone(),
                    decision: protocol::ExitPlanModeDecision::Approve,
                    feedback: None,
                }),
            },
        )
        .await
        .expect("send stale plan response");
    ambient_during_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "stale plan response ambient work during stimulus",
    )
    .await;
    let mut rejection_count = 0usize;
    let mut collector = BufferedEventCollector::new(&mut fixture.client);
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope = collector.next("stale plan response rejection").await;
            if envelope.stream != stream {
                collector.defer(envelope);
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                let error: protocol::AgentErrorPayload = envelope
                    .parse_payload()
                    .expect("parse stale plan response AgentError");
                assert!(
                    error.message.contains("No matching pending tool request")
                        || error.message.to_ascii_lowercase().contains("stale"),
                    "stale plan response produced the wrong visible rejection: {}",
                    error.message
                );
                rejection_count += 1;
                break;
            }
            if envelope.kind != FrameKind::ChatEvent {
                collector.defer(envelope);
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .expect("parse stale plan response event")
            {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) => panic!("stale plan response was consumed as user input: {content:?}"),
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => {
                    assert!(
                        content.contains("No matching pending tool request")
                            || content.to_ascii_lowercase().contains("stale"),
                        "stale plan response produced the wrong visible rejection: {content}"
                    );
                    rejection_count += 1;
                    break;
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    panic!("stale plan response completed the terminal request again")
                }
                _ => collector.defer(envelope),
            }
        }
    })
    .await
    .expect("stale plan response was not visibly rejected");
    assert_eq!(
        rejection_count, 1,
        "stale plan response was not rejected once"
    );
    let quiet_until = Instant::now() + Duration::from_millis(250);
    while Instant::now() < quiet_until {
        let remaining = quiet_until.saturating_duration_since(Instant::now());
        let Ok(envelope) = tokio::time::timeout(
            remaining,
            collector.next("stale plan response post-rejection observation"),
        )
        .await
        else {
            break;
        };
        if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
            collector.defer(envelope);
            continue;
        }
        match envelope
            .parse_payload::<ChatEvent>()
            .expect("parse stale plan response post-rejection event")
        {
            ChatEvent::MessageAdded(ChatMessage {
                sender: MessageSender::User,
                content,
                ..
            }) => panic!("stale plan response was consumed after rejection: {content:?}"),
            ChatEvent::ToolExecutionCompleted(completion)
                if completion.tool_call_id == tool_call_id =>
            {
                panic!("stale plan response completed the terminal request again")
            }
            ChatEvent::MessageAdded(ChatMessage {
                sender: MessageSender::Error,
                content,
                ..
            }) if content.contains("No matching pending tool request")
                || content.to_ascii_lowercase().contains("stale") =>
            {
                panic!("stale plan response was rejected more than once")
            }
            _ => collector.defer(envelope),
        }
    }
    collector.restore();
    ambient_after_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "stale plan response ambient work after stimulus",
    )
    .await;
    fixture.client.close_agent(&stream).await.unwrap();
    vec![observed_cell(
        SpecialToolContract::ExitPlanMode,
        ToolInputVariant::PlanApproval,
        ToolResultVariant::PlanStaleResponse,
        activity,
        ContractState::Terminal,
        ContractStimulus::UserRespondsAgain,
        ContractOutcome::RejectedVisiblyNotConsumed,
    )]
}

async fn assert_plan_approval_wait_contract(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
) -> Vec<ConformanceCoverageCell> {
    let (stream, _, _, tool_call_id, background_ids) =
        reach_plan_approval_wait(fixture, backend_kind, activity).await;
    let stimulus = ContractStimulus::TimeoutExpires;
    ambient_before_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "plan timeout ambient work before stimulus",
    )
    .await;
    if background_terminal_during_stimulus(activity) {
        tokio::time::sleep(Duration::from_secs(2)).await;
        ambient_during_stimulus(
            fixture,
            &stream,
            &background_ids,
            activity,
            stimulus,
            "plan timeout ambient work during stimulus",
        )
        .await;
    }
    let advanced = tokio::time::timeout(Duration::from_secs(5), async {
        loop {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    return true;
                }
                ChatEvent::TypingStatusChanged(true) | ChatEvent::StreamStart(_) => return true,
                _ => {}
            }
        }
    })
    .await;
    assert!(
        advanced.is_err(),
        "{backend_kind:?} advanced without plan approval"
    );
    ambient_after_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "plan timeout ambient work after stimulus",
    )
    .await;
    fixture.client.close_agent(&stream).await.unwrap();
    vec![observed_cell(
        SpecialToolContract::ExitPlanMode,
        ToolInputVariant::PlanApproval,
        ToolResultVariant::Pending,
        activity,
        ContractState::WaitingForUser,
        ContractStimulus::TimeoutExpires,
        ContractOutcome::RemainsWaiting,
    )]
}

