async fn assert_plan_approval_reconnect_contract(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
) -> Vec<ConformanceCoverageCell> {
    let (source_stream, session_id, _, tool_call_id, background_ids) =
        reach_plan_approval_wait(fixture, backend_kind, activity).await;
    let stimulus = ContractStimulus::DisconnectReconnect;
    ambient_before_stimulus(
        fixture,
        &source_stream,
        &background_ids,
        activity,
        stimulus,
        "plan reconnect ambient work before stimulus",
    )
    .await;
    let mut reconnected = fixture.connect().await;
    reconnected.inherit_live_trace_from(&fixture.client);
    std::mem::swap(&mut fixture.client, &mut reconnected);
    drop(reconnected);
    let mut stream = None;
    let mut replayed_request = false;
    tokio::time::timeout(Duration::from_secs(30), async {
        while !replayed_request {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind == FrameKind::HostBootstrap {
                let bootstrap: HostBootstrapPayload = envelope.parse_payload().unwrap();
                stream = Some(
                    bootstrap
                        .agents
                        .into_iter()
                        .find(|agent| agent.session_id.as_ref() == Some(&session_id))
                        .unwrap_or_else(|| {
                            panic!("{backend_kind:?} omitted pending plan agent on reconnect")
                        })
                        .instance_stream,
                );
                continue;
            }
            if envelope.kind != FrameKind::ChatEvent || stream.as_ref() != Some(&envelope.stream) {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolRequest(request) if request.tool_call_id == tool_call_id => {
                    assert!(matches!(
                        request.tool_type,
                        ToolRequestType::ExitPlanMode { .. }
                    ));
                    replayed_request = true;
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    panic!("{backend_kind:?} terminalized pending plan approval on reconnect")
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{backend_kind:?} did not replay plan approval on reconnect"));
    let stream = stream.expect("reconnected plan stream");
    ambient_during_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "plan reconnect ambient work during stimulus",
    )
    .await;
    ambient_after_stimulus(
        fixture,
        &stream,
        &background_ids,
        activity,
        stimulus,
        "plan reconnect ambient work after stimulus",
    )
    .await;
    fixture
        .client
        .send_message_payload(
            &stream,
            SendMessagePayload {
                message: "Approve the plan.".to_owned(),
                images: None,
                origin: None,
                tool_response: Some(SendMessageToolResponse::ExitPlanMode {
                    tool_call_id: tool_call_id.clone(),
                    decision: protocol::ExitPlanModeDecision::Approve,
                    feedback: None,
                }),
            },
        )
        .await
        .unwrap();
    let mut completion_count = 0usize;
    let mut result = false;
    let mut idle = false;
    tokio::time::timeout(Duration::from_secs(120), async {
        while !(result && idle) {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    assert!(completion.success());
                    completion_count += 1;
                }
                ChatEvent::StreamDelta(delta) => {
                    result |= delta.text.contains("PLAN_APPROVAL_OK");
                }
                ChatEvent::StreamEnd(end) => {
                    result |= end.message.content.contains("PLAN_APPROVAL_OK");
                }
                ChatEvent::TypingStatusChanged(false) if completion_count == 1 => idle = true,
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{backend_kind:?} did not consume approval after reconnect"));
    assert_eq!(completion_count, 1);
    fixture.client.close_agent(&stream).await.unwrap();
    vec![observed_cell(
        SpecialToolContract::ExitPlanMode,
        ToolInputVariant::PlanApproval,
        ToolResultVariant::Pending,
        activity,
        ContractState::WaitingForUser,
        ContractStimulus::DisconnectReconnect,
        ContractOutcome::RemainsWaiting,
    )]
}

async fn assert_plan_approval_not_copied_to_fork(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
) -> Vec<ConformanceCoverageCell> {
    let (source_stream, session_id, parent_agent_id, source_tool_call_id, background_ids) =
        reach_plan_approval_wait(fixture, backend_kind, activity).await;
    let stimulus = ContractStimulus::Fork;
    ambient_before_stimulus(
        fixture,
        &source_stream,
        &background_ids,
        activity,
        stimulus,
        "plan fork ambient work before stimulus",
    )
    .await;
    let fork_stream = fork_agent_via_protocol(
        &mut fixture.client,
        "fork-pending-plan",
        parent_agent_id,
        session_id,
        "Do not use tools. Reply exactly FORK_PENDING_INTERACTION_OK.",
    )
    .await;
    ambient_during_stimulus(
        fixture,
        &source_stream,
        &background_ids,
        activity,
        stimulus,
        "plan fork ambient work during stimulus",
    )
    .await;
    let mut result = false;
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != fork_stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolRequest(request)
                    if matches!(request.tool_type, ToolRequestType::ExitPlanMode { .. }) =>
                {
                    panic!("{backend_kind:?} copied pending plan approval into the fork")
                }
                ChatEvent::StreamDelta(delta) => {
                    result |= delta.text.contains("FORK_PENDING_INTERACTION_OK");
                }
                ChatEvent::StreamEnd(end) => {
                    result |= end.message.content.contains("FORK_PENDING_INTERACTION_OK");
                }
                ChatEvent::TypingStatusChanged(false) if result => break,
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{backend_kind:?} pending-plan fork did not run independently"));
    ambient_after_stimulus(
        fixture,
        &source_stream,
        &background_ids,
        activity,
        stimulus,
        "plan fork ambient work after stimulus",
    )
    .await;
    fixture
        .client
        .send_message_payload(
            &source_stream,
            SendMessagePayload {
                message: "Approve the source plan.".to_owned(),
                images: None,
                origin: None,
                tool_response: Some(SendMessageToolResponse::ExitPlanMode {
                    tool_call_id: source_tool_call_id.clone(),
                    decision: protocol::ExitPlanModeDecision::Approve,
                    feedback: None,
                }),
            },
        )
        .await
        .unwrap();
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != source_stream {
                continue;
            }
            if let ChatEvent::ToolExecutionCompleted(completion) =
                envelope.parse_payload::<ChatEvent>().unwrap()
                && completion.tool_call_id == source_tool_call_id
            {
                assert!(completion.success());
                break;
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{backend_kind:?} source plan approval was lost by fork"));
    fixture.client.close_agent(&source_stream).await.unwrap();
    fixture.client.close_agent(&fork_stream).await.unwrap();
    vec![observed_cell(
        SpecialToolContract::ExitPlanMode,
        ToolInputVariant::PlanApproval,
        ToolResultVariant::Pending,
        activity,
        ContractState::WaitingForUser,
        ContractStimulus::Fork,
        ContractOutcome::PendingInteractionNotCopied,
    )]
}

