async fn complete_question_response_events(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    tool_call_id: &str,
    expected_answer: &str,
) {
    tokio::time::timeout(Duration::from_secs(120), async {
        let mut user_echoes = 0usize;
        let mut completions = 0usize;
        let mut interpreted = false;
        loop {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == expected_answer => {
                    user_echoes += 1;
                    assert_eq!(user_echoes, 1, "typed answer was echoed more than once");
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    assert!(completion.success(), "typed answer failed: {completion:?}");
                    let ToolExecutionResult::Other { result } = &completion.tool_result() else {
                        panic!("typed answer result was not normalized: {completion:?}")
                    };
                    assert_eq!(
                        result.get("answer").and_then(Value::as_str),
                        Some(expected_answer),
                        "typed answer encoding changed in transit"
                    );
                    completions += 1;
                    assert_eq!(completions, 1, "typed answer completed more than once");
                }
                ChatEvent::StreamDelta(delta) => {
                    interpreted |= delta.text.contains("USER_QUESTION_MULTISELECT_OK");
                }
                ChatEvent::StreamEnd(end) => {
                    interpreted |= end.message.content.contains("USER_QUESTION_MULTISELECT_OK");
                }
                ChatEvent::TypingStatusChanged(false)
                    if user_echoes == 1 && completions == 1 && interpreted =>
                {
                    break;
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("typed answer failed: {content}"),
                _ => {}
            }
        }
    })
    .await
    .expect("typed answer did not complete exactly once");
}

