fn selected_real_backends() -> Result<Vec<BackendKind>, String> {
    let Ok(configured) = std::env::var(UNIVERSAL_REAL_BACKENDS_ENV) else {
        return Ok(ALL_SUPPORTED_REAL_BACKENDS.to_vec());
    };
    let mut backends = Vec::new();
    for value in configured
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let backend = match value.to_ascii_lowercase().as_str() {
            "claude" => BackendKind::Claude,
            "codex" => BackendKind::Codex,
            "kiro" | "acp" => BackendKind::Acp,
            "hermes" => BackendKind::Hermes,
            "tycode" => BackendKind::Tycode,
            "antigravity" | "agy" => {
                return Err("Antigravity is excluded from real-backend conformance".to_owned());
            }
            _ => {
                return Err(format!(
                    "unknown backend {value:?} in {UNIVERSAL_REAL_BACKENDS_ENV}"
                ));
            }
        };
        if !backends.contains(&backend) {
            backends.push(backend);
        }
    }
    if backends.is_empty() {
        return Err(format!(
            "{UNIVERSAL_REAL_BACKENDS_ENV} selected no backends"
        ));
    }
    Ok(backends)
}

fn remove_targeted_conformance_filters() -> Vec<EnvVarGuard> {
    TARGETED_CONFORMANCE_FILTER_ENVS
        .into_iter()
        .map(EnvVarGuard::remove)
        .collect()
}

fn universal_backend_config(backend_kind: BackendKind) -> server::backend::BackendSpawnConfig {
    let mut config = server::backend::BackendSpawnConfig {
        cost_hint: cost_hint_for(backend_kind),
        ..Default::default()
    };
    if backend_kind == BackendKind::Claude {
        let mut settings = SessionSettingsValues::default();
        settings.0.insert(
            "model".to_owned(),
            SessionSettingValue::String(UNIVERSAL_CLAUDE_MODEL.to_owned()),
        );
        settings.0.insert(
            "effort".to_owned(),
            SessionSettingValue::String(UNIVERSAL_CLAUDE_EFFORT.to_owned()),
        );
        config.session_settings = Some(settings);
    } else if backend_kind == BackendKind::Hermes {
        let provider = std::env::var("TYDE_HERMES_TEST_PROVIDER")
            .ok()
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| DEFAULT_HERMES_TEST_PROVIDER.to_owned());
        let model = std::env::var("TYDE_HERMES_TEST_MODEL")
            .ok()
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| DEFAULT_HERMES_TEST_MODEL.to_owned());
        let mut settings = SessionSettingsValues::default();
        settings.0.insert(
            "model".to_owned(),
            SessionSettingValue::String(format!("{model} --provider {provider}")),
        );
        settings.0.insert(
            "reasoning_effort".to_owned(),
            SessionSettingValue::String("none".to_owned()),
        );
        config.session_settings = Some(settings);
    } else if backend_kind == BackendKind::Codex {
        let mut settings = SessionSettingsValues::default();
        settings.0.insert(
            "model".to_owned(),
            SessionSettingValue::String(REQUIRED_CODEX_TEST_MODEL.to_owned()),
        );
        settings.0.insert(
            "reasoning_effort".to_owned(),
            SessionSettingValue::String(REQUIRED_CODEX_TEST_REASONING_EFFORT.to_owned()),
        );
        config.session_settings = Some(settings);
    }
    config
}

fn capability_witness_case(capability: BackendCapability) -> CertificationCase {
    match capability {
        BackendCapability::ListSessions => CertificationCase::SessionAppearsInList,
        BackendCapability::ResumeSession => CertificationCase::ResumeAcceptsFollowUp,
        BackendCapability::ForkSession => CertificationCase::ForkAcceptsInitialPrompt,
        BackendCapability::ImageInput => CertificationCase::ImageAttachmentContractMatrix,
        BackendCapability::Interrupt => CertificationCase::InterruptPhaseContractMatrix,
        BackendCapability::SessionSettings => CertificationCase::SessionSettingsApplied,
        BackendCapability::StartupMcpServers => CertificationCase::McpStartupAdversarialContract,
        BackendCapability::AgentControlTools => CertificationCase::AgentControlSpawnContract,
        BackendCapability::TurnUsageReported => CertificationCase::UsageLifecycleMatrix,
        BackendCapability::ModelRequestUsageReported => {
            CertificationCase::RequestUsageAggregatesToTurn
        }
        BackendCapability::ContextUsageReported => CertificationCase::ContextWindowValid,
        BackendCapability::ContextBreakdownReported => CertificationCase::ContextBreakdownPresent,
        BackendCapability::CompactionReported => CertificationCase::CompactionLifecycleMatrix,
        BackendCapability::Subagents => CertificationCase::NativeSubagentProjected,
        BackendCapability::ForegroundSubagents => CertificationCase::AgentSpawnContractMatrix,
        BackendCapability::BackgroundSubagents => {
            CertificationCase::BackgroundSubagentContractMatrix
        }
        BackendCapability::BackgroundTasks => CertificationCase::BackgroundCommandContractMatrix,
        BackendCapability::AgentInitiatedTurns => CertificationCase::AgentInitiatedResultDelivered,
        BackendCapability::MidTurnSteering => CertificationCase::MidTurnSteeringDelivered,
        BackendCapability::ReasoningDeltas => CertificationCase::ReasoningDeltaReported,
        BackendCapability::TaskUpdates => CertificationCase::TaskUpdateLifecycleMatrix,
        BackendCapability::TaskListReplacement => CertificationCase::TaskListReplacement,
        BackendCapability::TaskListClear => CertificationCase::TaskListClear,
        BackendCapability::WorkflowProgress => CertificationCase::WorkflowProgressLifecycle,
        BackendCapability::OpaqueToolProgress => CertificationCase::OpaqueToolProgressReported,
        BackendCapability::RetryTelemetry => CertificationCase::RetryLifecycleMatrix,
        BackendCapability::OrchestrationEvents => CertificationCase::OrchestrationEventReported,
        BackendCapability::UserQuestionRequests => {
            CertificationCase::UserQuestionResponseEdgeMatrix
        }
        BackendCapability::PlanApprovalRequests => {
            CertificationCase::PlanApprovalResponseEdgeMatrix
        }
        BackendCapability::WorkspaceInstructions => {
            CertificationCase::WorkspaceInstructionsObserved
        }
        BackendCapability::Customization => CertificationCase::LiveCustomizationMatrix,
        BackendCapability::GenericModifyFile => CertificationCase::GenericModifyFileContract,
        BackendCapability::GenericReadFiles => CertificationCase::GenericReadFilesContract,
        BackendCapability::GenericSearchTypes => CertificationCase::GenericSearchTypesContract,
        BackendCapability::GenericGetTypeDocs => CertificationCase::GenericGetTypeDocsContract,
        BackendCapability::GenericGenerateImage => CertificationCase::GenericGenerateImageContract,
        BackendCapability::GenericWebSearch => CertificationCase::GenericWebSearchContract,
        BackendCapability::GenericViewImage => CertificationCase::GenericViewImageContract,
        BackendCapability::GenericSleep => CertificationCase::GenericSleepContract,
        BackendCapability::GenericOtherTool => CertificationCase::GenericOtherToolContract,
        BackendCapability::CapacityTelemetry => CertificationCase::CapacityLifecycleMatrix,
    }
}

fn capability_reachability_prompt(
    backend_kind: BackendKind,
    capability: BackendCapability,
) -> String {
    let provider = match backend_kind {
        BackendKind::Claude => "Claude",
        BackendKind::Codex => "Codex",
        BackendKind::Acp => "Kiro",
        BackendKind::Hermes => "Hermes",
        BackendKind::Tycode => "Tycode",
        BackendKind::Antigravity => unreachable!("Antigravity is excluded from conformance"),
    };
    let instruction = match capability {
        BackendCapability::ListSessions => {
            "Use the backend's native session-listing operation exactly once and report how many resumable sessions it returns."
        }
        BackendCapability::ResumeSession => {
            "Use the backend's native session-resume operation exactly once to resume the current session."
        }
        BackendCapability::ForkSession => {
            "Use the backend's native session-fork operation exactly once to fork the current session."
        }
        BackendCapability::ImageInput => {
            "Use the backend's native image-input facility exactly once to inspect an attached image."
        }
        BackendCapability::Interrupt => {
            "Use the backend's native interrupt facility exactly once to interrupt your own active turn."
        }
        BackendCapability::SessionSettings => {
            "Use the backend's native per-session settings facility exactly once to read the active model setting."
        }
        BackendCapability::StartupMcpServers => {
            "Use a tool from the configured startup MCP server exactly once."
        }
        BackendCapability::AgentControlTools => {
            "Use the Tyde agent-control spawn tool exactly once to start a child that replies CAPABILITY_CHILD_OK."
        }
        BackendCapability::TurnUsageReported
        | BackendCapability::ModelRequestUsageReported
        | BackendCapability::ContextUsageReported
        | BackendCapability::ContextBreakdownReported => {
            "Complete one normal turn while emitting the requested native usage or context telemetry."
        }
        BackendCapability::CompactionReported => {
            "Use the backend's native context-compaction operation exactly once and report its typed result."
        }
        BackendCapability::Subagents => {
            "Use any native subagent facility exactly once to start a child that replies CAPABILITY_CHILD_OK."
        }
        BackendCapability::BackgroundTasks => {
            "Use your native command tool exactly once to run `sleep 1` as detached background work. Do not run it in the foreground."
        }
        BackendCapability::ForegroundSubagents => {
            "Use your native subagent tool exactly once to start a foreground child that replies CAPABILITY_CHILD_OK. Wait for it."
        }
        BackendCapability::BackgroundSubagents => {
            "Use your native subagent tool exactly once to start a detached background child that replies CAPABILITY_CHILD_OK. Do not wait for it."
        }
        BackendCapability::AgentInitiatedTurns => {
            "Start detached native background work that completes after the foreground becomes idle and allow its completion to initiate a new turn."
        }
        BackendCapability::MidTurnSteering => {
            "Begin a long response, accept one native mid-turn steering input, and incorporate its sentinel in the same turn."
        }
        BackendCapability::ReasoningDeltas => {
            "Reason step by step about whether 17 times 19 is 323, then answer only CAPABILITY_REASONING_DONE."
        }
        BackendCapability::TaskUpdates => {
            "Use your native task-list tool to create one pending task named CAPABILITY_TASK, then mark it completed."
        }
        BackendCapability::TaskListReplacement => {
            "Use the native task-list tool to create two tasks, then replace the entire list with one different task."
        }
        BackendCapability::TaskListClear => {
            "Use the native task-list tool to create one task, then clear the entire task list."
        }
        BackendCapability::WorkflowProgress => {
            "Use your native workflow tool exactly once to run one step that replies CAPABILITY_WORKFLOW_OK."
        }
        BackendCapability::OpaqueToolProgress => {
            "Use your native foreground command tool exactly once to run `sleep 1; printf CAPABILITY_PROGRESS_OK`, and wait for it."
        }
        BackendCapability::RetryTelemetry => {
            "Use the backend's native retry mechanism once and emit its typed retry lifecycle telemetry."
        }
        BackendCapability::OrchestrationEvents => {
            "Run one native orchestration worker through start and completion so its typed orchestration lifecycle is emitted."
        }
        BackendCapability::UserQuestionRequests => {
            "Use your native user-question tool exactly once to ask whether the capability probe should continue, with choices YES and NO. Wait for the answer."
        }
        BackendCapability::PlanApprovalRequests => {
            "Enter native plan mode, create a one-step plan to inspect README.txt, and request user approval with the native plan approval tool."
        }
        BackendCapability::WorkspaceInstructions => {
            "Use the backend's native workspace-instruction injection and reply with the injected capability sentinel without reading files."
        }
        BackendCapability::Customization => {
            "Use the backend's native customization injection and reply with the injected capability sentinel."
        }
        BackendCapability::GenericModifyFile => {
            "Use only your native structured file-edit tool to replace CAPABILITY_OLD with CAPABILITY_NEW in CAPABILITY_TRUTH.txt. Do not use a command tool."
        }
        BackendCapability::GenericReadFiles => {
            "Use only your native structured file-read tool to read CAPABILITY_TRUTH.txt. Do not use a command tool."
        }
        BackendCapability::GenericSearchTypes => {
            "Use your native structured type-search tool exactly once to search for type CapabilityTruth."
        }
        BackendCapability::GenericGetTypeDocs => {
            "Use your native structured type-documentation tool exactly once to request documentation for CapabilityTruth."
        }
        BackendCapability::GenericGenerateImage => {
            "Use your native image-generation tool exactly once to generate a one-pixel red square."
        }
        BackendCapability::GenericWebSearch => {
            "Use your native structured web-search tool exactly once to search for the phrase Tyde capability truth probe."
        }
        BackendCapability::GenericViewImage => {
            "Use your native structured image-view tool exactly once to inspect CAPABILITY_TRUTH.png."
        }
        BackendCapability::GenericSleep => {
            "Use your native structured sleep tool exactly once to sleep for one second. Do not use a command tool."
        }
        BackendCapability::GenericOtherTool => {
            "Use one configured MCP tool that normalizes to the generic Other tool family."
        }
        BackendCapability::CapacityTelemetry => {
            "Complete one normal turn while emitting the backend's native capacity snapshot telemetry."
        }
    };
    format!(
        "Authorized {provider} real-backend capability reachability probe. {instruction} If that exact native capability is unavailable, do not substitute another tool; reply exactly CAPABILITY_UNAVAILABLE."
    )
}

fn capability_uses_model_reachability(capability: BackendCapability) -> bool {
    matches!(
        capability,
        BackendCapability::AgentControlTools
            | BackendCapability::Subagents
            | BackendCapability::ForegroundSubagents
            | BackendCapability::BackgroundSubagents
            | BackendCapability::BackgroundTasks
            | BackendCapability::AgentInitiatedTurns
            | BackendCapability::MidTurnSteering
            | BackendCapability::ReasoningDeltas
            | BackendCapability::TaskUpdates
            | BackendCapability::TaskListReplacement
            | BackendCapability::TaskListClear
            | BackendCapability::WorkflowProgress
            | BackendCapability::OpaqueToolProgress
            | BackendCapability::RetryTelemetry
            | BackendCapability::OrchestrationEvents
            | BackendCapability::UserQuestionRequests
            | BackendCapability::PlanApprovalRequests
            | BackendCapability::WorkspaceInstructions
            | BackendCapability::Customization
            | BackendCapability::GenericModifyFile
            | BackendCapability::GenericReadFiles
            | BackendCapability::GenericSearchTypes
            | BackendCapability::GenericGetTypeDocs
            | BackendCapability::GenericGenerateImage
            | BackendCapability::GenericWebSearch
            | BackendCapability::GenericViewImage
            | BackendCapability::GenericSleep
            | BackendCapability::GenericOtherTool
    )
}

