async fn collect_capability_truth_direct_observation(
    backend_kind: BackendKind,
) -> DirectCertificationObservation {
    const PROMPT: &str = "Reply exactly CAPABILITY_OPERATIONAL_BASELINE.";
    match backend_kind {
        BackendKind::Claude => {
            collect_direct_certification_observation::<server::backend::claude::ClaudeBackend>(
                backend_kind,
                PROMPT,
            )
            .await
        }
        BackendKind::Codex => {
            collect_direct_certification_observation::<server::backend::codex::CodexBackend>(
                backend_kind,
                PROMPT,
            )
            .await
        }
        BackendKind::Acp => {
            collect_direct_certification_observation::<server::backend::kiro::KiroBackend>(
                backend_kind,
                PROMPT,
            )
            .await
        }
        BackendKind::Hermes => {
            collect_direct_certification_observation::<server::backend::hermes::HermesBackend>(
                backend_kind,
                PROMPT,
            )
            .await
        }
        BackendKind::Tycode => {
            collect_direct_certification_observation::<server::backend::tycode::TycodeBackend>(
                backend_kind,
                PROMPT,
            )
            .await
        }
        BackendKind::Antigravity => unreachable!(),
    }
}

async fn assert_undeclared_usage_unreachable(
    backend_kind: BackendKind,
    capability: BackendCapability,
) {
    let observation = collect_capability_truth_direct_observation(backend_kind).await;
    let message = observation.final_message();
    let reached = match capability {
        BackendCapability::TurnUsageReported => message.token_usage.is_some(),
        BackendCapability::ModelRequestUsageReported => {
            !observation.request_usage.is_empty()
                || message
                    .token_usage
                    .as_ref()
                    .is_some_and(|usage| usage.request.known_usage().is_some())
        }
        BackendCapability::ContextUsageReported => {
            observation.request_usage.iter().any(|usage| {
                usage
                    .current_context_usage
                    .as_ref()
                    .and_then(protocol::CurrentContextUsage::known)
                    .is_some()
            }) || message
                .context_breakdown
                .as_ref()
                .is_some_and(|breakdown| breakdown.context_window > 0)
        }
        BackendCapability::ContextBreakdownReported => message.context_breakdown.is_some(),
        _ => unreachable!(),
    };
    assert!(
        !reached,
        "{backend_kind:?} emitted undeclared {capability:?}; observation={observation:?}"
    );
}

