async fn assert_undeclared_direct_operation_unreachable_for<B: Backend>(
    backend_kind: BackendKind,
    capability: BackendCapability,
) {
    let workspace = tempfile::tempdir().expect("operational capability workspace");
    let roots = vec![workspace.path().to_string_lossy().to_string()];
    let prompt = match capability {
        BackendCapability::ImageInput => {
            "Inspect the attached solid red image and reply exactly RED."
        }
        BackendCapability::Interrupt => {
            "Without tools, write at least 4000 words beginning CAPABILITY_INTERRUPT_ACTIVE."
        }
        _ => "Reply exactly CAPABILITY_OPERATION_SOURCE_READY.",
    };
    let images = (capability == BackendCapability::ImageInput).then(|| {
        vec![ImageData {
            media_type: "image/png".to_owned(),
            data: SOLID_RED_PNG_BASE64.to_owned(),
        }]
    });
    let spawned = B::spawn(
        roots.clone(),
        universal_backend_config(backend_kind),
        SendMessagePayload {
            message: prompt.to_owned(),
            images,
            origin: None,
            tool_response: None,
        },
    )
    .await;
    let (backend, mut events) = match spawned {
        Ok(spawned) => spawned,
        Err(_) if capability == BackendCapability::ImageInput => return,
        Err(error) => panic!(
            "{backend_kind:?} could not establish the baseline for undeclared {capability:?}: {error}"
        ),
    };
    if capability == BackendCapability::ImageInput {
        let response = collect_backend_text_until_idle(&mut events, backend_kind).await;
        backend.shutdown().await;
        panic!(
            "{backend_kind:?} accepted and completed undeclared ImageInput with response {response:?}"
        );
    }
    if capability == BackendCapability::Interrupt {
        tokio::time::timeout(Duration::from_secs(120), async {
            while let Some(event) = events.recv().await {
                if matches!(
                    event,
                    ChatEvent::TypingStatusChanged(true) | ChatEvent::StreamDelta(_)
                ) {
                    break;
                }
            }
        })
        .await
        .expect("undeclared interrupt baseline never became active");
        let interrupted = backend.interrupt().await;
        backend.shutdown().await;
        assert!(
            !interrupted,
            "{backend_kind:?} accepted interrupt while Interrupt is undeclared"
        );
        return;
    }

    let source_text = collect_backend_text_until_idle(&mut events, backend_kind).await;
    assert!(source_text.contains("CAPABILITY_OPERATION_SOURCE_READY"));
    let session_id = backend.session_id();
    match capability {
        BackendCapability::ResumeSession => {
            backend.shutdown().await;
            let resumed =
                B::resume(roots, universal_backend_config(backend_kind), session_id).await;
            if let Ok((resumed, _)) = resumed {
                resumed.shutdown().await;
                panic!("{backend_kind:?} resumed while ResumeSession is undeclared");
            }
        }
        BackendCapability::ForkSession => {
            let forked = B::fork(
                roots,
                universal_backend_config(backend_kind),
                session_id,
                SendMessagePayload {
                    message: "Reply exactly CAPABILITY_FORK_READY.".to_owned(),
                    images: None,
                    origin: None,
                    tool_response: None,
                },
            )
            .await;
            backend.shutdown().await;
            if let Ok((forked, _)) = forked {
                forked.shutdown().await;
                panic!("{backend_kind:?} forked while ForkSession is undeclared");
            }
        }
        BackendCapability::CompactionReported => {
            let compaction = backend.compaction_capability();
            assert!(
                !server::backend::compaction_capability_is_native(&compaction),
                "{backend_kind:?} exposes native compaction while CompactionReported is undeclared: {compaction:?}"
            );
            let operation_id = protocol::CompactionOperationId(Uuid::new_v4().to_string());
            let start = backend
                .begin_compaction(server::backend::BackendCompactionRequest {
                    operation_id,
                    trigger: protocol::CompactionTrigger::UserRequested,
                    focus: None,
                    transcript_authoritative: true,
                })
                .await;
            backend.shutdown().await;
            assert!(
                matches!(
                    start,
                    server::backend::BackendCompactionStart::NotDispatched { .. }
                ),
                "{backend_kind:?} dispatched compaction while CompactionReported is undeclared: {start:?}"
            );
        }
        _ => unreachable!(),
    }
}

async fn assert_undeclared_startup_mcp_unreachable_for<B: Backend>(backend_kind: BackendKind) {
    let workspace = tempfile::tempdir().expect("startup MCP negative workspace");
    let script = workspace.path().join("capability_truth_mcp.py");
    std::fs::write(
        &script,
        r#"import json, sys
for line in sys.stdin:
    request = json.loads(line)
    request_id = request.get("id")
    if request_id is None:
        continue
    method = request.get("method")
    if method == "initialize":
        result = {"protocolVersion":"2025-06-18","capabilities":{"tools":{}},"serverInfo":{"name":"capability-truth","version":"1"}}
    elif method == "tools/list":
        result = {"tools":[{"name":"capability_truth_probe","description":"Return CAPABILITY_MCP_REACHED","inputSchema":{"type":"object","properties":{},"additionalProperties":False}}]}
    elif method == "tools/call":
        result = {"content":[{"type":"text","text":"CAPABILITY_MCP_REACHED"}],"isError":False}
    else:
        result = {}
    print(json.dumps({"jsonrpc":"2.0","id":request_id,"result":result}), flush=True)
"#,
    )
    .expect("write startup MCP negative server");
    let mut config = universal_backend_config(backend_kind);
    config.startup_mcp_servers = vec![server::backend::StartupMcpServer {
        name: "capability_truth".to_owned(),
        supports_parallel_tool_calls: false,
        transport: server::backend::StartupMcpTransport::Stdio {
            command: "python3".to_owned(),
            args: vec![script.to_string_lossy().to_string()],
            env: HashMap::new(),
        },
    }];
    let spawned = B::spawn(
        vec![workspace.path().to_string_lossy().to_string()],
        config,
        SendMessagePayload {
            message:
                "Call capability_truth_probe exactly once, then reply exactly with its result."
                    .to_owned(),
            images: None,
            origin: None,
            tool_response: None,
        },
    )
    .await;
    let Ok((backend, mut events)) = spawned else {
        return;
    };
    let reached = tokio::time::timeout(Duration::from_secs(120), async {
        while let Some(event) = events.recv().await {
            match event {
                ChatEvent::ToolRequest(_) => return true,
                ChatEvent::StreamEnd(end)
                    if end.message.content.contains("CAPABILITY_MCP_REACHED") =>
                {
                    return true;
                }
                ChatEvent::TypingStatusChanged(false) => return false,
                _ => {}
            }
        }
        false
    })
    .await
    .expect("undeclared startup MCP probe never settled");
    backend.shutdown().await;
    assert!(
        !reached,
        "{backend_kind:?} initialized and used startup MCP while StartupMcpServers is undeclared"
    );
}

