async fn assert_undeclared_operational_capabilities_unreachable(
    backend_kind: BackendKind,
) -> usize {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let selected = std::env::var("TYDE_CONFORMANCE_CAPABILITY").ok();
    let mut probed = 0usize;
    for capability in BackendCapability::ALL {
        if capabilities.contains(capability)
            || capability_uses_model_reachability(capability)
            || selected.as_deref().is_some_and(|selected| {
                !format!("{capability:?}").eq_ignore_ascii_case(selected.trim())
            })
        {
            continue;
        }
        probed += 1;
        match capability {
            BackendCapability::ListSessions => {
                assert_undeclared_list_sessions_unreachable(backend_kind).await;
            }
            BackendCapability::SessionSettings => {
                let schema = match backend_kind {
                    BackendKind::Claude => {
                        server::backend::claude::ClaudeBackend::session_settings_schema()
                    }
                    BackendKind::Codex => {
                        server::backend::codex::CodexBackend::session_settings_schema()
                    }
                    BackendKind::Acp => {
                        server::backend::kiro::KiroBackend::session_settings_schema()
                    }
                    BackendKind::Hermes => {
                        server::backend::hermes::HermesBackend::session_settings_schema()
                    }
                    BackendKind::Tycode => {
                        server::backend::tycode::TycodeBackend::session_settings_schema()
                    }
                    BackendKind::Antigravity => unreachable!(),
                };
                assert!(
                    schema.fields.is_empty(),
                    "{backend_kind:?} exposes session settings while SessionSettings is undeclared: {schema:?}"
                );
            }
            BackendCapability::TurnUsageReported
            | BackendCapability::ModelRequestUsageReported
            | BackendCapability::ContextUsageReported
            | BackendCapability::ContextBreakdownReported => {
                assert_undeclared_usage_unreachable(backend_kind, capability).await;
            }
            BackendCapability::CapacityTelemetry => {
                assert_undeclared_capacity_unreachable(backend_kind).await;
            }
            BackendCapability::ResumeSession
            | BackendCapability::ForkSession
            | BackendCapability::ImageInput
            | BackendCapability::Interrupt
            | BackendCapability::CompactionReported => {
                assert_undeclared_direct_operation_unreachable(backend_kind, capability).await;
            }
            BackendCapability::StartupMcpServers => {
                assert_undeclared_startup_mcp_unreachable(backend_kind).await;
            }
            _ => unreachable!("model-reachable capability escaped its classifier"),
        }
    }
    probed
}

fn event_reaches_capability(event: &ChatEvent, capability: BackendCapability) -> bool {
    match (capability, event) {
        (
            BackendCapability::BackgroundTasks,
            ChatEvent::ToolProgress(protocol::ToolProgressData {
                execution_mode: protocol::ToolExecutionMode::Background,
                ..
            }),
        )
        | (
            BackendCapability::WorkflowProgress,
            ChatEvent::ToolProgress(protocol::ToolProgressData {
                update: protocol::ToolProgressUpdate::Workflow(_),
                ..
            }),
        )
        | (
            BackendCapability::OpaqueToolProgress,
            ChatEvent::ToolProgress(protocol::ToolProgressData {
                update: protocol::ToolProgressUpdate::Other { .. },
                ..
            }),
        ) => true,
        (BackendCapability::ReasoningDeltas, ChatEvent::StreamReasoningDelta(_))
        | (
            BackendCapability::TaskUpdates
            | BackendCapability::TaskListReplacement
            | BackendCapability::TaskListClear,
            ChatEvent::TaskUpdate(_),
        )
        | (BackendCapability::RetryTelemetry, ChatEvent::RetryAttempt(_))
        | (BackendCapability::OrchestrationEvents, ChatEvent::Orchestration(_))
        | (BackendCapability::CompactionReported, ChatEvent::ContextCompaction(_)) => true,
        (
            BackendCapability::TurnUsageReported
            | BackendCapability::ModelRequestUsageReported
            | BackendCapability::ContextUsageReported
            | BackendCapability::ContextBreakdownReported,
            ChatEvent::StreamEnd(end),
        ) => match capability {
            BackendCapability::TurnUsageReported => end.message.token_usage.is_some(),
            BackendCapability::ModelRequestUsageReported => end
                .message
                .token_usage
                .as_ref()
                .is_some_and(|usage| usage.request.known_usage().is_some()),
            BackendCapability::ContextUsageReported => end
                .message
                .context_breakdown
                .as_ref()
                .is_some_and(|breakdown| breakdown.context_window > 0),
            BackendCapability::ContextBreakdownReported => end.message.context_breakdown.is_some(),
            _ => unreachable!(),
        },
        (
            BackendCapability::TurnUsageReported
            | BackendCapability::ModelRequestUsageReported
            | BackendCapability::ContextUsageReported
            | BackendCapability::ContextBreakdownReported,
            ChatEvent::MessageMetadataUpdated(update),
        ) => match capability {
            BackendCapability::TurnUsageReported => update.token_usage.is_some(),
            BackendCapability::ModelRequestUsageReported => update
                .token_usage
                .as_ref()
                .is_some_and(|usage| usage.request.known_usage().is_some()),
            BackendCapability::ContextUsageReported => update
                .context_breakdown
                .as_ref()
                .is_some_and(|breakdown| breakdown.context_window > 0),
            BackendCapability::ContextBreakdownReported => update.context_breakdown.is_some(),
            _ => unreachable!(),
        },
        (capability, ChatEvent::ToolRequest(request)) => match capability {
            BackendCapability::ForegroundSubagents => matches!(
                request.tool_type,
                ToolRequestType::AgentSpawn {
                    execution_mode: protocol::AgentExecutionMode::Foreground,
                    ..
                }
            ),
            BackendCapability::BackgroundSubagents => matches!(
                request.tool_type,
                ToolRequestType::AgentSpawn {
                    execution_mode: protocol::AgentExecutionMode::Background,
                    ..
                }
            ),
            BackendCapability::Subagents => {
                matches!(request.tool_type, ToolRequestType::AgentSpawn { .. })
            }
            BackendCapability::AgentControlTools => matches!(
                request.tool_type,
                ToolRequestType::AgentSpawn { .. }
                    | ToolRequestType::TydeSendAgentMessage { .. }
                    | ToolRequestType::TydeAwaitAgents { .. }
            ),
            BackendCapability::UserQuestionRequests => {
                matches!(request.tool_type, ToolRequestType::AskUserQuestion { .. })
            }
            BackendCapability::PlanApprovalRequests => {
                matches!(request.tool_type, ToolRequestType::ExitPlanMode { .. })
            }
            BackendCapability::GenericModifyFile => {
                matches!(request.tool_type, ToolRequestType::ModifyFile { .. })
            }
            BackendCapability::GenericReadFiles => {
                matches!(request.tool_type, ToolRequestType::ReadFiles { .. })
            }
            BackendCapability::GenericSearchTypes => {
                matches!(request.tool_type, ToolRequestType::SearchTypes { .. })
            }
            BackendCapability::GenericGetTypeDocs => {
                matches!(request.tool_type, ToolRequestType::GetTypeDocs { .. })
            }
            BackendCapability::GenericGenerateImage => {
                matches!(request.tool_type, ToolRequestType::GenerateImage { .. })
            }
            BackendCapability::GenericWebSearch => {
                matches!(request.tool_type, ToolRequestType::WebSearch { .. })
            }
            BackendCapability::GenericViewImage => {
                matches!(request.tool_type, ToolRequestType::ViewImage { .. })
            }
            BackendCapability::GenericSleep => {
                matches!(request.tool_type, ToolRequestType::Sleep { .. })
            }
            BackendCapability::GenericOtherTool => {
                matches!(request.tool_type, ToolRequestType::Other { .. })
            }
            _ => false,
        },
        _ => false,
    }
}

async fn assert_undeclared_model_capabilities_unreachable(backend_kind: BackendKind) -> usize {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let selected = std::env::var("TYDE_CONFORMANCE_CAPABILITY").ok();
    let mut probed = 0usize;
    for capability in BackendCapability::ALL {
        if capabilities.contains(capability) {
            continue;
        }
        if !capability_uses_model_reachability(capability) {
            continue;
        }
        if selected.as_deref().is_some_and(|selected| {
            !format!("{capability:?}").eq_ignore_ascii_case(selected.trim())
        }) {
            continue;
        }
        let prompt = capability_reachability_prompt(backend_kind, capability);
        probed += 1;
        eprintln!("CAPABILITY TRUTH NEGATIVE {backend_kind:?} {capability:?}");
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        std::fs::write(
            fixture.workspace_dir.path().join("CAPABILITY_TRUTH.txt"),
            "CAPABILITY_OLD\nstruct CapabilityTruth;\n",
        )
        .expect("seed capability-truth workspace");
        std::fs::write(
            fixture.workspace_dir.path().join("CAPABILITY_TRUTH.png"),
            b"capability truth image probe",
        )
        .expect("seed capability-truth image");
        let roots = fixture.workspace_roots();
        let (stream, start) = spawn_agent_via_protocol_with_start(
            &mut fixture.client,
            roots,
            backend_kind,
            "capability-truth-negative",
            &prompt,
            None,
            cost_hint_for(backend_kind),
        )
        .await;
        let mut saw_user = false;
        let mut final_text = None;
        tokio::time::timeout(Duration::from_secs(180), async {
            loop {
                let envelope =
                    expect_next_event(&mut fixture.client, "capability reachability result").await;
                if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                    continue;
                }
                let event = envelope
                    .parse_payload::<ChatEvent>()
                    .expect("parse capability reachability event");
                if event_reaches_capability(&event, capability) {
                    panic!(
                        "{backend_kind:?} reached undeclared capability {capability:?}: {event:?}"
                    );
                }
                match event {
                    ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::User,
                        content,
                        ..
                    }) if content == prompt => saw_user = true,
                    ChatEvent::ToolRequest(request) => panic!(
                        "{backend_kind:?} substituted tool {:?} while probing undeclared capability {capability:?}",
                        request.tool_type
                    ),
                    ChatEvent::StreamEnd(end) => {
                        final_text = Some(end.message.content);
                    }
                    ChatEvent::TypingStatusChanged(false) if saw_user => break,
                    ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::Error,
                        content,
                        ..
                    }) => panic!(
                        "{backend_kind:?} capability truth probe {capability:?} failed: {content}"
                    ),
                    _ => {}
                }
            }
        })
        .await
        .unwrap_or_else(|_| {
            panic!("{backend_kind:?} capability truth probe {capability:?} never settled")
        });
        assert_eq!(
            final_text.as_deref().map(str::trim),
            Some("CAPABILITY_UNAVAILABLE"),
            "{backend_kind:?} did not explicitly certify that undeclared capability {capability:?} was unavailable"
        );
        close_agent_at_definitive_boundary(
            &mut fixture,
            &stream,
            &start.agent_id,
            "close capability-truth probe",
        )
        .await;
    }
    probed
}

fn assert_declared_capabilities_have_live_witnesses(
    backend_kind: BackendKind,
    successful_cases: &HashSet<CertificationCase>,
) {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    capabilities.validate().unwrap_or_else(|error| {
        panic!("{backend_kind:?} has an invalid capability declaration: {error}")
    });
    for capability in capabilities.iter() {
        let witness = capability_witness_case(capability);
        assert!(
            successful_cases.contains(&witness),
            "{backend_kind:?} declared {capability:?} without a passing live witness case {}",
            witness.id()
        );
    }
}

