fn assert_session_occurrences(
    list: &SessionListPayload,
    session_id: &SessionId,
    expected: usize,
    context: &str,
) {
    assert_eq!(
        list.sessions
            .iter()
            .filter(|session| &session.id == session_id)
            .count(),
        expected,
        "{context}: wrong session-list multiplicity for {session_id:?}: {:?}",
        list.sessions
    );
}

