async fn assert_session_list_lifecycle_matrix(backend_kind: BackendKind) {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let mut ledger = EnumeratedCoverageLedger::new(
        SessionListLifecycleCell::required_for(&capabilities),
        "session-list lifecycle",
    );
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let roots = fixture.workspace_roots();
    let source_prompt = "Do not use tools. Reply exactly SESSION_LIST_SOURCE_OK.";
    let (source_stream, source) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "session-list-source",
        source_prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    expect_assistant_turn_after_user_echo(&mut fixture.client, &source_stream, source_prompt).await;
    let source_session = source.session_id.clone().expect("source session identity");
    let active = list_sessions_via_protocol(&mut fixture.client).await;
    assert_session_occurrences(&active, &source_session, 1, "active source");
    let active_source = active
        .sessions
        .iter()
        .find(|session| session.id == source_session)
        .expect("active source summary disappeared")
        .clone();
    ledger
        .record(SessionListLifecycleCell::ActiveAppearsOnce)
        .unwrap();

    let mut observer = fixture.connect().await;
    let observed = list_sessions_via_protocol(&mut observer).await;
    assert_session_occurrences(&observed, &source_session, 1, "concurrent observer");
    assert_eq!(
        observed
            .sessions
            .iter()
            .find(|session| session.id == source_session),
        Some(&active_source),
        "concurrent clients disagreed about the same session summary"
    );
    ledger
        .record(SessionListLifecycleCell::ConcurrentClientsAgree)
        .unwrap();

    let mut replacement = fixture.connect().await;
    replacement.inherit_live_trace_from(&fixture.client);
    std::mem::swap(&mut fixture.client, &mut replacement);
    drop(replacement);
    let reconnect_stream = loop {
        let envelope = expect_next_event(&mut fixture.client, "session-list reconnect").await;
        if envelope.kind == FrameKind::HostBootstrap {
            let bootstrap: HostBootstrapPayload = envelope.parse_payload().unwrap();
            break bootstrap
                .agents
                .into_iter()
                .find(|agent| agent.agent_id == source.agent_id)
                .expect("session-list reconnect omitted active source")
                .instance_stream;
        }
    };
    assert_eq!(reconnect_stream, source_stream);
    let reconnected = list_sessions_via_protocol(&mut fixture.client).await;
    assert_session_occurrences(&reconnected, &source_session, 1, "reconnected source");
    assert_eq!(
        reconnected
            .sessions
            .iter()
            .find(|session| session.id == source_session),
        Some(&active_source),
        "client reconnect changed the authoritative session summary"
    );
    ledger
        .record(SessionListLifecycleCell::ClientReconnectKeepsIdentityOnce)
        .unwrap();

    if capabilities.contains(tyde_agent_adapter::BackendCapability::ForkSession) {
        let fork_prompt = "Do not use tools. Reply exactly SESSION_LIST_FORK_OK.";
        let fork_stream = fork_agent_via_protocol(
            &mut fixture.client,
            "session-list-fork",
            source.agent_id.clone(),
            source_session.clone(),
            fork_prompt,
        )
        .await;
        expect_assistant_turn_after_user_echo(&mut fixture.client, &fork_stream, fork_prompt).await;
        let forked = list_sessions_via_protocol(&mut fixture.client).await;
        assert_session_occurrences(&forked, &source_session, 1, "source after fork");
        let fork_sessions = forked
            .sessions
            .iter()
            .filter(|session| session.parent_id.as_ref() == Some(&source_session))
            .collect::<Vec<_>>();
        assert_eq!(
            fork_sessions.len(),
            1,
            "fork did not add one child session: {forked:?}"
        );
        assert_ne!(fork_sessions[0].id, source_session);
        ledger
            .record(SessionListLifecycleCell::ForkAddsDistinctIdentity)
            .unwrap();
    }

    close_agent_at_definitive_boundary(
        &mut fixture,
        &reconnect_stream,
        &source.agent_id,
        "close session-list source",
    )
    .await;
    let closed = list_sessions_via_protocol(&mut fixture.client).await;
    assert_session_occurrences(&closed, &source_session, 1, "closed source");
    ledger
        .record(SessionListLifecycleCell::ClosedRemainsListedOnce)
        .unwrap();

    drop(observer);
    fixture.restart_host().await;
    let restarted = list_sessions_via_protocol(&mut fixture.client).await;
    assert_session_occurrences(&restarted, &source_session, 1, "source after host restart");
    let restarted_source = restarted
        .sessions
        .iter()
        .find(|session| session.id == source_session)
        .expect("host restart omitted closed source");
    assert_eq!(restarted_source.id, active_source.id);
    assert_eq!(restarted_source.backend_kind, active_source.backend_kind);
    assert_eq!(restarted_source.parent_id, active_source.parent_id);
    assert_eq!(
        restarted_source.workspace_roots,
        active_source.workspace_roots
    );
    ledger
        .record(SessionListLifecycleCell::HostRestartKeepsIdentityOnce)
        .unwrap();

    if capabilities.contains(tyde_agent_adapter::BackendCapability::ResumeSession) {
        let resume_prompt = "Do not use tools. Reply exactly SESSION_LIST_RESUME_OK.";
        let resumed_stream = resume_agent_via_protocol(
            &mut fixture.client,
            "session-list-resume",
            source_session.clone(),
            resume_prompt,
        )
        .await;
        expect_assistant_turn_after_user_echo(&mut fixture.client, &resumed_stream, resume_prompt)
            .await;
        let resumed = list_sessions_via_protocol(&mut fixture.client).await;
        assert_session_occurrences(&resumed, &source_session, 1, "resumed source");
        ledger
            .record(SessionListLifecycleCell::ResumeKeepsIdentityOnce)
            .unwrap();

        let resumed_agent_id = protocol::AgentId(
            resumed_stream
                .0
                .split('/')
                .nth(2)
                .expect("resumed stream omitted agent id")
                .to_owned(),
        );
        fixture.client.close_agent(&resumed_stream).await.unwrap();
        tokio::time::timeout(Duration::from_secs(30), async {
            loop {
                let envelope =
                    expect_next_event(&mut fixture.client, "resumed session close").await;
                if envelope.kind == FrameKind::AgentClosed {
                    let closed: protocol::AgentClosedPayload = envelope.parse_payload().unwrap();
                    if closed.agent_id == resumed_agent_id {
                        break;
                    }
                }
            }
        })
        .await
        .expect("resumed session did not close before deletion");
    }

    let mut delete_observer = fixture.connect().await;
    let before_delete = list_sessions_via_protocol(&mut delete_observer).await;
    assert_session_occurrences(
        &before_delete,
        &source_session,
        1,
        "delete observer subscription",
    );
    fixture
        .client
        .delete_session(protocol::DeleteSessionPayload {
            session_id: source_session.clone(),
        })
        .await
        .unwrap();
    let deleted = tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let payload = expect_next_event_kind(
                &mut fixture.client,
                FrameKind::SessionList,
                "session deletion broadcast",
            )
            .await
            .parse_payload::<SessionListPayload>()
            .expect("parse deletion SessionList broadcast");
            if !payload
                .sessions
                .iter()
                .any(|session| session.id == source_session)
            {
                break payload;
            }
        }
    })
    .await
    .expect("primary client never received the deletion broadcast");
    let observer_deleted = tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let payload = expect_next_event_kind(
                &mut delete_observer,
                FrameKind::SessionList,
                "session deletion observer broadcast",
            )
            .await
            .parse_payload::<SessionListPayload>()
            .expect("parse observer deletion SessionList broadcast");
            if !payload
                .sessions
                .iter()
                .any(|session| session.id == source_session)
            {
                break payload;
            }
        }
    })
    .await
    .expect("concurrent observer never received the deletion broadcast");
    assert_session_occurrences(&deleted, &source_session, 0, "deleted source");
    assert_session_occurrences(
        &observer_deleted,
        &source_session,
        0,
        "deleted source on concurrent observer",
    );
    ledger
        .record(SessionListLifecycleCell::DeleteRemovesIdentity)
        .unwrap();
    ledger
        .record(SessionListLifecycleCell::DeleteBroadcastsToAllClients)
        .unwrap();
    ledger.finish().unwrap();
}

