async fn assert_live_customization_matrix(backend_kind: BackendKind) {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let mut ledger = EnumeratedCoverageLedger::new(
        LiveCustomizationCell::required_for(&capabilities),
        "live customization",
    );
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    install_live_customization(&mut fixture, "LIVE_CUSTOMIZATION_ONE").await;
    let roots = fixture.workspace_roots();
    let prompt = "Reply exactly with the current live customization value and nothing else.";
    let (source_stream, source) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "live-customization-source",
        prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let initial =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &source_stream, prompt).await;
    assert_eq!(initial.final_text.trim(), "LIVE_CUSTOMIZATION_ONE");
    ledger.record(LiveCustomizationCell::InitialValue).unwrap();

    install_live_customization(&mut fixture, "LIVE_CUSTOMIZATION_TWO").await;
    assert_customization_turn(&mut fixture, &source_stream, "LIVE_CUSTOMIZATION_ONE").await;
    ledger
        .record(LiveCustomizationCell::ActiveSessionKeepsSpawnSnapshot)
        .unwrap();

    let fresh_roots = fixture.workspace_roots();
    let (fresh_stream, _) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        fresh_roots,
        backend_kind,
        "live-customization-refreshed",
        prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let fresh =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &fresh_stream, prompt).await;
    assert_eq!(fresh.final_text.trim(), "LIVE_CUSTOMIZATION_TWO");
    ledger
        .record(LiveCustomizationCell::NewSessionUsesLatestValue)
        .unwrap();

    let source_session = source.session_id.clone().expect("customization session");
    let lineage_prompt =
        "Reply exactly with the current live customization value and nothing else.";
    if capabilities.contains(tyde_agent_adapter::BackendCapability::ForkSession) {
        let fork_stream = fork_agent_via_protocol(
            &mut fixture.client,
            "live-customization-fork",
            source.agent_id.clone(),
            source_session.clone(),
            lineage_prompt,
        )
        .await;
        let forked = expect_assistant_turn_after_user_echo(
            &mut fixture.client,
            &fork_stream,
            lineage_prompt,
        )
        .await;
        assert_eq!(forked.final_text.trim(), "LIVE_CUSTOMIZATION_TWO");
        ledger
            .record(LiveCustomizationCell::ForkUsesLatestValue)
            .unwrap();
    }

    let mut replacement = fixture.connect().await;
    replacement.inherit_live_trace_from(&fixture.client);
    std::mem::swap(&mut fixture.client, &mut replacement);
    drop(replacement);
    let reconnect_stream = loop {
        let envelope = expect_next_event(&mut fixture.client, "customization reconnect").await;
        if envelope.kind == FrameKind::HostBootstrap {
            let bootstrap: HostBootstrapPayload = envelope.parse_payload().unwrap();
            break bootstrap
                .agents
                .into_iter()
                .find(|agent| agent.agent_id == source.agent_id)
                .expect("customization reconnect omitted source")
                .instance_stream;
        }
    };
    assert_customization_turn(&mut fixture, &reconnect_stream, "LIVE_CUSTOMIZATION_ONE").await;
    ledger
        .record(LiveCustomizationCell::ClientReconnectKeepsSpawnSnapshot)
        .unwrap();

    if capabilities.contains(tyde_agent_adapter::BackendCapability::ResumeSession) {
        fixture.client.close_agent(&reconnect_stream).await.unwrap();
        let resumed_stream = resume_agent_via_protocol(
            &mut fixture.client,
            "live-customization-resume",
            source_session.clone(),
            lineage_prompt,
        )
        .await;
        let resumed = expect_assistant_turn_after_user_echo(
            &mut fixture.client,
            &resumed_stream,
            lineage_prompt,
        )
        .await;
        assert_eq!(resumed.final_text.trim(), "LIVE_CUSTOMIZATION_TWO");
        ledger
            .record(LiveCustomizationCell::ResumeUsesLatestValue)
            .unwrap();
    }

    ledger.finish().unwrap();
}

fn assert_known_message_usage(usage: &protocol::MessageTokenUsage, context: &str) {
    let TokenUsageScope::Known { usage: turn } = &usage.turn else {
        panic!("{context}: turn usage was unavailable: {usage:?}");
    };
    assert_token_usage_sane(context, turn);
}

fn assert_reported_message_usage_sane(usage: &protocol::MessageTokenUsage, context: &str) {
    for (label, scope) in [
        ("request", &usage.request),
        ("turn", &usage.turn),
        ("cumulative", &usage.cumulative),
    ] {
        if let TokenUsageScope::Known { usage } = scope {
            assert_token_usage_sane(&format!("{context} {label}"), usage);
        }
    }
}

async fn expect_terminal_turn_usage(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    context: &str,
) {
    let mut message_id = None;
    let mut usage = None;
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, context).await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::StreamEnd(end) => {
                    message_id = end.message.message_id;
                    if end.message.token_usage.is_some() {
                        usage = end.message.token_usage;
                    }
                }
                ChatEvent::MessageMetadataUpdated(update)
                    if message_id.as_ref() == Some(&update.message_id) =>
                {
                    if update.token_usage.is_some() {
                        usage = update.token_usage;
                    }
                }
                ChatEvent::TypingStatusChanged(false) if usage.is_some() => break,
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context}: terminal turn emitted no usage"));
    assert_known_message_usage(usage.as_ref().unwrap(), context);
}

async fn expect_failed_turn_usage_contract(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    context: &str,
) {
    let mut message_id = None;
    let mut usage = None;
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, context).await;
            if envelope.kind == FrameKind::AgentError && envelope.stream == *stream {
                break;
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::StreamEnd(end) => {
                    message_id = end.message.message_id;
                    if end.message.token_usage.is_some() {
                        usage = end.message.token_usage;
                    }
                }
                ChatEvent::MessageMetadataUpdated(update)
                    if message_id.as_ref() == Some(&update.message_id) =>
                {
                    if update.token_usage.is_some() {
                        usage = update.token_usage;
                    }
                }
                ChatEvent::OperationCancelled(_)
                | ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    ..
                })
                | ChatEvent::TypingStatusChanged(false) => break,
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context}: failed turn emitted no definitive boundary"));
    if let Some(usage) = usage.as_ref() {
        assert_reported_message_usage_sane(usage, context);
    }
}

async fn reach_usage_streaming_turn(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
) -> (StreamPath, AgentStartPayload) {
    let roots = fixture.workspace_roots();
    let prompt = "Without using tools, begin exactly USAGE_LIFECYCLE_PARTIAL and continue for at least 1000 words.";
    let (stream, start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "usage-lifecycle",
        prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, "usage streaming phase").await;
            if envelope.kind == FrameKind::ChatEvent
                && envelope.stream == stream
                && let ChatEvent::StreamDelta(delta) =
                    envelope.parse_payload::<ChatEvent>().unwrap()
                && !delta.text.is_empty()
            {
                break;
            }
        }
    })
    .await
    .expect("usage lifecycle never reached partial output");
    (stream, start)
}

async fn assert_usage_lifecycle_matrix(backend_kind: BackendKind) {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let mut ledger = EnumeratedCoverageLedger::new(
        UsageLifecycleCell::required_for(&capabilities),
        "usage lifecycle",
    );

    let mut completed_fixture = RealBackendFixture::new(backend_kind).await;
    let completed_prompt = "Do not use tools. Reply exactly USAGE_LIFECYCLE_COMPLETED.";
    let completed_roots = completed_fixture.workspace_roots();
    let (completed_stream, _) = spawn_agent_via_protocol_with_start(
        &mut completed_fixture.client,
        completed_roots,
        backend_kind,
        "usage-lifecycle-completed",
        completed_prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    expect_terminal_turn_usage(
        &mut completed_fixture,
        &completed_stream,
        "completed usage turn",
    )
    .await;
    ledger.record(UsageLifecycleCell::Completed).unwrap();

    for cell in UsageLifecycleCell::required_for(&capabilities)
        .into_iter()
        .filter(|cell| {
            matches!(
                cell,
                UsageLifecycleCell::TransportFailure
                    | UsageLifecycleCell::Cancelled
                    | UsageLifecycleCell::HostRestartFailure
            )
        })
    {
        eprintln!("USAGE LIFECYCLE CELL {backend_kind:?} {cell:?}");
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        let (stream, start) = reach_usage_streaming_turn(&mut fixture, backend_kind).await;
        match cell {
            UsageLifecycleCell::TransportFailure => {
                fixture
                    .host
                    .force_agent_backend_shutdown_for_conformance(&start.agent_id)
                    .await;
            }
            UsageLifecycleCell::Cancelled => {
                fixture.client.interrupt(&stream).await.unwrap();
            }
            UsageLifecycleCell::HostRestartFailure => {
                fixture.host.shutdown_agents_for_conformance().await;
            }
            _ => unreachable!(),
        }
        expect_failed_turn_usage_contract(&mut fixture, &stream, "failed/cancelled usage turn")
            .await;
        ledger.record(cell).unwrap();
    }

    if !capabilities.contains(tyde_agent_adapter::BackendCapability::ResumeSession)
        && !capabilities.contains(tyde_agent_adapter::BackendCapability::ForkSession)
    {
        ledger.finish().unwrap();
        return;
    }

    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let roots = fixture.workspace_roots();
    let prompt = "Do not use tools. Reply exactly USAGE_LINEAGE_SOURCE.";
    let (source_stream, source) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "usage-lineage-source",
        prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    expect_terminal_turn_usage(&mut fixture, &source_stream, "usage lineage source").await;
    let session_id = source.session_id.clone().expect("usage lineage session");

    if capabilities.contains(tyde_agent_adapter::BackendCapability::ForkSession) {
        let fork_prompt = "Do not use tools. Reply exactly USAGE_LINEAGE_FORK.";
        let fork_stream = fork_agent_via_protocol(
            &mut fixture.client,
            "usage-lineage-fork",
            source.agent_id.clone(),
            session_id.clone(),
            fork_prompt,
        )
        .await;
        expect_terminal_turn_usage(&mut fixture, &fork_stream, "forked usage turn").await;
        ledger.record(UsageLifecycleCell::ForkedTurn).unwrap();
    }

    if capabilities.contains(tyde_agent_adapter::BackendCapability::ResumeSession) {
        fixture.client.close_agent(&source_stream).await.unwrap();
        let resume_prompt = "Do not use tools. Reply exactly USAGE_LINEAGE_RESUME.";
        let resumed_stream = resume_agent_via_protocol(
            &mut fixture.client,
            "usage-lineage-resume",
            session_id,
            resume_prompt,
        )
        .await;
        expect_terminal_turn_usage(&mut fixture, &resumed_stream, "resumed usage turn").await;
        ledger.record(UsageLifecycleCell::ResumedTurn).unwrap();
    }
    ledger.finish().unwrap();
}

async fn assert_usage_metadata_concurrency_matrix(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let roots = fixture.workspace_roots();
    let mut streams = Vec::new();
    for index in 1..=2 {
        let prompt = format!("Do not use tools. Reply exactly USAGE_CONCURRENCY_READY_{index}.");
        let (stream, _) = spawn_agent_via_protocol_with_start(
            &mut fixture.client,
            roots.clone(),
            backend_kind,
            "usage-metadata-concurrency",
            &prompt,
            None,
            cost_hint_for(backend_kind),
        )
        .await;
        expect_terminal_turn_usage(&mut fixture, &stream, "usage concurrency baseline").await;
        streams.push(stream);
    }
    let prompts = [
        "Do not use tools. Reply exactly USAGE_CONCURRENCY_ONE.",
        "Do not use tools. Reply exactly USAGE_CONCURRENCY_TWO.",
    ];
    for (stream, prompt) in streams.iter().zip(prompts) {
        fixture
            .client
            .send_message(stream, prompt.to_owned())
            .await
            .unwrap();
    }

    let mut message_ids = HashMap::<StreamPath, ChatMessageId>::new();
    let mut usage = HashMap::<StreamPath, protocol::MessageTokenUsage>::new();
    let mut metadata_updates = HashSet::new();
    let mut idle = HashSet::new();
    tokio::time::timeout(Duration::from_secs(180), async {
        while idle.len() != streams.len() || usage.len() != streams.len() {
            let envelope =
                expect_next_event(&mut fixture.client, "concurrent usage metadata").await;
            if envelope.kind != FrameKind::ChatEvent || !streams.contains(&envelope.stream) {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::StreamEnd(end) if !end.message.content.trim().is_empty() => {
                    let id = end
                        .message
                        .message_id
                        .expect("usage stream end omitted message id");
                    assert!(message_ids.insert(envelope.stream.clone(), id).is_none());
                    if let Some(token_usage) = end.message.token_usage {
                        assert!(usage.insert(envelope.stream.clone(), token_usage).is_none());
                    }
                }
                ChatEvent::MessageMetadataUpdated(update) => {
                    assert_eq!(
                        message_ids.get(&envelope.stream),
                        Some(&update.message_id),
                        "late usage metadata crossed stream/message ownership"
                    );
                    if let Some(token_usage) = update.token_usage {
                        assert!(
                            metadata_updates.insert(envelope.stream.clone()),
                            "usage metadata was updated more than once for {}",
                            envelope.stream
                        );
                        usage.insert(envelope.stream.clone(), token_usage);
                    }
                }
                ChatEvent::TypingStatusChanged(false)
                    if message_ids.contains_key(&envelope.stream) =>
                {
                    idle.insert(envelope.stream.clone());
                }
                _ => {}
            }
        }
    })
    .await
    .expect("concurrent turns did not each receive correlated terminal usage");
    assert_ne!(message_ids[&streams[0]], message_ids[&streams[1]]);
    for stream in &streams {
        assert_known_message_usage(&usage[stream], "concurrent usage metadata");
        fixture.client.close_agent(stream).await.unwrap();
    }
}

async fn assert_native_subagent_usage_isolated(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let roots = fixture.workspace_roots();
    let prompt = match backend_kind {
        BackendKind::Claude => {
            "Use the built-in Agent tool exactly once in foreground mode with model=haiku. Tell the child not to use tools and to reply exactly CHILD_USAGE_ISOLATION_OK. Wait for it to finish, then reply exactly PARENT_USAGE_ISOLATION_OK. Do not use ToolSearch or any MCP tool."
        }
        BackendKind::Codex => {
            "Spawn exactly one native Codex subagent in foreground mode with fork_context=true. Tell it not to use tools and to reply exactly CHILD_USAGE_ISOLATION_OK. Wait for it to finish, then reply exactly PARENT_USAGE_ISOLATION_OK. Do not use any Tyde MCP agent-control tool."
        }
        BackendKind::Hermes => {
            "Call the built-in `delegate_task` tool exactly once to run one provider-native background subagent. Tell it not to use tools and to reply exactly CHILD_USAGE_ISOLATION_OK. Do not poll it. When its result starts the follow-up turn, reply exactly PARENT_USAGE_ISOLATION_OK. Do not call `mcp_tyde_tyde_spawn_agent` or any MCP tool."
        }
        _ => {
            "Use exactly one provider-native foreground subagent. Tell it not to use tools and to reply exactly CHILD_USAGE_ISOLATION_OK. Wait for it to finish, then reply exactly PARENT_USAGE_ISOLATION_OK."
        }
    };
    let (parent_stream, parent_start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "native-subagent-usage-isolation",
        prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;

    let mut child_stream = None;
    let mut child_id = None;
    let mut parent_messages = Vec::<ChatMessage>::new();
    let mut child_messages = Vec::<ChatMessage>::new();
    let mut parent_pending = Vec::<MessageMetadataUpdateData>::new();
    let mut child_pending = Vec::<MessageMetadataUpdateData>::new();
    let mut parent_stats = None::<TokenUsage>;
    let mut child_stats = None::<TokenUsage>;
    let mut child_total_only = None::<u64>;
    let mut child_idle = false;
    let mut parent_idle = false;
    let mut parent_finished = false;
    let mut trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(240), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "native child usage isolation").await;
            trace.push(format!("{:?} {}", envelope.kind, envelope.stream));
            if envelope.kind == FrameKind::NewAgent {
                let child: NewAgentPayload = envelope.parse_payload().unwrap();
                if child.parent_agent_id.as_ref() == Some(&parent_start.agent_id) {
                    assert_eq!(child.origin, AgentOrigin::BackendNative);
                    assert_eq!(child.backend_kind, backend_kind);
                    assert!(child_stream.replace(child.instance_stream).is_none());
                    assert!(child_id.replace(child.agent_id).is_none());
                }
                continue;
            }
            let is_parent = envelope.stream == parent_stream;
            let is_child = child_stream.as_ref() == Some(&envelope.stream);
            if !is_parent && !is_child {
                continue;
            }
            eprintln!(
                "NATIVE CHILD USAGE EVENT backend={backend_kind:?} owner={} kind={:?} payload={}",
                if is_parent { "parent" } else { "child" },
                envelope.kind,
                envelope.payload
            );
            match envelope.kind {
                FrameKind::AgentActivityStats => {
                    let payload: AgentActivityStatsPayload = envelope.parse_payload().unwrap();
                    if is_parent {
                        if payload.stats.token_usage.total_tokens > 0 {
                            parent_stats = Some(payload.stats.token_usage);
                        }
                    } else {
                        child_total_only =
                            payload.stats.token_usage_total_only.or(child_total_only);
                        child_stats = Some(payload.stats.token_usage);
                    }
                }
                FrameKind::ChatEvent => match envelope.parse_payload::<ChatEvent>().unwrap() {
                    ChatEvent::StreamEnd(end) => {
                        let mut message = end.message;
                        if is_parent {
                            fold_pending_metadata_updates(&mut message, &mut parent_pending);
                            parent_finished = true;
                            parent_messages.push(message);
                        } else {
                            fold_pending_metadata_updates(&mut message, &mut child_pending);
                            child_messages.push(message);
                        }
                    }
                    ChatEvent::MessageMetadataUpdated(update) => {
                        let (messages, pending) = if is_parent {
                            (&mut parent_messages, &mut parent_pending)
                        } else {
                            (&mut child_messages, &mut child_pending)
                        };
                        if let Some(message) = messages
                            .iter_mut()
                            .find(|message| message.message_id.as_ref() == Some(&update.message_id))
                        {
                            fold_metadata_update_into_message(message, update);
                        } else {
                            pending.push(update);
                        }
                    }
                    ChatEvent::TypingStatusChanged(false) => {
                        if is_parent {
                            parent_idle |= parent_finished;
                        } else {
                            child_idle = true;
                        }
                    }
                    ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::Error,
                        content,
                        ..
                    }) => panic!("{backend_kind:?} native child usage setup failed: {content}"),
                    ChatEvent::MessageAdded(mut message)
                        if is_child
                            && matches!(&message.sender, MessageSender::Assistant { .. }) =>
                    {
                        fold_pending_metadata_updates(&mut message, &mut child_pending);
                        child_messages.push(message);
                    }
                    _ => {}
                },
                FrameKind::AgentError => {
                    let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                    panic!(
                        "{backend_kind:?} native child usage setup failed: {}",
                        error.message
                    );
                }
                _ => {}
            }
            if child_idle && parent_idle && child_stats.is_some() && parent_stats.is_some() {
                break;
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "{backend_kind:?} did not expose complete parent/child usage; trace:\n{}",
            trace.join("\n")
        )
    });

    let child_turn = child_messages.iter().find_map(|message| {
        let usage = message.token_usage.as_ref()?;
        usage.turn.known_usage()
    });
    let child_first_turn_total = child_turn
        .map(|usage| usage.total_tokens)
        .or(child_total_only)
        .expect("native child's first completed turn omitted all usage");
    let child_cumulative_total = child_stats
        .as_ref()
        .filter(|usage| usage.total_tokens > 0)
        .map(|usage| usage.total_tokens)
        .or(child_total_only)
        .expect("native child activity stats omitted all usage");
    assert_eq!(
        child_cumulative_total, child_first_turn_total,
        "{backend_kind:?} native child's first cumulative activity usage inherited tokens outside the child's first turn"
    );
    if let Some(child_turn) = child_turn
        && child_stats
            .as_ref()
            .is_some_and(|usage| usage.total_tokens > 0)
    {
        assert_eq!(
            child_stats.as_ref().unwrap(),
            child_turn,
            "{backend_kind:?} native child activity fields disagreed with its first turn"
        );
    }
    if let Some(child_cumulative) = child_messages
        .iter()
        .find_map(|message| message.token_usage.as_ref()?.cumulative.known_usage())
    {
        assert_eq!(
            child_cumulative.total_tokens, child_first_turn_total,
            "{backend_kind:?} native child's first message cumulative usage inherited tokens outside the child"
        );
    }
    assert!(
        parent_stats.as_ref().unwrap().total_tokens > 0,
        "parent established no usage before native child accounting"
    );
    assert!(
        child_id.is_some(),
        "native child identity was not projected"
    );
    fixture.client.close_agent(&parent_stream).await.unwrap();
}

async fn assert_progress_concurrency_matrix(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let roots = fixture.workspace_roots();
    let prompt = match backend_kind {
        BackendKind::Claude => {
            "Use Bash exactly twice with run_in_background=true: first run `sleep 2; printf PROGRESS_CONCURRENT_ONE`, then run `sleep 3; printf PROGRESS_CONCURRENT_TWO`. Do not poll either. After both report Running, reply exactly PROGRESS_CONCURRENT_READY."
        }
        BackendKind::Codex => {
            "Call exec_command exactly twice with yield_time_ms=1000: first with cmd `sleep 2; printf PROGRESS_CONCURRENT_ONE`, then with cmd `sleep 3; printf PROGRESS_CONCURRENT_TWO`. Do not poll either. After both report Running, reply exactly PROGRESS_CONCURRENT_READY."
        }
        BackendKind::Hermes => {
            "Use terminal exactly twice with background=true: first run `sleep 2; printf PROGRESS_CONCURRENT_ONE`, then run `sleep 3; printf PROGRESS_CONCURRENT_TWO`. Do not poll either. After both report Running, reply exactly PROGRESS_CONCURRENT_READY."
        }
        _ => unreachable!("backend declares no native background-task progress"),
    };
    let (stream, _) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "progress-concurrency",
        prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let mut requests = HashSet::new();
    let mut running = HashSet::new();
    let mut completed = HashSet::new();
    let mut trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(180), async {
        while completed.len() != 2 {
            let envelope = expect_next_event(&mut fixture.client, "concurrent progress").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolRequest(request) => {
                    trace.push(format!("request:{}", request.tool_call_id));
                    assert!(requests.insert(request.tool_call_id));
                }
                ChatEvent::ToolProgress(progress) => {
                    let Some(_task) = background_task_progress(&progress.update) else {
                        continue;
                    };
                    assert!(requests.contains(&progress.tool_call_id));
                    assert_eq!(
                        progress.execution_mode,
                        protocol::ToolExecutionMode::Background
                    );
                    trace.push(format!("running:{}", progress.tool_call_id));
                    running.insert(progress.tool_call_id);
                }
                ChatEvent::ToolExecutionCompleted(completion) => {
                    trace.push(format!("completion:{}", completion.tool_call_id));
                    assert!(requests.contains(&completion.tool_call_id));
                    assert!(running.contains(&completion.tool_call_id));
                    assert!(completion.success(), "background command completion failed");
                    assert!(completed.insert(completion.tool_call_id));
                }
                ChatEvent::TypingStatusChanged(false) if completed.len() < 2 => {
                    assert_eq!(
                        running.len(),
                        2,
                        "foreground idled before both progress identities ran"
                    );
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => {
                    panic!("concurrent progress failed: {content}")
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!("two concurrent progress identities did not complete exactly once: {trace:?}")
    });
    assert_eq!(requests.len(), 2);
    assert_eq!(running.len(), 2);
    fixture.client.close_agent(&stream).await.unwrap();
}

fn progress_family(update: &protocol::ToolProgressUpdate) -> ProgressFamily {
    if background_task_progress(update).is_some() {
        return ProgressFamily::BackgroundTask;
    }
    match update {
        protocol::ToolProgressUpdate::SubAgent(_) => ProgressFamily::SubAgent,
        protocol::ToolProgressUpdate::Workflow(_) => ProgressFamily::Workflow,
        protocol::ToolProgressUpdate::AgentControl(_) => ProgressFamily::AgentControl,
        protocol::ToolProgressUpdate::Other { .. } => ProgressFamily::Other,
    }
}

fn assert_progress_payload_contract(progress: &protocol::ToolProgressData, context: &str) {
    assert!(
        !progress.tool_call_id.trim().is_empty(),
        "{context}: progress omitted its correlated request identity: {progress:?}"
    );
    let normalized_optional = |label: &str, value: Option<&str>| {
        if let Some(value) = value {
            assert!(
                !value.trim().is_empty(),
                "{context}: {label} used an empty-present value: {progress:?}"
            );
        }
    };
    match &progress.update {
        protocol::ToolProgressUpdate::Workflow(workflow) => {
            assert!(!workflow.workflow_name.trim().is_empty());
            assert_ne!(workflow.status, protocol::WorkflowRunStatus::Unknown);
            normalized_optional("workflow description", workflow.description.as_deref());
            normalized_optional("workflow script", workflow.script.as_deref());
            normalized_optional("workflow summary", workflow.summary.as_deref());
            let indexes = workflow
                .agents
                .iter()
                .map(|agent| agent.index)
                .collect::<HashSet<_>>();
            assert_eq!(indexes.len(), workflow.agents.len());
            assert!(
                workflow
                    .agents
                    .windows(2)
                    .all(|pair| pair[0].index < pair[1].index)
            );
            for agent in &workflow.agents {
                assert!(!agent.label.trim().is_empty());
                assert_ne!(agent.state, protocol::WorkflowAgentStatus::Unknown);
                normalized_optional("workflow phase title", agent.phase_title.as_deref());
                normalized_optional("workflow model", agent.model.as_deref());
                normalized_optional("workflow prompt preview", agent.prompt_preview.as_deref());
                normalized_optional("workflow result preview", agent.result_preview.as_deref());
            }
        }
        protocol::ToolProgressUpdate::SubAgent(subagent) => {
            assert!(!subagent.agent_id.0.trim().is_empty());
            assert!(!subagent.agent_name.trim().is_empty());
            assert_ne!(subagent.status, protocol::SubAgentProgressStatus::Unknown);
            normalized_optional("subagent last tool", subagent.last_tool_name.as_deref());
            assert_eq!(
                subagent.completed,
                subagent.status != protocol::SubAgentProgressStatus::Running,
                "{context}: subagent completed flag disagreed with status: {progress:?}"
            );
        }
        protocol::ToolProgressUpdate::AgentControl(control) => {
            assert_ne!(
                control.status,
                protocol::AgentControlProgressStatus::Unknown
            );
            let ids = control
                .agents
                .iter()
                .map(|agent| &agent.agent_id)
                .collect::<HashSet<_>>();
            assert_eq!(ids.len(), control.agents.len());
            for agent in &control.agents {
                assert!(!agent.agent_id.0.trim().is_empty());
                normalized_optional("agent-control name", agent.name.as_deref());
            }
        }
        protocol::ToolProgressUpdate::Other { payload } => {
            assert!(
                !payload.is_null(),
                "{context}: opaque progress lost its payload"
            );
            if let Some(task) = background_task_progress(&progress.update) {
                normalized_optional("background description", task.description.as_deref());
                normalized_optional("background summary", task.summary.as_deref());
            }
        }
    }
}

async fn apply_progress_boundary(
    fixture: &mut RealBackendFixture,
    _backend_kind: BackendKind,
    stream: &StreamPath,
    start: &AgentStartPayload,
    tool_call_id: &str,
    boundary: (ProgressFamily, ProgressTransition, &str),
) {
    let (family, transition, context) = boundary;
    match transition {
        ProgressTransition::RunningThenInterrupt => {
            fixture
                .client
                .interrupt(stream)
                .await
                .expect("interrupt running progress");
        }
        ProgressTransition::RunningThenClose => {
            fixture
                .client
                .close_agent(stream)
                .await
                .expect("close running progress");
        }
        ProgressTransition::RunningThenHostRestart => {
            fixture.restart_host().await;
            let session_id = start
                .session_id
                .clone()
                .expect("progress host restart session");
            let resumed = resume_agent_without_prompt_via_protocol(
                &mut fixture.client,
                "progress-host-restart",
                session_id,
            )
            .await;
            fixture
                .client
                .close_agent(&resumed)
                .await
                .expect("close resumed progress boundary agent");
        }
        ProgressTransition::RunningThenTransportClose => {
            assert!(
                fixture
                    .host
                    .force_agent_backend_shutdown_for_conformance(&start.agent_id)
                    .await
            );
        }
        ProgressTransition::RunningForkIsolation => {
            let session_id = start.session_id.clone().expect("progress fork session");
            let fork = fork_agent_via_protocol(
                &mut fixture.client,
                "progress-fork-isolation",
                start.agent_id.clone(),
                session_id,
                "Do not use tools. Reply exactly PROGRESS_FORK_ISOLATED.",
            )
            .await;
            let fork_bootstrap = reconnected_agent_bootstrap(fixture, &fork).await;
            assert!(
                fork_bootstrap.events.iter().all(|event| !matches!(
                    event,
                    AgentBootstrapEvent::ChatEvent(ChatEvent::ToolProgress(progress))
                        if progress_update_is_running(&progress.update)
                )),
                "{context} fork copied live source progress"
            );
            let fork_turn = expect_assistant_turn_after_user_echo(
                &mut fixture.client,
                &fork,
                "Do not use tools. Reply exactly PROGRESS_FORK_ISOLATED.",
            )
            .await;
            assert_eq!(
                fork_turn.final_text.trim(),
                "PROGRESS_FORK_ISOLATED",
                "{context} fork did not remain isolated"
            );
            fixture
                .client
                .close_agent(&fork)
                .await
                .expect("close progress fork");
            assert!(
                fixture.client.running_progress.contains(&(
                    stream.clone(),
                    tool_call_id.to_owned(),
                    family,
                )),
                "{context} fork terminalized the source progress"
            );
            fixture
                .client
                .close_agent(stream)
                .await
                .expect("close progress source after isolation oracle");
        }
        ProgressTransition::RunningToSuccess
        | ProgressTransition::RunningToFailure
        | ProgressTransition::RunningAcrossReconnect => {
            panic!("{context}: non-boundary transition passed to boundary helper")
        }
    }
}

async fn assert_progress_terminal_is_stable(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    tool_call_id: &str,
    family: ProgressFamily,
    context: &str,
) {
    assert!(
        fixture.client.terminal_progress.contains(&(
            stream.clone(),
            tool_call_id.to_owned(),
            family,
        )),
        "{context}: common trace auditor did not register the {family:?} terminal"
    );
}

fn progress_update_is_running(update: &protocol::ToolProgressUpdate) -> bool {
    match update {
        protocol::ToolProgressUpdate::SubAgent(state) => {
            state.status == protocol::SubAgentProgressStatus::Running
        }
        protocol::ToolProgressUpdate::Workflow(state) => {
            state.status == protocol::WorkflowRunStatus::Running
        }
        protocol::ToolProgressUpdate::AgentControl(state) => {
            state.status == protocol::AgentControlProgressStatus::Running
        }
        protocol::ToolProgressUpdate::Other { .. } => true,
    }
}

async fn assert_progress_boundary_is_stable(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    tool_call_id: &str,
    family: ProgressFamily,
    context: &str,
) {
    let mut collector = BufferedEventCollector::new(&mut fixture.client);
    tokio::time::timeout(REAL_BACKEND_TIMEOUT, async {
        loop {
            let envelope = collector.next(context).await;
            if envelope.kind == FrameKind::ChatEvent
                && envelope.stream == *stream
                && let ChatEvent::ToolExecutionCompleted(completion) = envelope
                    .parse_payload::<ChatEvent>()
                    .expect("parse boundary completion")
                && completion.tool_call_id == tool_call_id
            {
                break;
            }
            collector.defer(envelope);
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context}: {family:?} emitted no terminal completion"));
    collector.restore();
    assert_progress_terminal_is_stable(fixture, stream, tool_call_id, family, context).await;
}

async fn assert_subagent_progress_transition(
    backend_kind: BackendKind,
    mode: ProgressSubagentMode,
    transition: ProgressTransition,
) {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let tool = match mode {
        ProgressSubagentMode::Foreground => {
            assert!(
                capabilities.contains(tyde_agent_adapter::BackendCapability::ForegroundSubagents)
            );
            SpecialToolContract::AgentSpawn
        }
        ProgressSubagentMode::Background => {
            assert!(
                capabilities.contains(tyde_agent_adapter::BackendCapability::BackgroundSubagents)
            );
            SpecialToolContract::BackgroundSubagent
        }
        ProgressSubagentMode::NotApplicable => {
            panic!("subagent progress requires an execution mode")
        }
    };
    let (result, stimulus) = match transition {
        ProgressTransition::RunningToSuccess => (
            ToolResultVariant::Succeeds,
            ContractStimulus::ChildCompletes,
        ),
        ProgressTransition::RunningToFailure => {
            (ToolResultVariant::Fails, ContractStimulus::ChildFails)
        }
        ProgressTransition::RunningAcrossReconnect => (
            ToolResultVariant::Pending,
            ContractStimulus::DisconnectReconnect,
        ),
        ProgressTransition::RunningThenInterrupt => {
            (ToolResultVariant::Pending, ContractStimulus::Interrupt)
        }
        ProgressTransition::RunningThenClose => {
            (ToolResultVariant::Pending, ContractStimulus::Close)
        }
        ProgressTransition::RunningThenHostRestart => (
            ToolResultVariant::Pending,
            ContractStimulus::HostRestartResume,
        ),
        ProgressTransition::RunningThenTransportClose => (
            ToolResultVariant::Pending,
            ContractStimulus::TransportClosed,
        ),
        ProgressTransition::RunningForkIsolation => {
            (ToolResultVariant::Pending, ContractStimulus::Fork)
        }
    };
    let cell = ConformanceCoverageCell::required_for(&capabilities)
        .into_iter()
        .find(|cell| {
            cell.tool == tool
                && cell.result == result
                && cell.activity == ActivityCondition::ForegroundOnly
                && cell.stimulus == stimulus
        })
        .unwrap_or_else(|| {
            panic!("{backend_kind:?} has no canonical {tool:?} progress cell for {transition:?}")
        });
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    assert_native_spawn_contract_cell(&mut fixture, backend_kind, cell).await;
}

async fn assert_agent_control_progress_transition(
    backend_kind: BackendKind,
    transition: ProgressTransition,
) {
    let case = match transition {
        ProgressTransition::RunningToSuccess => {
            CertificationCase::AgentAwaitCompletesOnChildSuccess
        }
        ProgressTransition::RunningToFailure => {
            CertificationCase::AgentAwaitCompletesOnChildFailure
        }
        ProgressTransition::RunningAcrossReconnect => {
            CertificationCase::AgentAwaitSurvivesReconnect
        }
        ProgressTransition::RunningThenInterrupt => CertificationCase::AgentAwaitInterrupts,
        ProgressTransition::RunningThenClose => CertificationCase::AgentAwaitCloses,
        ProgressTransition::RunningThenHostRestart => {
            CertificationCase::AgentAwaitExpiresOnHostRestart
        }
        ProgressTransition::RunningThenTransportClose => {
            CertificationCase::AgentAwaitFailsOnTransportClose
        }
        ProgressTransition::RunningForkIsolation => CertificationCase::AgentAwaitNotCopiedToFork,
    };
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    assert_agent_await_case(
        &mut fixture,
        backend_kind,
        case,
        ActivityCondition::ForegroundOnly,
    )
    .await;
}

async fn assert_progress_family_lifecycle_matrix(backend_kind: BackendKind) {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let selected = std::env::var("TYDE_CONFORMANCE_PROGRESS_CELL").ok();
    let required = ProgressCoverageCell::required_for(&capabilities)
        .into_iter()
        .filter(|cell| {
            selected.as_ref().is_none_or(|filter| {
                let canonical = format!(
                    "{:?}_{:?}_{:?}",
                    cell.family, cell.subagent_mode, cell.transition
                );
                let legacy = format!("{:?}_{:?}", cell.family, cell.transition);
                canonical.eq_ignore_ascii_case(filter) || legacy.eq_ignore_ascii_case(filter)
            })
        })
        .collect::<Vec<_>>();
    assert!(
        selected.is_none() || !required.is_empty(),
        "TYDE_CONFORMANCE_PROGRESS_CELL matched no required progress cell: {:?}",
        selected
    );
    let execution = required.clone();
    let mut ledger = EnumeratedCoverageLedger::new(required, "progress-family lifecycle");

    for cell in execution {
        let ProgressCoverageCell {
            family,
            subagent_mode,
            transition,
        } = cell;
        match family {
            ProgressFamily::BackgroundTask => {
                let mut fixture = RealBackendFixture::new(backend_kind).await;
                let roots = fixture.workspace_roots();
                let command = if transition == ProgressTransition::RunningToFailure {
                    "sleep 3; exit 17"
                } else {
                    "sleep 3; printf PROGRESS_MATRIX_DONE"
                };
                let prompt = match backend_kind {
                    BackendKind::Claude => format!(
                        "Use Bash exactly once with run_in_background=true to run `{command}`. Do not poll it. Reply exactly PROGRESS_MATRIX_READY after it reports Running."
                    ),
                    BackendKind::Codex => format!(
                        "Call exec_command exactly once with cmd `{command}` and yield_time_ms=1000. Do not poll it. Reply exactly PROGRESS_MATRIX_READY after it reports Running."
                    ),
                    BackendKind::Hermes => format!(
                        "Use terminal exactly once with background=true to run `{command}`. Do not poll it. Reply exactly PROGRESS_MATRIX_READY after it reports Running."
                    ),
                    _ => unreachable!(),
                };
                let (stream, start) = spawn_agent_via_protocol_with_start(
                    &mut fixture.client,
                    roots,
                    backend_kind,
                    "progress-family-matrix",
                    &prompt,
                    None,
                    cost_hint_for(backend_kind),
                )
                .await;
                let mut tool_id = None;
                tokio::time::timeout(Duration::from_secs(120), async {
                    loop {
                        let envelope =
                            expect_next_event(&mut fixture.client, "background progress running")
                                .await;
                        if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                            continue;
                        }
                        match envelope.parse_payload::<ChatEvent>().unwrap() {
                            ChatEvent::ToolRequest(request) => match request.tool_type {
                                ToolRequestType::RunCommand { command: observed, .. }
                                    if observed.contains(command) =>
                                {
                                    assert!(
                                        tool_id.replace(request.tool_call_id).is_none(),
                                        "background progress issued more than one command request"
                                    );
                                }
                                other => panic!(
                                    "background progress issued an unexpected tool request: {other:?}"
                                ),
                            },
                            ChatEvent::ToolProgress(progress)
                                if progress_family(&progress.update) == family
                                    && background_task_progress(&progress.update).is_some() =>
                            {
                                assert_eq!(
                                    tool_id.as_deref(),
                                    Some(progress.tool_call_id.as_str())
                                );
                                break;
                            }
                            _ => {}
                        }
                    }
                })
                .await
                .expect("background progress emitted no running state");
                if transition == ProgressTransition::RunningAcrossReconnect {
                    let mut replacement = fixture.connect().await;
                    replacement.inherit_live_trace_from(&fixture.client);
                    std::mem::swap(&mut fixture.client, &mut replacement);
                    drop(replacement);
                } else if !matches!(
                    transition,
                    ProgressTransition::RunningToSuccess | ProgressTransition::RunningToFailure
                ) {
                    apply_progress_boundary(
                        &mut fixture,
                        backend_kind,
                        &stream,
                        &start,
                        tool_id.as_deref().unwrap(),
                        (
                            ProgressFamily::BackgroundTask,
                            transition,
                            "background task progress",
                        ),
                    )
                    .await;
                    assert_progress_boundary_is_stable(
                        &mut fixture,
                        &stream,
                        tool_id.as_deref().unwrap(),
                        ProgressFamily::BackgroundTask,
                        "background progress boundary stability",
                    )
                    .await;
                    ledger.record(cell).unwrap();
                    continue;
                }
                tokio::time::timeout(Duration::from_secs(120), async {
                    loop {
                        let envelope =
                            expect_next_event(&mut fixture.client, "background tool completion")
                                .await;
                        if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                            continue;
                        }
                        if let ChatEvent::ToolExecutionCompleted(completion) =
                            envelope.parse_payload::<ChatEvent>().unwrap()
                            && tool_id.as_deref() == Some(completion.tool_call_id.as_str())
                        {
                            if transition == ProgressTransition::RunningToFailure {
                                assert!(matches!(
                                    completion.outcome,
                                    ToolExecutionOutcome::Failed { .. }
                                        | ToolExecutionOutcome::Cancelled { .. }
                                ));
                            } else {
                                assert!(matches!(
                                    completion.outcome,
                                    ToolExecutionOutcome::Succeeded { .. }
                                ));
                            }
                            break;
                        }
                    }
                })
                .await
                .expect("background tool emitted no completion");
            }
            ProgressFamily::Workflow => {
                assert_workflow_progress_transition(backend_kind, transition).await;
            }
            ProgressFamily::Other => {
                assert_opaque_tool_progress_lifecycle(backend_kind, transition).await;
            }
            ProgressFamily::AgentControl => {
                assert_agent_control_progress_transition(backend_kind, transition).await;
            }
            ProgressFamily::SubAgent => {
                assert_subagent_progress_transition(backend_kind, subagent_mode, transition).await;
            }
        }
        ledger.record(cell).unwrap();
    }
    ledger.finish().unwrap();
}

fn install_real_skill(
    fixture: &RealBackendFixture,
    skill_name: &str,
    title: &str,
    body: &str,
) -> protocol::Skill {
    let skill_dir = fixture
        .session_store_dir
        .path()
        .join("skills")
        .join(skill_name);
    std::fs::create_dir_all(&skill_dir).expect("create skill directory");
    let skill = protocol::Skill {
        id: protocol::SkillId(skill_name.to_owned()),
        name: skill_name.to_owned(),
        title: Some(title.to_owned()),
        description: Some("Live conformance skill with a secret result".to_owned()),
    };
    std::fs::write(
        skill_dir.join("metadata.json"),
        serde_json::to_vec_pretty(&skill).expect("serialize skill metadata"),
    )
    .expect("write skill metadata");
    std::fs::write(skill_dir.join("SKILL.md"), body).expect("write skill body");
    skill
}

fn install_real_skill_record(
    fixture: &RealBackendFixture,
    directory_name: &str,
    skill: &protocol::Skill,
    body: &str,
) {
    let skill_dir = fixture
        .session_store_dir
        .path()
        .join("skills")
        .join(directory_name);
    std::fs::create_dir_all(&skill_dir).expect("create raw skill directory");
    std::fs::write(
        skill_dir.join("metadata.json"),
        serde_json::to_vec_pretty(skill).expect("serialize raw skill metadata"),
    )
    .expect("write raw skill metadata");
    std::fs::write(skill_dir.join("SKILL.md"), body).expect("write raw skill body");
}

fn assert_exact_skill_oracle(turn: &AssistantTurn, expected: &str, forbidden: &[&str]) {
    assert_eq!(
        turn.final_text.trim(),
        expected,
        "skill invocation did not execute exactly the selected body"
    );
    for sentinel in forbidden {
        assert!(
            !turn.final_text.contains(sentinel),
            "skill invocation leaked or invoked a forbidden sibling body: {sentinel}"
        );
    }
}

fn real_skill_prompt(
    backend_kind: BackendKind,
    skill_name: &str,
    fallback: Option<&str>,
) -> String {
    let fallback = fallback
        .map(|value| format!(" If that skill is unavailable, reply exactly `{value}`."))
        .unwrap_or_default();
    match backend_kind {
        BackendKind::Codex => format!(
            "Use ${skill_name} now and follow its instructions exactly.{fallback} Do not inspect files or use any other tool."
        ),
        _ => format!(
            "Invoke the installed skill named `{skill_name}` and follow its instructions exactly.{fallback} Do not inspect files or use any other tool."
        ),
    }
}

async fn invoke_real_skill(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    stream: &StreamPath,
    skill_name: &str,
    fallback: Option<&str>,
) -> AssistantTurn {
    let prompt = real_skill_prompt(backend_kind, skill_name, fallback);
    fixture
        .client
        .send_message(stream, prompt.clone())
        .await
        .unwrap();
    expect_assistant_turn_after_user_echo(&mut fixture.client, stream, &prompt).await
}

async fn spawn_real_skill_agent(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    name: &str,
    custom_agent_id: Option<protocol::CustomAgentId>,
) -> (StreamPath, AgentStartPayload) {
    let prompt = "Do not use tools. Reply exactly SKILL_SESSION_READY.";
    fixture
        .client
        .spawn_agent(SpawnAgentPayload {
            name: Some(name.to_owned()),
            custom_agent_id: custom_agent_id.clone(),
            parent_agent_id: None,
            project_id: None,
            params: SpawnAgentParams::New {
                workspace_roots: fixture.workspace_roots(),
                prompt: prompt.to_owned(),
                images: None,
                backend_kind,
                launch_profile_id: None,
                cost_hint: cost_hint_for(backend_kind),
                access_mode: Default::default(),
                session_settings: None,
            },
        })
        .await
        .expect("spawn skill agent");
    let new_agent = loop {
        let envelope = expect_next_event(&mut fixture.client, "skill NewAgent").await;
        if envelope.kind == FrameKind::NewAgent {
            break envelope
                .parse_payload::<NewAgentPayload>()
                .expect("parse skill NewAgent");
        }
    };
    assert_eq!(new_agent.custom_agent_id, custom_agent_id);
    let start = expect_agent_start_on_stream(
        &mut fixture.client,
        &new_agent.instance_stream,
        "skill AgentStart",
    )
    .await;
    expect_assistant_turn_after_user_echo(&mut fixture.client, &new_agent.instance_stream, prompt)
        .await;
    (new_agent.instance_stream, start)
}

async fn assert_skill_lifecycle_matrix(backend_kind: BackendKind) {
    const ALL_SENTINEL: &str = "SKILL_ALL_INSTALLED_SECRET_7F31";
    const SELECTED_V1: &str = "SKILL_SELECTED_SECRET_V1_4C92";
    const SELECTED_V2: &str = "SKILL_SELECTED_SECRET_V2_8A16";
    const EXCLUDED_SENTINEL: &str = "SKILL_EXCLUDED_SECRET_2D75";
    const UNAVAILABLE: &str = "SKILL_EXCLUDED_UNAVAILABLE";

    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let required = SkillLifecycleCell::required_for(&capabilities);
    let mut ledger = EnumeratedCoverageLedger::new(required, "skill lifecycle");
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let suffix = Uuid::new_v4().simple().to_string();
    let all_name = format!("live-all-{suffix}");
    let selected_name = format!("live-selected-{suffix}");
    let excluded_name = format!("live-excluded-{suffix}");
    let all_skill = install_real_skill(
        &fixture,
        &all_name,
        "All-installed live skill",
        &format!("When invoked, reply exactly `{ALL_SENTINEL}`."),
    );
    let selected_skill = install_real_skill(
        &fixture,
        &selected_name,
        "Explicit live skill",
        &format!("When invoked, reply exactly `{SELECTED_V1}`."),
    );
    let _excluded_skill = install_real_skill(
        &fixture,
        &excluded_name,
        "Excluded live skill",
        &format!("When invoked, reply exactly `{EXCLUDED_SENTINEL}`."),
    );
    fixture
        .client
        .inner
        .skill_refresh(protocol::SkillRefreshPayload {})
        .await
        .unwrap();

    let (all_stream, _) =
        spawn_real_skill_agent(&mut fixture, backend_kind, "skill-all-installed", None).await;
    let all_turn =
        invoke_real_skill(&mut fixture, backend_kind, &all_stream, &all_name, None).await;
    assert_eq!(all_turn.final_text.trim(), ALL_SENTINEL);
    assert!(
        all_turn.delta_count > 0,
        "all-installed skill result did not stream"
    );
    ledger
        .record(SkillLifecycleCell::AllInstalledInvoked)
        .unwrap();

    let custom_agent_id = protocol::CustomAgentId(format!("live-skill-agent-{suffix}"));
    fixture
        .client
        .inner
        .custom_agent_upsert(protocol::CustomAgentUpsertPayload {
            custom_agent: protocol::CustomAgent {
                id: custom_agent_id.clone(),
                name: "Live skill selection".to_owned(),
                description: "Real conformance skill selection".to_owned(),
                instructions: None,
                skill_ids: vec![selected_skill.id.clone()],
                mcp_server_ids: Vec::new(),
                tool_policy: protocol::ToolPolicy::Unrestricted,
            },
        })
        .await
        .unwrap();
    let (selected_stream, selected_start) = spawn_real_skill_agent(
        &mut fixture,
        backend_kind,
        "skill-explicit-selection",
        Some(custom_agent_id.clone()),
    )
    .await;
    let selected_turn = invoke_real_skill(
        &mut fixture,
        backend_kind,
        &selected_stream,
        &selected_name,
        None,
    )
    .await;
    assert_eq!(selected_turn.final_text.trim(), SELECTED_V1);
    ledger
        .record(SkillLifecycleCell::ExplicitSelectionInvoked)
        .unwrap();

    let excluded_turn = invoke_real_skill(
        &mut fixture,
        backend_kind,
        &selected_stream,
        &excluded_name,
        Some(UNAVAILABLE),
    )
    .await;
    assert_eq!(
        excluded_turn.final_text.trim(),
        UNAVAILABLE,
        "explicit skill selection exposed an unselected skill; secret={EXCLUDED_SENTINEL:?}"
    );
    ledger
        .record(SkillLifecycleCell::ExplicitSelectionExcludesUnselected)
        .unwrap();

    install_real_skill(
        &fixture,
        &selected_name,
        "Explicit live skill",
        &format!("When invoked, reply exactly `{SELECTED_V2}`."),
    );
    fixture
        .client
        .inner
        .skill_refresh(protocol::SkillRefreshPayload {})
        .await
        .unwrap();
    let active_turn = invoke_real_skill(
        &mut fixture,
        backend_kind,
        &selected_stream,
        &selected_name,
        None,
    )
    .await;
    assert_eq!(active_turn.final_text.trim(), SELECTED_V1);
    ledger
        .record(SkillLifecycleCell::ActiveSessionKeepsSpawnSnapshot)
        .unwrap();

    let mut replacement = fixture.connect().await;
    replacement.inherit_live_trace_from(&fixture.client);
    std::mem::swap(&mut fixture.client, &mut replacement);
    drop(replacement);
    let reconnect_stream = loop {
        let envelope = expect_next_event(&mut fixture.client, "skill reconnect").await;
        if envelope.kind == FrameKind::HostBootstrap {
            let bootstrap: HostBootstrapPayload = envelope.parse_payload().unwrap();
            break bootstrap
                .agents
                .into_iter()
                .find(|agent| agent.agent_id == selected_start.agent_id)
                .expect("skill reconnect omitted source")
                .instance_stream;
        }
    };
    let reconnect_turn = invoke_real_skill(
        &mut fixture,
        backend_kind,
        &reconnect_stream,
        &selected_name,
        None,
    )
    .await;
    assert_eq!(reconnect_turn.final_text.trim(), SELECTED_V1);
    ledger
        .record(SkillLifecycleCell::ClientReconnectKeepsSpawnSnapshot)
        .unwrap();

    let (fresh_stream, _) = spawn_real_skill_agent(
        &mut fixture,
        backend_kind,
        "skill-refreshed-session",
        Some(custom_agent_id.clone()),
    )
    .await;
    let fresh_turn = invoke_real_skill(
        &mut fixture,
        backend_kind,
        &fresh_stream,
        &selected_name,
        None,
    )
    .await;
    assert_eq!(fresh_turn.final_text.trim(), SELECTED_V2);
    ledger
        .record(SkillLifecycleCell::RefreshAffectsNewSession)
        .unwrap();

    let source_session = selected_start.session_id.clone().expect("skill session id");
    if capabilities.contains(BackendCapability::ForkSession) {
        let prompt = real_skill_prompt(backend_kind, &selected_name, None);
        let fork = fork_agent_via_protocol(
            &mut fixture.client,
            "skill-refreshed-fork",
            selected_start.agent_id.clone(),
            source_session.clone(),
            &prompt,
        )
        .await;
        let fork_turn =
            expect_assistant_turn_after_user_echo(&mut fixture.client, &fork, &prompt).await;
        assert_eq!(fork_turn.final_text.trim(), SELECTED_V2);
        ledger
            .record(SkillLifecycleCell::ForkUsesLatestSelection)
            .unwrap();
    }
    if capabilities.contains(BackendCapability::ResumeSession) {
        fixture.client.close_agent(&reconnect_stream).await.unwrap();
        let prompt = real_skill_prompt(backend_kind, &selected_name, None);
        let resumed = resume_agent_via_protocol(
            &mut fixture.client,
            "skill-refreshed-resume",
            source_session,
            &prompt,
        )
        .await;
        let resumed_turn =
            expect_assistant_turn_after_user_echo(&mut fixture.client, &resumed, &prompt).await;
        assert_eq!(resumed_turn.final_text.trim(), SELECTED_V2);
        ledger
            .record(SkillLifecycleCell::ResumeUsesLatestSelection)
            .unwrap();
    }

    const COLLISION_FIRST: &str = "SKILL_COLLISION_FIRST_93A1";
    const COLLISION_SECOND: &str = "SKILL_COLLISION_SECOND_B742";
    const DUPLICATE_ID_WINNER: &str = "SKILL_DUPLICATE_ID_WINNER_C815";
    const DUPLICATE_ID_LOSER: &str = "SKILL_DUPLICATE_ID_LOSER_D926";
    const DELETED_SENTINEL: &str = "SKILL_DELETED_SECRET_E037";
    const MISSING_SELECTED_SENTINEL: &str = "SKILL_MISSING_SELECTED_F148";
    const MATRIX_UNAVAILABLE: &str = "SKILL_MATRIX_UNAVAILABLE";

    let collision_first_name = format!("collision-name-{suffix}");
    let collision_second_name = format!("collision_name_{suffix}");
    install_real_skill(
        &fixture,
        &collision_first_name,
        "First normalized-name collision skill",
        &format!("When invoked, reply exactly `{COLLISION_FIRST}`."),
    );
    install_real_skill(
        &fixture,
        &collision_second_name,
        "Second normalized-name collision skill",
        &format!("When invoked, reply exactly `{COLLISION_SECOND}`."),
    );

    let duplicate_id = protocol::SkillId(format!("duplicate-id-{suffix}"));
    let duplicate_winner_name = format!("aa-duplicate-id-{suffix}");
    let duplicate_loser_name = format!("zz-duplicate-id-{suffix}");
    install_real_skill_record(
        &fixture,
        &duplicate_winner_name,
        &protocol::Skill {
            id: duplicate_id.clone(),
            name: duplicate_winner_name.clone(),
            title: Some("Duplicate id deterministic winner".to_owned()),
            description: Some("First directory by name".to_owned()),
        },
        &format!("When invoked, reply exactly `{DUPLICATE_ID_WINNER}`."),
    );
    install_real_skill_record(
        &fixture,
        &duplicate_loser_name,
        &protocol::Skill {
            id: duplicate_id,
            name: duplicate_loser_name.clone(),
            title: Some("Duplicate id deterministic loser".to_owned()),
            description: Some("Later directory by name".to_owned()),
        },
        &format!("When invoked, reply exactly `{DUPLICATE_ID_LOSER}`."),
    );

    let invalid_name = format!("invalid-metadata-{suffix}");
    let invalid_dir = fixture
        .session_store_dir
        .path()
        .join("skills")
        .join(&invalid_name);
    std::fs::create_dir_all(&invalid_dir).expect("create invalid metadata skill directory");
    std::fs::write(
        invalid_dir.join("metadata.json"),
        b"{ not valid skill metadata",
    )
    .expect("write invalid skill metadata");
    std::fs::write(
        invalid_dir.join("SKILL.md"),
        "When invoked, reply exactly `INVALID_METADATA_BODY_RAN`.",
    )
    .expect("write invalid metadata skill body");

    let deleted_name = format!("deleted-skill-{suffix}");
    install_real_skill(
        &fixture,
        &deleted_name,
        "Deleted refresh skill",
        &format!("When invoked, reply exactly `{DELETED_SENTINEL}`."),
    );
    fixture
        .client
        .inner
        .skill_refresh(protocol::SkillRefreshPayload {})
        .await
        .unwrap();

    let (matrix_stream, _) =
        spawn_real_skill_agent(&mut fixture, backend_kind, "skill-collision-matrix", None).await;
    let collision_first = invoke_real_skill(
        &mut fixture,
        backend_kind,
        &matrix_stream,
        &collision_first_name,
        None,
    )
    .await;
    assert_exact_skill_oracle(&collision_first, COLLISION_FIRST, &[COLLISION_SECOND]);
    ledger
        .record(SkillLifecycleCell::NormalizedNameCollisionFirstInvoked)
        .unwrap();
    let collision_second = invoke_real_skill(
        &mut fixture,
        backend_kind,
        &matrix_stream,
        &collision_second_name,
        None,
    )
    .await;
    assert_exact_skill_oracle(&collision_second, COLLISION_SECOND, &[COLLISION_FIRST]);
    ledger
        .record(SkillLifecycleCell::NormalizedNameCollisionSecondInvoked)
        .unwrap();
    let duplicate_winner = invoke_real_skill(
        &mut fixture,
        backend_kind,
        &matrix_stream,
        &duplicate_winner_name,
        None,
    )
    .await;
    assert_exact_skill_oracle(
        &duplicate_winner,
        DUPLICATE_ID_WINNER,
        &[DUPLICATE_ID_LOSER],
    );
    ledger
        .record(SkillLifecycleCell::DuplicateIdFirstDirectoryInvoked)
        .unwrap();
    let duplicate_loser = invoke_real_skill(
        &mut fixture,
        backend_kind,
        &matrix_stream,
        &duplicate_loser_name,
        Some(MATRIX_UNAVAILABLE),
    )
    .await;
    assert_exact_skill_oracle(
        &duplicate_loser,
        MATRIX_UNAVAILABLE,
        &[DUPLICATE_ID_LOSER, DUPLICATE_ID_WINNER],
    );
    ledger
        .record(SkillLifecycleCell::DuplicateIdLaterDirectoryExcluded)
        .unwrap();
    let invalid = invoke_real_skill(
        &mut fixture,
        backend_kind,
        &matrix_stream,
        &invalid_name,
        Some(MATRIX_UNAVAILABLE),
    )
    .await;
    assert_exact_skill_oracle(&invalid, MATRIX_UNAVAILABLE, &["INVALID_METADATA_BODY_RAN"]);
    ledger
        .record(SkillLifecycleCell::InvalidMetadataExcluded)
        .unwrap();

    fixture
        .client
        .inner
        .custom_agent_upsert(protocol::CustomAgentUpsertPayload {
            custom_agent: protocol::CustomAgent {
                id: custom_agent_id.clone(),
                name: "Live skill duplicate selection".to_owned(),
                description: "Duplicate selected skill id conformance".to_owned(),
                instructions: None,
                skill_ids: vec![selected_skill.id.clone(), selected_skill.id.clone()],
                mcp_server_ids: Vec::new(),
                tool_policy: protocol::ToolPolicy::Unrestricted,
            },
        })
        .await
        .expect("send duplicate selected skill upsert");
    let duplicate_selection_error = loop {
        let envelope =
            expect_next_event(&mut fixture.client, "duplicate selected skill rejection").await;
        if envelope.kind == FrameKind::CommandError {
            break envelope
                .parse_payload::<CommandErrorPayload>()
                .expect("parse duplicate selected skill CommandError");
        }
    };
    assert_eq!(
        duplicate_selection_error.code,
        protocol::CommandErrorCode::InvalidInput
    );
    assert_eq!(duplicate_selection_error.operation, "custom_agent_upsert");
    assert!(
        duplicate_selection_error.message.contains("duplicate id"),
        "duplicate selected skill rejection was not explicit: {duplicate_selection_error:?}"
    );
    ledger
        .record(SkillLifecycleCell::DuplicateSelectionIdRejected)
        .unwrap();

    std::fs::remove_dir_all(
        fixture
            .session_store_dir
            .path()
            .join("skills")
            .join(&deleted_name),
    )
    .expect("delete installed skill directory");
    fixture
        .client
        .inner
        .skill_refresh(protocol::SkillRefreshPayload {})
        .await
        .unwrap();
    let active_deleted = invoke_real_skill(
        &mut fixture,
        backend_kind,
        &matrix_stream,
        &deleted_name,
        None,
    )
    .await;
    assert_exact_skill_oracle(&active_deleted, DELETED_SENTINEL, &[MATRIX_UNAVAILABLE]);
    ledger
        .record(SkillLifecycleCell::DeletedSkillRemainsInActiveSnapshot)
        .unwrap();
    let (deleted_stream, _) =
        spawn_real_skill_agent(&mut fixture, backend_kind, "skill-deletion-refresh", None).await;
    let deleted = invoke_real_skill(
        &mut fixture,
        backend_kind,
        &deleted_stream,
        &deleted_name,
        Some(MATRIX_UNAVAILABLE),
    )
    .await;
    assert_exact_skill_oracle(&deleted, MATRIX_UNAVAILABLE, &[DELETED_SENTINEL]);
    ledger
        .record(SkillLifecycleCell::DeletionRefreshExcludesDeleted)
        .unwrap();

    let missing_name = format!("missing-selected-{suffix}");
    let missing_skill = install_real_skill(
        &fixture,
        &missing_name,
        "Missing explicitly selected skill",
        &format!("When invoked, reply exactly `{MISSING_SELECTED_SENTINEL}`."),
    );
    fixture
        .client
        .inner
        .skill_refresh(protocol::SkillRefreshPayload {})
        .await
        .unwrap();
    let missing_agent_id = protocol::CustomAgentId(format!("missing-skill-agent-{suffix}"));
    fixture
        .client
        .inner
        .custom_agent_upsert(protocol::CustomAgentUpsertPayload {
            custom_agent: protocol::CustomAgent {
                id: missing_agent_id.clone(),
                name: "Missing selected skill".to_owned(),
                description: "Selected skill disappears before spawn".to_owned(),
                instructions: None,
                skill_ids: vec![missing_skill.id],
                mcp_server_ids: Vec::new(),
                tool_policy: protocol::ToolPolicy::Unrestricted,
            },
        })
        .await
        .unwrap();
    std::fs::remove_dir_all(
        fixture
            .session_store_dir
            .path()
            .join("skills")
            .join(&missing_name),
    )
    .expect("delete selected skill before spawn");
    fixture
        .client
        .inner
        .skill_refresh(protocol::SkillRefreshPayload {})
        .await
        .unwrap();
    fixture
        .client
        .spawn_agent(SpawnAgentPayload {
            name: Some("skill-missing-selection".to_owned()),
            custom_agent_id: Some(missing_agent_id),
            parent_agent_id: None,
            project_id: None,
            params: SpawnAgentParams::New {
                workspace_roots: fixture.workspace_roots(),
                prompt: "Do not use tools. Reply exactly SKILL_SESSION_READY.".to_owned(),
                images: None,
                backend_kind,
                launch_profile_id: None,
                cost_hint: cost_hint_for(backend_kind),
                access_mode: Default::default(),
                session_settings: None,
            },
        })
        .await
        .expect("send missing selected skill spawn");
    let error = loop {
        let envelope =
            expect_next_event(&mut fixture.client, "missing selected skill rejection").await;
        match envelope.kind {
            FrameKind::CommandError => {
                break envelope
                    .parse_payload::<CommandErrorPayload>()
                    .expect("parse missing selected skill CommandError");
            }
            FrameKind::NewAgent => panic!("missing selected skill unexpectedly spawned an agent"),
            _ => {}
        }
    };
    assert_eq!(error.request_kind, FrameKind::SpawnAgent);
    assert_eq!(error.code, protocol::CommandErrorCode::NotFound);
    assert!(
        error.message.contains("cannot resolve missing skill")
            && error.message.contains(&missing_name),
        "missing selected skill rejection was not explicit: {error:?}"
    );
    ledger
        .record(SkillLifecycleCell::MissingSelectedSkillRejectsSpawn)
        .unwrap();
    ledger.finish().unwrap();
    let _ = all_skill;
}

#[derive(Clone)]
struct LiveHttpMcpServer;

impl ServerHandler for LiveHttpMcpServer {
    fn get_info(&self) -> ServerInfo {
        ServerInfo {
            capabilities: ServerCapabilities::builder().enable_tools().build(),
            ..Default::default()
        }
    }

    async fn list_tools(
        &self,
        _request: Option<PaginatedRequestParams>,
        _context: RequestContext<RoleServer>,
    ) -> Result<ListToolsResult, McpError> {
        Ok(ListToolsResult {
            tools: vec![Tool::new(
                "http_probe",
                "Return HTTP_MCP_AUTH_OK",
                serde_json::Map::new(),
            )],
            next_cursor: None,
            meta: None,
        })
    }

    async fn call_tool(
        &self,
        _request: CallToolRequestParams,
        _context: RequestContext<RoleServer>,
    ) -> Result<CallToolResult, McpError> {
        Ok(CallToolResult::success(vec![Content::text(
            "HTTP_MCP_AUTH_OK",
        )]))
    }
}

async fn connection_ownership_http_handler(
    State(initialize_count): State<Arc<AtomicUsize>>,
    Json(request): Json<Value>,
) -> Response {
    let Some(id) = request.get("id").cloned() else {
        return StatusCode::ACCEPTED.into_response();
    };
    let result = match request.get("method").and_then(Value::as_str) {
        Some("initialize") => {
            let prior = initialize_count.fetch_add(1, AtomicOrdering::SeqCst);
            eprintln!("TYDE MCP HTTP OWNERSHIP INITIALIZE prior={prior} request={request}");
            json!({
                "protocolVersion": request
                    .pointer("/params/protocolVersion")
                    .cloned()
                    .unwrap_or_else(|| json!("2025-06-18")),
                "capabilities": {"tools": {}},
                "serverInfo": {"name": "single-session-certification", "version": "1"}
            })
        }
        Some("tools/list") => json!({
            "tools": [{
                "name": "connection_ownership_probe",
                "description": "Return MCP_CONNECTION_OWNERSHIP_OK",
                "inputSchema": {"type": "object", "properties": {}, "additionalProperties": false}
            }]
        }),
        Some("tools/call") => json!({
            "content": [{"type": "text", "text": "MCP_CONNECTION_OWNERSHIP_OK"}],
            "isError": false
        }),
        _ => json!({}),
    };
    Json(json!({"jsonrpc": "2.0", "id": id, "result": result})).into_response()
}

