async fn start_authenticated_http_mcp() -> (String, tokio::task::JoinHandle<()>) {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("bind live HTTP MCP server");
    let address = listener.local_addr().expect("live HTTP MCP address");
    let mcp: StreamableHttpService<LiveHttpMcpServer, LocalSessionManager> =
        StreamableHttpService::new(
            || Ok(LiveHttpMcpServer),
            Default::default(),
            StreamableHttpServerConfig {
                stateful_mode: false,
                sse_keep_alive: None,
                ..Default::default()
            },
        );
    let auth = middleware::from_fn(
        |request: axum::extract::Request, next: middleware::Next| async move {
            let static_header = request
                .headers()
                .get("x-tyde-mcp-conformance")
                .and_then(|value| value.to_str().ok());
            let authorization = request
                .headers()
                .get("authorization")
                .and_then(|value| value.to_str().ok());
            if static_header != Some("static-header-ok")
                || authorization != Some("Bearer bearer-token-ok")
            {
                return StatusCode::UNAUTHORIZED.into_response();
            }
            next.run(request).await
        },
    );
    let task = tokio::spawn(async move {
        axum::serve(
            listener,
            Router::new().nest_service("/mcp", mcp).layer(auth),
        )
        .await
        .expect("serve live HTTP MCP");
    });
    (format!("http://{address}/mcp"), task)
}

async fn start_single_session_http_mcp() -> (String, tokio::task::JoinHandle<()>, Arc<AtomicUsize>)
{
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("bind single-session HTTP MCP server");
    let address = listener
        .local_addr()
        .expect("single-session HTTP MCP address");
    let sessions = Arc::new(AtomicUsize::new(0));
    let state = Arc::clone(&sessions);
    let task = tokio::spawn(async move {
        axum::serve(
            listener,
            Router::new()
                .route("/mcp", post(connection_ownership_http_handler))
                .with_state(state),
        )
        .await
        .expect("serve single-session HTTP MCP");
    });
    (format!("http://{address}/mcp"), task, sessions)
}

