async fn start_broken_http_mcp(timeout: bool) -> (String, tokio::task::JoinHandle<()>) {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("bind broken HTTP MCP server");
    let address = listener.local_addr().expect("broken HTTP MCP address");
    let task = tokio::spawn(async move {
        while let Ok((mut socket, _)) = listener.accept().await {
            let mut request = [0_u8; 4096];
            let _ = socket.read(&mut request).await;
            if timeout {
                std::future::pending::<()>().await;
            } else {
                let _ = socket
                    .write_all(
                        b"HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: 8\r\n\r\nnot-json",
                    )
                    .await;
            }
        }
    });
    (format!("http://{address}/mcp"), task)
}

async fn start_call_dropping_http_mcp()
-> (String, Vec<tokio::task::JoinHandle<()>>, Arc<AtomicUsize>) {
    let upstream_listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("bind call-dropping HTTP MCP upstream");
    let upstream_address = upstream_listener
        .local_addr()
        .expect("call-dropping HTTP MCP upstream address");
    let mcp: StreamableHttpService<LiveHttpMcpServer, LocalSessionManager> =
        StreamableHttpService::new(
            || Ok(LiveHttpMcpServer),
            Default::default(),
            StreamableHttpServerConfig {
                stateful_mode: false,
                sse_keep_alive: None,
                ..Default::default()
            },
        );
    let upstream = tokio::spawn(async move {
        axum::serve(upstream_listener, Router::new().nest_service("/mcp", mcp))
            .await
            .expect("serve call-dropping HTTP MCP upstream");
    });

    let proxy_listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("bind call-dropping HTTP MCP proxy");
    let proxy_address = proxy_listener
        .local_addr()
        .expect("call-dropping HTTP MCP proxy address");
    let dropped_calls = Arc::new(AtomicUsize::new(0));
    let proxy_drop_count = Arc::clone(&dropped_calls);
    let proxy = tokio::spawn(async move {
        while let Ok((client, _)) = proxy_listener.accept().await {
            let proxy_drop_count = Arc::clone(&proxy_drop_count);
            tokio::spawn(async move {
                let Ok(upstream) = tokio::net::TcpStream::connect(upstream_address).await else {
                    return;
                };
                let (mut client_read, mut client_write) = client.into_split();
                let (mut upstream_read, mut upstream_write) = upstream.into_split();
                let request_path = async {
                    let mut buffer = [0_u8; 8192];
                    let mut recent = Vec::new();
                    loop {
                        let count = client_read.read(&mut buffer).await?;
                        if count == 0 {
                            return std::io::Result::Ok(());
                        }
                        recent.extend_from_slice(&buffer[..count]);
                        if recent
                            .windows(b"tools/call".len())
                            .any(|window| window == b"tools/call")
                        {
                            proxy_drop_count.fetch_add(1, AtomicOrdering::SeqCst);
                            return Ok(());
                        }
                        if recent.len() > 64 * 1024 {
                            recent.drain(..recent.len() - 1024);
                        }
                        upstream_write.write_all(&buffer[..count]).await?;
                    }
                };
                let response_path = async {
                    tokio::io::copy(&mut upstream_read, &mut client_write).await?;
                    std::io::Result::Ok(())
                };
                tokio::select! {
                    _ = request_path => {}
                    _ = response_path => {}
                }
            });
        }
    });
    (
        format!("http://{proxy_address}/mcp"),
        vec![proxy, upstream],
        dropped_calls,
    )
}

async fn expect_http_mcp_startup_failure(
    backend_kind: BackendKind,
    url: String,
    context: &str,
    activity: ActivityCondition,
) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let ambient_context = format!(
        "MCP_HTTP_STARTUP_{}_AMBIENT",
        context.to_ascii_uppercase().replace('-', "_")
    );
    let (ambient_stream, ambient_ids, ambient_release) =
        start_mcp_activity_ambient(&mut fixture, backend_kind, activity, &ambient_context).await;
    fixture
        .client
        .inner
        .mcp_server_upsert(protocol::McpServerUpsertPayload {
            mcp_server: protocol::McpServerConfig {
                id: protocol::McpServerId(format!("http-{context}")),
                name: format!("http_{context}"),
                supports_parallel_tool_calls: false,
                transport: protocol::McpTransportConfig::Http {
                    url,
                    headers: HashMap::new(),
                    bearer_token_env_var: None,
                },
            },
        })
        .await
        .expect("install broken HTTP MCP");
    fixture
        .client
        .spawn_agent(SpawnAgentPayload {
            name: Some(format!("http-{context}")),
            custom_agent_id: None,
            parent_agent_id: None,
            project_id: None,
            params: SpawnAgentParams::New {
                workspace_roots: fixture.workspace_roots(),
                prompt: "Do not use tools. Reply exactly HTTP_MCP_MUST_NOT_START.".to_owned(),
                images: None,
                backend_kind,
                launch_profile_id: None,
                cost_hint: cost_hint_for(backend_kind),
                access_mode: Default::default(),
                session_settings: None,
            },
        })
        .await
        .expect("submit broken HTTP MCP startup");
    let diagnostic = tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope = expect_next_unfiltered_event(&mut fixture.client, context).await;
            match envelope.kind {
                FrameKind::AgentError => {
                    break envelope
                        .parse_payload::<protocol::AgentErrorPayload>()
                        .expect("parse HTTP MCP AgentError")
                        .message;
                }
                FrameKind::ChatEvent => {
                    if let ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::Error | MessageSender::Warning,
                        content,
                        ..
                    }) = envelope.parse_payload().expect("parse HTTP MCP ChatEvent")
                    {
                        break content;
                    }
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{backend_kind:?} did not bound HTTP MCP {context}"));
    assert!(
        diagnostic.to_ascii_lowercase().contains("mcp"),
        "HTTP MCP {context} failure was unnamed: {diagnostic}"
    );
    finish_mcp_activity_ambient(
        &mut fixture,
        &ambient_stream,
        &ambient_ids,
        activity,
        ambient_release,
        "HTTP MCP startup failure ambient lifecycle",
    )
    .await;
}

async fn start_mcp_activity_ambient(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
    context: &str,
) -> (
    StreamPath,
    HashSet<String>,
    Option<tokio::task::JoinHandle<()>>,
) {
    let expected = format!("{context}_READY");
    std::fs::write(
        fixture.workspace_dir.path().join("MCP_AMBIENT_READY.txt"),
        &expected,
    )
    .expect("write MCP ambient readiness file");
    let prompt = match backend_kind {
        BackendKind::Acp => "Read MCP_AMBIENT_READY.txt from the current workspace and reply with its exact contents. This is a normal repository inspection task.".to_owned(),
        _ => format!("Do not use tools. Reply exactly {context}_READY."),
    };
    let roots = fixture.workspace_roots();
    let stream = spawn_agent_via_protocol(
        &mut fixture.client,
        roots,
        backend_kind,
        "mcp-activity-ambient",
        &prompt,
    )
    .await;
    let ready = expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, &prompt).await;
    assert_eq!(
        ready.final_text.matches(&expected).count(),
        1,
        "MCP ambient readiness response did not contain its unique marker exactly once"
    );
    let ids = start_agent_control_ambient_work(fixture, backend_kind, &stream, activity).await;
    ambient_before_stimulus(
        fixture,
        &stream,
        &ids,
        activity,
        ContractStimulus::ProviderAccepts,
        context,
    )
    .await;
    let release = schedule_image_ambient_during_stimulus(
        fixture,
        activity,
        ContractStimulus::ProviderAccepts,
    );
    (stream, ids, release)
}

async fn finish_mcp_activity_ambient(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    ids: &HashSet<String>,
    activity: ActivityCondition,
    release: Option<tokio::task::JoinHandle<()>>,
    context: &str,
) {
    finish_image_ambient_during_stimulus(
        release,
        fixture,
        stream,
        ids,
        activity,
        ContractStimulus::ProviderAccepts,
        context,
    )
    .await;
    ambient_after_stimulus(
        fixture,
        stream,
        ids,
        activity,
        ContractStimulus::ProviderAccepts,
        context,
    )
    .await;
}

async fn assert_mcp_http_transport_activity_row(
    backend_kind: BackendKind,
    activity: ActivityCondition,
) {
    let mut ledger = EnumeratedCoverageLedger::new(McpHttpTransportCell::ALL, "MCP HTTP transport");
    let mut failure_ledger = EnumeratedCoverageLedger::new(
        [
            McpFailureConsistencyCell::RuntimeNamedToolError,
            McpFailureConsistencyCell::RuntimeSocketDrop,
        ],
        "MCP HTTP runtime failure consistency",
    );
    let (url, server) = start_authenticated_http_mcp().await;
    let _token = EnvVarGuard::set("TYDE_MCP_HTTP_BEARER", "bearer-token-ok".to_owned());
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let (ambient_stream, ambient_ids, ambient_release) = start_mcp_activity_ambient(
        &mut fixture,
        backend_kind,
        activity,
        "MCP_HTTP_SUCCESS_AMBIENT",
    )
    .await;
    fixture
        .client
        .inner
        .mcp_server_upsert(protocol::McpServerUpsertPayload {
            mcp_server: protocol::McpServerConfig {
                id: protocol::McpServerId("authenticated-http-live".to_owned()),
                name: "authenticated_http_live".to_owned(),
                supports_parallel_tool_calls: false,
                transport: protocol::McpTransportConfig::Http {
                    url,
                    headers: HashMap::from([(
                        "x-tyde-mcp-conformance".to_owned(),
                        "static-header-ok".to_owned(),
                    )]),
                    bearer_token_env_var: Some("TYDE_MCP_HTTP_BEARER".to_owned()),
                },
            },
        })
        .await
        .expect("install authenticated HTTP MCP");
    let prompt = match backend_kind {
        BackendKind::Codex => {
            "Invoke the MCP tool `http_probe` from server `authenticated_http_live` exactly once, then reply with its exact result."
        }
        _ => {
            "Use MCP tool `http_probe` from server `authenticated_http_live` exactly once, then reply with its exact result."
        }
    };
    let roots = fixture.workspace_roots();
    let stream = spawn_agent_via_protocol(
        &mut fixture.client,
        roots,
        backend_kind,
        "authenticated-http-mcp",
        prompt,
    )
    .await;
    let turn = expect_tool_turn_after_user_echo(&mut fixture.client, &stream, prompt).await;
    assert_eq!(
        turn.tool_requests.len(),
        1,
        "authenticated HTTP MCP emitted wrong or extra tool requests: {turn:?}"
    );
    assert_eq!(
        turn.tool_completions.len(),
        1,
        "authenticated HTTP MCP emitted missing, wrong, or extra terminals: {turn:?}"
    );
    let request = turn
        .tool_requests
        .iter()
        .find(|request| turn.tool_name(&request.tool_call_id).contains("http_probe"))
        .expect("authenticated HTTP MCP tool was not discovered or called");
    let completion = turn
        .tool_completions
        .iter()
        .find(|completion| completion.tool_call_id == request.tool_call_id)
        .expect("authenticated HTTP MCP call lacked correlated completion");
    assert!(completion.success(), "HTTP MCP call failed: {completion:?}");
    assert!(
        serde_json::to_string(&completion.tool_result())
            .expect("serialize HTTP MCP result")
            .contains("HTTP_MCP_AUTH_OK"),
        "HTTP MCP result was not preserved: {completion:?}"
    );
    let mut delivered_text = turn.final_text.clone();
    let mut streamed_text = String::new();
    while !delivered_text.contains("HTTP_MCP_AUTH_OK") {
        let envelope = expect_next_event(&mut fixture.client, "HTTP MCP result delivery").await;
        if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
            continue;
        }
        match envelope
            .parse_payload::<ChatEvent>()
            .expect("parse HTTP MCP delivery")
        {
            ChatEvent::StreamStart(_) => streamed_text.clear(),
            ChatEvent::StreamDelta(delta) => streamed_text.push_str(&delta.text),
            ChatEvent::StreamEnd(end) => {
                delivered_text = if end.message.content.trim().is_empty() {
                    streamed_text.clone()
                } else {
                    end.message.content
                };
            }
            ChatEvent::MessageAdded(ChatMessage {
                sender: MessageSender::Error,
                content,
                ..
            }) => panic!("HTTP MCP result delivery failed: {content}"),
            ChatEvent::TypingStatusChanged(false) => {
                panic!("model became idle before receiving HTTP MCP result: {delivered_text:?}")
            }
            _ => {}
        }
    }
    for cell in [
        McpHttpTransportCell::Discovery,
        McpHttpTransportCell::AuthHeaders,
        McpHttpTransportCell::BearerToken,
        McpHttpTransportCell::CorrelatedCallResult,
    ] {
        ledger.record(cell).expect("record HTTP MCP success cell");
    }
    finish_mcp_activity_ambient(
        &mut fixture,
        &ambient_stream,
        &ambient_ids,
        activity,
        ambient_release,
        "HTTP MCP success ambient lifecycle",
    )
    .await;
    server.abort();

    let (url, server) = start_error_http_mcp().await;
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let (ambient_stream, ambient_ids, ambient_release) = start_mcp_activity_ambient(
        &mut fixture,
        backend_kind,
        activity,
        "MCP_HTTP_ERROR_AMBIENT",
    )
    .await;
    fixture
        .client
        .inner
        .mcp_server_upsert(protocol::McpServerUpsertPayload {
            mcp_server: protocol::McpServerConfig {
                id: protocol::McpServerId("error-http-live".to_owned()),
                name: "error_http_live".to_owned(),
                supports_parallel_tool_calls: false,
                transport: protocol::McpTransportConfig::Http {
                    url,
                    headers: HashMap::new(),
                    bearer_token_env_var: None,
                },
            },
        })
        .await
        .expect("install error HTTP MCP");
    let prompt = match backend_kind {
        BackendKind::Codex => {
            "Invoke the MCP tool `http_probe` from server `error_http_live` exactly once. Do not call another tool. Stop after the call fails."
        }
        _ => {
            "Use MCP tool `http_probe` from server `error_http_live` exactly once. Do not call another tool. Stop after the call fails."
        }
    };
    let roots = fixture.workspace_roots();
    let stream = spawn_agent_via_protocol(
        &mut fixture.client,
        roots,
        backend_kind,
        "error-http-mcp",
        prompt,
    )
    .await;
    let turn = tokio::time::timeout(
        Duration::from_secs(120),
        expect_tool_turn_after_user_echo(&mut fixture.client, &stream, prompt),
    )
    .await
    .expect("HTTP MCP call error did not terminalize");
    assert_eq!(
        turn.tool_requests.len(),
        1,
        "HTTP MCP call error emitted wrong or extra tool requests: {turn:?}"
    );
    assert_eq!(
        turn.tool_completions.len(),
        1,
        "HTTP MCP call error emitted missing, wrong, or extra terminals: {turn:?}"
    );
    let requests = turn
        .tool_requests
        .iter()
        .filter(|request| turn.tool_name(&request.tool_call_id).contains("http_probe"))
        .collect::<Vec<_>>();
    assert_eq!(
        requests.len(),
        1,
        "HTTP MCP call error repeated its request"
    );
    let completions = turn
        .tool_completions
        .iter()
        .filter(|completion| completion.tool_call_id == requests[0].tool_call_id)
        .collect::<Vec<_>>();
    assert_eq!(
        completions.len(),
        1,
        "HTTP MCP call error did not emit exactly one correlated terminal"
    );
    assert_failed_mcp_request_result_contract(
        requests[0],
        completions[0],
        "named HTTP MCP call error",
    );
    let diagnostic = format!(
        "{:?} {:?}",
        completions[0].error(),
        completions[0].tool_result()
    );
    assert!(
        diagnostic.contains("HTTP_MCP_CALL_ERROR"),
        "HTTP MCP call error lost its diagnostic: {diagnostic}"
    );
    server.abort();
    finish_mcp_activity_ambient(
        &mut fixture,
        &ambient_stream,
        &ambient_ids,
        activity,
        ambient_release,
        "HTTP MCP named error ambient lifecycle",
    )
    .await;
    ledger
        .record(McpHttpTransportCell::CallErrorBounded)
        .expect("record HTTP MCP call error");
    failure_ledger
        .record(McpFailureConsistencyCell::RuntimeNamedToolError)
        .expect("record named HTTP MCP call error");

    let (url, servers, dropped_calls) = start_call_dropping_http_mcp().await;
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let (ambient_stream, ambient_ids, ambient_release) = start_mcp_activity_ambient(
        &mut fixture,
        backend_kind,
        activity,
        "MCP_HTTP_DROP_AMBIENT",
    )
    .await;
    fixture
        .client
        .inner
        .mcp_server_upsert(protocol::McpServerUpsertPayload {
            mcp_server: protocol::McpServerConfig {
                id: protocol::McpServerId("call-dropping-http-live".to_owned()),
                name: "call_dropping_http_live".to_owned(),
                supports_parallel_tool_calls: false,
                transport: protocol::McpTransportConfig::Http {
                    url,
                    headers: HashMap::new(),
                    bearer_token_env_var: None,
                },
            },
        })
        .await
        .expect("install call-dropping HTTP MCP");
    let prompt = match backend_kind {
        BackendKind::Codex => {
            "Invoke the MCP tool `http_probe` from server `call_dropping_http_live` exactly once. Do not call another tool. Stop after the call fails."
        }
        _ => {
            "Use MCP tool `http_probe` from server `call_dropping_http_live` exactly once. Do not call another tool. Stop after the call fails."
        }
    };
    let roots = fixture.workspace_roots();
    let stream = spawn_agent_via_protocol(
        &mut fixture.client,
        roots,
        backend_kind,
        "call-dropping-http-mcp",
        prompt,
    )
    .await;
    let turn = tokio::time::timeout(
        Duration::from_secs(120),
        expect_tool_turn_after_user_echo(&mut fixture.client, &stream, prompt),
    )
    .await
    .expect("HTTP MCP socket drop did not terminalize");
    assert_eq!(
        turn.tool_requests.len(),
        1,
        "HTTP MCP socket drop emitted wrong or extra tool requests: {turn:?}"
    );
    assert_eq!(
        turn.tool_completions.len(),
        1,
        "HTTP MCP socket drop emitted missing, wrong, or extra terminals: {turn:?}"
    );
    let requests = turn
        .tool_requests
        .iter()
        .filter(|request| turn.tool_name(&request.tool_call_id).contains("http_probe"))
        .collect::<Vec<_>>();
    assert_eq!(
        requests.len(),
        1,
        "HTTP MCP socket drop repeated its tool request"
    );
    let completions = turn
        .tool_completions
        .iter()
        .filter(|completion| completion.tool_call_id == requests[0].tool_call_id)
        .collect::<Vec<_>>();
    assert_eq!(
        completions.len(),
        1,
        "HTTP MCP socket drop did not emit exactly one correlated terminal"
    );
    assert_failed_mcp_request_result_contract(requests[0], completions[0], "HTTP MCP socket drop");
    assert_eq!(
        dropped_calls.load(AtomicOrdering::SeqCst),
        1,
        "HTTP MCP call was silently retried after its socket dropped"
    );
    for server in servers {
        server.abort();
    }
    finish_mcp_activity_ambient(
        &mut fixture,
        &ambient_stream,
        &ambient_ids,
        activity,
        ambient_release,
        "HTTP MCP socket-drop ambient lifecycle",
    )
    .await;
    ledger
        .record(McpHttpTransportCell::CallSocketDropBounded)
        .expect("record HTTP MCP call socket drop");
    failure_ledger
        .record(McpFailureConsistencyCell::RuntimeSocketDrop)
        .expect("record HTTP MCP runtime socket drop");

    let (url, server) = start_broken_http_mcp(false).await;
    expect_http_mcp_startup_failure(backend_kind, url, "malformed-response", activity).await;
    ledger
        .record(McpHttpTransportCell::MalformedResponseBounded)
        .expect("record malformed HTTP MCP response");
    server.abort();

    let (url, server) = start_broken_http_mcp(true).await;
    expect_http_mcp_startup_failure(backend_kind, url, "timeout", activity).await;
    ledger
        .record(McpHttpTransportCell::TimeoutBounded)
        .expect("record HTTP MCP timeout");
    server.abort();
    ledger.finish().expect("complete MCP HTTP transport matrix");
    failure_ledger
        .finish()
        .expect("complete MCP HTTP runtime failure consistency");
}

