fn assert_connection_ownership_tool_turn(turn: &ToolTurn, context: &str) {
    assert_eq!(
        turn.tool_requests.len(),
        1,
        "{context}: ownership probe emitted wrong or extra tool requests"
    );
    assert_eq!(
        turn.tool_completions.len(),
        1,
        "{context}: ownership probe emitted missing, wrong, or extra terminals"
    );
    let requests = turn
        .tool_requests
        .iter()
        .filter(|request| {
            turn.tool_name(&request.tool_call_id)
                .contains("connection_ownership_probe")
        })
        .collect::<Vec<_>>();
    assert_eq!(
        requests.len(),
        1,
        "{context}: ownership probe was not called exactly once"
    );
    let completions = turn
        .tool_completions
        .iter()
        .filter(|completion| completion.tool_call_id == requests[0].tool_call_id)
        .collect::<Vec<_>>();
    assert_eq!(
        completions.len(),
        1,
        "{context}: ownership probe did not terminalize exactly once"
    );
    assert!(
        completions[0].success(),
        "{context}: ownership probe failed: {:?}",
        completions[0]
    );
    assert!(
        serde_json::to_string(&completions[0].tool_result())
            .expect("serialize ownership probe result")
            .contains("MCP_CONNECTION_OWNERSHIP_OK"),
        "{context}: ownership probe result was lost: {:?}",
        completions[0]
    );
}

async fn assert_mcp_connection_ownership_matrix(backend_kind: BackendKind) {
    let selected = std::env::var("TYDE_CONFORMANCE_MCP_CONNECTION_CELL").ok();
    let required = McpConnectionOwnershipCell::ALL
        .iter()
        .copied()
        .filter(|cell| {
            selected
                .as_ref()
                .is_none_or(|selected| format!("{cell:?}").eq_ignore_ascii_case(selected))
        })
        .collect::<Vec<_>>();
    assert!(
        selected.is_none() || !required.is_empty(),
        "TYDE_CONFORMANCE_MCP_CONNECTION_CELL matched no ownership cell: {selected:?}"
    );
    let mut ledger = EnumeratedCoverageLedger::new(required.clone(), "MCP connection ownership");

    for cell in required {
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        let mut stdio_journal = None;
        let mut http_server = None;
        let mut http_sessions = None;
        let transport = match cell {
            McpConnectionOwnershipCell::StdioSingleProcess => {
                let script = fixture.workspace_dir.path().join("single_process_mcp.py");
                let claim = fixture
                    .workspace_dir
                    .path()
                    .join("single_process_mcp.claim");
                let journal = fixture
                    .workspace_dir
                    .path()
                    .join("single_process_mcp.launches");
                std::fs::write(
                    &script,
                    r#"import json, os, sys
claim, journal = sys.argv[1:]
with open(journal, "a", encoding="utf-8") as launches:
    launches.write("launch\n")
    launches.flush()
try:
    claim_fd = os.open(claim, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
    os.close(claim_fd)
except FileExistsError:
    sys.exit(73)
for line in sys.stdin:
    request = json.loads(line)
    request_id = request.get("id")
    if request_id is None:
        continue
    method = request.get("method")
    if method == "initialize":
        result = {"protocolVersion":"2025-06-18","capabilities":{"tools":{}},"serverInfo":{"name":"single-process-certification","version":"1"}}
    elif method == "tools/list":
        result = {"tools":[{"name":"connection_ownership_probe","description":"Return MCP_CONNECTION_OWNERSHIP_OK","inputSchema":{"type":"object","properties":{},"additionalProperties":False}}]}
    elif method == "tools/call":
        result = {"content":[{"type":"text","text":"MCP_CONNECTION_OWNERSHIP_OK"}],"isError":False}
    else:
        result = {}
    print(json.dumps({"jsonrpc":"2.0","id":request_id,"result":result}), flush=True)
"#,
                )
                .expect("write single-process MCP server");
                stdio_journal = Some(journal.clone());
                protocol::McpTransportConfig::Stdio {
                    command: "python3".to_owned(),
                    args: vec![
                        script.to_string_lossy().to_string(),
                        claim.to_string_lossy().to_string(),
                        journal.to_string_lossy().to_string(),
                    ],
                    env: HashMap::new(),
                }
            }
            McpConnectionOwnershipCell::HttpSingleSession => {
                let (url, server, sessions) = start_single_session_http_mcp().await;
                http_server = Some(server);
                http_sessions = Some(sessions);
                protocol::McpTransportConfig::Http {
                    url,
                    headers: HashMap::new(),
                    bearer_token_env_var: None,
                }
            }
        };
        fixture
            .client
            .inner
            .mcp_server_upsert(protocol::McpServerUpsertPayload {
                mcp_server: protocol::McpServerConfig {
                    id: protocol::McpServerId(format!("connection-ownership-{cell:?}")),
                    name: "connection_ownership_live".to_owned(),
                    supports_parallel_tool_calls: false,
                    transport,
                },
            })
            .await
            .expect("install connection-ownership MCP server");
        let prompt = match backend_kind {
            BackendKind::Codex => {
                "Invoke the MCP tool whose description says Return MCP_CONNECTION_OWNERSHIP_OK exactly once, then reply with its exact result."
            }
            _ => {
                "Use the MCP tool whose description says Return MCP_CONNECTION_OWNERSHIP_OK exactly once, then reply with its exact result."
            }
        };
        let roots = fixture.workspace_roots();
        let stream = spawn_agent_via_protocol(
            &mut fixture.client,
            roots,
            backend_kind,
            "mcp-connection-ownership",
            prompt,
        )
        .await;
        let turn = tokio::time::timeout(
            Duration::from_secs(120),
            expect_named_tool_turn_after_user_echo(
                &mut fixture.client,
                &stream,
                prompt,
                "connection_ownership_probe",
            ),
        )
        .await
        .expect("connection ownership probe did not complete");
        assert_connection_ownership_tool_turn(&turn, &format!("{backend_kind:?} {cell:?}"));

        if let Some(journal) = stdio_journal {
            let launches = std::fs::read_to_string(journal)
                .expect("read single-process MCP launch journal")
                .lines()
                .count();
            assert_eq!(
                launches, 1,
                "{backend_kind:?} started a disposable MCP process before the provider-owned process"
            );
        }
        if let Some(sessions) = http_sessions {
            assert_eq!(
                sessions.load(AtomicOrdering::SeqCst),
                1,
                "{backend_kind:?} opened a disposable MCP session before the provider-owned session"
            );
        }
        if let Some(server) = http_server {
            server.abort();
        }
        ledger.record(cell).expect("record MCP ownership cell");
    }
    ledger
        .finish()
        .expect("complete MCP connection ownership matrix");
}

async fn observe_mcp_case(backend_kind: BackendKind) -> ToolTurn {
    const TOOL_NAME: &str = "narrow_probe";
    const SENTINEL: &str = "NARROW_MCP_OK";
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let script = fixture.workspace_dir.path().join("narrow_mcp_probe.py");
    std::fs::write(
        &script,
        r#"import json, sys
for line in sys.stdin:
    request = json.loads(line)
    request_id = request.get("id")
    if request_id is None:
        continue
    if request.get("method") == "initialize":
        result = {"protocolVersion":"2025-06-18","capabilities":{"tools":{}},"serverInfo":{"name":"narrow-certification","version":"1"}}
    elif request.get("method") == "tools/list":
        result = {"tools":[{"name":"narrow_probe","description":"Return NARROW_MCP_OK","inputSchema":{"type":"object","properties":{},"additionalProperties":False}}]}
    elif request.get("method") == "tools/call":
        result = {"content":[{"type":"text","text":"NARROW_MCP_OK"}],"isError":False}
    else:
        result = {}
    print(json.dumps({"jsonrpc":"2.0","id":request_id,"result":result}), flush=True)
"#,
    )
    .expect("write narrow MCP server");
    fixture
        .client
        .inner
        .mcp_server_upsert(protocol::McpServerUpsertPayload {
            mcp_server: protocol::McpServerConfig {
                id: protocol::McpServerId("narrow-live-mcp".to_owned()),
                name: "narrow_certification".to_owned(),
                supports_parallel_tool_calls: false,
                transport: protocol::McpTransportConfig::Stdio {
                    command: "python3".to_owned(),
                    args: vec![script.to_string_lossy().to_string()],
                    env: HashMap::new(),
                },
            },
        })
        .await
        .expect("install narrow MCP server");
    let prompt = "Call the MCP tool whose description says Return NARROW_MCP_OK, then reply with its exact result.";
    let roots = fixture.workspace_roots();
    let stream = spawn_agent_via_protocol(
        &mut fixture.client,
        roots,
        backend_kind,
        "narrow-mcp-case",
        prompt,
    )
    .await;
    let mut turn = expect_tool_turn_after_user_echo(&mut fixture.client, &stream, prompt).await;
    let complete = |turn: &ToolTurn| {
        turn.tool_requests.iter().any(|request| {
            turn.tool_name(&request.tool_call_id)
                .to_ascii_lowercase()
                .contains(TOOL_NAME)
                && turn.tool_completions.iter().any(|completion| {
                    completion.tool_call_id == request.tool_call_id && completion.success()
                })
        }) && turn.final_text.contains(SENTINEL)
    };
    let mut streamed_text = String::new();
    while !complete(&turn) {
        let env = expect_next_event(&mut fixture.client, "completed narrow MCP turn").await;
        if env.kind != FrameKind::ChatEvent || env.stream != stream {
            continue;
        }
        let event: ChatEvent = env.parse_payload().expect("parse narrow MCP ChatEvent");
        match event {
            ChatEvent::StreamStart(_) => streamed_text.clear(),
            ChatEvent::StreamDelta(delta) => streamed_text.push_str(&delta.text),
            ChatEvent::StreamEnd(data) => {
                turn.final_text = if data.message.content.trim().is_empty() {
                    streamed_text.clone()
                } else {
                    data.message.content
                };
            }
            ChatEvent::ToolRequest(request) => {
                if !turn
                    .tool_requests
                    .iter()
                    .any(|existing| existing.tool_call_id == request.tool_call_id)
                {
                    turn.tool_requests.push(request);
                }
            }
            ChatEvent::ToolExecutionCompleted(completion) => {
                if let Some(existing) = turn
                    .tool_completions
                    .iter_mut()
                    .find(|existing| existing.tool_call_id == completion.tool_call_id)
                {
                    *existing = completion;
                } else {
                    turn.tool_completions.push(completion);
                }
            }
            ChatEvent::MessageAdded(ChatMessage {
                sender: MessageSender::Error,
                content,
                ..
            }) => panic!("narrow MCP turn failed: {content}"),
            ChatEvent::TypingStatusChanged(false) => {
                panic!("narrow MCP turn became idle before delivering its tool result: {turn:?}")
            }
            _ => {}
        }
    }
    assert_eq!(
        turn.tool_requests.len(),
        1,
        "narrow MCP probe emitted wrong or extra tool requests: {turn:?}"
    );
    assert_eq!(
        turn.tool_completions.len(),
        1,
        "narrow MCP probe emitted missing, wrong, or extra terminals: {turn:?}"
    );
    let request = &turn.tool_requests[0];
    assert!(
        turn.tool_name(&request.tool_call_id)
            .to_ascii_lowercase()
            .contains(TOOL_NAME)
    );
    let ToolRequestType::Other { args } = &request.tool_type else {
        panic!("narrow MCP probe did not normalize to generic Other: {turn:?}")
    };
    assert_eq!(
        args,
        &json!({}),
        "narrow MCP probe changed its empty arguments"
    );
    assert_eq!(turn.tool_completions[0].tool_call_id, request.tool_call_id);
    turn
}

const ADVERSARIAL_MCP_NAME: &str = "adversarial_mcp_live";
const ADVERSARIAL_MCP_TOOL: &str = "echo_value";
const ADVERSARIAL_MCP_MODES: [&str; 11] = [
    "startup_exit",
    "malformed_initialize",
    "malformed_schema",
    "duplicate_schema",
    "initialize_timeout",
    "list_timeout",
    "wrong_response_id",
    "malformed_json",
    "stderr_flood",
    "duplicate_late_response",
    "http_unreachable",
];

fn selected_adversarial_mcp_mode() -> Option<String> {
    std::env::var("TYDE_CONFORMANCE_MCP_ADVERSARIAL_MODE")
        .ok()
        .filter(|value| !value.trim().is_empty())
        .map(|value| {
            let value = value.trim().to_owned();
            assert!(
                ADVERSARIAL_MCP_MODES.contains(&value.as_str()),
                "unknown adversarial MCP mode {value:?}"
            );
            value
        })
}

fn write_adversarial_mcp_fixture(fixture: &RealBackendFixture) -> PathBuf {
    let script = fixture.workspace_dir.path().join("adversarial_mcp.py");
    std::fs::write(
        &script,
        r#"import json, os, sys, time
mode, journal, release = sys.argv[1:4]
def record(kind, **fields):
    with open(journal, "a") as output:
        output.write(json.dumps({"kind":kind, "pid":os.getpid(), **fields}) + "\n")
        output.flush()
record("process_start", mode=mode)
if mode == "startup_exit":
    sys.exit(19)
for line in sys.stdin:
    request = json.loads(line)
    request_id = request.get("id")
    method = request.get("method")
    if request_id is None:
        continue
    record("request", method=method)
    if method == "initialize":
        if mode == "initialize_timeout":
            time.sleep(90)
        if mode == "malformed_initialize":
            result = {"protocolVersion":17,"capabilities":"broken","serverInfo":None}
        else:
            result = {"protocolVersion":"2025-06-18","capabilities":{"tools":{}},"serverInfo":{"name":"adversarial-mcp","version":"1"}}
    elif method == "tools/list":
        if mode == "list_timeout":
            time.sleep(90)
        schema = {"type":"object","properties":{"value":{"type":"string"}},"required":["value"],"additionalProperties":False}
        tool = {"name":"echo_value","description":"Echo the supplied value","inputSchema":schema}
        if mode == "malformed_schema":
            tool["inputSchema"] = {"type":"definitely-not-a-json-schema-type"}
            result = {"tools":[tool]}
        elif mode == "duplicate_schema":
            result = {"tools":[tool, dict(tool)]}
        else:
            result = {"tools":[tool]}
    elif method == "tools/call":
        value = request.get("params", {}).get("arguments", {}).get("value", "")
        record("call", value=value)
        if mode == "pending_death":
            os._exit(23)
        if mode == "wrong_response_id":
            print(json.dumps({"jsonrpc":"2.0","id":"definitely-wrong-id","result":{"content":[{"type":"text","text":"WRONG"}]}}), flush=True)
            os._exit(24)
        if mode == "malformed_json":
            print("{this is not json", flush=True)
            os._exit(25)
        if mode == "stderr_flood":
            sys.stderr.write("MCP_STDERR_FLOOD" * 131072)
            sys.stderr.flush()
        if mode == "pending_wait" or (mode == "pending_wait_first" and "BEFORE" in value):
            while not os.path.exists(release):
                time.sleep(0.05)
        env_value = os.environ.get("TYDE_MCP_STDIO_SENTINEL", "")
        result = {"content":[{"type":"text","text":"ADVERSARIAL_MCP_RESULT:" + value + env_value}],"isError":False}
    else:
        result = {}
    response = json.dumps({"jsonrpc":"2.0","id":request_id,"result":result})
    print(response, flush=True)
    if mode == "duplicate_late_response" and method == "tools/call":
        print(response, flush=True)
        record("duplicate_response", request_id=request_id)
record("process_loop_ended")
"#,
    )
    .expect("write adversarial MCP fixture");
    script
}

fn adversarial_mcp_journal(fixture: &RealBackendFixture) -> PathBuf {
    fixture.workspace_dir.path().join("adversarial_mcp.journal")
}

fn adversarial_mcp_release(fixture: &RealBackendFixture) -> PathBuf {
    fixture.workspace_dir.path().join("adversarial_mcp.release")
}

async fn install_adversarial_mcp(fixture: &mut RealBackendFixture, mode: &str) {
    let journal = adversarial_mcp_journal(fixture);
    install_named_adversarial_mcp(
        fixture,
        mode,
        "adversarial-mcp-live",
        ADVERSARIAL_MCP_NAME,
        journal,
    )
    .await;
}

async fn install_named_adversarial_mcp(
    fixture: &mut RealBackendFixture,
    mode: &str,
    id: &str,
    name: &str,
    journal: PathBuf,
) {
    let script = write_adversarial_mcp_fixture(fixture);
    let release = adversarial_mcp_release(fixture);
    let _ = std::fs::remove_file(&journal);
    let _ = std::fs::remove_file(&release);
    fixture
        .client
        .inner
        .mcp_server_upsert(protocol::McpServerUpsertPayload {
            mcp_server: protocol::McpServerConfig {
                id: protocol::McpServerId(id.to_owned()),
                name: name.to_owned(),
                supports_parallel_tool_calls: false,
                transport: protocol::McpTransportConfig::Stdio {
                    command: "python3".to_owned(),
                    args: vec![
                        script.to_string_lossy().to_string(),
                        mode.to_owned(),
                        journal.to_string_lossy().to_string(),
                        release.to_string_lossy().to_string(),
                    ],
                    env: HashMap::new(),
                },
            },
        })
        .await
        .expect("install adversarial MCP server");
}

fn read_adversarial_mcp_journal(fixture: &RealBackendFixture) -> Vec<Value> {
    std::fs::read_to_string(adversarial_mcp_journal(fixture))
        .unwrap_or_default()
        .lines()
        .map(|line| serde_json::from_str(line).expect("parse adversarial MCP journal"))
        .collect()
}

async fn wait_for_adversarial_journal(journal: PathBuf, kind: &str, count: usize) {
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let actual = std::fs::read_to_string(&journal)
                .unwrap_or_default()
                .lines()
                .map(|line| {
                    serde_json::from_str::<Value>(line).expect("parse adversarial MCP journal")
                })
                .filter(|entry| entry.get("kind").and_then(Value::as_str) == Some(kind))
                .count();
            if actual >= count {
                break;
            }
            tokio::time::sleep(Duration::from_millis(50)).await;
        }
    })
    .await
    .unwrap_or_else(|_| panic!("adversarial MCP journal never recorded {count} {kind} entries"));
}

async fn wait_for_adversarial_process_exit(journal: PathBuf) {
    let pid = tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let pid = std::fs::read_to_string(&journal)
                .unwrap_or_default()
                .lines()
                .filter_map(|line| serde_json::from_str::<Value>(line).ok())
                .find(|entry| entry.get("kind").and_then(Value::as_str) == Some("process_start"))
                .and_then(|entry| entry.get("pid").and_then(Value::as_u64));
            if let Some(pid) = pid {
                break pid;
            }
            tokio::time::sleep(Duration::from_millis(50)).await;
        }
    })
    .await
    .expect("adversarial MCP process never recorded its pid");

    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let alive = std::process::Command::new("kill")
                .args(["-0", &pid.to_string()])
                .stdout(Stdio::null())
                .stderr(Stdio::null())
                .status()
                .is_ok_and(|status| status.success());
            eprintln!("ADVERSARIAL MCP PROCESS pid={pid} alive={alive}");
            if !alive {
                break;
            }
            tokio::time::sleep(Duration::from_millis(50)).await;
        }
    })
    .await
    .unwrap_or_else(|_| panic!("adversarial MCP process {pid} remained alive"));
}

fn adversarial_mcp_prompt(backend_kind: BackendKind, value: &str, wait: bool) -> String {
    let tail = if wait {
        "Do not respond before the tool returns."
    } else {
        "After it returns, stop."
    };
    match backend_kind {
        BackendKind::Codex => format!(
            "Invoke tool `{ADVERSARIAL_MCP_TOOL}` from MCP server `{ADVERSARIAL_MCP_NAME}` exactly once. Pass exactly this JSON arguments object: {{\"value\":\"{value}\"}}. Do not call another tool. {tail}"
        ),
        _ => format!(
            "Use the MCP tool `{ADVERSARIAL_MCP_TOOL}` from server `{ADVERSARIAL_MCP_NAME}` exactly once with value `{value}`. Do not call another tool. {tail}"
        ),
    }
}

async fn reach_adversarial_mcp_request(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    prompt: &str,
    name: &str,
) -> (StreamPath, AgentStartPayload, protocol::ToolRequest) {
    let roots = fixture.workspace_roots();
    let (stream, start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        name,
        prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let mut saw_user = false;
    let mut events = Vec::new();
    let mut tool_names = HashMap::new();
    let tool_request = tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, "adversarial MCP request").await;
            if envelope.kind == FrameKind::AgentError && envelope.stream == stream {
                let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                panic!(
                    "backend failed before adversarial MCP request: {}",
                    error.message
                );
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            let event = envelope.parse_payload::<ChatEvent>().unwrap();
            events.push(format!("{event:?}"));
            match event {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == prompt => saw_user = true,
                ChatEvent::StreamEnd(end) if saw_user => {
                    for tool in end.message.tool_calls {
                        tool_names.insert(tool.tool_call_id, tool.name);
                    }
                }
                ChatEvent::ToolRequest(request) if saw_user => {
                    assert!(
                        tool_names
                            .get(&request.tool_call_id)
                            .is_some_and(|name| name.contains(ADVERSARIAL_MCP_TOOL)),
                        "adversarial MCP setup invoked a wrong tool: {request:?}"
                    );
                    let ToolRequestType::Other { args } = &request.tool_type else {
                        panic!("adversarial MCP request did not normalize to Other: {request:?}")
                    };
                    let object = args.as_object().unwrap_or_else(|| {
                        panic!("adversarial MCP arguments were not an object: {request:?}")
                    });
                    assert_eq!(
                        object.len(),
                        1,
                        "adversarial MCP request added arguments: {request:?}"
                    );
                    let value = object
                        .get("value")
                        .and_then(Value::as_str)
                        .unwrap_or_else(|| {
                            panic!("adversarial MCP request omitted string value: {request:?}")
                        });
                    assert!(
                        prompt.contains(value),
                        "adversarial MCP request changed the requested sentinel: {request:?}"
                    );
                    break request;
                }
                ChatEvent::TypingStatusChanged(false) if saw_user => {
                    panic!("adversarial MCP turn became idle before invoking its tool")
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "adversarial MCP tool was not called after events:\n{}",
            events.join("\n")
        )
    });
    (stream, start, tool_request)
}

async fn wait_for_adversarial_turn_idle(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    context: &str,
) {
    tokio::time::timeout(Duration::from_secs(60), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, context).await;
            if envelope.kind == FrameKind::AgentError && envelope.stream == *stream {
                let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                panic!("adversarial MCP turn failed: {}", error.message);
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::TypingStatusChanged(false) => break,
                ChatEvent::ToolRequest(request) => {
                    panic!("{context}: emitted an extra MCP request after its terminal: {request:?}")
                }
                ChatEvent::ToolExecutionCompleted(completion) => panic!(
                    "{context}: emitted an extra MCP terminal after its expected terminal: {completion:?}"
                ),
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("adversarial MCP turn failed: {content}"),
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context} did not become idle"));
}

async fn assert_no_adversarial_mcp_activity(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    context: &str,
) {
    let mut collector = BufferedEventCollector::new(&mut fixture.client);
    let deadline = Instant::now() + Duration::from_millis(500);
    while Instant::now() < deadline {
        let remaining = deadline.saturating_duration_since(Instant::now());
        let observation = tokio::time::timeout(
            remaining.min(Duration::from_millis(50)),
            collector.next(context),
        )
        .await;
        let Ok(envelope) = observation else { continue };
        if envelope.stream != *stream {
            collector.defer(envelope);
            continue;
        }
        if envelope.kind == FrameKind::AgentError {
            let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
            panic!("{context}: emitted a late AgentError: {error:?}");
        }
        if envelope.kind != FrameKind::ChatEvent {
            collector.defer(envelope);
            continue;
        }
        match envelope.parse_payload::<ChatEvent>().unwrap() {
            ChatEvent::ToolRequest(request) => {
                panic!("{context}: emitted a late MCP request: {request:?}")
            }
            ChatEvent::ToolExecutionCompleted(completion) => {
                panic!("{context}: emitted a late MCP terminal: {completion:?}")
            }
            _ => collector.defer(envelope),
        }
    }
    collector.restore();
}

async fn expect_nonfatal_mcp_startup_turn(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    prompt: &str,
    sentinel: &str,
) {
    let mut stream = None;
    let mut saw_user = false;
    let mut saw_response = false;
    tokio::time::timeout(Duration::from_secs(60), async {
        loop {
            let envelope =
                expect_next_unfiltered_event(&mut fixture.client, "nonfatal custom MCP startup")
                    .await;
            if envelope.kind == FrameKind::NewAgent {
                let new_agent: NewAgentPayload = envelope.parse_payload().unwrap();
                stream = Some(new_agent.instance_stream);
                continue;
            }
            if stream
                .as_ref()
                .is_some_and(|stream| stream != &envelope.stream)
            {
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                panic!(
                    "{backend_kind:?} made custom MCP startup failure fatal: {}",
                    error.message
                );
            }
            if envelope.kind != FrameKind::ChatEvent {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Warning,
                    ..
                }) => {}
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{backend_kind:?} emitted a fatal-looking MCP error: {content}"),
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == prompt => saw_user = true,
                ChatEvent::StreamEnd(end) if saw_user && end.message.content.contains(sentinel) => {
                    saw_response = true;
                }
                ChatEvent::TypingStatusChanged(false) if saw_user && saw_response => {
                    break;
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!("{backend_kind:?} did not complete after a custom MCP server failed")
    });
}

async fn assert_mcp_startup_adversarial_activity_row(
    backend_kind: BackendKind,
    activity: ActivityCondition,
) {
    let selected_mode = selected_adversarial_mcp_mode();
    let startup_modes = [
        (
            "startup_exit",
            McpFailureConsistencyCell::StartupProcessExit,
        ),
        (
            "malformed_initialize",
            McpFailureConsistencyCell::StartupMalformedInitialize,
        ),
        (
            "malformed_schema",
            McpFailureConsistencyCell::StartupMalformedSchema,
        ),
        (
            "duplicate_schema",
            McpFailureConsistencyCell::StartupDuplicateSchema,
        ),
        (
            "http_unreachable",
            McpFailureConsistencyCell::StartupHttpUnreachable,
        ),
    ];
    let required = startup_modes
        .iter()
        .filter(|(mode, _)| {
            selected_mode
                .as_deref()
                .is_none_or(|selected| selected == *mode)
        })
        .map(|(_, cell)| *cell)
        .collect::<Vec<_>>();
    let mut failure_ledger =
        EnumeratedCoverageLedger::new(required, "MCP startup failure consistency");
    for (mode, cell) in startup_modes.into_iter().take(4) {
        if selected_mode
            .as_deref()
            .is_some_and(|selected| selected != mode)
        {
            continue;
        }
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        let ambient_context = format!("MCP_STARTUP_{}_AMBIENT", mode.to_ascii_uppercase());
        let (ambient_stream, ambient_ids, ambient_release) =
            start_mcp_activity_ambient(&mut fixture, backend_kind, activity, &ambient_context)
                .await;
        install_adversarial_mcp(&mut fixture, mode).await;
        let prompt = "Do not use tools. Reply exactly MCP_STARTUP_CONTINUES.";
        fixture
            .client
            .spawn_agent(SpawnAgentPayload {
                name: Some(format!("mcp-startup-{mode}")),
                custom_agent_id: None,
                parent_agent_id: None,
                project_id: None,
                params: SpawnAgentParams::New {
                    workspace_roots: fixture.workspace_roots(),
                    prompt: prompt.to_owned(),
                    images: None,
                    backend_kind,
                    launch_profile_id: None,
                    cost_hint: cost_hint_for(backend_kind),
                    access_mode: Default::default(),
                    session_settings: None,
                },
            })
            .await
            .expect("submit adversarial MCP startup");
        expect_nonfatal_mcp_startup_turn(
            &mut fixture,
            backend_kind,
            prompt,
            "MCP_STARTUP_CONTINUES",
        )
        .await;
        wait_for_adversarial_process_exit(adversarial_mcp_journal(&fixture)).await;
        finish_mcp_activity_ambient(
            &mut fixture,
            &ambient_stream,
            &ambient_ids,
            activity,
            ambient_release,
            "MCP stdio startup failure ambient lifecycle",
        )
        .await;
        failure_ledger.record(cell).unwrap();
    }

    if selected_mode
        .as_deref()
        .is_none_or(|selected| selected == "http_unreachable")
    {
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        let (ambient_stream, ambient_ids, ambient_release) = start_mcp_activity_ambient(
            &mut fixture,
            backend_kind,
            activity,
            "MCP_HTTP_UNREACHABLE_AMBIENT",
        )
        .await;
        fixture
            .client
            .inner
            .mcp_server_upsert(protocol::McpServerUpsertPayload {
                mcp_server: protocol::McpServerConfig {
                    id: protocol::McpServerId("unreachable-http-live".to_owned()),
                    name: "unreachable_http_live".to_owned(),
                    supports_parallel_tool_calls: false,
                    transport: protocol::McpTransportConfig::Http {
                        url: "http://127.0.0.1:1/mcp".to_owned(),
                        headers: HashMap::new(),
                        bearer_token_env_var: None,
                    },
                },
            })
            .await
            .expect("install unreachable HTTP MCP server");
        fixture
            .client
            .spawn_agent(SpawnAgentPayload {
                name: Some("mcp-startup-http-unreachable".to_owned()),
                custom_agent_id: None,
                parent_agent_id: None,
                project_id: None,
                params: SpawnAgentParams::New {
                    workspace_roots: fixture.workspace_roots(),
                    prompt: "Do not use tools. Reply exactly MCP_HTTP_CONTINUES.".to_owned(),
                    images: None,
                    backend_kind,
                    launch_profile_id: None,
                    cost_hint: cost_hint_for(backend_kind),
                    access_mode: Default::default(),
                    session_settings: None,
                },
            })
            .await
            .expect("submit unreachable HTTP MCP startup");
        expect_nonfatal_mcp_startup_turn(
            &mut fixture,
            backend_kind,
            "Do not use tools. Reply exactly MCP_HTTP_CONTINUES.",
            "MCP_HTTP_CONTINUES",
        )
        .await;
        failure_ledger
            .record(McpFailureConsistencyCell::StartupHttpUnreachable)
            .unwrap();
        finish_mcp_activity_ambient(
            &mut fixture,
            &ambient_stream,
            &ambient_ids,
            activity,
            ambient_release,
            "unreachable HTTP MCP startup ambient lifecycle",
        )
        .await;
    }
    failure_ledger.finish().unwrap();
}

async fn assert_mcp_startup_adversarial_contract(backend_kind: BackendKind) {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    for activity in conformance_activity_conditions(&capabilities) {
        assert_mcp_startup_adversarial_activity_row(backend_kind, activity).await;
    }
}

async fn expect_adversarial_call_terminal(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    tool_call_id: &str,
    expected_success: bool,
    context: &str,
) -> ToolExecutionCompletedData {
    let completion =
        expect_correlated_tool_completion(fixture, stream, tool_call_id, context).await;
    assert_eq!(
        completion.success(),
        expected_success,
        "{context}: wrong terminal: {completion:?}"
    );
    let duplicate = tokio::time::timeout(Duration::from_millis(500), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, context).await;
            if envelope.kind == FrameKind::ChatEvent
                && envelope.stream == *stream
            {
                match envelope.parse_payload::<ChatEvent>().unwrap() {
                    ChatEvent::ToolExecutionCompleted(other)
                        if other.tool_call_id == tool_call_id => break other,
                    ChatEvent::ToolExecutionCompleted(other) => panic!(
                        "{context}: unrelated MCP call terminalized during exact-once window: {other:?}"
                    ),
                    ChatEvent::ToolRequest(other) => panic!(
                        "{context}: extra MCP tool request during exact-once window: {other:?}"
                    ),
                    _ => {}
                }
            }
        }
    })
    .await;
    assert!(
        duplicate.is_err(),
        "{context}: MCP call terminalized twice: {:?}",
        duplicate.unwrap()
    );
    completion
}

fn assert_failed_mcp_request_result_contract(
    request: &protocol::ToolRequest,
    completion: &ToolExecutionCompletedData,
    context: &str,
) {
    assert_eq!(
        completion.tool_call_id, request.tool_call_id,
        "{context}: MCP failure crossed request identities"
    );
    assert!(
        !completion.success(),
        "{context}: MCP failure reported success"
    );
    assert_eq!(
        completion.normalization_failure(),
        None,
        "{context}: generic MCP failure was misclassified as a normalization failure"
    );
    assert!(
        completion
            .error()
            .as_ref()
            .is_some_and(|error| !error.trim().is_empty())
            || matches!(&completion.outcome, ToolExecutionOutcome::Failed { .. }),
        "{context}: MCP failure had no visible diagnostic: {completion:?}"
    );
}

async fn expect_adversarial_calls_after_user_echo(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    prompt: &str,
    expected_calls: usize,
    context: &str,
) -> (Vec<protocol::ToolRequest>, Vec<ToolExecutionCompletedData>) {
    let mut saw_user = false;
    let mut requests = Vec::new();
    let mut completions = Vec::new();
    let mut tool_names = HashMap::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, context).await;
            if envelope.kind == FrameKind::AgentError && envelope.stream == *stream {
                let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                panic!("{context}: backend failed: {}", error.message);
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == prompt => saw_user = true,
                ChatEvent::StreamEnd(end) if saw_user => {
                    for tool in end.message.tool_calls {
                        tool_names.insert(tool.tool_call_id, tool.name);
                    }
                }
                ChatEvent::ToolRequest(request)
                    if saw_user
                        && tool_names
                            .get(&request.tool_call_id)
                            .is_some_and(|name| name.contains(ADVERSARIAL_MCP_TOOL)) =>
                {
                    assert!(
                        !requests.iter().any(|existing: &protocol::ToolRequest| {
                            existing.tool_call_id == request.tool_call_id
                        }),
                        "{context}: duplicate MCP request identity {}",
                        request.tool_call_id
                    );
                    requests.push(request);
                    assert!(
                        requests.len() <= expected_calls,
                        "{context}: issued more than {expected_calls} MCP calls: {requests:?}"
                    );
                }
                ChatEvent::ToolRequest(request) if saw_user => {
                    panic!("{context}: invoked a wrong or extra tool: {request:?}")
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if requests
                        .iter()
                        .any(|request| request.tool_call_id == completion.tool_call_id) =>
                {
                    assert_eq!(
                        requests.len(),
                        expected_calls,
                        "{context}: a call completed before all concurrent requests were admitted: {requests:?}"
                    );
                    assert!(
                        !completions
                            .iter()
                            .any(|existing: &ToolExecutionCompletedData| {
                                existing.tool_call_id == completion.tool_call_id
                            }),
                        "{context}: MCP call {} terminalized twice",
                        completion.tool_call_id
                    );
                    completions.push(completion);
                }
                ChatEvent::ToolExecutionCompleted(completion) if saw_user => {
                    panic!("{context}: emitted an uncorrelated tool terminal: {completion:?}")
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{context}: MCP turn failed: {content}"),
                ChatEvent::TypingStatusChanged(false) if saw_user => {
                    assert_eq!(
                        requests.len(),
                        expected_calls,
                        "{context}: wrong MCP call count: {requests:?}"
                    );
                    assert_eq!(
                        completions.len(),
                        expected_calls,
                        "{context}: wrong MCP terminal count: {completions:?}"
                    );
                    break;
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context}: MCP turn did not settle"));
    (requests, completions)
}

async fn assert_mcp_extended_adversarial_activity_row(
    backend_kind: BackendKind,
    activity: ActivityCondition,
) {
    let selected_mode = selected_adversarial_mcp_mode();
    let extended_modes = [
        (
            "initialize_timeout",
            McpFailureConsistencyCell::StartupInitializeTimeout,
        ),
        (
            "list_timeout",
            McpFailureConsistencyCell::StartupListTimeout,
        ),
        (
            "wrong_response_id",
            McpFailureConsistencyCell::RuntimeWrongResponseId,
        ),
        (
            "malformed_json",
            McpFailureConsistencyCell::RuntimeMalformedJson,
        ),
        (
            "stderr_flood",
            McpFailureConsistencyCell::RuntimeStderrFlood,
        ),
        (
            "duplicate_late_response",
            McpFailureConsistencyCell::RuntimeDuplicateLateResponse,
        ),
    ];
    let required = extended_modes
        .iter()
        .filter(|(mode, _)| {
            selected_mode
                .as_deref()
                .is_none_or(|selected| selected == *mode)
        })
        .map(|(_, cell)| *cell)
        .collect::<Vec<_>>();
    let mut failure_ledger =
        EnumeratedCoverageLedger::new(required, "MCP extended failure consistency");
    for (mode, cell) in extended_modes.into_iter().take(2) {
        if selected_mode
            .as_deref()
            .is_some_and(|selected| selected != mode)
        {
            continue;
        }
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        let ambient_context = format!("MCP_TIMEOUT_{}_AMBIENT", mode.to_ascii_uppercase());
        let (ambient_stream, ambient_ids, ambient_release) =
            start_mcp_activity_ambient(&mut fixture, backend_kind, activity, &ambient_context)
                .await;
        install_adversarial_mcp(&mut fixture, mode).await;
        let prompt = "Do not use tools. Reply exactly MCP_TIMEOUT_MUST_FAIL_STARTUP.";
        fixture
            .client
            .spawn_agent(SpawnAgentPayload {
                name: Some(format!("mcp-{mode}")),
                custom_agent_id: None,
                parent_agent_id: None,
                project_id: None,
                params: SpawnAgentParams::New {
                    workspace_roots: fixture.workspace_roots(),
                    prompt: prompt.to_owned(),
                    images: None,
                    backend_kind,
                    launch_profile_id: None,
                    cost_hint: cost_hint_for(backend_kind),
                    access_mode: Default::default(),
                    session_settings: None,
                },
            })
            .await
            .unwrap();
        let failure = tokio::time::timeout(Duration::from_secs(75), async {
            loop {
                let envelope =
                    expect_next_unfiltered_event(&mut fixture.client, "MCP startup timeout").await;
                match envelope.kind {
                    FrameKind::AgentError => {
                        break envelope
                            .parse_payload::<protocol::AgentErrorPayload>()
                            .unwrap()
                            .message;
                    }
                    FrameKind::ChatEvent => match envelope.parse_payload::<ChatEvent>().unwrap() {
                        ChatEvent::MessageAdded(ChatMessage {
                            sender: MessageSender::Error | MessageSender::Warning,
                            content,
                            ..
                        }) => break content,
                        ChatEvent::TypingStatusChanged(false) => {
                            panic!("{mode} was silently ignored")
                        }
                        _ => {}
                    },
                    _ => {}
                }
            }
        })
        .await
        .unwrap_or_else(|_| panic!("{backend_kind:?} did not bound MCP {mode}"));
        assert!(
            failure.to_ascii_lowercase().contains("mcp"),
            "unnamed MCP timeout: {failure}"
        );
        wait_for_adversarial_process_exit(adversarial_mcp_journal(&fixture)).await;
        finish_mcp_activity_ambient(
            &mut fixture,
            &ambient_stream,
            &ambient_ids,
            activity,
            ambient_release,
            "MCP startup timeout ambient lifecycle",
        )
        .await;
        failure_ledger.record(cell).unwrap();
    }

    for (mode, expected_success, cell) in [
        (
            "wrong_response_id",
            false,
            McpFailureConsistencyCell::RuntimeWrongResponseId,
        ),
        (
            "malformed_json",
            false,
            McpFailureConsistencyCell::RuntimeMalformedJson,
        ),
        (
            "stderr_flood",
            true,
            McpFailureConsistencyCell::RuntimeStderrFlood,
        ),
        (
            "duplicate_late_response",
            true,
            McpFailureConsistencyCell::RuntimeDuplicateLateResponse,
        ),
    ] {
        if selected_mode
            .as_deref()
            .is_some_and(|selected| selected != mode)
        {
            continue;
        }
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        let ambient_context = format!("MCP_RUNTIME_{}_AMBIENT", mode.to_ascii_uppercase());
        let (ambient_stream, ambient_ids, ambient_release) =
            start_mcp_activity_ambient(&mut fixture, backend_kind, activity, &ambient_context)
                .await;
        install_adversarial_mcp(&mut fixture, mode).await;
        let sentinel = format!("MCP_{mode}_{}", Uuid::new_v4().simple());
        let prompt = adversarial_mcp_prompt(backend_kind, &sentinel, true);
        let (stream, start, request) = reach_adversarial_mcp_request(
            &mut fixture,
            backend_kind,
            &prompt,
            &format!("mcp-{mode}"),
        )
        .await;
        let completion = expect_adversarial_call_terminal(
            &mut fixture,
            &stream,
            &request.tool_call_id,
            expected_success,
            mode,
        )
        .await;
        if expected_success {
            assert!(
                serde_json::to_string(&completion.tool_result())
                    .unwrap()
                    .contains(&sentinel)
            );
        } else {
            assert_failed_mcp_request_result_contract(&request, &completion, mode);
        }
        close_agent_at_definitive_boundary(
            &mut fixture,
            &stream,
            &start.agent_id,
            "close adversarial MCP row",
        )
        .await;
        wait_for_adversarial_process_exit(adversarial_mcp_journal(&fixture)).await;
        finish_mcp_activity_ambient(
            &mut fixture,
            &ambient_stream,
            &ambient_ids,
            activity,
            ambient_release,
            "MCP runtime failure ambient lifecycle",
        )
        .await;
        failure_ledger.record(cell).unwrap();
    }

    failure_ledger.finish().unwrap();

    if selected_mode.is_some() {
        return;
    }
    let mut configuration_ledger =
        EnumeratedCoverageLedger::new(McpConfigurationRaceCell::ALL, "MCP configuration race");

    {
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        let (ambient_stream, ambient_ids, ambient_release) = start_mcp_activity_ambient(
            &mut fixture,
            backend_kind,
            activity,
            "MCP_STDIO_CONFIG_AMBIENT",
        )
        .await;
        let script = write_adversarial_mcp_fixture(&fixture);
        let journal = adversarial_mcp_journal(&fixture);
        let release = adversarial_mcp_release(&fixture);
        fixture
            .client
            .inner
            .mcp_server_upsert(protocol::McpServerUpsertPayload {
                mcp_server: protocol::McpServerConfig {
                    id: protocol::McpServerId("adversarial-mcp-live".to_owned()),
                    name: ADVERSARIAL_MCP_NAME.to_owned(),
                    supports_parallel_tool_calls: false,
                    transport: protocol::McpTransportConfig::Stdio {
                        command: "python3".to_owned(),
                        args: vec![
                            script.to_string_lossy().to_string(),
                            "normal".to_owned(),
                            journal.to_string_lossy().to_string(),
                            release.to_string_lossy().to_string(),
                        ],
                        env: HashMap::from([(
                            "TYDE_MCP_STDIO_SENTINEL".to_owned(),
                            ":STDIO_ENV_OK".to_owned(),
                        )]),
                    },
                },
            })
            .await
            .expect("install stdio environment MCP server");
        let prompt = adversarial_mcp_prompt(backend_kind, "MCP_STDIO_ENV", true);
        let (stream, start, request) =
            reach_adversarial_mcp_request(&mut fixture, backend_kind, &prompt, "mcp-stdio-env")
                .await;
        let completion = expect_adversarial_call_terminal(
            &mut fixture,
            &stream,
            &request.tool_call_id,
            true,
            "stdio MCP environment",
        )
        .await;
        assert!(
            serde_json::to_string(&completion.tool_result())
                .unwrap()
                .contains("MCP_STDIO_ENV:STDIO_ENV_OK"),
            "stdio MCP environment did not reach the real child: {completion:?}"
        );
        close_agent_at_definitive_boundary(
            &mut fixture,
            &stream,
            &start.agent_id,
            "close stdio environment MCP agent",
        )
        .await;
        wait_for_adversarial_process_exit(journal).await;
        finish_mcp_activity_ambient(
            &mut fixture,
            &ambient_stream,
            &ambient_ids,
            activity,
            ambient_release,
            "stdio MCP configuration ambient lifecycle",
        )
        .await;
    }
    configuration_ledger
        .record(McpConfigurationRaceCell::StdioEnvironment)
        .expect("record stdio MCP environment");

    {
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        let (ambient_stream, ambient_ids, ambient_release) = start_mcp_activity_ambient(
            &mut fixture,
            backend_kind,
            activity,
            "MCP_CONCURRENT_CONFIG_AMBIENT",
        )
        .await;
        install_adversarial_mcp(&mut fixture, "normal").await;
        let first = format!("MCP_CONCURRENT_FIRST_{}", Uuid::new_v4().simple());
        let second = format!("MCP_CONCURRENT_SECOND_{}", Uuid::new_v4().simple());
        let prompt = match backend_kind {
            BackendKind::Codex => format!(
                "Invoke `{ADVERSARIAL_MCP_TOOL}` from `{ADVERSARIAL_MCP_NAME}` exactly twice concurrently, once with value `{first}` and once with value `{second}`. Do not use another tool. Wait for both."
            ),
            _ => format!(
                "Use MCP tool `{ADVERSARIAL_MCP_TOOL}` from `{ADVERSARIAL_MCP_NAME}` exactly twice in parallel, once with value `{first}` and once with value `{second}`. Do not use another tool. Wait for both."
            ),
        };
        let roots = fixture.workspace_roots();
        let stream = spawn_agent_via_protocol(
            &mut fixture.client,
            roots,
            backend_kind,
            "mcp-concurrent",
            &prompt,
        )
        .await;
        let (requests, completions) = expect_adversarial_calls_after_user_echo(
            &mut fixture,
            &stream,
            &prompt,
            2,
            "concurrent MCP calls",
        )
        .await;
        assert_ne!(requests[0].tool_call_id, requests[1].tool_call_id);
        let expected_values = [first.as_str(), second.as_str()];
        for request in &requests {
            let ToolRequestType::Other { args } = &request.tool_type else {
                panic!("concurrent MCP call did not normalize to Other: {request:?}")
            };
            let value = args
                .as_object()
                .filter(|args| args.len() == 1)
                .and_then(|args| args.get("value"))
                .and_then(Value::as_str)
                .unwrap_or_else(|| {
                    panic!("concurrent MCP call changed its arguments: {request:?}")
                });
            assert!(
                expected_values.contains(&value),
                "concurrent MCP call used an unexpected sentinel: {request:?}"
            );
            let completion = completions
                .iter()
                .find(|completion| completion.tool_call_id == request.tool_call_id)
                .expect("concurrent MCP request lacked its correlated terminal");
            assert!(completion.success());
            assert!(
                serde_json::to_string(&completion.tool_result())
                    .unwrap()
                    .contains(value),
                "concurrent MCP completion crossed identities: {completion:?}"
            );
        }
        assert_ne!(
            requests[0].tool_type.clone(),
            requests[1].tool_type.clone(),
            "concurrent MCP requests duplicated one argument set"
        );
        wait_for_adversarial_journal(adversarial_mcp_journal(&fixture), "call", 2).await;
        finish_mcp_activity_ambient(
            &mut fixture,
            &ambient_stream,
            &ambient_ids,
            activity,
            ambient_release,
            "concurrent MCP configuration ambient lifecycle",
        )
        .await;
    }
    configuration_ledger
        .record(McpConfigurationRaceCell::ConcurrentCalls)
        .expect("record concurrent MCP calls");

    {
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        let (ambient_stream, ambient_ids, ambient_release) = start_mcp_activity_ambient(
            &mut fixture,
            backend_kind,
            activity,
            "MCP_COLLISION_CONFIG_AMBIENT",
        )
        .await;
        let first_journal = fixture.workspace_dir.path().join("collision-first.journal");
        let second_journal = fixture
            .workspace_dir
            .path()
            .join("collision-second.journal");
        install_named_adversarial_mcp(
            &mut fixture,
            "normal",
            "collision-first",
            "collision_first",
            first_journal.clone(),
        )
        .await;
        install_named_adversarial_mcp(
            &mut fixture,
            "normal",
            "collision-second",
            "collision_second",
            second_journal.clone(),
        )
        .await;
        let sentinel = format!("MCP_COLLISION_{}", Uuid::new_v4().simple());
        let prompt = match backend_kind {
            BackendKind::Codex => format!(
                "Invoke `{ADVERSARIAL_MCP_TOOL}` specifically from MCP server `collision_second` exactly once with value `{sentinel}`. Never call `collision_first`."
            ),
            _ => format!(
                "Use `{ADVERSARIAL_MCP_TOOL}` specifically from MCP server `collision_second` exactly once with value `{sentinel}`. Never call `collision_first`."
            ),
        };
        let roots = fixture.workspace_roots();
        let stream = spawn_agent_via_protocol(
            &mut fixture.client,
            roots,
            backend_kind,
            "mcp-collision",
            &prompt,
        )
        .await;
        let (_, completions) = expect_adversarial_calls_after_user_echo(
            &mut fixture,
            &stream,
            &prompt,
            1,
            "MCP tool-name collision",
        )
        .await;
        assert!(completions[0].success());
        assert!(
            serde_json::to_string(&completions[0].tool_result())
                .unwrap()
                .contains(&sentinel)
        );
        wait_for_adversarial_journal(second_journal, "call", 1).await;
        assert_eq!(
            std::fs::read_to_string(first_journal)
                .unwrap_or_default()
                .lines()
                .filter(|line| line.contains("\"kind\": \"call\""))
                .count(),
            0,
            "tool-name collision routed to wrong MCP server"
        );
        finish_mcp_activity_ambient(
            &mut fixture,
            &ambient_stream,
            &ambient_ids,
            activity,
            ambient_release,
            "MCP collision configuration ambient lifecycle",
        )
        .await;
    }
    configuration_ledger
        .record(McpConfigurationRaceCell::ToolNameCollisionAcrossServers)
        .expect("record MCP tool-name collision across servers");

    {
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        let (ambient_stream, ambient_ids, ambient_release) = start_mcp_activity_ambient(
            &mut fixture,
            backend_kind,
            activity,
            "MCP_REPLACE_CONFIG_AMBIENT",
        )
        .await;
        let old_journal = fixture.workspace_dir.path().join("replace-old.journal");
        let new_journal = fixture.workspace_dir.path().join("replace-new.journal");
        install_named_adversarial_mcp(
            &mut fixture,
            "pending_wait",
            "replace-live",
            ADVERSARIAL_MCP_NAME,
            old_journal.clone(),
        )
        .await;
        let old_prompt = adversarial_mcp_prompt(backend_kind, "MCP_REPLACE_OLD", true);
        let (old_stream, old_start, old_request) = reach_adversarial_mcp_request(
            &mut fixture,
            backend_kind,
            &old_prompt,
            "mcp-replace-old",
        )
        .await;
        wait_for_adversarial_journal(old_journal.clone(), "call", 1).await;
        install_named_adversarial_mcp(
            &mut fixture,
            "normal",
            "replace-live",
            ADVERSARIAL_MCP_NAME,
            new_journal.clone(),
        )
        .await;
        assert_generic_other_remains_pending(
            &mut fixture,
            &old_stream,
            &old_request.tool_call_id,
            "replaced MCP in-flight call",
        )
        .await;
        std::fs::write(adversarial_mcp_release(&fixture), b"release").unwrap();
        let old_completion = expect_adversarial_call_terminal(
            &mut fixture,
            &old_stream,
            &old_request.tool_call_id,
            true,
            "replaced MCP old in-flight completion",
        )
        .await;
        assert!(
            serde_json::to_string(&old_completion.tool_result())
                .unwrap()
                .contains("MCP_REPLACE_OLD")
        );
        let retained_prompt =
            adversarial_mcp_prompt(backend_kind, "MCP_REPLACE_EXISTING_RETAINS_OLD", true);
        fixture
            .client
            .send_message(&old_stream, retained_prompt.clone())
            .await
            .unwrap();
        let (_, retained_completions) = expect_adversarial_calls_after_user_echo(
            &mut fixture,
            &old_stream,
            &retained_prompt,
            1,
            "replacement excluded from existing MCP agent",
        )
        .await;
        assert!(retained_completions[0].success());
        assert!(
            serde_json::to_string(&retained_completions[0].tool_result())
                .unwrap()
                .contains("MCP_REPLACE_EXISTING_RETAINS_OLD")
        );
        wait_for_adversarial_journal(old_journal.clone(), "call", 2).await;
        assert_eq!(
            std::fs::read_to_string(&new_journal)
                .unwrap_or_default()
                .lines()
                .filter(|line| line.contains("\"kind\": \"call\""))
                .count(),
            0,
            "replacement was injected into an already-running agent"
        );
        configuration_ledger
            .record(McpConfigurationRaceCell::ReplacementExcludedFromExistingAgent)
            .unwrap();
        close_agent_at_definitive_boundary(
            &mut fixture,
            &old_stream,
            &old_start.agent_id,
            "close replaced MCP old agent",
        )
        .await;
        wait_for_adversarial_process_exit(old_journal.clone()).await;

        let new_prompt = adversarial_mcp_prompt(backend_kind, "MCP_REPLACE_NEW", true);
        let (new_stream, new_start, new_request) = reach_adversarial_mcp_request(
            &mut fixture,
            backend_kind,
            &new_prompt,
            "mcp-replace-new",
        )
        .await;
        let new_completion = expect_adversarial_call_terminal(
            &mut fixture,
            &new_stream,
            &new_request.tool_call_id,
            true,
            "replacement MCP new call",
        )
        .await;
        assert!(
            serde_json::to_string(&new_completion.tool_result())
                .unwrap()
                .contains("MCP_REPLACE_NEW")
        );
        configuration_ledger
            .record(McpConfigurationRaceCell::ReplacementAvailableToNewAgent)
            .unwrap();
        wait_for_adversarial_journal(new_journal, "call", 1).await;
        assert_eq!(
            std::fs::read_to_string(old_journal)
                .unwrap_or_default()
                .lines()
                .filter(|line| line.contains("\"kind\": \"call\""))
                .count(),
            2,
            "replacement MCP config re-routed or repeated the in-flight call"
        );
        close_agent_at_definitive_boundary(
            &mut fixture,
            &new_stream,
            &new_start.agent_id,
            "close replacement MCP new agent",
        )
        .await;
        finish_mcp_activity_ambient(
            &mut fixture,
            &ambient_stream,
            &ambient_ids,
            activity,
            ambient_release,
            "MCP replacement configuration ambient lifecycle",
        )
        .await;
    }
    configuration_ledger
        .record(McpConfigurationRaceCell::ReplaceDuringCall)
        .expect("record MCP replacement race");

    {
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        let (ambient_stream, ambient_ids, ambient_release) = start_mcp_activity_ambient(
            &mut fixture,
            backend_kind,
            activity,
            "MCP_DELETE_CONFIG_AMBIENT",
        )
        .await;
        let ready = "Reply exactly MCP_DYNAMIC_READY and do not use tools.";
        let roots = fixture.workspace_roots();
        let original = spawn_agent_via_protocol(
            &mut fixture.client,
            roots,
            backend_kind,
            "mcp-dynamic-original",
            ready,
        )
        .await;
        let response =
            expect_assistant_turn_after_user_echo(&mut fixture.client, &original, ready).await;
        assert!(response.final_text.contains("MCP_DYNAMIC_READY"));
        install_adversarial_mcp(&mut fixture, "pending_wait").await;
        let existing_without_add_prompt = match backend_kind {
            BackendKind::Codex => {
                "Inspect only this agent's current tool inventory. If `echo_value` from MCP server `adversarial_mcp_live` is present, invoke it exactly once with value `MCP_ADD_EXISTING_PRESENT`; otherwise invoke no tool and reply exactly MCP_ADD_EXISTING_UNAVAILABLE."
            }
            _ => {
                "Inspect only this agent's current tool inventory. If MCP tool `echo_value` from server `adversarial_mcp_live` is present, use it exactly once with value `MCP_ADD_EXISTING_PRESENT`; otherwise use no tool and reply exactly MCP_ADD_EXISTING_UNAVAILABLE."
            }
        };
        fixture
            .client
            .send_message(&original, existing_without_add_prompt.to_owned())
            .await
            .unwrap();
        assert_exact_no_tool_follow_up(
            &mut fixture.client,
            &original,
            existing_without_add_prompt,
            "MCP_ADD_EXISTING_UNAVAILABLE",
        )
        .await;
        configuration_ledger
            .record(McpConfigurationRaceCell::AddedServerExcludedFromExistingAgent)
            .unwrap();
        let prompt = adversarial_mcp_prompt(backend_kind, "MCP_DYNAMIC_DELETE", true);
        let (stream, start, request) =
            reach_adversarial_mcp_request(&mut fixture, backend_kind, &prompt, "mcp-dynamic-new")
                .await;
        fixture
            .client
            .inner
            .mcp_server_delete(protocol::McpServerDeletePayload {
                id: protocol::McpServerId("adversarial-mcp-live".to_owned()),
            })
            .await
            .unwrap();
        assert_generic_other_remains_pending(
            &mut fixture,
            &stream,
            &request.tool_call_id,
            "deleted MCP pending call",
        )
        .await;
        std::fs::write(adversarial_mcp_release(&fixture), b"release").unwrap();
        let completion = expect_adversarial_call_terminal(
            &mut fixture,
            &stream,
            &request.tool_call_id,
            true,
            "deleted MCP in-flight completion",
        )
        .await;
        assert!(
            serde_json::to_string(&completion.tool_result())
                .unwrap()
                .contains("MCP_DYNAMIC_DELETE")
        );
        configuration_ledger
            .record(McpConfigurationRaceCell::AddedServerAvailableToNewAgent)
            .unwrap();
        let retained_prompt =
            adversarial_mcp_prompt(backend_kind, "MCP_DYNAMIC_DELETE_RETAINED", true);
        fixture
            .client
            .send_message(&stream, retained_prompt.clone())
            .await
            .unwrap();
        let (retained_requests, retained_completions) = expect_adversarial_calls_after_user_echo(
            &mut fixture,
            &stream,
            &retained_prompt,
            1,
            "deleted MCP retained by existing agent",
        )
        .await;
        assert_eq!(retained_requests.len(), 1);
        assert!(retained_completions[0].success());
        assert!(
            serde_json::to_string(&retained_completions[0].tool_result())
                .unwrap()
                .contains("MCP_DYNAMIC_DELETE_RETAINED")
        );
        configuration_ledger
            .record(McpConfigurationRaceCell::DeletedServerRemainsInExistingAgent)
            .unwrap();
        close_agent_at_definitive_boundary(
            &mut fixture,
            &stream,
            &start.agent_id,
            "close dynamically deleted MCP agent",
        )
        .await;
        wait_for_adversarial_process_exit(adversarial_mcp_journal(&fixture)).await;
        let follow_up = "Reply exactly MCP_DYNAMIC_ORIGINAL_OK and do not use tools.";
        fixture
            .client
            .send_message(&original, follow_up.to_owned())
            .await
            .unwrap();
        assert_exact_no_tool_follow_up(
            &mut fixture.client,
            &original,
            follow_up,
            "MCP_DYNAMIC_ORIGINAL_OK",
        )
        .await;

        let deleted_prompt = match backend_kind {
            BackendKind::Codex => {
                "Inspect only this agent's current tool inventory. If `echo_value` from MCP server `adversarial_mcp_live` is present, invoke it exactly once with value `MCP_DELETED_PRESENT`; otherwise invoke no tool and reply exactly MCP_DELETED_UNAVAILABLE."
            }
            _ => {
                "Inspect only this agent's current tool inventory. If MCP tool `echo_value` from server `adversarial_mcp_live` is present, use it exactly once with value `MCP_DELETED_PRESENT`; otherwise use no tool and reply exactly MCP_DELETED_UNAVAILABLE."
            }
        };
        let roots = fixture.workspace_roots();
        let deleted_stream = spawn_agent_via_protocol(
            &mut fixture.client,
            roots,
            backend_kind,
            "mcp-dynamic-deleted",
            deleted_prompt,
        )
        .await;
        assert_exact_no_tool_follow_up(
            &mut fixture.client,
            &deleted_stream,
            deleted_prompt,
            "MCP_DELETED_UNAVAILABLE",
        )
        .await;
        finish_mcp_activity_ambient(
            &mut fixture,
            &ambient_stream,
            &ambient_ids,
            activity,
            ambient_release,
            "MCP deletion configuration ambient lifecycle",
        )
        .await;
    }
    configuration_ledger
        .record(McpConfigurationRaceCell::DeleteDuringCall)
        .expect("record MCP deletion race");
    configuration_ledger
        .record(McpConfigurationRaceCell::DeletedServerUnavailableToNewAgent)
        .expect("record deleted MCP absence for new agent");
    configuration_ledger
        .finish()
        .expect("complete MCP configuration race matrix");
}

