async fn assert_mcp_pending_process_death_contract(backend_kind: BackendKind) {
    let mut failure_ledger = EnumeratedCoverageLedger::new(
        [
            McpFailureConsistencyCell::RuntimeProcessDeath,
            McpFailureConsistencyCell::RuntimeProcessDeathRecovery,
        ],
        "MCP process-death failure consistency",
    );
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    install_adversarial_mcp(&mut fixture, "pending_death").await;
    let value = "MCP_PENDING_DEATH";
    let prompt = adversarial_mcp_prompt(backend_kind, value, true);
    let (stream, start, tool_request) =
        reach_adversarial_mcp_request(&mut fixture, backend_kind, &prompt, "mcp-pending-death")
            .await;
    wait_for_adversarial_journal(adversarial_mcp_journal(&fixture), "call", 1).await;
    let mut completions = 0;
    tokio::time::timeout(Duration::from_secs(60), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, "dead MCP terminal").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_request.tool_call_id =>
                {
                    completions += 1;
                    assert_failed_mcp_request_result_contract(
                        &tool_request,
                        &completion,
                        "dead MCP process",
                    );
                }
                ChatEvent::ToolExecutionCompleted(completion) => {
                    panic!("dead MCP process emitted an uncorrelated terminal: {completion:?}")
                }
                ChatEvent::ToolRequest(request) => {
                    panic!("dead MCP process caused an extra tool request: {request:?}")
                }
                ChatEvent::TypingStatusChanged(false) if completions == 1 => break,
                ChatEvent::TypingStatusChanged(false) => {
                    panic!("dead MCP process became idle without exactly one terminal")
                }
                _ => {}
            }
        }
    })
    .await
    .expect("dead MCP process did not terminalize its call");
    assert_eq!(completions, 1);
    assert_no_adversarial_mcp_activity(&mut fixture, &stream, "dead MCP terminal quiet window")
        .await;
    assert_eq!(
        read_adversarial_mcp_journal(&fixture)
            .iter()
            .filter(|entry| entry.get("kind").and_then(Value::as_str) == Some("call"))
            .count(),
        1,
        "dead MCP call was retried"
    );
    let follow_up = "Do not use tools. Reply exactly MCP_DEATH_SESSION_OK.";
    fixture
        .client
        .send_message(&stream, follow_up.to_owned())
        .await
        .unwrap();
    assert_exact_no_tool_follow_up(
        &mut fixture.client,
        &stream,
        follow_up,
        "MCP_DEATH_SESSION_OK",
    )
    .await;
    failure_ledger
        .record(McpFailureConsistencyCell::RuntimeProcessDeath)
        .unwrap();
    close_agent_at_definitive_boundary(
        &mut fixture,
        &stream,
        &start.agent_id,
        "close agent after MCP process death",
    )
    .await;
    install_adversarial_mcp(&mut fixture, "normal").await;
    let recovery_value = "MCP_PROCESS_DEATH_RECOVERED";
    let recovery_prompt = adversarial_mcp_prompt(backend_kind, recovery_value, true);
    let (recovery_stream, recovery_start, recovery_request) = reach_adversarial_mcp_request(
        &mut fixture,
        backend_kind,
        &recovery_prompt,
        "mcp-process-death-recovery",
    )
    .await;
    let recovery_completion = expect_adversarial_call_terminal(
        &mut fixture,
        &recovery_stream,
        &recovery_request.tool_call_id,
        true,
        "MCP process-death recovery",
    )
    .await;
    assert!(
        serde_json::to_string(&recovery_completion.tool_result())
            .unwrap()
            .contains(recovery_value),
        "replacement MCP process did not recover the failed server: {recovery_completion:?}"
    );
    close_agent_at_definitive_boundary(
        &mut fixture,
        &recovery_stream,
        &recovery_start.agent_id,
        "close recovered MCP agent",
    )
    .await;
    wait_for_adversarial_process_exit(adversarial_mcp_journal(&fixture)).await;
    failure_ledger
        .record(McpFailureConsistencyCell::RuntimeProcessDeathRecovery)
        .unwrap();
    failure_ledger.finish().unwrap();
}

async fn assert_mcp_reconnect_contract(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    install_adversarial_mcp(&mut fixture, "pending_wait").await;
    let prompt = adversarial_mcp_prompt(backend_kind, "MCP_RECONNECT", true);
    let (_source, start, tool_request) =
        reach_adversarial_mcp_request(&mut fixture, backend_kind, &prompt, "mcp-reconnect").await;
    wait_for_adversarial_journal(adversarial_mcp_journal(&fixture), "call", 1).await;
    let mut replacement = fixture.connect().await;
    replacement.inherit_live_trace_from(&fixture.client);
    std::mem::swap(&mut fixture.client, &mut replacement);
    drop(replacement);
    let replay_stream = loop {
        let envelope = expect_next_event(&mut fixture.client, "MCP reconnect bootstrap").await;
        if envelope.kind != FrameKind::HostBootstrap {
            continue;
        }
        let bootstrap: HostBootstrapPayload = envelope.parse_payload().unwrap();
        break bootstrap
            .agents
            .into_iter()
            .find(|agent| agent.agent_id == start.agent_id)
            .expect("reconnect omitted pending MCP agent")
            .instance_stream;
    };
    let replayed = tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "replayed pending MCP call").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != replay_stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolRequest(request)
                    if request.tool_call_id == tool_request.tool_call_id => break request,
                ChatEvent::ToolRequest(request) => {
                    panic!("MCP reconnect replayed a wrong or extra request: {request:?}")
                }
                ChatEvent::ToolExecutionCompleted(completion) => panic!(
                    "pending MCP call terminalized before its release after reconnect: {completion:?}"
                ),
                ChatEvent::TypingStatusChanged(false) => {
                    panic!("pending MCP call became idle during reconnect")
                }
                _ => {}
            }
        }
    })
    .await
    .expect("pending MCP request was not replayed");
    assert_eq!(
        serde_json::to_value(&replayed).unwrap(),
        serde_json::to_value(&tool_request).unwrap(),
        "client reconnect did not replay the exact pending MCP request"
    );
    assert_eq!(
        read_adversarial_mcp_journal(&fixture)
            .iter()
            .filter(|entry| entry.get("kind").and_then(Value::as_str) == Some("call"))
            .count(),
        1,
        "client reconnect re-called the provider MCP tool"
    );
    std::fs::write(adversarial_mcp_release(&fixture), b"release").unwrap();
    let completion = expect_correlated_tool_completion(
        &mut fixture,
        &replay_stream,
        &tool_request.tool_call_id,
        "MCP completion after reconnect",
    )
    .await;
    assert!(completion.success());
    wait_for_adversarial_turn_idle(&mut fixture, &replay_stream, "MCP turn after reconnect").await;
    assert_no_adversarial_mcp_activity(
        &mut fixture,
        &replay_stream,
        "MCP reconnect terminal quiet window",
    )
    .await;
}

async fn assert_mcp_host_restart_resume_contract(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    install_adversarial_mcp(&mut fixture, "pending_wait_first").await;
    let first_prompt = adversarial_mcp_prompt(backend_kind, "MCP_BEFORE_RESTART", true);
    let (_first_stream, start, first_request) = reach_adversarial_mcp_request(
        &mut fixture,
        backend_kind,
        &first_prompt,
        "mcp-before-host-restart",
    )
    .await;
    wait_for_adversarial_journal(adversarial_mcp_journal(&fixture), "call", 1).await;
    fixture.host.shutdown_agents_for_conformance().await;
    wait_for_adversarial_process_exit(adversarial_mcp_journal(&fixture)).await;
    fixture.restart_host().await;
    let second_prompt = adversarial_mcp_prompt(backend_kind, "MCP_AFTER_RESTART", false);
    let resumed = resume_agent_via_protocol(
        &mut fixture.client,
        "mcp-after-host-restart",
        start.session_id.expect("MCP restart session id"),
        &second_prompt,
    )
    .await;
    let mut saw_user = false;
    let mut tool_names = HashMap::new();
    let second_id = tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, "MCP request after resume").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != resumed {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == second_prompt => saw_user = true,
                ChatEvent::StreamEnd(end) if saw_user => {
                    for tool in end.message.tool_calls {
                        tool_names.insert(tool.tool_call_id, tool.name);
                    }
                }
                ChatEvent::ToolRequest(request) if saw_user => {
                    assert_ne!(
                        request.tool_call_id, first_request.tool_call_id,
                        "host restart replayed the abandoned MCP call"
                    );
                    assert!(
                        tool_names
                            .get(&request.tool_call_id)
                            .is_some_and(|name| name.contains(ADVERSARIAL_MCP_TOOL)),
                        "resumed MCP session invoked a wrong tool: {request:?}"
                    );
                    let ToolRequestType::Other { args } = &request.tool_type else {
                        panic!("resumed MCP call did not normalize to Other: {request:?}")
                    };
                    assert_eq!(args, &json!({"value": "MCP_AFTER_RESTART"}));
                    break request.tool_call_id;
                }
                ChatEvent::ToolRequest(request) => panic!(
                    "host restart replayed a tool request before the new user prompt: {request:?}"
                ),
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == first_request.tool_call_id =>
                {
                    panic!("host restart replayed the abandoned MCP terminal: {completion:?}")
                }
                ChatEvent::TypingStatusChanged(false) if saw_user => {
                    panic!("resumed MCP session became idle before invoking its new tool")
                }
                _ => {}
            }
        }
    })
    .await
    .expect("resumed session did not reregister MCP tool");
    let second = expect_correlated_tool_completion(
        &mut fixture,
        &resumed,
        &second_id,
        "MCP completion after host restart",
    )
    .await;
    assert!(second.success());
    wait_for_adversarial_turn_idle(&mut fixture, &resumed, "MCP turn after host restart").await;
    assert_no_adversarial_mcp_activity(
        &mut fixture,
        &resumed,
        "MCP host-restart terminal quiet window",
    )
    .await;
    wait_for_adversarial_journal(adversarial_mcp_journal(&fixture), "call", 2).await;
    let journal = read_adversarial_mcp_journal(&fixture);
    assert_eq!(
        journal
            .iter()
            .filter(|entry| {
                entry.get("kind").and_then(Value::as_str) == Some("call")
                    && entry.get("value").and_then(Value::as_str) == Some("MCP_BEFORE_RESTART")
            })
            .count(),
        1,
        "host restart re-executed the abandoned in-flight MCP call"
    );
    assert_eq!(
        journal
            .iter()
            .filter(|entry| {
                entry.get("kind").and_then(Value::as_str) == Some("call")
                    && entry.get("value").and_then(Value::as_str) == Some("MCP_AFTER_RESTART")
            })
            .count(),
        1,
        "resumed session did not execute its new MCP call exactly once"
    );
    assert!(
        journal
            .iter()
            .filter(|entry| entry.get("kind").and_then(Value::as_str) == Some("process_start"))
            .count()
            >= 2,
        "host restart did not start a fresh MCP registration process"
    );
}

