async fn collect_backend_text_until_idle(
    events: &mut server::backend::EventStream,
    backend_kind: BackendKind,
) -> String {
    let mut streamed = String::new();
    let mut final_text = String::new();
    let mut saw_end = false;
    tokio::time::timeout(Duration::from_secs(180), async {
        while let Some(event) = events.recv().await {
            assert_required_test_model(backend_kind, &event);
            match event {
                ChatEvent::StreamDelta(delta) => streamed.push_str(&delta.text),
                ChatEvent::StreamEnd(end) => {
                    saw_end = true;
                    final_text = end.message.content;
                }
                ChatEvent::TypingStatusChanged(false) if saw_end => break,
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("backend direct conformance case failed: {content}"),
                _ => {}
            }
        }
    })
    .await
    .expect("backend fork turn timed out");
    if final_text.trim().is_empty() {
        streamed
    } else {
        final_text
    }
}

async fn drain_resume_replay(
    events: &mut server::backend::EventStream,
    backend_kind: BackendKind,
    cycle: usize,
) {
    if let Some(replay_complete) = events.take_resume_replay_complete() {
        tokio::time::timeout(Duration::from_secs(180), replay_complete)
            .await
            .unwrap_or_else(|_| {
                panic!("resume replay cycle {cycle} timed out for {backend_kind:?}")
            })
            .unwrap_or_else(|_| {
                panic!("resume replay cycle {cycle} closed early for {backend_kind:?}")
            });
    }
    while let Ok(event) = events.try_recv() {
        if let ChatEvent::MessageAdded(ChatMessage {
            sender: MessageSender::Error,
            content,
            ..
        }) = event
        {
            panic!("resume replay cycle {cycle} failed for {backend_kind:?}: {content}");
        }
    }
}

#[derive(Clone, Copy, Debug)]
enum StartupLifecycleOrigin {
    New,
    Resume,
    Fork,
}

#[derive(Clone, Copy, Debug)]
enum StartupLifecyclePhase {
    BeforeBackendReady,
    BackendReadyBeforeAgentStart,
}

#[derive(Clone, Copy, Debug)]
enum StartupLifecycleStimulus {
    Close,
    Interrupt,
    QueuedDelivery,
    LastClientReconnect,
    AbruptOwnerDeath,
    CloseInterruptRace,
    QueuedDeliveryCloseRace,
    OwnerDeathCloseRace,
}

async fn expect_startup_prompt_result(
    client: &mut ValidatedConnection,
    stream: &StreamPath,
    prompt: &str,
    sentinel: &str,
) {
    let mut saw_user = false;
    let mut streamed = String::new();
    tokio::time::timeout(Duration::from_secs(180), async {
        loop {
            let envelope = expect_next_event(client, "startup lifecycle prompt result").await;
            if envelope.stream != *stream {
                continue;
            }
            if envelope.kind == FrameKind::AgentError {
                let error: protocol::AgentErrorPayload =
                    envelope.parse_payload().expect("parse startup AgentError");
                panic!("startup prompt {prompt:?} failed: {}", error.message);
            }
            if envelope.kind != FrameKind::ChatEvent {
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .expect("parse startup lifecycle ChatEvent")
            {
                ChatEvent::MessageAdded(message)
                    if matches!(message.sender, MessageSender::User)
                        && message.content == prompt =>
                {
                    saw_user = true;
                }
                ChatEvent::MessageAdded(message)
                    if saw_user
                        && matches!(message.sender, MessageSender::Assistant { .. })
                        && message.content.contains(sentinel) =>
                {
                    break;
                }
                ChatEvent::MessageAdded(message)
                    if saw_user && matches!(message.sender, MessageSender::Error) =>
                {
                    panic!("startup prompt {prompt:?} failed: {}", message.content);
                }
                ChatEvent::StreamStart(_) if saw_user => streamed.clear(),
                ChatEvent::StreamDelta(delta) if saw_user => streamed.push_str(&delta.text),
                ChatEvent::StreamEnd(end) if saw_user => {
                    let text = if end.message.content.trim().is_empty() {
                        streamed.as_str()
                    } else {
                        end.message.content.as_str()
                    };
                    if text.contains(sentinel) {
                        break;
                    }
                }
                ChatEvent::TypingStatusChanged(false) if saw_user => {
                    panic!("startup prompt {prompt:?} became idle without delivering {sentinel:?}")
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("startup prompt {prompt:?} timed out"));
}

async fn expect_startup_agent_closed(
    client: &mut ValidatedConnection,
    agent_id: &protocol::AgentId,
    deadline: Duration,
) {
    tokio::time::timeout(deadline, async {
        loop {
            let envelope = expect_next_event(client, "startup AgentClosed").await;
            if envelope.kind != FrameKind::AgentClosed {
                continue;
            }
            let closed: protocol::AgentClosedPayload =
                envelope.parse_payload().expect("parse startup AgentClosed");
            if &closed.agent_id == agent_id {
                break;
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("agent close did not terminate within {deadline:?}"));
}

async fn assert_startup_terminal_stays_closed(
    client: &mut ValidatedConnection,
    agent_id: &protocol::AgentId,
) {
    let late = tokio::time::timeout(Duration::from_millis(500), async {
        loop {
            let envelope =
                expect_next_unfiltered_event(client, "startup terminal quiet window").await;
            match envelope.kind {
                FrameKind::NewAgent => {
                    let created: NewAgentPayload = envelope.parse_payload().unwrap();
                    if &created.agent_id == agent_id {
                        break format!("duplicate NewAgent: {created:?}");
                    }
                }
                FrameKind::AgentClosed => {
                    let closed: protocol::AgentClosedPayload = envelope.parse_payload().unwrap();
                    if &closed.agent_id == agent_id {
                        break format!("duplicate AgentClosed: {closed:?}");
                    }
                }
                FrameKind::AgentBootstrap => {
                    let bootstrap: AgentBootstrapPayload = envelope.parse_payload().unwrap();
                    if bootstrap.events.iter().any(|event| {
                        matches!(
                            event,
                            AgentBootstrapEvent::AgentStart(start) if &start.agent_id == agent_id
                        )
                    }) {
                        break format!("AgentStart after AgentClosed: {bootstrap:?}");
                    }
                }
                _ => {}
            }
        }
    })
    .await;
    assert!(late.is_err(), "startup terminal resurrected: {late:?}");
}

async fn connect_startup_racer(
    fixture: &mut RealBackendFixture,
    agent_id: &protocol::AgentId,
) -> (ValidatedConnection, StreamPath) {
    let mut racer = fixture.connect().await;
    racer.inherit_live_trace_from(&fixture.client);
    loop {
        let envelope =
            expect_next_unfiltered_event(&mut racer, "startup racer HostBootstrap").await;
        if envelope.kind == FrameKind::HostBootstrap {
            let bootstrap: HostBootstrapPayload = envelope.parse_payload().unwrap();
            let stream = bootstrap
                .agents
                .iter()
                .find(|agent| &agent.agent_id == agent_id)
                .unwrap_or_else(|| {
                    panic!(
                        "a new client cannot control an agent during startup because HostBootstrap omitted {agent_id}"
                    )
                })
                .instance_stream
                .clone();
            return (racer, stream);
        }
    }
}

async fn expect_startup_terminal_failure(
    client: &mut ValidatedConnection,
    stream: &StreamPath,
    expected_message: &str,
) {
    tokio::time::timeout(Duration::from_secs(5), async {
        loop {
            let envelope = expect_next_event(client, "startup terminal failure").await;
            if envelope.kind != FrameKind::AgentBootstrap || envelope.stream != *stream {
                continue;
            }
            let bootstrap: AgentBootstrapPayload = envelope
                .parse_payload()
                .expect("parse failed startup AgentBootstrap");
            assert!(bootstrap.events.iter().any(|event| matches!(
                event,
                AgentBootstrapEvent::AgentError(error)
                    if error.fatal && error.message.contains(expected_message)
            )));
            break;
        }
    })
    .await
    .expect("startup failure was not published within five seconds");
}

async fn close_startup_matrix_agent(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    agent_id: &protocol::AgentId,
) {
    fixture
        .client
        .close_agent(stream)
        .await
        .expect("close startup matrix agent");
    expect_startup_agent_closed(&mut fixture.client, agent_id, Duration::from_secs(5)).await;
}

async fn assert_startup_lifecycle_matrix(
    backend_kind: BackendKind,
    origins: &[StartupLifecycleOrigin],
) {
    let selected_cell = std::env::var("TYDE_CONFORMANCE_STARTUP_CELL")
        .ok()
        .filter(|value| !value.trim().is_empty());
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let source_prompt = "Reply exactly STARTUP_RESUME_SOURCE_READY.";
    let source_roots = fixture.workspace_roots();
    let (source_stream, source_start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        source_roots,
        backend_kind,
        "startup-lifecycle-resume-source",
        source_prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    expect_startup_prompt_result(
        &mut fixture.client,
        &source_stream,
        source_prompt,
        "STARTUP_RESUME_SOURCE_READY",
    )
    .await;
    let mut resume_session_id = source_start
        .session_id
        .clone()
        .expect("startup matrix source missing session id");
    let source_agent_id = source_start.agent_id.clone();
    let source_remains_active = origins
        .iter()
        .any(|origin| matches!(origin, StartupLifecycleOrigin::Fork));
    if !source_remains_active {
        fixture
            .client
            .close_agent(&source_stream)
            .await
            .expect("close startup resume source");
        expect_startup_agent_closed(
            &mut fixture.client,
            &source_start.agent_id,
            Duration::from_secs(30),
        )
        .await;
    }

    let mut cells = 0usize;
    let mut executions = 0usize;
    for &origin in origins {
        for phase in [
            StartupLifecyclePhase::BeforeBackendReady,
            StartupLifecyclePhase::BackendReadyBeforeAgentStart,
        ] {
            for stimulus in [
                StartupLifecycleStimulus::Close,
                StartupLifecycleStimulus::Interrupt,
                StartupLifecycleStimulus::QueuedDelivery,
                StartupLifecycleStimulus::LastClientReconnect,
                StartupLifecycleStimulus::AbruptOwnerDeath,
                StartupLifecycleStimulus::CloseInterruptRace,
                StartupLifecycleStimulus::QueuedDeliveryCloseRace,
                StartupLifecycleStimulus::OwnerDeathCloseRace,
            ] {
                cells += 1;
                let selector = format!("{origin:?}:{phase:?}:{stimulus:?}").to_ascii_lowercase();
                if selected_cell
                    .as_ref()
                    .is_some_and(|selected| selected.to_ascii_lowercase() != selector)
                {
                    continue;
                }
                executions += 1;
                let cell = format!(
                    "{}-{origin:?}-{phase:?}-{stimulus:?}-{cells}",
                    backend_label(backend_kind)
                );
                let initial_sentinel = format!("STARTUP_INITIAL_{cells}");
                let initial_prompt = format!("Reply exactly {initial_sentinel}.");
                let queued_sentinel = format!("STARTUP_QUEUED_{cells}");
                let queued_prompt = format!("Reply exactly {queued_sentinel}.");
                let gate = match phase {
                    StartupLifecyclePhase::BeforeBackendReady => fixture
                        .host
                        .install_agent_startup_completion_test_gate(&cell),
                    StartupLifecyclePhase::BackendReadyBeforeAgentStart => fixture
                        .host
                        .install_agent_startup_backend_ready_test_gate(&cell),
                };
                let params = match origin {
                    StartupLifecycleOrigin::New => SpawnAgentParams::New {
                        workspace_roots: fixture.workspace_roots(),
                        prompt: initial_prompt.clone(),
                        images: None,
                        backend_kind,
                        launch_profile_id: None,
                        cost_hint: cost_hint_for(backend_kind),
                        access_mode: Default::default(),
                        session_settings: None,
                    },
                    StartupLifecycleOrigin::Resume => SpawnAgentParams::Resume {
                        session_id: resume_session_id.clone(),
                        prompt: Some(initial_prompt.clone()),
                    },
                    StartupLifecycleOrigin::Fork => SpawnAgentParams::Fork {
                        from_session_id: resume_session_id.clone(),
                        prompt: initial_prompt.clone(),
                        images: None,
                        access_mode: None,
                    },
                };
                fixture
                    .client
                    .spawn_agent(SpawnAgentPayload {
                        name: Some(cell.clone()),
                        custom_agent_id: None,
                        parent_agent_id: matches!(origin, StartupLifecycleOrigin::Fork)
                            .then(|| source_agent_id.clone()),
                        project_id: None,
                        params,
                    })
                    .await
                    .expect("spawn startup matrix cell");
                tokio::time::timeout(Duration::from_secs(180), gate.wait_until_entered())
                    .await
                    .unwrap_or_else(|_| panic!("startup gate was never reached for {cell}"));
                let new_agent: NewAgentPayload = expect_next_event_kind(
                    &mut fixture.client,
                    FrameKind::NewAgent,
                    "startup matrix NewAgent",
                )
                .await
                .parse_payload()
                .expect("parse startup matrix NewAgent");
                assert_eq!(new_agent.backend_kind, backend_kind);
                assert_eq!(
                    new_agent.origin,
                    match origin {
                        StartupLifecycleOrigin::New | StartupLifecycleOrigin::Resume => {
                            AgentOrigin::User
                        }
                        StartupLifecycleOrigin::Fork => AgentOrigin::SideQuestion,
                    }
                );
                eprintln!("STARTUP MATRIX STIMULUS {cell}");

                match stimulus {
                    StartupLifecycleStimulus::Close => {
                        close_startup_matrix_agent(
                            &mut fixture,
                            &new_agent.instance_stream,
                            &new_agent.agent_id,
                        )
                        .await;
                    }
                    StartupLifecycleStimulus::Interrupt => {
                        fixture
                            .client
                            .interrupt(&new_agent.instance_stream)
                            .await
                            .expect("interrupt startup matrix agent");
                        expect_startup_terminal_failure(
                            &mut fixture.client,
                            &new_agent.instance_stream,
                            "agent startup interrupted",
                        )
                        .await;
                        close_startup_matrix_agent(
                            &mut fixture,
                            &new_agent.instance_stream,
                            &new_agent.agent_id,
                        )
                        .await;
                    }
                    StartupLifecycleStimulus::AbruptOwnerDeath => {
                        assert!(
                            tokio::time::timeout(
                                Duration::from_secs(5),
                                fixture.host.force_agent_backend_shutdown_for_conformance(
                                    &new_agent.agent_id,
                                ),
                            )
                            .await
                            .expect("startup owner-death command timed out")
                        );
                        expect_startup_terminal_failure(
                            &mut fixture.client,
                            &new_agent.instance_stream,
                            "agent backend owner died during startup",
                        )
                        .await;
                        close_startup_matrix_agent(
                            &mut fixture,
                            &new_agent.instance_stream,
                            &new_agent.agent_id,
                        )
                        .await;
                    }
                    StartupLifecycleStimulus::QueuedDelivery => {
                        fixture
                            .client
                            .send_message(&new_agent.instance_stream, queued_prompt.clone())
                            .await
                            .expect("queue delivery during startup");
                        gate.release_one();
                        let start = expect_agent_start_on_stream(
                            &mut fixture.client,
                            &new_agent.instance_stream,
                            "released startup AgentStart",
                        )
                        .await;
                        expect_startup_prompt_result(
                            &mut fixture.client,
                            &new_agent.instance_stream,
                            &initial_prompt,
                            &initial_sentinel,
                        )
                        .await;
                        expect_startup_prompt_result(
                            &mut fixture.client,
                            &new_agent.instance_stream,
                            &queued_prompt,
                            &queued_sentinel,
                        )
                        .await;
                        if matches!(origin, StartupLifecycleOrigin::Resume) {
                            resume_session_id = start
                                .session_id
                                .clone()
                                .expect("resumed startup cell missing session id");
                        }
                        close_startup_matrix_agent(
                            &mut fixture,
                            &new_agent.instance_stream,
                            &new_agent.agent_id,
                        )
                        .await;
                    }
                    StartupLifecycleStimulus::LastClientReconnect => {
                        fixture = fixture.reconnect_after_last_client_disconnect().await;
                        let bootstrap = loop {
                            let envelope = expect_next_unfiltered_event(
                                &mut fixture.client,
                                "reconnected HostBootstrap",
                            )
                            .await;
                            if envelope.kind == FrameKind::HostBootstrap {
                                break envelope
                                    .parse_payload::<HostBootstrapPayload>()
                                    .expect("parse reconnected HostBootstrap");
                            }
                        };
                        let reconnected_agent = bootstrap
                            .agents
                            .iter()
                            .find(|agent| agent.agent_id == new_agent.agent_id)
                            .expect("reconnected HostBootstrap omitted starting agent")
                            .clone();
                        gate.release_one();
                        let start = expect_agent_start_on_stream(
                            &mut fixture.client,
                            &reconnected_agent.instance_stream,
                            "reconnected startup AgentStart",
                        )
                        .await;
                        expect_startup_prompt_result(
                            &mut fixture.client,
                            &reconnected_agent.instance_stream,
                            &initial_prompt,
                            &initial_sentinel,
                        )
                        .await;
                        if matches!(origin, StartupLifecycleOrigin::Resume) {
                            resume_session_id = start
                                .session_id
                                .clone()
                                .expect("reconnected resume missing session id");
                        }
                        close_startup_matrix_agent(
                            &mut fixture,
                            &reconnected_agent.instance_stream,
                            &new_agent.agent_id,
                        )
                        .await;
                    }
                    StartupLifecycleStimulus::CloseInterruptRace => {
                        let (mut racer, racer_stream) =
                            connect_startup_racer(&mut fixture, &new_agent.agent_id).await;
                        let (closed, interrupted) = tokio::join!(
                            fixture.client.close_agent(&new_agent.instance_stream),
                            racer.interrupt(&racer_stream),
                        );
                        closed.expect("close startup agent in interrupt race");
                        interrupted.expect("interrupt startup agent in close race");
                        expect_startup_agent_closed(
                            &mut fixture.client,
                            &new_agent.agent_id,
                            Duration::from_secs(5),
                        )
                        .await;
                    }
                    StartupLifecycleStimulus::QueuedDeliveryCloseRace => {
                        let (mut racer, racer_stream) =
                            connect_startup_racer(&mut fixture, &new_agent.agent_id).await;
                        let (delivered, closed) = tokio::join!(
                            fixture
                                .client
                                .send_message(&new_agent.instance_stream, queued_prompt.clone(),),
                            racer.close_agent(&racer_stream),
                        );
                        delivered.expect("deliver input in startup close race");
                        closed.expect("close startup agent in delivery race");
                        expect_startup_agent_closed(
                            &mut fixture.client,
                            &new_agent.agent_id,
                            Duration::from_secs(5),
                        )
                        .await;
                    }
                    StartupLifecycleStimulus::OwnerDeathCloseRace => {
                        let (mut racer, racer_stream) =
                            connect_startup_racer(&mut fixture, &new_agent.agent_id).await;
                        let (owner_died, closed) = tokio::join!(
                            fixture
                                .host
                                .force_agent_backend_shutdown_for_conformance(&new_agent.agent_id,),
                            racer.close_agent(&racer_stream),
                        );
                        assert!(owner_died, "startup owner-death race was not admitted");
                        closed.expect("close startup agent in owner-death race");
                        expect_startup_agent_closed(
                            &mut fixture.client,
                            &new_agent.agent_id,
                            Duration::from_secs(5),
                        )
                        .await;
                    }
                }
                let raced_terminal = matches!(
                    stimulus,
                    StartupLifecycleStimulus::CloseInterruptRace
                        | StartupLifecycleStimulus::QueuedDeliveryCloseRace
                        | StartupLifecycleStimulus::OwnerDeathCloseRace
                );
                drop(gate);
                if raced_terminal {
                    assert_startup_terminal_stays_closed(&mut fixture.client, &new_agent.agent_id)
                        .await;
                }
            }
        }
    }
    assert_eq!(
        cells,
        origins.len() * 16,
        "startup lifecycle cross-product is incomplete"
    );
    assert!(
        executions > 0,
        "startup lifecycle cell selection matched nothing"
    );
    if source_remains_active {
        close_startup_matrix_agent(&mut fixture, &source_stream, &source_agent_id).await;
    }
}

async fn assert_backend_resume_startup_case<B: Backend>(backend_kind: BackendKind) {
    let workspace = tempfile::tempdir().expect("resume workspace");
    let root = workspace.path().to_string_lossy().to_string();
    let initial_prompt =
        "Write 100 numbered lines containing the word context, then end with READY_TO_RESUME.";
    let (mut backend, mut events) = B::spawn(
        vec![root.clone()],
        universal_backend_config(backend_kind),
        protocol::SendMessagePayload {
            message: initial_prompt.to_owned(),
            images: None,
            origin: None,
            tool_response: None,
        },
    )
    .await
    .unwrap_or_else(|error| panic!("initial resume source spawn failed: {error}"));
    let mut session_id = backend.session_id();
    let initial_text = collect_backend_text_until_idle(&mut events, backend_kind).await;
    assert!(
        initial_text.contains("READY_TO_RESUME"),
        "resume source turn failed for {backend_kind:?}: {initial_text:?}"
    );
    for cycle in 1..=10 {
        backend.shutdown().await;
        let (resumed, mut resumed_events) = B::resume(
            vec![root.clone()],
            universal_backend_config(backend_kind),
            session_id.clone(),
        )
        .await
        .unwrap_or_else(|error| panic!("closed-session resume cycle {cycle} failed: {error}"));
        assert_eq!(
            resumed.session_id(),
            session_id,
            "resume cycle {cycle} changed provider session identity"
        );
        drain_resume_replay(&mut resumed_events, backend_kind, cycle).await;
        let resume_prompt =
            format!("In one short sentence, explain why resume cycle {cycle} is useful.");
        assert!(
            resumed
                .send(protocol::AgentInput::SendMessage(
                    protocol::SendMessagePayload {
                        message: resume_prompt,
                        images: None,
                        origin: None,
                        tool_response: None,
                    },
                ))
                .await,
            "resumed backend rejected input for cycle {cycle}"
        );
        let resumed_text = collect_backend_text_until_idle(&mut resumed_events, backend_kind).await;
        assert!(
            !resumed_text.trim().is_empty(),
            "resume cycle {cycle} produced no response for {backend_kind:?}"
        );
        session_id = resumed.session_id();
        backend = resumed;
        events = resumed_events;
    }

    let follow_up = "In one short sentence, confirm that this session still works.";
    assert!(
        backend
            .send(protocol::AgentInput::SendMessage(
                protocol::SendMessagePayload {
                    message: follow_up.to_owned(),
                    images: None,
                    origin: None,
                    tool_response: None,
                },
            ))
            .await,
        "resumed backend rejected follow-up input"
    );
    let follow_up_text = collect_backend_text_until_idle(&mut events, backend_kind).await;
    backend.shutdown().await;
    assert!(
        !follow_up_text.trim().is_empty(),
        "resumed backend produced no follow-up for {backend_kind:?}"
    );
}

async fn assert_resume_startup_case(backend_kind: BackendKind) {
    match backend_kind {
        BackendKind::Claude => {
            assert_backend_resume_startup_case::<server::backend::claude::ClaudeBackend>(
                backend_kind,
            )
            .await
        }
        BackendKind::Codex => {
            assert_backend_resume_startup_case::<server::backend::codex::CodexBackend>(backend_kind)
                .await
        }
        BackendKind::Acp => {
            assert_backend_resume_startup_case::<server::backend::kiro::KiroBackend>(backend_kind)
                .await
        }
        BackendKind::Hermes => {
            assert_backend_resume_startup_case::<server::backend::hermes::HermesBackend>(
                backend_kind,
            )
            .await
        }
        BackendKind::Tycode => {
            assert_backend_resume_startup_case::<server::backend::tycode::TycodeBackend>(
                backend_kind,
            )
            .await
        }
        BackendKind::Antigravity => {
            assert_backend_resume_startup_case::<server::backend::antigravity::AntigravityBackend>(
                backend_kind,
            )
            .await
        }
    }
}

fn resume_queue_cell(state: InputAdmissionState) -> InputAdmissionCoverageCell {
    InputAdmissionCoverageCell {
        activity: ActivityCondition::ForegroundOnly,
        state,
        input: InputAdmissionKind::PlainMessage,
        action: InputAdmissionAction::HostRestart,
    }
}

async fn prepare_persisted_resume_queue(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
) -> (InputAdmissionRun, String) {
    let run = reach_input_admission_state(
        fixture,
        backend_kind,
        resume_queue_cell(InputAdmissionState::ModelStreaming),
    )
    .await;
    let queued = format!(
        "Do not use tools. Reply exactly RESUME_QUEUE_{}.",
        Uuid::new_v4().simple()
    );
    fixture
        .client
        .send_message(&run.stream, queued.clone())
        .await
        .unwrap();
    expect_queued_messages_exact(&mut fixture.client, &run.stream, &[queued.as_str()]).await;
    fixture.host.shutdown_agents_for_conformance().await;
    (run, queued)
}

async fn assert_no_false_idle_before_queued_dispatch(
    client: &mut ValidatedConnection,
    stream: &StreamPath,
    queued: &str,
    context: &str,
) {
    let mut deferred = Vec::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_unfiltered_event(client, context).await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                deferred.push(envelope);
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == queued => {
                    deferred.push(envelope);
                    break;
                }
                ChatEvent::TypingStatusChanged(false) => {
                    panic!("{context}: resume published false Idle before dispatching its durable queue")
                }
                _ => deferred.push(envelope),
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context}: durable queued input was never dispatched"));
    client.restore_events(deferred);
}

async fn assert_repeated_resume_follow_up_exactly_once(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let initial = "Do not use tools. Reply exactly REPEATED_RESUME_INITIAL.";
    let roots = fixture.workspace_roots();
    let (mut stream, start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "repeated-resume-exactly-once",
        initial,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, initial).await;
    let session_id = start.session_id.expect("repeated resume session id");
    let mut prompts = vec![(initial.to_owned(), "REPEATED_RESUME_INITIAL".to_owned())];
    for cycle in 1..=3 {
        fixture.host.shutdown_agents_for_conformance().await;
        fixture.restart_host().await;
        let prompt = format!("Do not use tools. Reply exactly REPEATED_RESUME_{cycle}.");
        stream = resume_agent_via_protocol(
            &mut fixture.client,
            "repeated-resume-cycle",
            session_id.clone(),
            &prompt,
        )
        .await;
        expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, &prompt).await;
        prompts.push((prompt, format!("REPEATED_RESUME_{cycle}")));
    }

    let request_id =
        protocol::HistoryPageRequestId(format!("repeated-resume-{}", Uuid::new_v4().simple()));
    fixture
        .client
        .inner
        .fetch_session_history(
            &stream,
            FetchSessionHistoryPayload {
                agent_id: start.agent_id,
                request_id: request_id.clone(),
                before_seq: None,
                limit: 1000,
            },
        )
        .await
        .unwrap();
    let history = loop {
        let envelope = expect_next_event(&mut fixture.client, "repeated resume history").await;
        if envelope.kind == FrameKind::SessionHistory && envelope.stream == stream {
            let history: SessionHistoryPayload = envelope.parse_payload().unwrap();
            if history.request_id == request_id {
                break history;
            }
        }
    };
    for (prompt, marker) in prompts {
        assert_eq!(
            history.events.iter().filter(|event| matches!(
                event,
                ChatEvent::MessageAdded(ChatMessage { sender: MessageSender::User, content, .. })
                    if content == &prompt
            )).count(),
            1,
            "resume/follow-up cycle did not persist its accepted input exactly once: {prompt:?}"
        );
        assert_eq!(
            history
                .events
                .iter()
                .filter(|event| matches!(
                    event,
                    ChatEvent::StreamEnd(end) if end.message.content.contains(&marker)
                ))
                .count(),
            1,
            "resume/follow-up cycle did not persist its assistant terminal exactly once: {marker:?}"
        );
    }
}

async fn assert_persisted_queue_resume_no_false_idle(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let (run, queued) = prepare_persisted_resume_queue(&mut fixture, backend_kind).await;
    let (resumed, messages, _) = resume_input_admission_agent(&mut fixture, &run).await;
    assert_eq!(messages.len(), 1);
    assert_eq!(messages[0].message, queued);
    assert_no_false_idle_before_queued_dispatch(
        &mut fixture.client,
        &resumed,
        &queued,
        "persisted queue resume",
    )
    .await;
    let response =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &resumed, &queued).await;
    assert!(response.final_text.contains("RESUME_QUEUE_"));
}

async fn assert_resume_closed_dispatch_terminalizes_once(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let (run, queued) = prepare_persisted_resume_queue(&mut fixture, backend_kind).await;
    fixture.restart_host().await;
    let dispatch_gate = fixture
        .host
        .install_resume_queue_dispatch_test_gate("resume-closed-dispatch");
    fixture
        .client
        .spawn_agent(SpawnAgentPayload {
            name: Some("resume-closed-dispatch".to_owned()),
            custom_agent_id: None,
            parent_agent_id: None,
            project_id: None,
            params: SpawnAgentParams::Resume {
                session_id: run.session_id,
                prompt: None,
            },
        })
        .await
        .unwrap();
    let new_agent: NewAgentPayload = expect_next_event_kind(
        &mut fixture.client,
        FrameKind::NewAgent,
        "closed resume NewAgent",
    )
    .await
    .parse_payload()
    .unwrap();
    let resumed = new_agent.instance_stream;
    let resumed_agent_id = new_agent.agent_id;
    let start =
        expect_agent_start_on_stream(&mut fixture.client, &resumed, "closed resume AgentStart")
            .await;
    assert_eq!(start.agent_id, resumed_agent_id);
    dispatch_gate.wait_until_entered().await;
    assert!(
        fixture
            .host
            .force_agent_backend_shutdown_for_conformance(&resumed_agent_id)
            .await,
        "resume backend was not live at the forced-close boundary"
    );
    dispatch_gate.release_one();
    let mut fatal = 0usize;
    let mut fatal_seen_at: Option<Instant> = None;
    let deadline = Instant::now() + Duration::from_secs(30);
    while Instant::now() < deadline
        && fatal_seen_at.is_none_or(|seen| seen.elapsed() < Duration::from_millis(500))
    {
        let remaining = fatal_seen_at
            .map(|seen: Instant| Duration::from_millis(500).saturating_sub(seen.elapsed()))
            .unwrap_or_else(|| deadline.saturating_duration_since(Instant::now()));
        let Ok(envelope) = tokio::time::timeout(
            remaining.min(Duration::from_millis(500)),
            expect_next_unfiltered_event(&mut fixture.client, "closed resume dispatch"),
        )
        .await
        else {
            if fatal > 0 {
                break;
            }
            continue;
        };
        if envelope.stream != resumed {
            continue;
        }
        match envelope.kind {
            FrameKind::AgentError => {
                let error: protocol::AgentErrorPayload = envelope.parse_payload().unwrap();
                if error.fatal {
                    fatal += 1;
                    assert_eq!(
                        fatal, 1,
                        "closed resume dispatch emitted duplicate fatal errors"
                    );
                    fatal_seen_at.get_or_insert_with(Instant::now);
                }
            }
            FrameKind::ChatEvent => {
                if let ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) = envelope.parse_payload::<ChatEvent>().unwrap()
                {
                    assert_ne!(content, queued, "closed backend consumed the durable queue");
                }
            }
            _ => {}
        }
    }
    assert_eq!(
        fatal, 1,
        "closed resume dispatch did not terminalize visibly"
    );
}

