async fn assert_authoritative_resume_preserves_concurrent_events(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let run = reach_input_admission_state(
        &mut fixture,
        backend_kind,
        resume_queue_cell(InputAdmissionState::BackgroundOnlyIdle),
    )
    .await;
    assert!(!run.background_tool_ids.is_empty());
    let foreground = "Without using tools, write at least 2000 words beginning exactly AUTHORITATIVE_FOREGROUND_ACTIVE.";
    fixture
        .client
        .send_message(&run.stream, foreground.to_owned())
        .await
        .unwrap();
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "authoritative foreground stream").await;
            if envelope.kind == FrameKind::ChatEvent
                && envelope.stream == run.stream
                && matches!(
                    envelope.parse_payload::<ChatEvent>().unwrap(),
                    ChatEvent::StreamDelta(_)
                )
            {
                break;
            }
        }
    })
    .await
    .expect("authoritative resume setup never opened its foreground turn");
    let queued = "Do not use tools. Reply exactly AUTHORITATIVE_RESUME_WAKE.".to_owned();
    fixture
        .client
        .send_message(&run.stream, queued.clone())
        .await
        .unwrap();
    expect_queued_messages_exact(&mut fixture.client, &run.stream, &[queued.as_str()]).await;
    fixture.host.shutdown_agents_for_conformance().await;
    let (resumed, messages, bootstrap) = resume_input_admission_agent(&mut fixture, &run).await;
    assert_eq!(messages.len(), 1);
    assert_eq!(messages[0].message, queued);
    let mut terminal_progress = HashMap::<String, usize>::new();
    let mut subagent_progress = HashSet::new();
    let mut terminal_completions = HashMap::<String, usize>::new();
    let mut saw_stats = false;
    for event in bootstrap {
        match event {
            AgentBootstrapEvent::AgentActivityStats(_) => saw_stats = true,
            AgentBootstrapEvent::ChatEvent(ChatEvent::ToolProgress(progress))
                if run.background_tool_ids.contains(&progress.tool_call_id) =>
            {
                let terminal = match progress.update {
                    protocol::ToolProgressUpdate::SubAgent(subagent) => {
                        subagent_progress.insert(progress.tool_call_id.clone());
                        subagent.completed
                    }
                    update if background_task_progress(&update).is_some() => false,
                    _ => false,
                };
                if terminal {
                    *terminal_progress.entry(progress.tool_call_id).or_default() += 1;
                }
            }
            AgentBootstrapEvent::ChatEvent(ChatEvent::ToolExecutionCompleted(completion))
                if run.background_tool_ids.contains(&completion.tool_call_id) =>
            {
                *terminal_completions
                    .entry(completion.tool_call_id)
                    .or_default() += 1;
            }
            _ => {}
        }
    }
    assert!(
        saw_stats,
        "authoritative resume dropped its usage/activity snapshot"
    );
    for id in &run.background_tool_ids {
        if subagent_progress.contains(id) {
            assert_eq!(
                terminal_progress.get(id),
                Some(&1),
                "resume lost or duplicated terminal subagent progress for {id}"
            );
        } else {
            assert_eq!(
                terminal_progress.get(id),
                None,
                "resume fabricated terminal progress for background command {id}"
            );
        }
        assert_eq!(
            terminal_completions.get(id),
            Some(&1),
            "resume lost or duplicated tool completion for {id}"
        );
    }
    assert_no_false_idle_before_queued_dispatch(
        &mut fixture.client,
        &resumed,
        &queued,
        "authoritative resume concurrent events",
    )
    .await;
    let response =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &resumed, &queued).await;
    assert!(response.final_text.contains("AUTHORITATIVE_RESUME_WAKE"));
}

async fn assert_fork_case(backend_kind: BackendKind) {
    assert_host_fork_case(backend_kind).await;
}

async fn assert_host_fork_case(backend_kind: BackendKind) {
    const SOURCE_READY: &str = "FORK_SOURCE_HISTORY_READY";
    const FORK_READY: &str = "FORK_CHILD_READY";
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let roots = fixture.workspace_roots();
    let identifier = unique_project_identifier();
    std::fs::write(
        fixture
            .workspace_dir
            .path()
            .join("FORK_HISTORY_SENTINEL.txt"),
        &identifier,
    )
    .expect("seed fork history sentinel");
    std::fs::write(
        fixture.workspace_dir.path().join("READ_ONLY_PROOF.txt"),
        "FORK_ACCESS_ORIGINAL",
    )
    .expect("seed fork access sentinel");
    let source_prompt =
        session_lineage_read_prompt(backend_kind, "FORK_HISTORY_SENTINEL.txt", SOURCE_READY);
    fixture
        .client
        .spawn_agent(SpawnAgentPayload {
            name: Some("fork-source".to_owned()),
            custom_agent_id: None,
            parent_agent_id: None,
            project_id: None,
            params: SpawnAgentParams::New {
                workspace_roots: roots.clone(),
                prompt: source_prompt.clone(),
                images: None,
                backend_kind,
                launch_profile_id: None,
                cost_hint: cost_hint_for(backend_kind),
                access_mode: protocol::BackendAccessMode::ReadOnly,
                session_settings: None,
            },
        })
        .await
        .expect("spawn fork source");
    let source_new: NewAgentPayload = expect_next_event_kind(
        &mut fixture.client,
        FrameKind::NewAgent,
        "fork source NewAgent",
    )
    .await
    .parse_payload()
    .expect("parse fork source NewAgent");
    let source_start = expect_agent_start_on_stream(
        &mut fixture.client,
        &source_new.instance_stream,
        "fork source AgentStart",
    )
    .await;
    assert_eq!(source_start.agent_id, source_new.agent_id);
    assert_eq!(source_start.workspace_roots, roots);
    let source_session = source_start
        .session_id
        .clone()
        .expect("fork source session id");
    let source_turn = expect_tool_turn_after_user_echo(
        &mut fixture.client,
        &source_new.instance_stream,
        &source_prompt,
    )
    .await;
    assert!(source_turn.final_text.contains(SOURCE_READY));
    let source_requests: Vec<_> = source_turn
        .tool_requests
        .iter()
        .filter(|request| matches!(&request.tool_type, ToolRequestType::RunCommand { .. }))
        .collect();
    assert_eq!(source_requests.len(), 1);
    let source_tool_id = source_requests[0].tool_call_id.clone();
    assert_eq!(
        source_turn
            .tool_completions
            .iter()
            .filter(|completion| completion.tool_call_id == source_tool_id && completion.success())
            .count(),
        1
    );
    let source_bootstrap =
        reconnected_agent_bootstrap(&mut fixture, &source_new.instance_stream).await;
    let source_history = serialized_bootstrap_chat_history(&source_bootstrap);
    let source_settings = bootstrap_session_settings(&source_bootstrap, "fork source");
    assert_bootstrap_has_one_normalized_completion(
        &source_bootstrap,
        &source_tool_id,
        "fork source",
    );

    let fork_prompt = format!(
        "The inherited history contains a project identifier. Reply exactly {FORK_READY}-{identifier} and do not use tools."
    );
    fixture
        .client
        .spawn_agent(SpawnAgentPayload {
            name: Some("fork-child".to_owned()),
            custom_agent_id: None,
            parent_agent_id: Some(source_new.agent_id.clone()),
            project_id: None,
            params: SpawnAgentParams::Fork {
                from_session_id: source_session.clone(),
                prompt: fork_prompt.clone(),
                images: None,
                access_mode: None,
            },
        })
        .await
        .expect("fork source session");
    let fork_new: NewAgentPayload = expect_next_event_kind(
        &mut fixture.client,
        FrameKind::NewAgent,
        "fork child NewAgent",
    )
    .await
    .parse_payload()
    .expect("parse fork child NewAgent");
    assert_eq!(fork_new.origin, AgentOrigin::SideQuestion);
    assert_eq!(
        fork_new.parent_agent_id.as_ref(),
        Some(&source_new.agent_id)
    );
    assert_eq!(fork_new.backend_kind, backend_kind);
    assert_eq!(fork_new.workspace_roots, roots);
    assert_ne!(fork_new.agent_id, source_new.agent_id);
    assert_ne!(fork_new.instance_stream, source_new.instance_stream);
    let fork_session = fork_new.session_id.clone().expect("fork child session id");
    assert_ne!(fork_session, source_session);
    let fork_bootstrap = loop {
        let envelope =
            expect_next_unfiltered_event(&mut fixture.client, "fork child AgentBootstrap").await;
        if envelope.kind == FrameKind::AgentBootstrap && envelope.stream == fork_new.instance_stream
        {
            break envelope
                .parse_payload::<AgentBootstrapPayload>()
                .expect("parse fork child AgentBootstrap");
        }
    };
    let fork_starts: Vec<_> = fork_bootstrap
        .events
        .iter()
        .filter_map(|event| match event {
            AgentBootstrapEvent::AgentStart(start) => Some(start),
            _ => None,
        })
        .collect();
    assert_eq!(fork_starts.len(), 1);
    assert_eq!(fork_starts[0].agent_id, fork_new.agent_id);
    assert_eq!(
        fork_starts[0].parent_agent_id.as_ref(),
        Some(&source_new.agent_id)
    );
    assert_eq!(fork_starts[0].session_id.as_ref(), Some(&fork_session));
    assert_eq!(fork_starts[0].workspace_roots, roots);
    let fork_history = serialized_bootstrap_chat_history(&fork_bootstrap);
    assert!(
        fork_history.starts_with(&source_history),
        "fork did not preserve the source history exactly"
    );
    assert_eq!(
        bootstrap_session_settings(&fork_bootstrap, "fork child"),
        source_settings,
        "fork changed inherited effective session settings"
    );
    assert_bootstrap_has_one_normalized_completion(&fork_bootstrap, &source_tool_id, "fork child");
    let fork_turn = expect_assistant_turn_after_user_echo(
        &mut fixture.client,
        &fork_new.instance_stream,
        &fork_prompt,
    )
    .await;
    assert!(
        fork_turn
            .final_text
            .contains(&format!("{FORK_READY}-{identifier}"))
    );
    assert_inherited_read_only_denies_command(
        &mut fixture,
        backend_kind,
        &fork_new.instance_stream,
        "FORK_ACCESS_ORIGINAL",
        "FORK_ACCESS_MUTATED",
    )
    .await;

    let source_follow_up = "Reply exactly FORK_SOURCE_STILL_INDEPENDENT and do not use tools.";
    fixture
        .client
        .send_message(&source_new.instance_stream, source_follow_up.to_owned())
        .await
        .expect("send source follow-up after fork");
    let source_after = expect_assistant_turn_after_user_echo(
        &mut fixture.client,
        &source_new.instance_stream,
        source_follow_up,
    )
    .await;
    assert_eq!(
        source_after.final_text.trim(),
        "FORK_SOURCE_STILL_INDEPENDENT"
    );
    let fork_follow_up = "Reply exactly FORK_CHILD_STILL_INDEPENDENT and do not use tools.";
    fixture
        .client
        .send_message(&fork_new.instance_stream, fork_follow_up.to_owned())
        .await
        .expect("send fork follow-up");
    let fork_after = expect_assistant_turn_after_user_echo(
        &mut fixture.client,
        &fork_new.instance_stream,
        fork_follow_up,
    )
    .await;
    assert_eq!(fork_after.final_text.trim(), "FORK_CHILD_STILL_INDEPENDENT");

    let sessions = list_sessions_via_protocol(&mut fixture.client).await;
    let source_summary = sessions
        .sessions
        .iter()
        .find(|session| session.id == source_session)
        .expect("session list omitted fork source");
    let fork_summary = sessions
        .sessions
        .iter()
        .find(|session| session.id == fork_session)
        .expect("session list omitted fork child");
    assert_eq!(source_summary.workspace_roots, roots);
    assert_eq!(fork_summary.workspace_roots, roots);
    assert_eq!(source_summary.parent_id, None);
    assert_eq!(fork_summary.parent_id.as_ref(), Some(&source_session));
    assert_eq!(source_summary.message_count, 2);
    assert_eq!(fork_summary.message_count, 4);
    let source_after_bootstrap =
        reconnected_agent_bootstrap(&mut fixture, &source_new.instance_stream).await;
    let source_after_json =
        serde_json::to_string(&serialized_bootstrap_chat_history(&source_after_bootstrap))
            .expect("serialize source isolation history");
    assert!(!source_after_json.contains(FORK_READY));
    assert!(!source_after_json.contains("FORK_CHILD_STILL_INDEPENDENT"));
}

struct AgentControlPair {
    parent_stream: StreamPath,
    parent_id: protocol::AgentId,
    parent_session_id: SessionId,
    child_stream: StreamPath,
    child_id: protocol::AgentId,
    child_release: PathBuf,
}

struct AgentControlChild {
    stream: StreamPath,
    id: protocol::AgentId,
    release: PathBuf,
}

async fn spawn_idle_agent_control_agent(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    parent_agent_id: Option<protocol::AgentId>,
    name: &str,
) -> (StreamPath, protocol::AgentId) {
    let prompt = format!("Do not use tools. Reply exactly {name}_READY.");
    let workspace_roots = fixture.workspace_roots();
    fixture
        .client
        .spawn_agent(SpawnAgentPayload {
            name: Some(name.to_owned()),
            custom_agent_id: None,
            parent_agent_id: parent_agent_id.clone(),
            project_id: None,
            params: SpawnAgentParams::New {
                workspace_roots,
                prompt: prompt.clone(),
                images: None,
                backend_kind,
                launch_profile_id: None,
                cost_hint: cost_hint_for(backend_kind),
                access_mode: Default::default(),
                session_settings: None,
            },
        })
        .await
        .expect("spawn idle agent-control topology agent");
    let new_agent: NewAgentPayload = expect_next_event_kind(
        &mut fixture.client,
        FrameKind::NewAgent,
        "idle agent-control topology NewAgent",
    )
    .await
    .parse_payload()
    .expect("parse idle agent-control topology NewAgent");
    assert_eq!(new_agent.parent_agent_id, parent_agent_id);
    let started = expect_agent_start_on_stream(
        &mut fixture.client,
        &new_agent.instance_stream,
        "idle agent-control topology AgentStart",
    )
    .await;
    let response = expect_assistant_turn_after_user_echo(
        &mut fixture.client,
        &new_agent.instance_stream,
        &prompt,
    )
    .await;
    assert!(response.final_text.contains(&format!("{name}_READY")));
    (new_agent.instance_stream, started.agent_id)
}

async fn spawn_agent_control_child(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    roots: Vec<String>,
    parent_id: &protocol::AgentId,
    name: &str,
) -> AgentControlChild {
    let child_release = fixture
        .workspace_dir
        .path()
        .join(format!("child_release_{}", Uuid::new_v4().simple()));
    let release_name = child_release
        .file_name()
        .expect("child release filename")
        .to_string_lossy();
    let command = format!(
        "while [ ! -f {release_name} ]; do sleep 0.1; done; printf AGENT_CONTROL_CHILD_DONE"
    );
    let child_prompt = match backend_kind {
        BackendKind::Claude => format!(
            "Use Bash exactly once in the foreground to run `{command}`. Do not use run_in_background and do not use another tool."
        ),
        BackendKind::Codex => format!(
            "Call run_command exactly once now with command `{command}` and yield_time_ms=30000. Do not reply or finish before making the call. Do not alter the command, add `&`, or use another tool."
        ),
        BackendKind::Hermes => format!(
            "Use the terminal tool exactly once in the foreground to run `{command}`. Do not use background mode or another tool."
        ),
        _ => format!(
            "Use the command tool exactly once in the foreground to run `{command}`. Do not use another tool."
        ),
    };
    fixture
        .client
        .spawn_agent(SpawnAgentPayload {
            name: Some(name.to_owned()),
            custom_agent_id: None,
            parent_agent_id: Some(parent_id.clone()),
            project_id: None,
            params: SpawnAgentParams::New {
                workspace_roots: roots,
                prompt: child_prompt.clone(),
                images: None,
                backend_kind,
                launch_profile_id: None,
                cost_hint: cost_hint_for(backend_kind),
                access_mode: Default::default(),
                session_settings: None,
            },
        })
        .await
        .expect("spawn real agent-control child");
    let child_new: NewAgentPayload = expect_next_event_kind(
        &mut fixture.client,
        FrameKind::NewAgent,
        "agent-control child NewAgent",
    )
    .await
    .parse_payload()
    .expect("parse agent-control child NewAgent");
    assert_eq!(child_new.parent_agent_id.as_ref(), Some(parent_id));
    assert_eq!(child_new.origin, AgentOrigin::User);
    let child = expect_agent_start_on_stream(
        &mut fixture.client,
        &child_new.instance_stream,
        "agent-control child AgentStart",
    )
    .await;
    let mut saw_child_input = false;
    let mut saw_child_typing = false;
    let mut child_trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "running agent-control child").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != child_new.instance_stream
            {
                continue;
            }
            let event = envelope
                .parse_payload::<ChatEvent>()
                .expect("parse child event");
            child_trace.push(format!("{event:?}"));
            match event {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == child_prompt => saw_child_input = true,
                ChatEvent::TypingStatusChanged(true) if saw_child_input => saw_child_typing = true,
                ChatEvent::ToolRequest(ToolRequest {
                    tool_type: ToolRequestType::RunCommand { ref command, .. },
                    ..
                }) if command.contains(release_name.as_ref()) => break,
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("child failed before barrier: {content}"),
                ChatEvent::TypingStatusChanged(false) if saw_child_typing => {
                    panic!(
                        "child became idle before entering its barrier; trace:\n{}",
                        child_trace.join("\n")
                    )
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "child did not enter its real command barrier; trace:\n{}",
            child_trace.join("\n")
        )
    });
    AgentControlChild {
        stream: child_new.instance_stream,
        id: child.agent_id,
        release: child_release,
    }
}

async fn spawn_agent_control_pair(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
) -> AgentControlPair {
    let roots = fixture.workspace_roots();
    let ready_prompt = "Reply exactly AGENT_CONTROL_PARENT_READY.";
    let (parent_stream, parent) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots.clone(),
        backend_kind,
        "agent-control-parent",
        ready_prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let ready =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &parent_stream, ready_prompt)
            .await;
    assert!(ready.final_text.contains("AGENT_CONTROL_PARENT_READY"));

    let child = spawn_agent_control_child(
        fixture,
        backend_kind,
        roots,
        &parent.agent_id,
        "agent-control-child",
    )
    .await;
    AgentControlPair {
        parent_stream,
        parent_id: parent.agent_id,
        parent_session_id: parent.session_id.expect("agent-control parent session id"),
        child_stream: child.stream,
        child_id: child.id,
        child_release: child.release,
    }
}

async fn assert_agent_control_spawn_contract(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let roots = fixture.workspace_roots();
    let ready_prompt = "Do not use tools. Reply exactly AGENT_CONTROL_SPAWN_PARENT_READY.";
    let (parent_stream, parent) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots.clone(),
        backend_kind,
        "agent-control-spawn-parent",
        ready_prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let ready =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &parent_stream, ready_prompt)
            .await;
    assert!(
        ready
            .final_text
            .contains("AGENT_CONTROL_SPAWN_PARENT_READY")
    );

    let child_prompt = "Do not use tools. Reply exactly AGENT_CONTROL_SPAWN_CHILD_OK.";
    let child_name = "agent-control-spawn-child";
    let backend_name = backend_label(backend_kind);
    let prompt = match backend_kind {
        BackendKind::Claude => format!(
            "Call the Tyde MCP tool tyde_spawn_agent exactly once with backend_kind `{backend_name}`, workspace_roots {roots:?}, name `{child_name}`, cost_hint `low`, and prompt `{child_prompt}`. Do not use Agent or another tool. After the tool returns, stop."
        ),
        BackendKind::Codex => format!(
            "Call tyde_spawn_agent from the tyde-agent-control MCP server exactly once with backend_kind `{backend_name}`, workspace_roots {roots:?}, name `{child_name}`, cost_hint `low`, and prompt `{child_prompt}`. Do not use native collaboration or another tool. After the tool returns, stop."
        ),
        _ => format!(
            "Call the Tyde agent-control MCP tool tyde_spawn_agent exactly once with backend_kind `{backend_name}`, workspace_roots {roots:?}, name `{child_name}`, cost_hint `low`, and prompt `{child_prompt}`. Do not use a native subagent tool or another tool. After the tool returns, stop."
        ),
    };
    fixture
        .client
        .send_message(&parent_stream, prompt.clone())
        .await
        .expect("send agent-control spawn prompt");

    let mut request_id = None;
    let mut child = None;
    let mut child_started = false;
    let mut spawn_progress = 0usize;
    let mut completion_count = 0usize;
    let mut child_result = false;
    let mut trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(240), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "agent-control spawn contract").await;
            if envelope.kind == FrameKind::NewAgent {
                let spawned: NewAgentPayload = envelope.parse_payload().unwrap();
                if spawned.parent_agent_id.as_ref() == Some(&parent.agent_id) {
                    assert_eq!(spawned.origin, AgentOrigin::AgentControl);
                    assert_eq!(spawned.backend_kind, backend_kind);
                    assert_eq!(spawned.workspace_roots, roots);
                    assert_eq!(spawned.name, child_name);
                    assert!(
                        child
                            .replace((spawned.agent_id, spawned.instance_stream))
                            .is_none()
                    );
                }
                continue;
            }
            if envelope.kind != FrameKind::ChatEvent {
                continue;
            }
            let event = envelope.parse_payload::<ChatEvent>().unwrap();
            trace.push(format!("{} {event:?}", envelope.stream.0));
            if envelope.stream == parent_stream {
                match event {
                    ChatEvent::ToolRequest(ToolRequest {
                        tool_call_id,
                        tool_type:
                            ToolRequestType::AgentSpawn {
                                prompt: Some(actual_prompt),
                                name,
                                execution_mode,
                            },
                        ..
                    }) => {
                        assert_eq!(actual_prompt, child_prompt);
                        assert_eq!(name.as_deref(), Some(child_name));
                        assert_eq!(execution_mode, protocol::AgentExecutionMode::Background);
                        assert!(request_id.replace(tool_call_id).is_none());
                    }
                    ChatEvent::ToolProgress(progress)
                        if request_id.as_deref() == Some(progress.tool_call_id.as_str()) =>
                    {
                        let protocol::ToolProgressUpdate::AgentControl(update) = progress.update
                        else {
                            panic!("agent-control spawn emitted the wrong progress family");
                        };
                        assert_eq!(
                            update.progress_kind,
                            protocol::AgentControlProgressKind::Spawn
                        );
                        assert_eq!(
                            update.status,
                            protocol::AgentControlProgressStatus::Completed
                        );
                        let child_id = &child.as_ref().expect("spawn progress preceded NewAgent").0;
                        assert_eq!(update.agents.len(), 1);
                        assert_eq!(&update.agents[0].agent_id, child_id);
                        spawn_progress += 1;
                        assert_eq!(spawn_progress, 1);
                    }
                    ChatEvent::ToolExecutionCompleted(completion)
                        if request_id.as_deref() == Some(completion.tool_call_id.as_str()) =>
                    {
                        assert!(
                            completion.success(),
                            "agent-control spawn failed: {completion:?}"
                        );
                        completion_count += 1;
                        assert_eq!(completion_count, 1);
                    }
                    ChatEvent::ToolRequest(request) => panic!(
                        "agent-control spawn issued an unexpected extra tool request: {request:?}"
                    ),
                    ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::Error,
                        content,
                        ..
                    }) => panic!("agent-control spawn parent failed: {content}"),
                    _ => {}
                }
            } else if child
                .as_ref()
                .is_some_and(|(_, stream)| *stream == envelope.stream)
            {
                match event {
                    ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::User,
                        content,
                        ..
                    }) if content == child_prompt => child_started = true,
                    ChatEvent::StreamEnd(end)
                        if end.message.content.contains("AGENT_CONTROL_SPAWN_CHILD_OK") =>
                    {
                        assert!(child_started, "child replied before its input was observed");
                        child_result = true;
                    }
                    ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::Error,
                        content,
                        ..
                    }) => panic!("agent-control spawned child failed: {content}"),
                    _ => {}
                }
            }
            if request_id.is_some()
                && child.is_some()
                && spawn_progress == 1
                && completion_count == 1
                && child_result
            {
                break;
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "agent-control spawn contract timed out; trace:\n{}",
            trace.join("\n")
        )
    });

    close_agent_at_definitive_boundary(
        &mut fixture,
        &parent_stream,
        &parent.agent_id,
        "close agent-control spawn parent",
    )
    .await;
}

fn agent_control_tool_prompt(
    backend_kind: BackendKind,
    tool: &str,
    child_id: &protocol::AgentId,
) -> String {
    agent_control_tool_prompt_for_ids(backend_kind, tool, std::slice::from_ref(child_id))
}

fn agent_control_tool_prompt_for_ids(
    backend_kind: BackendKind,
    tool: &str,
    child_ids: &[protocol::AgentId],
) -> String {
    let instruction = match (backend_kind, tool) {
        (BackendKind::Claude, "send") => "Call tyde_send_agent_message exactly once",
        (BackendKind::Claude, "await") => "Call tyde_await_agents exactly once",
        (BackendKind::Codex, "send") => {
            "Call tyde_send_agent_message from the connected Tyde agent-control MCP server exactly once; do not merely describe the call"
        }
        (BackendKind::Codex, "await") => {
            "Call the available tyde_await_agents tool exactly once; do not use wait, exec, shell, tool search, or merely describe the call"
        }
        (BackendKind::Tycode | BackendKind::Hermes, "send") => {
            "Call the available tyde_send_agent_message tool from the connected Tyde agent-control MCP server exactly once; do not merely describe the call"
        }
        (BackendKind::Tycode | BackendKind::Hermes, "await") => {
            "Call the available tyde_await_agents tool from the connected Tyde agent-await MCP server exactly once; do not merely describe the call"
        }
        (_, "send") => "Use the Tyde agent-control send-message tool exactly once",
        (_, "await") => "Use the Tyde agent-control await-agents tool exactly once",
        _ => unreachable!(),
    };
    match tool {
        "send" => format!(
            "{instruction} with agent_id `{}` and message `AGENT_CONTROL_MESSAGE_731`. Do not call any other tool. After it returns, reply exactly AGENT_MESSAGE_DONE.",
            child_ids[0].0
        ),
        "await" => {
            let ids = child_ids
                .iter()
                .map(|id| format!("`{}`", id.0))
                .collect::<Vec<_>>()
                .join(", ");
            format!(
                "{instruction} with agent_ids [{ids}] in exactly that order. Do not omit or duplicate an ID. Do not call any other tool. Do not send a textual response: remain blocked inside that tool until a child changes state."
            )
        }
        _ => unreachable!(),
    }
}

fn ambient_barrier_command(activity: ActivityCondition, index: usize, label: &str) -> String {
    if ambient_work_fails(activity) {
        format!(
            "while [ ! -f QUESTION_RELEASE_{index} ]; do sleep 0.1; done; printf {label}_FAILED_{index} >&2; exit 37"
        )
    } else {
        format!(
            "while [ ! -f QUESTION_RELEASE_{index} ]; do sleep 0.1; done; printf {label}_DONE_{index}"
        )
    }
}

fn ambient_setup_instruction(
    backend_kind: BackendKind,
    activity: ActivityCondition,
    label: &str,
) -> String {
    let kind = activity.ambient_work_kind();
    if kind == AmbientWorkKind::None {
        return "Do not start background work.".to_owned();
    }
    let total = ambient_work_count(activity);
    let command_count = match kind {
        AmbientWorkKind::Commands => total,
        AmbientWorkKind::Mixed => 1,
        AmbientWorkKind::None | AmbientWorkKind::Subagents => 0,
    };
    let subagent_count = match kind {
        AmbientWorkKind::Subagents => total,
        AmbientWorkKind::Mixed => 1,
        AmbientWorkKind::None | AmbientWorkKind::Commands => 0,
    };
    let mut clauses = Vec::new();
    if command_count > 0 {
        let commands = (1..=command_count)
            .map(|index| format!("`{}`", ambient_barrier_command(activity, index, label)))
            .collect::<Vec<_>>()
            .join(" and ");
        clauses.push(match backend_kind {
            BackendKind::Claude => format!(
                "start exactly {command_count} Bash command(s), each with run_in_background=true, for {commands}"
            ),
            BackendKind::Codex => format!(
                "start exactly {command_count} command execution session(s), each with yield_time_ms=1000, for {commands}; do not add `&`"
            ),
            BackendKind::Hermes => format!(
                "start exactly {command_count} terminal command(s), each with background=true, for {commands}"
            ),
            _ => format!("start exactly {command_count} background command(s) for {commands}"),
        });
    }
    if subagent_count > 0 {
        let first_index = command_count + 1;
        let jobs = (first_index..first_index + subagent_count)
            .map(|index| {
                format!(
                    "a child whose only task is to run `{}` in the foreground and report its result",
                    ambient_barrier_command(activity, index, label)
                )
            })
            .collect::<Vec<_>>()
            .join(" and ");
        clauses.push(match backend_kind {
            BackendKind::Claude => format!(
                "use the built-in Agent tool to start exactly {subagent_count} child task(s), each with model=haiku and run_in_background=true: {jobs}; do not use ToolSearch or any MCP tool"
            ),
            BackendKind::Codex => format!(
                "delegate exactly {subagent_count} native Codex subagent(s) in background: {jobs}"
            ),
            BackendKind::Hermes => format!(
                "start exactly {subagent_count} provider-native subagent(s) in background: {jobs}"
            ),
            _ => format!(
                "start exactly {subagent_count} provider-native subagent(s) in background: {jobs}"
            ),
        });
    }
    format!(
        "First {}. Do not wait for, poll, stop, or perform the work of any background item yourself.",
        clauses.join(", then ")
    )
}

async fn start_agent_control_ambient_work(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    stream: &StreamPath,
    activity: ActivityCondition,
) -> HashSet<String> {
    let count = ambient_work_count(activity);
    if count == 0 {
        return HashSet::new();
    }
    let instruction = format!(
        "{} After every background item reports Running, reply exactly AWAIT_AMBIENT_READY.",
        ambient_setup_instruction(backend_kind, activity, "AWAIT_AMBIENT")
    );
    fixture
        .client
        .send_message(stream, instruction)
        .await
        .unwrap();
    let mut ambient = AmbientWorkObservation::default();
    let mut ready = false;
    let mut setup_trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        while ambient.running.len() != count || !ready {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            let event = envelope.parse_payload::<ChatEvent>().unwrap();
            setup_trace.push(event.clone());
            match event {
                ChatEvent::ToolProgress(progress) => ambient.observe_running(&progress),
                ChatEvent::StreamEnd(end) => {
                    ready |= end.message.content.contains("AWAIT_AMBIENT_READY")
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("ambient await setup failed: {content}"),
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!("await ambient background work did not start; trace={setup_trace:#?}")
    });
    ambient.assert_exact(activity, "agent-control ambient setup");
    ambient.ids()
}

async fn assert_agent_message_case(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    child_failed: bool,
) {
    let pair = spawn_agent_control_pair(fixture, backend_kind).await;
    if child_failed {
        assert!(
            fixture
                .host
                .force_agent_backend_shutdown_for_conformance(&pair.child_id)
                .await
        );
    }
    let prompt = agent_control_tool_prompt(backend_kind, "send", &pair.child_id);
    fixture
        .client
        .send_message(&pair.parent_stream, prompt.clone())
        .await
        .expect("send agent-message prompt");
    let turn =
        expect_tool_turn_after_user_echo(&mut fixture.client, &pair.parent_stream, &prompt).await;
    let requests: Vec<_> = turn
        .tool_requests
        .iter()
        .filter(|request| {
            matches!(
                &request.tool_type,
                ToolRequestType::TydeSendAgentMessage { .. }
            )
        })
        .collect();
    assert_eq!(
        requests.len(),
        1,
        "expected exactly one normalized agent-message request; all requests={:?}; completions={:?}; final_text={:?}",
        turn.tool_requests,
        turn.tool_completions,
        turn.final_text
    );
    let request = requests[0];
    let completions: Vec<_> = turn
        .tool_completions
        .iter()
        .filter(|completion| completion.tool_call_id == request.tool_call_id)
        .collect();
    assert_eq!(
        completions.len(),
        1,
        "agent-message request was not terminalized exactly once"
    );
    assert_eq!(
        turn.tool_completions.len(),
        1,
        "agent-message turn emitted an unrelated tool completion: {:?}",
        turn.tool_completions
    );
    assert_eq!(completions[0].success(), !child_failed);
    if !child_failed {
        assert!(matches!(
            &completions[0].tool_result(),
            ToolExecutionResult::TydeSendAgentMessage
        ));
        std::fs::write(&pair.child_release, b"release").expect("release messaged child");
        let mut echoes = 0usize;
        tokio::time::timeout(Duration::from_secs(120), async {
            loop {
                let envelope =
                    expect_next_event(&mut fixture.client, "agent-message child echo").await;
                if envelope.kind != FrameKind::ChatEvent || envelope.stream != pair.child_stream {
                    continue;
                }
                match envelope
                    .parse_payload::<ChatEvent>()
                    .expect("parse messaged child event")
                {
                    ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::User,
                        content,
                        ..
                    }) if content == "AGENT_CONTROL_MESSAGE_731" => echoes += 1,
                    ChatEvent::TypingStatusChanged(false) if echoes > 0 => break,
                    ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::Error,
                        content,
                        ..
                    }) => panic!("messaged child failed: {content}"),
                    _ => {}
                }
            }
        })
        .await
        .expect("accepted agent message was not delivered to the real child");
        assert_eq!(echoes, 1, "agent message was not consumed exactly once");
    }
}

struct NativeSpawnWait {
    parent_stream: StreamPath,
    parent_id: protocol::AgentId,
    parent_session_id: SessionId,
    child_id: protocol::AgentId,
    tool_call_id: String,
    release: PathBuf,
    completion_marker: PathBuf,
    ambient_ids: HashSet<String>,
}

async fn reach_native_spawn_wait(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    tool: SpecialToolContract,
    result: ToolResultVariant,
    activity: ActivityCondition,
) -> NativeSpawnWait {
    let roots = fixture.workspace_roots();
    let ready_prompt = "Do not use tools. Reply exactly NATIVE_SPAWN_PARENT_READY.";
    let (parent_stream, parent) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "native-spawn-contract-parent",
        ready_prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let ready =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &parent_stream, ready_prompt)
            .await;
    assert!(ready.final_text.contains("NATIVE_SPAWN_PARENT_READY"));
    let ambient_ids =
        start_agent_control_ambient_work(fixture, backend_kind, &parent_stream, activity).await;
    let release = fixture
        .workspace_dir
        .path()
        .join(format!("NATIVE_SPAWN_RELEASE_{}", Uuid::new_v4().simple()));
    let completion_marker = fixture
        .workspace_dir
        .path()
        .join(format!("NATIVE_SPAWN_EXECUTED_{}", Uuid::new_v4().simple()));
    let release_name = release.to_string_lossy();
    let completion_marker_name = completion_marker.to_string_lossy();
    let background = tool == SpecialToolContract::BackgroundSubagent;
    let child_job = if result == ToolResultVariant::Fails {
        format!(
            "run exactly `while [ ! -f {release_name} ]; do sleep 0.1; done; printf executed > {completion_marker_name}; printf NATIVE_CHILD_FAILED >&2; exit 7` in the foreground and report the failure"
        )
    } else {
        format!(
            "run exactly `while [ ! -f {release_name} ]; do sleep 0.1; done; printf executed > {completion_marker_name}; printf NATIVE_CHILD_DONE` in the foreground and wait for it"
        )
    };
    let prompt = match (backend_kind, background, result) {
        (BackendKind::Claude, false, ToolResultVariant::Fails) => format!(
            "Use Agent exactly once with run_in_background=false and max_turns=1. Tell the child to {child_job}. Wait for that child and do not use another tool."
        ),
        (BackendKind::Claude, true, ToolResultVariant::Fails) => format!(
            "Use Agent exactly once with run_in_background=true and max_turns=1. Tell the child to {child_job}. Do not poll or stop it. End the foreground turn after it reports running."
        ),
        (BackendKind::Claude, false, _) => format!(
            "Use Agent exactly once with run_in_background=false. Tell the child to {child_job}. Wait for that child and do not use another tool."
        ),
        (BackendKind::Claude, true, _) => format!(
            "Use Agent exactly once with run_in_background=true. Tell the child to {child_job}. Do not poll or stop it. End the foreground turn after it reports running."
        ),
        (BackendKind::Codex, true, _) => format!(
            "Delegate exactly one native Codex subagent named `native_wait_child` to this task: {child_job}. Return immediately after starting it. Do not use any Tyde MCP tool, do not wait or poll, and do not perform the task yourself."
        ),
        (BackendKind::Hermes, true, ToolResultVariant::Fails) => format!(
            "This is an IDE-managed child failure-lifecycle integration test. Call the built-in `delegate_task` tool exactly once with goal `{child_job}`, `acp_command` set to `false`, and `acp_args` set to an empty array. The deliberately non-ACP executable must make this dispatched child fail visibly. Return immediately after `delegate_task` reports that it dispatched the child. Do not use any MCP tool, do not wait or poll, and do not perform the task yourself."
        ),
        (BackendKind::Hermes, true, _) => format!(
            "This is an IDE-managed child lifecycle integration test. Call the built-in `delegate_task` tool exactly once to start one managed background subagent for this task: {child_job}. The harness will create the release file after it observes the child running, so the wait and any requested nonzero exit are intentional. Return immediately after `delegate_task` reports that it dispatched the child. Do not use any MCP tool, do not wait or poll, and do not perform the task yourself."
        ),
        (_, false, _) => format!(
            "Use the native subagent tool exactly once in foreground/attached mode. Tell the child to {child_job}. Wait for that child and do not use another tool."
        ),
        (_, true, _) => format!(
            "Use the native subagent tool exactly once in background/detached mode. Tell the child to {child_job}. Do not poll or stop it. End the foreground turn after it reports running."
        ),
    };
    fixture
        .client
        .send_message(&parent_stream, prompt.clone())
        .await
        .unwrap();
    let expected_mode = if background {
        protocol::AgentExecutionMode::Background
    } else {
        protocol::AgentExecutionMode::Foreground
    };
    let mut request_id = None;
    let mut progress_id = None;
    let mut child_id = None;
    let mut projected_child = None;
    let mut parent_idle = false;
    let mut saw_parent_input = false;
    let mut saw_parent_typing = false;
    let mut trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(180), async {
        loop {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind == FrameKind::NewAgent {
                let child: NewAgentPayload = envelope.parse_payload().unwrap();
                if child.parent_agent_id.as_ref() == Some(&parent.agent_id) {
                    assert!(
                        projected_child.replace(child.agent_id).is_none(),
                        "native spawn projected more than one new child"
                    );
                }
                continue;
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != parent_stream {
                continue;
            }
            let event = envelope.parse_payload::<ChatEvent>().unwrap();
            trace.push(format!("{event:?}"));
            match event {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == prompt => saw_parent_input = true,
                ChatEvent::TypingStatusChanged(true) if saw_parent_input => {
                    saw_parent_typing = true
                }
                ChatEvent::ToolRequest(ToolRequest {
                    tool_call_id,
                    tool_type:
                        ToolRequestType::AgentSpawn {
                            prompt,
                            name,
                            execution_mode,
                        },
                    ..
                }) => {
                    assert_agent_spawn_request_shape(
                        prompt.as_deref(),
                        name.as_deref(),
                        execution_mode,
                    );
                    assert_eq!(execution_mode, expected_mode);
                    assert!(request_id.replace(tool_call_id).is_none());
                }
                ChatEvent::ToolRequest(request) => panic!(
                    "native spawn issued an unexpected extra tool request: {request:?}"
                ),
                ChatEvent::ToolProgress(progress) => {
                    if let protocol::ToolProgressUpdate::SubAgent(child) = progress.update {
                        assert!(
                            !child.completed,
                            "child terminalized before running was observed"
                        );
                        assert_eq!(child.status, protocol::SubAgentProgressStatus::Running);
                        if let Some(existing) = progress_id.as_ref() {
                            assert_eq!(existing, &progress.tool_call_id);
                        } else {
                            progress_id = Some(progress.tool_call_id);
                        }
                        if let Some(existing) = child_id.as_ref() {
                            assert_eq!(existing, &child.agent_id);
                        } else {
                            child_id = Some(child.agent_id);
                        }
                    }
                }
                ChatEvent::TypingStatusChanged(false) if saw_parent_typing => {
                    assert!(
                        background,
                        "foreground native spawn became idle while its child was still running; trace:\n{}",
                        trace.join("\n")
                    );
                    parent_idle = true;
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("native spawn setup failed: {content}"),
                _ => {}
            }
            if request_id.is_some()
                && progress_id.is_some()
                && child_id.is_some()
                && projected_child.is_some()
                && (!background || parent_idle)
            {
                break;
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "native spawn did not reach correlated Running; trace:\n{}",
            trace.join("\n")
        )
    });
    assert_eq!(
        request_id, progress_id,
        "spawn progress was not correlated to its request"
    );
    assert_eq!(
        projected_child, child_id,
        "spawned child was not projected exactly once"
    );
    NativeSpawnWait {
        parent_stream,
        parent_id: parent.agent_id,
        parent_session_id: parent.session_id.expect("native spawn parent session"),
        child_id: child_id.unwrap(),
        tool_call_id: request_id.unwrap(),
        release,
        completion_marker,
        ambient_ids,
    }
}

async fn expect_native_spawn_terminal(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    tool_call_id: &str,
    child_id: &protocol::AgentId,
    expected_success: bool,
) -> protocol::ToolExecutionCompletedData {
    let mut terminal_progress = 0usize;
    let mut terminal_status = None;
    let mut completions = 0usize;
    let mut trace = Vec::new();
    let completion = tokio::time::timeout(Duration::from_secs(180), async {
        let mut observed_completion = None;
        while terminal_progress != 1 || completions != 1 {
            let envelope = fixture.client.next_event().await.unwrap().unwrap();
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            let event = envelope.parse_payload::<ChatEvent>().unwrap();
            trace.push(format!("{event:?}"));
            match event {
                ChatEvent::ToolProgress(progress) if progress.tool_call_id == tool_call_id => {
                    let protocol::ToolProgressUpdate::SubAgent(child) = progress.update else {
                        panic!("native spawn emitted the wrong progress family")
                    };
                    if child.completed {
                        assert_eq!(&child.agent_id, child_id);
                        terminal_progress += 1;
                        assert_eq!(terminal_progress, 1);
                        terminal_status = Some(child.status);
                    }
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    completions += 1;
                    assert_eq!(completions, 1);
                    assert_eq!(
                        completion.success(), expected_success,
                        "wrong spawn terminal: {completion:?}"
                    );
                    observed_completion = Some(completion);
                }
                ChatEvent::ToolRequest(request) => panic!(
                    "native spawn issued another tool request while its child was pending: {request:?}"
                ),
                _ => {}
            }
        }
        let completion = observed_completion.expect("native spawn completion");
        let expected_status = if completion.success() {
            protocol::SubAgentProgressStatus::Completed
        } else if matches!(&completion.outcome, ToolExecutionOutcome::Cancelled { .. }) {
            protocol::SubAgentProgressStatus::Stopped
        } else {
            protocol::SubAgentProgressStatus::Failed
        };
        assert_eq!(terminal_status, Some(expected_status));
        completion
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "native spawn did not emit one correlated progress and completion terminal; trace:\n{}",
            trace.join("\n")
        )
    });
    assert_progress_terminal_is_stable(
        fixture,
        stream,
        tool_call_id,
        ProgressFamily::SubAgent,
        "native subagent terminal stability",
    )
    .await;
    completion
}

async fn expect_replayed_native_spawn_request(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    tool_call_id: &str,
) {
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(
                &mut fixture.client,
                "replayed native spawn request after reconnect",
            )
            .await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolRequest(ToolRequest {
                    tool_call_id: replayed_id,
                    tool_type: ToolRequestType::AgentSpawn { .. },
                    ..
                }) => {
                    assert_eq!(replayed_id, tool_call_id);
                    break;
                }
                ChatEvent::ToolRequest(request) => {
                    panic!("reconnect replayed an unrelated tool request: {request:?}")
                }
                _ => {}
            }
        }
    })
    .await
    .expect("reconnect did not replay the pending native spawn request");
}

fn native_spawn_contract_cells(
    tool: SpecialToolContract,
    capabilities: &tyde_agent_adapter::BackendCapabilities,
) -> Vec<ConformanceCoverageCell> {
    let input = if tool == SpecialToolContract::AgentSpawn {
        ToolInputVariant::AgentSpawn
    } else {
        ToolInputVariant::BackgroundSubagent
    };
    let activities: HashSet<_> = conformance_activity_conditions(capabilities)
        .into_iter()
        .collect();
    let stimulus_filter = std::env::var("TYDE_CONFORMANCE_STIMULUS").ok();
    ConformanceCoverageCell::required_for(capabilities)
        .into_iter()
        .filter(|cell| cell.tool == tool && cell.input == input)
        .filter(|cell| activities.contains(&cell.activity))
        .filter(|cell| {
            stimulus_filter
                .as_ref()
                .is_none_or(|filter| format!("{:?}", cell.stimulus).eq_ignore_ascii_case(filter))
        })
        .collect()
}

async fn assert_native_spawn_contract_cell(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    cell: ConformanceCoverageCell,
) -> ConformanceCoverageCell {
    eprintln!("NATIVE SPAWN CONTRACT CELL {cell:?}");
    let wait =
        reach_native_spawn_wait(fixture, backend_kind, cell.tool, cell.result, cell.activity).await;
    eprintln!("NATIVE SPAWN REACHED RUNNING {cell:?}");
    let stimulus = cell.stimulus;
    ambient_before_stimulus(
        fixture,
        &wait.parent_stream,
        &wait.ambient_ids,
        cell.activity,
        stimulus,
        "native spawn ambient work before stimulus",
    )
    .await;
    let mut lifecycle_stream = wait.parent_stream.clone();
    let mut parent_closed = false;
    match stimulus {
        ContractStimulus::ProviderAccepts => {
            assert_eq!(cell.result, ToolResultVariant::Pending);
            ambient_during_stimulus(
                fixture,
                &wait.parent_stream,
                &wait.ambient_ids,
                cell.activity,
                stimulus,
                "native spawn ambient work during provider acceptance",
            )
            .await;
            std::fs::write(&wait.release, b"release").unwrap();
            expect_native_spawn_terminal(
                fixture,
                &wait.parent_stream,
                &wait.tool_call_id,
                &wait.child_id,
                true,
            )
            .await;
        }
        ContractStimulus::ChildCompletes => {
            assert_eq!(cell.result, ToolResultVariant::Succeeds);
            std::fs::write(&wait.release, b"release").unwrap();
            ambient_during_stimulus(
                fixture,
                &wait.parent_stream,
                &wait.ambient_ids,
                cell.activity,
                stimulus,
                "native spawn ambient work during child completion",
            )
            .await;
            expect_native_spawn_terminal(
                fixture,
                &wait.parent_stream,
                &wait.tool_call_id,
                &wait.child_id,
                true,
            )
            .await;
        }
        ContractStimulus::ChildFails => {
            assert_eq!(cell.result, ToolResultVariant::Fails);
            std::fs::write(&wait.release, b"release").unwrap();
            ambient_during_stimulus(
                fixture,
                &wait.parent_stream,
                &wait.ambient_ids,
                cell.activity,
                stimulus,
                "native spawn ambient work during child failure",
            )
            .await;
            expect_native_spawn_terminal(
                fixture,
                &wait.parent_stream,
                &wait.tool_call_id,
                &wait.child_id,
                false,
            )
            .await;
        }
        ContractStimulus::Interrupt => {
            fixture.client.interrupt(&wait.parent_stream).await.unwrap();
            eprintln!("NATIVE SPAWN INTERRUPT ACKNOWLEDGED {cell:?}");
            ambient_during_stimulus(
                fixture,
                &wait.parent_stream,
                &wait.ambient_ids,
                cell.activity,
                stimulus,
                "native spawn ambient work during interrupt",
            )
            .await;
            if cell.tool == SpecialToolContract::AgentSpawn {
                let completion = expect_native_spawn_terminal(
                    fixture,
                    &wait.parent_stream,
                    &wait.tool_call_id,
                    &wait.child_id,
                    false,
                )
                .await;
                assert!(
                    matches!(&completion.outcome, ToolExecutionOutcome::Cancelled { .. }),
                    "foreground spawn interrupt was not normalized as Cancelled: {completion:?}"
                );
            } else {
                let follow_up = "Do not use tools. Reply exactly BACKGROUND_CHILD_INTERRUPT_OK.";
                fixture
                    .client
                    .send_message(&wait.parent_stream, follow_up.to_owned())
                    .await
                    .unwrap();
                std::fs::write(&wait.release, b"release").unwrap();
                eprintln!("NATIVE SPAWN CHILD RELEASED {cell:?}");
                let response = expect_assistant_turn_after_user_echo(
                    &mut fixture.client,
                    &wait.parent_stream,
                    follow_up,
                )
                .await;
                eprintln!("NATIVE SPAWN FOLLOW-UP COMPLETED {cell:?}");
                assert!(
                    response
                        .final_text
                        .contains("BACKGROUND_CHILD_INTERRUPT_OK")
                );
                expect_native_spawn_terminal(
                    fixture,
                    &wait.parent_stream,
                    &wait.tool_call_id,
                    &wait.child_id,
                    true,
                )
                .await;
                eprintln!("NATIVE SPAWN CHILD TERMINAL {cell:?}");
            }
        }
        ContractStimulus::Close => {
            fixture
                .client
                .close_agent(&wait.parent_stream)
                .await
                .expect("close native spawn parent");
            ambient_during_stimulus(
                fixture,
                &wait.parent_stream,
                &wait.ambient_ids,
                cell.activity,
                stimulus,
                "native spawn ambient work during close",
            )
            .await;
            tokio::time::timeout(Duration::from_secs(120), async {
                loop {
                    let envelope =
                        expect_next_event(&mut fixture.client, "closed native spawn parent").await;
                    if envelope.kind != FrameKind::AgentClosed {
                        continue;
                    }
                    let closed: protocol::AgentClosedPayload = envelope.parse_payload().unwrap();
                    if closed.agent_id == wait.parent_id {
                        break;
                    }
                }
            })
            .await
            .expect("native spawn parent did not reach AgentClosed");
            parent_closed = true;
            assert_progress_terminal_is_stable(
                fixture,
                &wait.parent_stream,
                &wait.tool_call_id,
                ProgressFamily::SubAgent,
                "closed native subagent progress stability",
            )
            .await;
        }
        ContractStimulus::DisconnectReconnect => {
            let mut replacement = fixture.connect().await;
            replacement.inherit_live_trace_from(&fixture.client);
            std::mem::swap(&mut fixture.client, &mut replacement);
            drop(replacement);
            lifecycle_stream = loop {
                let envelope =
                    expect_next_event(&mut fixture.client, "native spawn reconnect bootstrap")
                        .await;
                if envelope.kind != FrameKind::HostBootstrap {
                    continue;
                }
                let bootstrap: HostBootstrapPayload = envelope.parse_payload().unwrap();
                break bootstrap
                    .agents
                    .into_iter()
                    .find(|agent| agent.agent_id == wait.parent_id)
                    .expect("reconnect omitted native spawn parent")
                    .instance_stream;
            };
            expect_replayed_native_spawn_request(fixture, &lifecycle_stream, &wait.tool_call_id)
                .await;
            ambient_during_stimulus(
                fixture,
                &lifecycle_stream,
                &wait.ambient_ids,
                cell.activity,
                stimulus,
                "native spawn ambient work during reconnect",
            )
            .await;
            std::fs::write(&wait.release, b"release").unwrap();
            expect_native_spawn_terminal(
                fixture,
                &lifecycle_stream,
                &wait.tool_call_id,
                &wait.child_id,
                true,
            )
            .await;
        }
        ContractStimulus::Fork => {
            let fork_stream = fork_agent_via_protocol(
                &mut fixture.client,
                "fork-pending-native-spawn",
                wait.parent_id.clone(),
                wait.parent_session_id.clone(),
                "Do not use tools. Reply exactly NATIVE_SPAWN_FORK_OK.",
            )
            .await;
            ambient_during_stimulus(
                fixture,
                &wait.parent_stream,
                &wait.ambient_ids,
                cell.activity,
                stimulus,
                "native spawn ambient work during fork",
            )
            .await;
            let response = expect_assistant_turn_after_user_echo(
                &mut fixture.client,
                &fork_stream,
                "Do not use tools. Reply exactly NATIVE_SPAWN_FORK_OK.",
            )
            .await;
            assert!(response.final_text.contains("NATIVE_SPAWN_FORK_OK"));
            std::fs::write(&wait.release, b"release").unwrap();
            expect_native_spawn_terminal(
                fixture,
                &wait.parent_stream,
                &wait.tool_call_id,
                &wait.child_id,
                cell.result != ToolResultVariant::Fails,
            )
            .await;
            fixture.client.close_agent(&fork_stream).await.unwrap();
        }
        ContractStimulus::HostRestartResume => {
            eprintln!("NATIVE SPAWN HOST SHUTDOWN START {cell:?}");
            fixture.host.shutdown_agents_for_conformance().await;
            eprintln!("NATIVE SPAWN HOST SHUTDOWN DONE {cell:?}");
            ambient_during_stimulus(
                fixture,
                &wait.parent_stream,
                &wait.ambient_ids,
                cell.activity,
                stimulus,
                "native spawn ambient work during host restart",
            )
            .await;
            expect_native_spawn_terminal(
                fixture,
                &wait.parent_stream,
                &wait.tool_call_id,
                &wait.child_id,
                false,
            )
            .await;
            fixture.restart_host().await;
            lifecycle_stream = resume_agent_via_protocol(
                &mut fixture.client,
                "resume-after-native-spawn",
                wait.parent_session_id.clone(),
                "Do not use tools. Reply exactly NATIVE_SPAWN_RESTART_OK.",
            )
            .await;
            let response = expect_assistant_turn_after_user_echo(
                &mut fixture.client,
                &lifecycle_stream,
                "Do not use tools. Reply exactly NATIVE_SPAWN_RESTART_OK.",
            )
            .await;
            assert!(response.final_text.contains("NATIVE_SPAWN_RESTART_OK"));
        }
        ContractStimulus::TransportClosed => {
            assert!(
                fixture
                    .host
                    .force_agent_backend_shutdown_for_conformance(&wait.parent_id)
                    .await
            );
            ambient_during_stimulus(
                fixture,
                &wait.parent_stream,
                &wait.ambient_ids,
                cell.activity,
                stimulus,
                "native spawn ambient work during transport close",
            )
            .await;
            expect_native_spawn_terminal(
                fixture,
                &wait.parent_stream,
                &wait.tool_call_id,
                &wait.child_id,
                false,
            )
            .await;
            std::fs::write(&wait.release, b"release").unwrap();
        }
        ContractStimulus::TimeoutExpires => {
            ambient_during_stimulus(
                fixture,
                &wait.parent_stream,
                &wait.ambient_ids,
                cell.activity,
                stimulus,
                "background subagent work during timeout",
            )
            .await;
            let premature_terminal = tokio::time::timeout(Duration::from_secs(5), async {
                loop {
                    let envelope =
                        expect_next_event(&mut fixture.client, "native spawn timeout observation")
                            .await;
                    if envelope.kind != FrameKind::ChatEvent
                        || envelope.stream != wait.parent_stream
                    {
                        continue;
                    }
                    match envelope.parse_payload::<ChatEvent>().unwrap() {
                        ChatEvent::ToolExecutionCompleted(completion)
                            if completion.tool_call_id == wait.tool_call_id =>
                        {
                            return format!("premature tool completion: {completion:?}");
                        }
                        ChatEvent::ToolProgress(progress)
                            if progress.tool_call_id == wait.tool_call_id
                                && matches!(
                                    progress.update,
                                    protocol::ToolProgressUpdate::SubAgent(
                                        protocol::SubAgentProgress {
                                            completed: true,
                                            ..
                                        }
                                    )
                                ) =>
                        {
                            return format!("premature terminal progress: {progress:?}");
                        }
                        ChatEvent::TypingStatusChanged(false)
                            if cell.tool == SpecialToolContract::AgentSpawn =>
                        {
                            return "foreground parent became idle while child remained active"
                                .to_owned();
                        }
                        _ => {}
                    }
                }
            })
            .await;
            assert!(
                premature_terminal.is_err(),
                "native spawn did not remain running through timeout: {}",
                premature_terminal.unwrap()
            );
            std::fs::write(&wait.release, b"release").unwrap();
            expect_native_spawn_terminal(
                fixture,
                &wait.parent_stream,
                &wait.tool_call_id,
                &wait.child_id,
                true,
            )
            .await;
        }
        other => panic!("unimplemented required native-spawn stimulus {other:?}"),
    }
    if matches!(
        stimulus,
        ContractStimulus::Close
            | ContractStimulus::HostRestartResume
            | ContractStimulus::TransportClosed
    ) {
        if !wait.release.exists() {
            std::fs::write(&wait.release, b"release").unwrap();
        }
        tokio::time::sleep(Duration::from_secs(1)).await;
        assert!(
            !wait.completion_marker.exists(),
            "native child continued executing after its owner boundary: {stimulus:?}"
        );
    } else {
        assert!(
            wait.completion_marker.exists(),
            "native child terminalized before executing its commanded work: {stimulus:?}"
        );
    }
    ambient_after_stimulus(
        fixture,
        &lifecycle_stream,
        &wait.ambient_ids,
        cell.activity,
        stimulus,
        "native spawn ambient work after stimulus",
    )
    .await;
    if !parent_closed && stimulus != ContractStimulus::HostRestartResume {
        close_agent_at_definitive_boundary(
            fixture,
            &lifecycle_stream,
            &wait.parent_id,
            "close completed native spawn contract",
        )
        .await;
    }
    cell
}

async fn assert_native_spawn_contract_matrix(
    backend_kind: BackendKind,
    tool: SpecialToolContract,
) -> Vec<ConformanceCoverageCell> {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let cells = native_spawn_contract_cells(tool, &capabilities);
    let mut witnessed = Vec::with_capacity(cells.len());
    for cell in cells {
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        witnessed.push(assert_native_spawn_contract_cell(&mut fixture, backend_kind, cell).await);
    }
    witnessed
}

struct ForegroundCommandContractRun {
    stream: StreamPath,
    agent_id: protocol::AgentId,
    session_id: SessionId,
    tool_call_id: String,
    release_path: PathBuf,
    marker: String,
    ambient_ids: HashSet<String>,
}

fn shell_single_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\"'\"'"))
}

fn foreground_command_prompt(
    backend_kind: BackendKind,
    command: &str,
    working_directory: &Path,
) -> String {
    let working_directory = working_directory.to_string_lossy();
    let fallback_command = format!("cd {} && {command}", shell_single_quote(&working_directory));
    match backend_kind {
        BackendKind::Claude => format!(
            "Use Bash exactly once to run `{fallback_command}` in the foreground. Do not set run_in_background, do not use another tool, and wait for the result."
        ),
        BackendKind::Codex => format!(
            "Use exec_command exactly once to run `{command}` with workdir `{working_directory}`, yield_time_ms=30000, and no tty. Do not use write_stdin or another tool, and wait for the result."
        ),
        BackendKind::Hermes => format!(
            "Use terminal exactly once with background=false and cwd `{working_directory}` to run `{command}`. Do not use another tool, and wait for the result."
        ),
        _ => format!(
            "Use the command tool exactly once in foreground/attached mode to run `{command}` from working directory `{working_directory}`. If the tool has no working-directory argument, run `{fallback_command}` instead. Do not use another tool, and wait for the result."
        ),
    }
}

fn assert_run_command_working_directory_shape(
    workspace_root: &Path,
    expected: &Path,
    command: &str,
    working_directory: &str,
) {
    if working_directory.is_empty() {
        assert!(
            command.contains(expected.to_string_lossy().as_ref()),
            "RunCommand omitted working_directory without carrying the requested directory in its command: {command:?}"
        );
        return;
    }
    let actual = PathBuf::from(working_directory);
    let actual = if actual.is_absolute() {
        actual
    } else {
        workspace_root.join(actual)
    };
    let actual = actual.canonicalize().unwrap_or(actual);
    let expected = expected
        .canonicalize()
        .unwrap_or_else(|_| expected.to_path_buf());
    assert_eq!(
        actual, expected,
        "RunCommand normalized the requested working directory incorrectly"
    );
}

async fn reach_pending_foreground_command(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
    stimulus: ContractStimulus,
    fails: bool,
) -> ForegroundCommandContractRun {
    let roots = fixture.workspace_roots();
    let ready_prompt = match backend_kind {
        BackendKind::Claude => "Do not use tools. Reply exactly FOREGROUND_COMMAND_PARENT_READY.",
        _ => "Reply exactly FOREGROUND_COMMAND_PARENT_READY.",
    };
    let (stream, start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "foreground-command-contract",
        ready_prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let ready =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, ready_prompt).await;
    assert!(ready.final_text.contains("FOREGROUND_COMMAND_PARENT_READY"));
    let ambient_ids =
        start_agent_control_ambient_work(fixture, backend_kind, &stream, activity).await;
    if stimulus == ContractStimulus::ProviderAccepts {
        ambient_before_stimulus(
            fixture,
            &stream,
            &ambient_ids,
            activity,
            stimulus,
            "foreground-command ambient work before acceptance",
        )
        .await;
    }

    let marker = format!("FOREGROUND_COMMAND_{}", Uuid::new_v4().simple());
    let release_path = fixture
        .workspace_dir
        .path()
        .join(format!("{marker}_RELEASE"));
    let command_working_directory = fixture.workspace_dir.path().join(format!(
        "foreground command cwd {}",
        Uuid::new_v4().simple()
    ));
    std::fs::create_dir(&command_working_directory)
        .expect("create foreground command working directory");
    let terminal = if fails {
        format!("printf {marker}_FAILED >&2; exit 37")
    } else {
        format!("printf {marker}_SUCCEEDED")
    };
    let command = format!(
        "while [ ! -f {} ]; do sleep 0.1; done; {terminal}",
        release_path.display()
    );
    let prompt = foreground_command_prompt(backend_kind, &command, &command_working_directory);
    fixture.client.send_message(&stream, prompt).await.unwrap();

    let mut request_id = None;
    let mut trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "pending foreground command").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            let event = envelope.parse_payload::<ChatEvent>().unwrap();
            trace.push(event.clone());
            match event {
                ChatEvent::ToolRequest(request) => {
                    let ToolRequestType::RunCommand {
                        command,
                        working_directory,
                    } = request.tool_type
                    else {
                        continue;
                    };
                    assert_run_command_request_shape(&command, &working_directory);
                    if !command.contains(&marker) {
                        continue;
                    }
                    assert_run_command_working_directory_shape(
                        fixture.workspace_dir.path(),
                        &command_working_directory,
                        &command,
                        &working_directory,
                    );
                    assert!(
                        request_id.replace(request.tool_call_id).is_none(),
                        "foreground command requested more than once: {trace:#?}"
                    );
                    break;
                }
                ChatEvent::ToolProgress(progress)
                    if request_id.as_deref() == Some(progress.tool_call_id.as_str()) =>
                {
                    assert!(
                        progress.execution_mode != protocol::ToolExecutionMode::Background,
                        "foreground command was reclassified as background work: {progress:?}"
                    );
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if request_id.as_deref() == Some(completion.tool_call_id.as_str()) =>
                {
                    panic!("foreground command terminalized before its boundary: {completion:?}")
                }
                ChatEvent::TypingStatusChanged(false) => {
                    panic!("foreground command became idle while its command remained pending")
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => {
                    panic!("foreground-command setup failed: {content}")
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("backend did not request the foreground command; trace={trace:#?}"));

    ForegroundCommandContractRun {
        stream,
        agent_id: start.agent_id,
        session_id: start.session_id.expect("foreground-command session id"),
        tool_call_id: request_id.unwrap(),
        release_path,
        marker,
        ambient_ids,
    }
}

async fn assert_foreground_command_remains_pending(
    fixture: &mut RealBackendFixture,
    run: &ForegroundCommandContractRun,
    context: &str,
) {
    let mut collector = BufferedEventCollector::new(&mut fixture.client);
    let deadline = Instant::now() + Duration::from_secs(5);
    while Instant::now() < deadline {
        let remaining = deadline.saturating_duration_since(Instant::now());
        let Ok(envelope) = tokio::time::timeout(
            remaining.min(Duration::from_millis(50)),
            collector.next(context),
        )
        .await
        else {
            continue;
        };
        if envelope.kind != FrameKind::ChatEvent || envelope.stream != run.stream {
            collector.defer(envelope);
            continue;
        }
        match envelope.parse_payload::<ChatEvent>().unwrap() {
            ChatEvent::ToolRequest(request) => {
                if let ToolRequestType::RunCommand { command, .. } = request.tool_type
                    && command.contains(&run.marker)
                {
                    panic!("{context}: foreground command was requested more than once")
                }
                collector.defer(envelope);
            }
            ChatEvent::ToolProgress(progress) if progress.tool_call_id == run.tool_call_id => {
                assert!(
                    progress.execution_mode != protocol::ToolExecutionMode::Background,
                    "{context}: foreground command became background work: {progress:?}"
                );
            }
            ChatEvent::ToolExecutionCompleted(completion)
                if completion.tool_call_id == run.tool_call_id =>
            {
                panic!("{context}: foreground command completed while blocked: {completion:?}")
            }
            ChatEvent::TypingStatusChanged(false) => {
                panic!("{context}: foreground turn became idle while command remained pending")
            }
            _ => collector.defer(envelope),
        }
    }
    collector.restore();
}

async fn expect_one_foreground_command_terminal(
    fixture: &mut RealBackendFixture,
    run: &ForegroundCommandContractRun,
    expected_exit: i32,
    context: &str,
) {
    let completion = tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, context).await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != run.stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolRequest(request) => {
                    if let ToolRequestType::RunCommand { command, .. } = request.tool_type
                        && command.contains(&run.marker)
                    {
                        panic!("{context}: foreground command was requested more than once")
                    }
                }
                ChatEvent::ToolProgress(progress) if progress.tool_call_id == run.tool_call_id => {
                    assert!(
                        progress.execution_mode != protocol::ToolExecutionMode::Background,
                        "{context}: foreground command emitted background progress: {progress:?}"
                    );
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == run.tool_call_id =>
                {
                    break completion;
                }
                ChatEvent::TypingStatusChanged(false) => {
                    panic!("{context}: foreground command became idle before its terminal")
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context}: correlated foreground-command terminal did not arrive"));
    assert_eq!(
        completion.success(),
        expected_exit == 0,
        "{context}: wrong success bit"
    );
    let ToolExecutionResult::RunCommand {
        exit_code,
        stdout,
        stderr,
    } = &completion.tool_result()
    else {
        panic!("{context}: foreground command returned wrong normalized result: {completion:?}")
    };
    assert_eq!(*exit_code, expected_exit, "{context}: wrong exit code");
    let output = format!("{stdout}{stderr}");
    assert!(
        output.contains(&run.marker),
        "{context}: command output lost its marker: {completion:?}"
    );

    let mut completions = 1usize;
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, context).await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != run.stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolRequest(request) => {
                    if let ToolRequestType::RunCommand { command, .. } = request.tool_type
                        && command.contains(&run.marker)
                    {
                        panic!("{context}: foreground command was requested again after completion")
                    }
                }
                ChatEvent::ToolExecutionCompleted(other)
                    if other.tool_call_id == run.tool_call_id =>
                {
                    completions += 1;
                    panic!("{context}: foreground command terminalized more than once: {other:?}")
                }
                ChatEvent::TypingStatusChanged(false) => break,
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) if expected_exit == 0 => {
                    panic!("{context}: successful command produced backend error: {content}")
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context}: foreground turn never reached idle"));
    assert_eq!(completions, 1);
}

async fn expect_one_foreground_command_boundary_terminal(
    fixture: &mut RealBackendFixture,
    run: &ForegroundCommandContractRun,
    context: &str,
) -> ToolExecutionCompletedData {
    let completion = tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, context).await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != run.stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolRequest(request) => {
                    if let ToolRequestType::RunCommand { command, .. } = request.tool_type
                        && command.contains(&run.marker)
                    {
                        panic!("{context}: foreground command was requested more than once")
                    }
                }
                ChatEvent::ToolProgress(progress) if progress.tool_call_id == run.tool_call_id => {
                    assert!(
                        progress.execution_mode != protocol::ToolExecutionMode::Background,
                        "{context}: foreground command became background work: {progress:?}"
                    );
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == run.tool_call_id =>
                {
                    break completion;
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context}: correlated boundary terminal did not arrive"));
    assert_visible_generic_other_failure(&completion, context);

    let mut collector = BufferedEventCollector::new(&mut fixture.client);
    let deadline = Instant::now() + Duration::from_millis(300);
    while Instant::now() < deadline {
        let remaining = deadline.saturating_duration_since(Instant::now());
        let Ok(envelope) = tokio::time::timeout(remaining, collector.next(context)).await else {
            break;
        };
        if envelope.kind == FrameKind::ChatEvent
            && envelope.stream == run.stream
            && let ChatEvent::ToolExecutionCompleted(duplicate) =
                envelope.parse_payload::<ChatEvent>().unwrap()
            && duplicate.tool_call_id == run.tool_call_id
        {
            panic!("{context}: foreground command terminalized more than once: {duplicate:?}")
        }
        collector.defer(envelope);
    }
    collector.restore();
    completion
}

async fn assert_foreground_command_contract_cell(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
    result: ToolResultVariant,
    from: ContractState,
    stimulus: ContractStimulus,
    outcome: ContractOutcome,
) -> ConformanceCoverageCell {
    eprintln!(
        "FOREGROUND COMMAND CONTRACT CELL result={result:?} activity={activity:?} from={from:?} stimulus={stimulus:?} outcome={outcome:?}"
    );
    let run = reach_pending_foreground_command(
        fixture,
        backend_kind,
        activity,
        stimulus,
        result == ToolResultVariant::Fails,
    )
    .await;
    let mut lifecycle_stream = run.stream.clone();
    if stimulus != ContractStimulus::ProviderAccepts {
        ambient_before_stimulus(
            fixture,
            &run.stream,
            &run.ambient_ids,
            activity,
            stimulus,
            "foreground-command ambient work before lifecycle boundary",
        )
        .await;
    }

    match stimulus {
        ContractStimulus::ProviderAccepts => {
            assert_foreground_command_remains_pending(
                fixture,
                &run,
                "foreground command acceptance",
            )
            .await;
            fixture.client.interrupt(&run.stream).await.unwrap();
            expect_exact_cancelled_tool_request(
                fixture,
                &run.stream,
                &run.tool_call_id,
                "foreground command acceptance cleanup",
            )
            .await;
        }
        ContractStimulus::ToolCompletes | ContractStimulus::ToolFails => {
            std::fs::write(&run.release_path, b"release").unwrap();
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "foreground-command ambient work during completion",
            )
            .await;
            expect_one_foreground_command_terminal(
                fixture,
                &run,
                if stimulus == ContractStimulus::ToolCompletes {
                    0
                } else {
                    37
                },
                "foreground command completion",
            )
            .await;
        }
        ContractStimulus::Interrupt => {
            fixture.client.interrupt(&run.stream).await.unwrap();
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "foreground-command ambient work during interrupt",
            )
            .await;
            expect_exact_cancelled_tool_request(
                fixture,
                &run.stream,
                &run.tool_call_id,
                "foreground command interrupt",
            )
            .await;
        }
        ContractStimulus::Close => {
            fixture.client.close_agent(&run.stream).await.unwrap();
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "foreground-command ambient work during close",
            )
            .await;
            let completion = expect_one_foreground_command_boundary_terminal(
                fixture,
                &run,
                "foreground command close",
            )
            .await;
            assert!(
                !completion.success(),
                "close reported pending foreground command success"
            );
            tokio::time::timeout(Duration::from_secs(120), async {
                loop {
                    let envelope =
                        expect_next_event(&mut fixture.client, "foreground command AgentClosed")
                            .await;
                    if envelope.kind == FrameKind::AgentClosed {
                        let closed: protocol::AgentClosedPayload =
                            envelope.parse_payload().unwrap();
                        if closed.agent_id == run.agent_id {
                            break;
                        }
                    }
                    if envelope.kind == FrameKind::ChatEvent
                        && envelope.stream == run.stream
                        && let ChatEvent::ToolExecutionCompleted(duplicate) =
                            envelope.parse_payload::<ChatEvent>().unwrap()
                        && duplicate.tool_call_id == run.tool_call_id
                    {
                        panic!("close duplicated foreground command terminal: {duplicate:?}")
                    }
                }
            })
            .await
            .expect("foreground command did not close definitively");
        }
        ContractStimulus::DisconnectReconnect => {
            let mut replacement = fixture.connect().await;
            replacement.inherit_live_trace_from(&fixture.client);
            std::mem::swap(&mut fixture.client, &mut replacement);
            drop(replacement);
            lifecycle_stream = loop {
                let envelope =
                    expect_next_event(&mut fixture.client, "foreground command reconnect").await;
                if envelope.kind != FrameKind::HostBootstrap {
                    continue;
                }
                let bootstrap: HostBootstrapPayload = envelope.parse_payload().unwrap();
                break bootstrap
                    .agents
                    .into_iter()
                    .find(|agent| agent.agent_id == run.agent_id)
                    .expect("reconnect omitted pending foreground-command agent")
                    .instance_stream;
            };
            let replay = tokio::time::timeout(Duration::from_secs(30), async {
                loop {
                    let envelope =
                        expect_next_event(&mut fixture.client, "foreground command replay").await;
                    if envelope.kind == FrameKind::AgentBootstrap
                        && envelope.stream == lifecycle_stream
                    {
                        break envelope.parse_payload::<AgentBootstrapPayload>().unwrap();
                    }
                }
            })
            .await
            .expect("reconnect omitted foreground-command bootstrap");
            let requests = replay
                .events
                .iter()
                .filter_map(|event| match event {
                    AgentBootstrapEvent::ChatEvent(ChatEvent::ToolRequest(request))
                        if request.tool_call_id == run.tool_call_id =>
                    {
                        Some(request)
                    }
                    _ => None,
                })
                .collect::<Vec<_>>();
            assert_eq!(
                requests.len(),
                1,
                "reconnect lost or duplicated pending foreground command"
            );
            assert!(
                matches!(&requests[0].tool_type, ToolRequestType::RunCommand { command, .. } if command.contains(&run.marker))
            );
            assert!(
                replay.turn_active,
                "reconnect replayed pending foreground command as idle"
            );
            assert!(
                !replay.events.iter().any(|event| matches!(event,
                    AgentBootstrapEvent::ChatEvent(ChatEvent::ToolExecutionCompleted(completion))
                        if completion.tool_call_id == run.tool_call_id
                )),
                "reconnect invented a terminal for the pending foreground command"
            );
            ambient_during_stimulus(
                fixture,
                &lifecycle_stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "foreground-command ambient work during reconnect",
            )
            .await;
            assert_foreground_command_remains_pending(
                fixture,
                &ForegroundCommandContractRun {
                    stream: lifecycle_stream.clone(),
                    agent_id: run.agent_id.clone(),
                    session_id: run.session_id.clone(),
                    tool_call_id: run.tool_call_id.clone(),
                    release_path: run.release_path.clone(),
                    marker: run.marker.clone(),
                    ambient_ids: run.ambient_ids.clone(),
                },
                "foreground command after reconnect",
            )
            .await;
            std::fs::write(&run.release_path, b"release").unwrap();
            let replay_run = ForegroundCommandContractRun {
                stream: lifecycle_stream.clone(),
                agent_id: run.agent_id.clone(),
                session_id: run.session_id.clone(),
                tool_call_id: run.tool_call_id.clone(),
                release_path: run.release_path.clone(),
                marker: run.marker.clone(),
                ambient_ids: run.ambient_ids.clone(),
            };
            expect_one_foreground_command_terminal(
                fixture,
                &replay_run,
                0,
                "foreground command after reconnect",
            )
            .await;
        }
        ContractStimulus::Fork => {
            let fork_prompt = "Do not use tools. Reply exactly FOREGROUND_COMMAND_FORK_OK.";
            let fork_stream = fork_agent_via_protocol(
                &mut fixture.client,
                "fork-pending-foreground-command",
                run.agent_id.clone(),
                run.session_id.clone(),
                fork_prompt,
            )
            .await;
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "foreground-command ambient work during fork",
            )
            .await;
            let response = expect_assistant_turn_after_user_echo(
                &mut fixture.client,
                &fork_stream,
                fork_prompt,
            )
            .await;
            assert!(response.final_text.contains("FOREGROUND_COMMAND_FORK_OK"));
            assert_foreground_command_remains_pending(
                fixture,
                &run,
                "source foreground command after fork",
            )
            .await;
            fixture.client.interrupt(&run.stream).await.unwrap();
            expect_exact_cancelled_tool_request(
                fixture,
                &run.stream,
                &run.tool_call_id,
                "source foreground command cleanup after fork",
            )
            .await;
            fixture.client.close_agent(&fork_stream).await.ok();
        }
        ContractStimulus::HostRestartResume => {
            fixture.host.shutdown_agents_for_conformance().await;
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "foreground-command ambient work during host restart",
            )
            .await;
            let completion = expect_one_foreground_command_boundary_terminal(
                fixture,
                &run,
                "foreground command host restart",
            )
            .await;
            assert!(
                !completion.success(),
                "host restart reported pending foreground command success"
            );
            fixture.restart_host().await;
            let follow_up = "Do not use tools. Reply exactly FOREGROUND_COMMAND_RESTART_OK.";
            lifecycle_stream = resume_agent_via_protocol(
                &mut fixture.client,
                "resume-foreground-command-contract",
                run.session_id.clone(),
                follow_up,
            )
            .await;
            let response = expect_assistant_turn_after_user_echo(
                &mut fixture.client,
                &lifecycle_stream,
                follow_up,
            )
            .await;
            assert!(
                response
                    .final_text
                    .contains("FOREGROUND_COMMAND_RESTART_OK")
            );
        }
        ContractStimulus::TransportClosed => {
            assert!(
                fixture
                    .host
                    .force_agent_backend_shutdown_for_conformance(&run.agent_id)
                    .await
            );
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "foreground-command ambient work during transport close",
            )
            .await;
            let completion = expect_one_foreground_command_boundary_terminal(
                fixture,
                &run,
                "foreground command transport close",
            )
            .await;
            assert!(
                !completion.success(),
                "transport close reported pending foreground command success"
            );
        }
        ContractStimulus::TimeoutExpires => {
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "foreground-command ambient work during timeout",
            )
            .await;
            assert_foreground_command_remains_pending(fixture, &run, "foreground command timeout")
                .await;
            std::fs::write(&run.release_path, b"release").unwrap();
            expect_one_foreground_command_terminal(
                fixture,
                &run,
                0,
                "foreground command after timeout",
            )
            .await;
        }
        other => panic!("invalid foreground-command contract stimulus {other:?}"),
    }

    if stimulus != ContractStimulus::Close {
        ambient_after_stimulus(
            fixture,
            &lifecycle_stream,
            &run.ambient_ids,
            activity,
            stimulus,
            "foreground-command ambient work after lifecycle boundary",
        )
        .await;
        fixture.client.close_agent(&lifecycle_stream).await.ok();
    }
    observed_cell(
        SpecialToolContract::ForegroundCommand,
        ToolInputVariant::ForegroundCommand,
        result,
        activity,
        from,
        stimulus,
        outcome,
    )
}

async fn assert_foreground_command_contract_matrix(
    backend_kind: BackendKind,
) -> Vec<ConformanceCoverageCell> {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let cells = ConformanceCoverageCell::required_for(&capabilities)
        .into_iter()
        .filter(|cell| cell.tool == SpecialToolContract::ForegroundCommand)
        .collect::<Vec<_>>();
    let mut witnessed = Vec::with_capacity(cells.len());
    for cell in cells {
        if std::env::var("TYDE_CONFORMANCE_STIMULUS")
            .ok()
            .is_some_and(|filter| !format!("{:?}", cell.stimulus).eq_ignore_ascii_case(&filter))
        {
            continue;
        }
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        witnessed.push(
            assert_foreground_command_contract_cell(
                &mut fixture,
                backend_kind,
                cell.activity,
                cell.result,
                cell.from,
                cell.stimulus,
                cell.outcome,
            )
            .await,
        );
    }
    witnessed
}

struct BackgroundCommandContractRun {
    stream: StreamPath,
    agent_id: protocol::AgentId,
    session_id: SessionId,
    tool_call_id: String,
    release_path: PathBuf,
    ambient_ids: HashSet<String>,
}

async fn reach_running_background_command(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
    stimulus: ContractStimulus,
    focal_fails: bool,
) -> BackgroundCommandContractRun {
    let roots = fixture.workspace_roots();
    let ready_prompt = match backend_kind {
        BackendKind::Claude => {
            "Before we begin a software engineering task, confirm you are ready. Do not use tools yet. Reply with exactly the single line BACKGROUND_CONTRACT_PARENT_READY and nothing else."
        }
        _ => "Reply exactly BACKGROUND_CONTRACT_PARENT_READY.",
    };
    let (stream, start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "background-command-contract",
        ready_prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let ready =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, ready_prompt).await;
    assert!(
        ready
            .final_text
            .contains("BACKGROUND_CONTRACT_PARENT_READY")
    );

    let ambient_ids =
        start_agent_control_ambient_work(fixture, backend_kind, &stream, activity).await;
    if stimulus == ContractStimulus::ProviderAccepts {
        ambient_before_stimulus(
            fixture,
            &stream,
            &ambient_ids,
            activity,
            stimulus,
            "background-command ambient work before acceptance",
        )
        .await;
    }

    let release_name = format!("BACKGROUND_FOCAL_RELEASE_{}", Uuid::new_v4().simple());
    let release_path = fixture.workspace_dir.path().join(&release_name);
    let terminal = if focal_fails {
        "printf BACKGROUND_FOCAL_FAILED >&2; exit 37"
    } else {
        "printf BACKGROUND_FOCAL_DONE"
    };
    let command = format!(
        "while [ ! -f {} ]; do sleep 0.1; done; {terminal}",
        release_path.display()
    );
    let prompt = match backend_kind {
        BackendKind::Claude => format!(
            "Use Bash exactly once with run_in_background=true to run `{command}`. Do not poll, wait for, or stop it. After it reports Running, reply exactly BACKGROUND_FOCAL_RUNNING."
        ),
        BackendKind::Codex => format!(
            "Use command execution exactly once to run `{command}`, setting the tool's `yield_time_ms` argument to `1000` so it remains a background session. Do not poll, wait for, or stop it. After it reports Running, reply exactly BACKGROUND_FOCAL_RUNNING."
        ),
        BackendKind::Hermes => format!(
            "Use terminal exactly once with background=true to run `{command}`. Do not poll, wait for, or stop it. After it reports Running, reply exactly BACKGROUND_FOCAL_RUNNING."
        ),
        _ => format!(
            "Use the command tool exactly once to start `{command}` as background work. Do not poll, wait for, or stop it. After it reports Running, reply exactly BACKGROUND_FOCAL_RUNNING."
        ),
    };
    fixture
        .client
        .send_message(&stream, prompt)
        .await
        .expect("send focal background-command prompt");

    let mut request_id = None;
    let mut running_id = None;
    let mut setup_trace = Vec::new();
    let mut deferred = Vec::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = fixture
                .client
                .next_event()
                .await
                .expect("read focal background command")
                .expect("focal background-command stream closed");
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            let event = envelope
                .parse_payload::<ChatEvent>()
                .expect("parse focal background-command event");
            setup_trace.push(event.clone());
            let mut focal_event = false;
            match event {
                ChatEvent::ToolRequest(request) => {
                    let ToolRequestType::RunCommand {
                        command,
                        working_directory,
                    } = request.tool_type else {
                        deferred.push(envelope);
                        continue;
                    };
                    assert_run_command_request_shape(&command, &working_directory);
                    if !command.contains(&release_name) {
                        deferred.push(envelope);
                        continue;
                    }
                    focal_event = true;
                    assert!(request_id.replace(request.tool_call_id).is_none());
                    if background_terminal_during_stimulus(activity)
                        && stimulus == ContractStimulus::ProviderAccepts
                    {
                        release_question_background_work(fixture, ambient_ids.len());
                    }
                }
                ChatEvent::ToolProgress(progress) => {
                    if background_task_progress(&progress.update).is_some()
                        && request_id.as_deref() == Some(progress.tool_call_id.as_str())
                    {
                        focal_event = true;
                        assert!(running_id.replace(progress.tool_call_id).is_none());
                    }
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if request_id.as_deref() == Some(completion.tool_call_id.as_str()) =>
                {
                    panic!("focal background command terminalized before its boundary")
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("focal background-command setup failed: {content}"),
                _ => {}
            }
            if !focal_event {
                deferred.push(envelope);
            }
            if let (Some(request_id), Some(running_id)) = (&request_id, &running_id) {
                assert_eq!(request_id, running_id);
                break;
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "backend did not expose the focal command as running background work; trace={setup_trace:#?}"
        )
    });
    fixture.client.restore_events(deferred);

    if stimulus == ContractStimulus::ProviderAccepts
        && background_terminal_during_stimulus(activity)
    {
        wait_for_background_terminal_lifecycle(
            fixture,
            &stream,
            &ambient_ids,
            expected_background_outcome(activity).unwrap(),
            "background-command ambient work during acceptance",
        )
        .await;
    }

    BackgroundCommandContractRun {
        stream,
        agent_id: start.agent_id,
        session_id: start.session_id.expect("background-command session id"),
        tool_call_id: request_id.expect("focal background-command request id"),
        release_path,
        ambient_ids,
    }
}

async fn assert_background_command_contract_cell(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
    result: ToolResultVariant,
    from: ContractState,
    stimulus: ContractStimulus,
    outcome: ContractOutcome,
) -> ConformanceCoverageCell {
    eprintln!(
        "BACKGROUND COMMAND CONTRACT CELL result={result:?} activity={activity:?} from={from:?} stimulus={stimulus:?} outcome={outcome:?}"
    );
    let focal_fails = result == ToolResultVariant::Fails;
    let run =
        reach_running_background_command(fixture, backend_kind, activity, stimulus, focal_fails)
            .await;
    let focal_ids = HashSet::from([run.tool_call_id.clone()]);
    let mut lifecycle_stream = run.stream.clone();

    if stimulus == ContractStimulus::ProviderAccepts {
        ambient_after_stimulus(
            fixture,
            &run.stream,
            &run.ambient_ids,
            activity,
            stimulus,
            "background-command ambient work after acceptance",
        )
        .await;
    } else {
        ambient_before_stimulus(
            fixture,
            &run.stream,
            &run.ambient_ids,
            activity,
            stimulus,
            "background-command ambient work before lifecycle boundary",
        )
        .await;
    }

    match stimulus {
        ContractStimulus::ProviderAccepts => {}
        ContractStimulus::ToolCompletes | ContractStimulus::ToolFails => {
            std::fs::write(&run.release_path, b"release")
                .expect("release focal background command");
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "background-command ambient work during completion",
            )
            .await;
            let expected = if stimulus == ContractStimulus::ToolCompletes {
                ExpectedBackgroundOutcome::Succeeded
            } else {
                ExpectedBackgroundOutcome::Failed
            };
            wait_for_background_terminal_lifecycle(
                fixture,
                &run.stream,
                &focal_ids,
                expected,
                "focal background-command completion",
            )
            .await;
        }
        ContractStimulus::Interrupt => {
            fixture
                .client
                .interrupt(&run.stream)
                .await
                .expect("interrupt while focal background command runs");
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "background-command ambient work during interrupt",
            )
            .await;
            assert_background_remains_running(
                fixture,
                &run.stream,
                &focal_ids,
                "conversation interrupt stopped focal background work",
            )
            .await;
            let follow_up = "Reply exactly BACKGROUND_INTERRUPT_FOLLOW_UP_OK.";
            fixture
                .client
                .send_message(&run.stream, follow_up.to_owned())
                .await
                .expect("send follow-up over running background command");
            std::fs::write(&run.release_path, b"release")
                .expect("release focal command after interrupt boundary");
            let response =
                expect_assistant_turn_after_user_echo(&mut fixture.client, &run.stream, follow_up)
                    .await;
            assert!(
                response
                    .final_text
                    .contains("BACKGROUND_INTERRUPT_FOLLOW_UP_OK")
            );
            wait_for_background_terminal_lifecycle(
                fixture,
                &run.stream,
                &focal_ids,
                ExpectedBackgroundOutcome::Succeeded,
                "focal background command after interrupt",
            )
            .await;
        }
        ContractStimulus::Close => {
            fixture
                .client
                .close_agent(&run.stream)
                .await
                .expect("close agent with running background command");
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "background-command ambient work during close",
            )
            .await;
            wait_for_background_terminal_lifecycle(
                fixture,
                &run.stream,
                &focal_ids,
                ExpectedBackgroundOutcome::Cancelled,
                "focal background command at close",
            )
            .await;
            tokio::time::timeout(Duration::from_secs(120), async {
                loop {
                    let envelope =
                        expect_next_event(&mut fixture.client, "closed background-command agent")
                            .await;
                    if envelope.kind == FrameKind::AgentClosed {
                        let closed: protocol::AgentClosedPayload = envelope
                            .parse_payload()
                            .expect("parse closed background-command agent");
                        if closed.agent_id == run.agent_id {
                            break;
                        }
                    }
                }
            })
            .await
            .expect("background-command agent did not close");
        }
        ContractStimulus::DisconnectReconnect => {
            let mut replacement = fixture.connect().await;
            replacement.inherit_live_trace_from(&fixture.client);
            std::mem::swap(&mut fixture.client, &mut replacement);
            drop(replacement);
            lifecycle_stream = loop {
                let envelope =
                    expect_next_event(&mut fixture.client, "background reconnect bootstrap").await;
                if envelope.kind != FrameKind::HostBootstrap {
                    continue;
                }
                let bootstrap: HostBootstrapPayload = envelope
                    .parse_payload()
                    .expect("parse background reconnect bootstrap");
                break bootstrap
                    .agents
                    .into_iter()
                    .find(|agent| agent.agent_id == run.agent_id)
                    .expect("reconnect omitted background-command agent")
                    .instance_stream;
            };
            ambient_during_stimulus(
                fixture,
                &lifecycle_stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "background-command ambient work during reconnect",
            )
            .await;
            assert_background_remains_running(
                fixture,
                &lifecycle_stream,
                &focal_ids,
                "focal background command did not survive reconnect",
            )
            .await;
            std::fs::write(&run.release_path, b"release")
                .expect("release focal command after reconnect boundary");
            wait_for_background_terminal_lifecycle(
                fixture,
                &lifecycle_stream,
                &focal_ids,
                ExpectedBackgroundOutcome::Succeeded,
                "focal background command after reconnect",
            )
            .await;
        }
        ContractStimulus::Fork => {
            let fork_prompt = "Do not use tools. Reply exactly BACKGROUND_FORK_OK.";
            let fork_stream = fork_agent_via_protocol(
                &mut fixture.client,
                "fork-running-background-command",
                run.agent_id.clone(),
                run.session_id.clone(),
                fork_prompt,
            )
            .await;
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "background-command ambient work during fork",
            )
            .await;
            let response = expect_assistant_turn_after_user_echo(
                &mut fixture.client,
                &fork_stream,
                fork_prompt,
            )
            .await;
            assert!(response.final_text.contains("BACKGROUND_FORK_OK"));
            assert_background_remains_running(
                fixture,
                &run.stream,
                &focal_ids,
                "fork damaged source background command",
            )
            .await;
            std::fs::write(&run.release_path, b"release")
                .expect("release source background command after fork");
            wait_for_background_terminal_lifecycle(
                fixture,
                &run.stream,
                &focal_ids,
                ExpectedBackgroundOutcome::Succeeded,
                "source background command after fork",
            )
            .await;
            fixture.client.close_agent(&fork_stream).await.unwrap();
        }
        ContractStimulus::HostRestartResume => {
            fixture.host.shutdown_agents_for_conformance().await;
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "background-command ambient work during host restart",
            )
            .await;
            wait_for_background_terminal_lifecycle(
                fixture,
                &run.stream,
                &focal_ids,
                ExpectedBackgroundOutcome::Cancelled,
                "focal background command at host restart",
            )
            .await;
            fixture.restart_host().await;
            lifecycle_stream = resume_agent_via_protocol(
                &mut fixture.client,
                "resume-background-command-contract",
                run.session_id.clone(),
                "Do not use tools. Reply exactly BACKGROUND_HOST_RESTART_OK.",
            )
            .await;
            let response = expect_assistant_turn_after_user_echo(
                &mut fixture.client,
                &lifecycle_stream,
                "Do not use tools. Reply exactly BACKGROUND_HOST_RESTART_OK.",
            )
            .await;
            assert!(response.final_text.contains("BACKGROUND_HOST_RESTART_OK"));
        }
        ContractStimulus::TransportClosed => {
            assert!(
                fixture
                    .host
                    .force_agent_backend_shutdown_for_conformance(&run.agent_id)
                    .await
            );
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "background-command ambient work during transport close",
            )
            .await;
            wait_for_background_terminal_lifecycle(
                fixture,
                &run.stream,
                &focal_ids,
                ExpectedBackgroundOutcome::Failed,
                "focal background command at transport close",
            )
            .await;
        }
        ContractStimulus::TimeoutExpires => {
            ambient_during_stimulus(
                fixture,
                &run.stream,
                &run.ambient_ids,
                activity,
                stimulus,
                "background-command ambient work during timeout",
            )
            .await;
            assert_background_remains_running(
                fixture,
                &run.stream,
                &focal_ids,
                "focal background command advanced without a boundary",
            )
            .await;
            std::fs::write(&run.release_path, b"release")
                .expect("release focal command after timeout boundary");
            wait_for_background_terminal_lifecycle(
                fixture,
                &run.stream,
                &focal_ids,
                ExpectedBackgroundOutcome::Succeeded,
                "focal background command after timeout",
            )
            .await;
        }
        _ => panic!("invalid background-command contract stimulus {stimulus:?}"),
    }

    if !matches!(
        stimulus,
        ContractStimulus::ProviderAccepts | ContractStimulus::Close
    ) {
        ambient_after_stimulus(
            fixture,
            &lifecycle_stream,
            &run.ambient_ids,
            activity,
            stimulus,
            "background-command ambient work after lifecycle boundary",
        )
        .await;
    }
    if stimulus != ContractStimulus::Close {
        fixture.client.close_agent(&lifecycle_stream).await.ok();
    }

    observed_cell(
        SpecialToolContract::BackgroundCommand,
        ToolInputVariant::BackgroundCommand,
        result,
        activity,
        from,
        stimulus,
        outcome,
    )
}

async fn assert_background_command_contract_matrix(
    backend_kind: BackendKind,
) -> Vec<ConformanceCoverageCell> {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let activities: HashSet<_> = conformance_activity_conditions(&capabilities)
        .into_iter()
        .collect();
    let cells = ConformanceCoverageCell::required_for(&capabilities)
        .into_iter()
        .filter(|cell| cell.tool == SpecialToolContract::BackgroundCommand)
        .filter(|cell| activities.contains(&cell.activity))
        .collect::<Vec<_>>();
    let mut witnessed = Vec::new();
    for cell in cells {
        if std::env::var("TYDE_CONFORMANCE_STIMULUS")
            .ok()
            .is_some_and(|filter| !format!("{:?}", cell.stimulus).eq_ignore_ascii_case(&filter))
        {
            continue;
        }
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        witnessed.push(
            assert_background_command_contract_cell(
                &mut fixture,
                backend_kind,
                cell.activity,
                cell.result,
                cell.from,
                cell.stimulus,
                cell.outcome,
            )
            .await,
        );
    }
    witnessed
}

async fn expect_correlated_tool_completion(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    tool_call_id: &str,
    context: &str,
) -> ToolExecutionCompletedData {
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, context).await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .unwrap_or_else(|error| panic!("{context}: parse failed: {error:?}"))
            {
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    return completion;
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{context}: backend error: {content}"),
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context}: correlated tool completion did not arrive"))
}

async fn reach_pending_agent_message(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
    stimulus: ContractStimulus,
) -> (AgentControlPair, String, HashSet<String>) {
    let pair = spawn_agent_control_pair(fixture, backend_kind).await;
    let ambient_ids =
        start_agent_control_ambient_work(fixture, backend_kind, &pair.parent_stream, activity)
            .await;
    if stimulus == ContractStimulus::ProviderAccepts {
        ambient_before_stimulus(
            fixture,
            &pair.parent_stream,
            &ambient_ids,
            activity,
            stimulus,
            "agent-message ambient work before acceptance",
        )
        .await;
    }

    fixture
        .host
        .hold_agent_message_delivery_for_conformance(true)
        .await;
    let prompt = agent_control_tool_prompt(backend_kind, "send", &pair.child_id);
    fixture
        .client
        .send_message(&pair.parent_stream, prompt)
        .await
        .expect("send pending agent-message prompt");

    let mut request_id = None;
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, "pending agent-message").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != pair.parent_stream {
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .expect("parse pending agent-message event")
            {
                ChatEvent::ToolRequest(request) => {
                    let ToolRequestType::TydeSendAgentMessage { agent_id, message } =
                        request.tool_type
                    else {
                        continue;
                    };
                    assert_eq!(agent_id, pair.child_id);
                    assert_eq!(message, "AGENT_CONTROL_MESSAGE_731");
                    assert!(request_id.replace(request.tool_call_id).is_none());
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if request_id.as_deref() == Some(completion.tool_call_id.as_str()) =>
                {
                    panic!("agent-message completed before its execution boundary was applied")
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("agent-message request failed: {content}"),
                _ => {}
            }
            if request_id.is_some()
                && fixture
                    .host
                    .active_agent_message_delivery_count_for_conformance()
                    .await
                    == 1
            {
                break;
            }
        }
    })
    .await
    .expect("real agent-message request never reached the held MCP execution boundary");

    (
        pair,
        request_id.expect("normalized agent-message request id"),
        ambient_ids,
    )
}

async fn finish_successful_agent_message_delivery(
    fixture: &mut RealBackendFixture,
    parent_stream: &StreamPath,
    child_stream: &StreamPath,
    child_release: &Path,
    tool_call_id: &str,
    context: &str,
) {
    fixture
        .host
        .hold_agent_message_delivery_for_conformance(false)
        .await;
    let completion =
        expect_correlated_tool_completion(fixture, parent_stream, tool_call_id, context).await;
    assert!(
        completion.success(),
        "agent-message was rejected: {completion:?}"
    );
    assert!(matches!(
        completion.tool_result(),
        ToolExecutionResult::TydeSendAgentMessage
    ));
    std::fs::write(child_release, b"release").expect("release successfully messaged child");
    let mut echo_count = 0usize;
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, context).await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *child_stream {
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .expect("parse agent-message child event")
            {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == "AGENT_CONTROL_MESSAGE_731" => echo_count += 1,
                ChatEvent::TypingStatusChanged(false) if echo_count > 0 => break,
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("messaged child failed: {content}"),
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("{context}: successful message was not delivered to the child"));
    assert_eq!(echo_count, 1, "agent-message was not consumed exactly once");
}

async fn expect_fork_turn_without_agent_message_request(
    client: &mut ValidatedConnection,
    fork_stream: &StreamPath,
    prompt: &str,
) {
    let mut got_user_echo = false;
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(client, "agent-message fork response").await;
            if envelope.kind == FrameKind::AgentError && envelope.stream == *fork_stream {
                let error: protocol::AgentErrorPayload = envelope
                    .parse_payload()
                    .expect("parse agent-message fork error");
                panic!("agent-message fork failed: {}", error.message);
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *fork_stream {
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .expect("parse agent-message fork event")
            {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == prompt => got_user_echo = true,
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("agent-message fork returned an error: {content}"),
                ChatEvent::ToolRequest(ToolRequest {
                    tool_type: ToolRequestType::TydeSendAgentMessage { .. },
                    ..
                }) => panic!("fork copied the source's pending agent-message request"),
                ChatEvent::StreamEnd(end)
                    if got_user_echo && end.message.content.contains("AGENT_MESSAGE_FORK_OK") =>
                {
                    break;
                }
                ChatEvent::TypingStatusChanged(false) if got_user_echo => {
                    panic!("agent-message fork became idle without completing its follow-up")
                }
                _ => {}
            }
        }
    })
    .await
    .expect("agent-message fork follow-up did not complete");
}

async fn assert_agent_message_contract_cell(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
    result: ToolResultVariant,
    stimulus: ContractStimulus,
    outcome: ContractOutcome,
) -> ConformanceCoverageCell {
    let (pair, tool_call_id, ambient_ids) =
        reach_pending_agent_message(fixture, backend_kind, activity, stimulus).await;
    let mut lifecycle_stream = pair.parent_stream.clone();

    if stimulus != ContractStimulus::ProviderAccepts {
        ambient_before_stimulus(
            fixture,
            &pair.parent_stream,
            &ambient_ids,
            activity,
            stimulus,
            "agent-message ambient work before lifecycle boundary",
        )
        .await;
    }

    match stimulus {
        ContractStimulus::ProviderAccepts => {
            ambient_during_stimulus(
                fixture,
                &pair.parent_stream,
                &ambient_ids,
                activity,
                stimulus,
                "agent-message ambient work during acceptance",
            )
            .await;
            finish_successful_agent_message_delivery(
                fixture,
                &pair.parent_stream,
                &pair.child_stream,
                &pair.child_release,
                &tool_call_id,
                "successful agent-message",
            )
            .await;
        }
        ContractStimulus::ChildFails => {
            assert!(
                fixture
                    .host
                    .force_agent_backend_shutdown_for_conformance(&pair.child_id)
                    .await
            );
            ambient_during_stimulus(
                fixture,
                &pair.parent_stream,
                &ambient_ids,
                activity,
                stimulus,
                "agent-message ambient work during child failure",
            )
            .await;
            fixture
                .host
                .hold_agent_message_delivery_for_conformance(false)
                .await;
            let completion = expect_correlated_tool_completion(
                fixture,
                &pair.parent_stream,
                &tool_call_id,
                "failed agent-message",
            )
            .await;
            assert!(!completion.success(), "message to failed child succeeded");
        }
        ContractStimulus::Interrupt => {
            fixture
                .client
                .interrupt(&pair.parent_stream)
                .await
                .expect("interrupt pending agent-message");
            ambient_during_stimulus(
                fixture,
                &pair.parent_stream,
                &ambient_ids,
                activity,
                stimulus,
                "agent-message ambient work during interrupt",
            )
            .await;
            let completion = expect_correlated_tool_completion(
                fixture,
                &pair.parent_stream,
                &tool_call_id,
                "interrupted agent-message",
            )
            .await;
            assert!(!completion.success());
            assert!(
                matches!(&completion.outcome, ToolExecutionOutcome::Cancelled { .. }),
                "interrupted agent-message returned the wrong terminal result: {completion:?}"
            );
            fixture
                .host
                .hold_agent_message_delivery_for_conformance(false)
                .await;
        }
        ContractStimulus::Close => {
            fixture
                .client
                .close_agent(&pair.parent_stream)
                .await
                .expect("close pending agent-message parent");
            ambient_during_stimulus(
                fixture,
                &pair.parent_stream,
                &ambient_ids,
                activity,
                stimulus,
                "agent-message ambient work during close",
            )
            .await;
            tokio::time::timeout(Duration::from_secs(120), async {
                loop {
                    let envelope =
                        expect_next_event(&mut fixture.client, "closed agent-message parent").await;
                    if envelope.kind == FrameKind::AgentClosed {
                        let closed: protocol::AgentClosedPayload = envelope
                            .parse_payload()
                            .expect("parse closed agent-message parent");
                        if closed.agent_id == pair.parent_id {
                            break;
                        }
                    }
                }
            })
            .await
            .expect("pending agent-message parent did not close");
            fixture
                .host
                .hold_agent_message_delivery_for_conformance(false)
                .await;
        }
        ContractStimulus::DisconnectReconnect => {
            let mut replacement = fixture.connect().await;
            replacement.inherit_live_trace_from(&fixture.client);
            std::mem::swap(&mut fixture.client, &mut replacement);
            drop(replacement);
            let (reconnected_parent_stream, reconnected_child_stream) = loop {
                let envelope =
                    expect_next_event(&mut fixture.client, "agent-message reconnect bootstrap")
                        .await;
                if envelope.kind != FrameKind::HostBootstrap {
                    continue;
                }
                let bootstrap: HostBootstrapPayload = envelope
                    .parse_payload()
                    .expect("parse agent-message reconnect bootstrap");
                let parent_stream = bootstrap
                    .agents
                    .iter()
                    .find(|agent| agent.agent_id == pair.parent_id)
                    .expect("reconnect omitted agent-message parent")
                    .instance_stream
                    .clone();
                let child_stream = bootstrap
                    .agents
                    .iter()
                    .find(|agent| agent.agent_id == pair.child_id)
                    .expect("reconnect omitted agent-message child")
                    .instance_stream
                    .clone();
                break (parent_stream, child_stream);
            };
            lifecycle_stream = reconnected_parent_stream;
            tokio::time::timeout(Duration::from_secs(120), async {
                loop {
                    let envelope =
                        expect_next_event(&mut fixture.client, "replayed pending agent-message")
                            .await;
                    if envelope.kind != FrameKind::ChatEvent
                        || envelope.stream != lifecycle_stream
                    {
                        continue;
                    }
                    match envelope
                        .parse_payload::<ChatEvent>()
                        .expect("parse replayed pending agent-message")
                    {
                        ChatEvent::ToolRequest(request) if request.tool_call_id == tool_call_id => {
                            let ToolRequestType::TydeSendAgentMessage { agent_id, message } =
                                request.tool_type
                            else {
                                panic!("reconnected agent-message changed normalized tool type")
                            };
                            assert_eq!(agent_id, pair.child_id);
                            assert_eq!(message, "AGENT_CONTROL_MESSAGE_731");
                            break;
                        }
                        ChatEvent::ToolExecutionCompleted(completion)
                            if completion.tool_call_id == tool_call_id =>
                        {
                            panic!(
                                "agent-message completed while its delivery remained held: {completion:?}"
                            )
                        }
                        ChatEvent::MessageAdded(ChatMessage {
                            sender: MessageSender::Error,
                            content,
                            ..
                        }) => panic!("reconnected agent-message failed: {content}"),
                        _ => {}
                    }
                }
            })
            .await
            .expect("reconnect did not replay the pending agent-message request");
            assert_eq!(
                fixture
                    .host
                    .active_agent_message_delivery_count_for_conformance()
                    .await,
                1,
                "reconnect did not preserve the active agent-message delivery"
            );
            ambient_during_stimulus(
                fixture,
                &lifecycle_stream,
                &ambient_ids,
                activity,
                stimulus,
                "agent-message ambient work during reconnect",
            )
            .await;
            finish_successful_agent_message_delivery(
                fixture,
                &lifecycle_stream,
                &reconnected_child_stream,
                &pair.child_release,
                &tool_call_id,
                "agent-message after reconnect",
            )
            .await;
        }
        ContractStimulus::HostRestartResume => {
            fixture.host.shutdown_agents_for_conformance().await;
            ambient_during_stimulus(
                fixture,
                &pair.parent_stream,
                &ambient_ids,
                activity,
                stimulus,
                "agent-message ambient work during host restart",
            )
            .await;
            let completion = expect_correlated_tool_completion(
                fixture,
                &pair.parent_stream,
                &tool_call_id,
                "agent-message at host restart",
            )
            .await;
            assert!(
                !completion.success(),
                "host restart did not visibly fail the pending agent-message"
            );
            fixture
                .host
                .hold_agent_message_delivery_for_conformance(false)
                .await;
            fixture.restart_host().await;
            let follow_up = "Do not use tools. Reply exactly AGENT_MESSAGE_HOST_RESTART_OK.";
            lifecycle_stream = resume_agent_via_protocol(
                &mut fixture.client,
                "resume-after-pending-agent-message",
                pair.parent_session_id.clone(),
                follow_up,
            )
            .await;
            let response = expect_assistant_turn_after_user_echo(
                &mut fixture.client,
                &lifecycle_stream,
                follow_up,
            )
            .await;
            assert!(
                response
                    .final_text
                    .contains("AGENT_MESSAGE_HOST_RESTART_OK")
            );
        }
        ContractStimulus::Fork => {
            let follow_up = "Do not use tools. Reply exactly AGENT_MESSAGE_FORK_OK.";
            let fork_stream = fork_agent_via_protocol(
                &mut fixture.client,
                "fork-pending-agent-message",
                pair.parent_id.clone(),
                pair.parent_session_id.clone(),
                follow_up,
            )
            .await;
            ambient_during_stimulus(
                fixture,
                &pair.parent_stream,
                &ambient_ids,
                activity,
                stimulus,
                "agent-message ambient work during fork",
            )
            .await;
            expect_fork_turn_without_agent_message_request(
                &mut fixture.client,
                &fork_stream,
                follow_up,
            )
            .await;
            assert_eq!(
                fixture
                    .host
                    .active_agent_message_delivery_count_for_conformance()
                    .await,
                1,
                "fork damaged the source's pending agent-message delivery"
            );
            finish_successful_agent_message_delivery(
                fixture,
                &pair.parent_stream,
                &pair.child_stream,
                &pair.child_release,
                &tool_call_id,
                "source agent-message after fork",
            )
            .await;
            fixture.client.close_agent(&fork_stream).await.ok();
        }
        ContractStimulus::TransportClosed => {
            assert!(
                fixture
                    .host
                    .force_agent_backend_shutdown_for_conformance(&pair.parent_id)
                    .await
            );
            ambient_during_stimulus(
                fixture,
                &pair.parent_stream,
                &ambient_ids,
                activity,
                stimulus,
                "agent-message ambient work during transport close",
            )
            .await;
            let completion = expect_correlated_tool_completion(
                fixture,
                &pair.parent_stream,
                &tool_call_id,
                "transport-closed agent-message",
            )
            .await;
            assert!(!completion.success());
            fixture
                .host
                .hold_agent_message_delivery_for_conformance(false)
                .await;
        }
        ContractStimulus::TimeoutExpires => {
            ambient_during_stimulus(
                fixture,
                &pair.parent_stream,
                &ambient_ids,
                activity,
                stimulus,
                "agent-message ambient work during timeout",
            )
            .await;
            let mut collector = BufferedEventCollector::new(&mut fixture.client);
            let deadline = Instant::now() + Duration::from_secs(5);
            while Instant::now() < deadline {
                assert_eq!(
                    fixture
                        .host
                        .active_agent_message_delivery_count_for_conformance()
                        .await,
                    1,
                    "agent-message request stopped being active during timeout observation"
                );
                let remaining = deadline.saturating_duration_since(Instant::now());
                let observation = tokio::time::timeout(
                    remaining.min(Duration::from_millis(50)),
                    collector.next("pending agent-message timeout observation"),
                )
                .await;
                let Ok(envelope) = observation else {
                    continue;
                };
                if envelope.kind == FrameKind::AgentError && envelope.stream == pair.parent_stream {
                    let error: protocol::AgentErrorPayload = envelope
                        .parse_payload()
                        .expect("parse timed agent-message error");
                    panic!(
                        "pending agent-message failed during timeout: {}",
                        error.message
                    );
                }
                if envelope.kind != FrameKind::ChatEvent || envelope.stream != pair.parent_stream {
                    collector.defer(envelope);
                    continue;
                }
                match envelope
                    .parse_payload::<ChatEvent>()
                    .expect("parse pending agent-message timeout event")
                {
                    ChatEvent::ToolExecutionCompleted(completion)
                        if completion.tool_call_id == tool_call_id =>
                    {
                        panic!("agent-message completed during timeout: {completion:?}")
                    }
                    ChatEvent::TypingStatusChanged(false) => {
                        panic!(
                            "agent-message parent became idle while its request remained pending"
                        )
                    }
                    ChatEvent::MessageAdded(ChatMessage {
                        sender: MessageSender::Error,
                        content,
                        ..
                    }) => panic!("pending agent-message failed during timeout: {content}"),
                    _ => collector.defer(envelope),
                }
            }
            collector.restore();
            assert_eq!(
                fixture
                    .host
                    .active_agent_message_delivery_count_for_conformance()
                    .await,
                1,
                "agent-message request did not remain active through timeout"
            );
            finish_successful_agent_message_delivery(
                fixture,
                &pair.parent_stream,
                &pair.child_stream,
                &pair.child_release,
                &tool_call_id,
                "agent-message after timeout",
            )
            .await;
        }
        _ => panic!("invalid agent-message contract stimulus {stimulus:?}"),
    }

    tokio::time::timeout(Duration::from_secs(5), async {
        while fixture
            .host
            .active_agent_message_delivery_count_for_conformance()
            .await
            != 0
        {
            tokio::time::sleep(Duration::from_millis(25)).await;
        }
    })
    .await
    .expect("agent-message MCP execution leaked after its lifecycle boundary");

    if stimulus != ContractStimulus::Close {
        ambient_after_stimulus(
            fixture,
            &lifecycle_stream,
            &ambient_ids,
            activity,
            stimulus,
            "agent-message ambient work after stimulus",
        )
        .await;
        fixture.client.close_agent(&lifecycle_stream).await.ok();
    }
    std::fs::write(&pair.child_release, b"release").ok();

    observed_cell(
        SpecialToolContract::SendAgentMessage,
        ToolInputVariant::SendAgentMessage,
        result,
        activity,
        ContractState::Requested,
        stimulus,
        outcome,
    )
}

async fn assert_agent_message_contract_matrix(
    backend_kind: BackendKind,
) -> Vec<ConformanceCoverageCell> {
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let cells = ConformanceCoverageCell::required_for(&capabilities)
        .into_iter()
        .filter(|cell| cell.tool == SpecialToolContract::SendAgentMessage)
        .collect::<Vec<_>>();
    let mut witnessed = Vec::new();
    for cell in cells {
        if std::env::var("TYDE_CONFORMANCE_STIMULUS")
            .ok()
            .is_some_and(|filter| !format!("{:?}", cell.stimulus).eq_ignore_ascii_case(&filter))
        {
            continue;
        }
        let mut fixture = RealBackendFixture::new(backend_kind).await;
        witnessed.push(
            assert_agent_message_contract_cell(
                &mut fixture,
                backend_kind,
                cell.activity,
                cell.result,
                cell.stimulus,
                cell.outcome,
            )
            .await,
        );
    }
    witnessed
}

async fn reach_agent_await(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    activity: ActivityCondition,
    stimulus: ContractStimulus,
) -> (AgentControlPair, String, HashSet<String>) {
    let pair = spawn_agent_control_pair(fixture, backend_kind).await;
    let ambient_ids =
        start_agent_control_ambient_work(fixture, backend_kind, &pair.parent_stream, activity)
            .await;
    if stimulus == ContractStimulus::ProviderAccepts
        && background_terminal_before_stimulus(activity)
    {
        release_and_wait_for_background_terminal(
            fixture,
            &pair.parent_stream,
            &ambient_ids,
            activity,
            ContractStimulus::ProviderAccepts,
            "ambient work before await acceptance",
        )
        .await;
    }
    let prompt = agent_control_tool_prompt(backend_kind, "await", &pair.child_id);
    fixture
        .client
        .send_message(&pair.parent_stream, prompt)
        .await
        .expect("send agent-await prompt");
    let workspace_path = fixture.workspace_dir.path().to_path_buf();
    let mut trace = Vec::new();
    let mut collector = BufferedEventCollector::new(&mut fixture.client);
    let tool_call_id = tokio::time::timeout(Duration::from_secs(120), async {
        let mut request_id = None;
        let mut progress_id = None;
        loop {
            let envelope = collector.next("agent-await request").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != pair.parent_stream {
                collector.defer(envelope);
                continue;
            }
            let event = envelope
                .parse_payload::<ChatEvent>()
                .expect("parse agent-await event");
            trace.push(format!("{event:?}"));
            match event {
                ChatEvent::ToolRequest(request) => {
                    let agent_ids = match request.tool_type {
                        ToolRequestType::TydeAwaitAgents { agent_ids } => agent_ids,
                        other => {
                            panic!("agent-await issued an unexpected extra tool request: {other:?}")
                        }
                    };
                    assert_eq!(agent_ids, vec![pair.child_id.clone()]);
                    assert!(request_id.replace(request.tool_call_id).is_none());
                    if stimulus == ContractStimulus::ProviderAccepts
                        && background_terminal_during_stimulus(activity)
                    {
                        for index in 1..=ambient_ids.len() {
                            std::fs::write(
                                workspace_path.join(format!("QUESTION_RELEASE_{index}")),
                                "release",
                            )
                            .expect("release await background work");
                        }
                    }
                }
                ChatEvent::ToolProgress(progress) => {
                    if ambient_ids.contains(&progress.tool_call_id) {
                        collector.defer(envelope);
                        continue;
                    }
                    let protocol::ToolProgressUpdate::AgentControl(agent_progress) =
                        progress.update
                    else {
                        panic!("agent-await emitted the wrong progress family")
                    };
                    assert_eq!(
                        agent_progress.progress_kind,
                        protocol::AgentControlProgressKind::Await
                    );
                    assert_eq!(agent_progress.agents.len(), 1);
                    assert_eq!(agent_progress.agents[0].agent_id, pair.child_id);
                    assert_eq!(
                        agent_progress.status,
                        protocol::AgentControlProgressStatus::Running
                    );
                    assert!(progress_id.replace(progress.tool_call_id).is_none());
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("agent-await setup failed: {content}"),
                _ => collector.defer(envelope),
            }
            if let (Some(request_id), Some(progress_id)) = (&request_id, &progress_id) {
                assert_eq!(
                    request_id, progress_id,
                    "agent-await progress used another tool id"
                );
                break request_id.clone();
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "backend did not emit a normalized agent-await request; trace:\n{}",
            trace.join("\n")
        )
    });
    collector.restore();
    tokio::time::timeout(Duration::from_secs(5), async {
        while fixture
            .host
            .active_agent_control_await_request_count()
            .await
            == 0
        {
            tokio::time::sleep(Duration::from_millis(25)).await;
        }
    })
    .await
    .expect("real agent-control await request never became active");
    if stimulus == ContractStimulus::ProviderAccepts
        && background_terminal_during_stimulus(activity)
    {
        wait_for_background_terminal_lifecycle(
            fixture,
            &pair.parent_stream,
            &ambient_ids,
            expected_background_outcome(activity).unwrap(),
            "ambient work during await acceptance",
        )
        .await;
    }
    if stimulus == ContractStimulus::ProviderAccepts {
        ambient_after_stimulus(
            fixture,
            &pair.parent_stream,
            &ambient_ids,
            activity,
            ContractStimulus::ProviderAccepts,
            "ambient work after await acceptance",
        )
        .await;
    }
    (pair, tool_call_id, ambient_ids)
}

async fn start_multi_agent_await_request(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    parent_stream: &StreamPath,
    child_ids: &[protocol::AgentId],
    expect_pending: bool,
) -> String {
    let prompt = agent_control_tool_prompt_for_ids(backend_kind, "await", child_ids);
    fixture
        .client
        .send_message(parent_stream, prompt)
        .await
        .expect("send multi-agent await prompt");
    let expected_ids = child_ids.to_vec();
    let mut trace = Vec::new();
    let mut collector = BufferedEventCollector::new(&mut fixture.client);
    let tool_call_id = tokio::time::timeout(Duration::from_secs(120), async {
        let mut request_id = None;
        let mut progress_id = None;
        loop {
            let envelope = collector.next("multi-agent await request").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *parent_stream {
                collector.defer(envelope);
                continue;
            }
            let event = envelope
                .parse_payload::<ChatEvent>()
                .expect("parse multi-agent await event");
            trace.push(format!("{event:?}"));
            match event {
                ChatEvent::ToolRequest(request) => {
                    let agent_ids = match request.tool_type {
                        ToolRequestType::TydeAwaitAgents { agent_ids } => agent_ids,
                        other => panic!(
                            "multi-agent await issued an unexpected extra tool request: {other:?}"
                        ),
                    };
                    assert_eq!(agent_ids, expected_ids);
                    assert!(request_id.replace(request.tool_call_id).is_none());
                }
                ChatEvent::ToolProgress(progress) => {
                    let protocol::ToolProgressUpdate::AgentControl(agent_progress) =
                        progress.update
                    else {
                        panic!("multi-agent await emitted the wrong progress family")
                    };
                    assert_eq!(
                        agent_progress.progress_kind,
                        protocol::AgentControlProgressKind::Await
                    );
                    assert_eq!(agent_progress.agents.len(), expected_ids.len());
                    let progress_ids = agent_progress
                        .agents
                        .iter()
                        .map(|agent| agent.agent_id.clone())
                        .collect::<Vec<_>>();
                    assert_eq!(progress_ids, expected_ids);
                    assert_eq!(
                        agent_progress.status,
                        protocol::AgentControlProgressStatus::Running
                    );
                    assert!(progress_id.replace(progress.tool_call_id).is_none());
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("multi-agent await setup failed: {content}"),
                _ => collector.defer(envelope),
            }
            if let Some(request_id) = &request_id {
                if !expect_pending {
                    break request_id.clone();
                }
                if let Some(progress_id) = &progress_id {
                    assert_eq!(request_id, progress_id);
                    break request_id.clone();
                }
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "backend did not emit one correlated multi-agent await request; trace:\n{}",
            trace.join("\n")
        )
    });
    collector.restore();
    tool_call_id
}

async fn expect_agent_await_completion(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    tool_call_id: &str,
) -> ToolExecutionCompletedData {
    let mut trace = Vec::new();
    let mut terminal_status = None;
    let completion = tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = fixture
                .client
                .next_event()
                .await
                .expect("read agent-await completion")
                .expect("agent-await completion connection closed");
            let traced_event = (envelope.kind == FrameKind::ChatEvent)
                .then(|| envelope.parse_payload::<ChatEvent>().ok())
                .flatten();
            trace.push(format!(
                "{} {:?}{}",
                envelope.stream,
                envelope.kind,
                traced_event
                    .as_ref()
                    .map(|event| format!(" {event:?}"))
                    .unwrap_or_default()
            ));
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            let event = envelope
                .parse_payload::<ChatEvent>()
                .expect("parse agent-await completion event");
            trace.push(format!("{event:?}"));
            match event {
                ChatEvent::ToolProgress(progress) if progress.tool_call_id == tool_call_id => {
                    if let protocol::ToolProgressUpdate::AgentControl(agent_progress) =
                        progress.update
                        && agent_progress.progress_kind == protocol::AgentControlProgressKind::Await
                        && agent_progress.status != protocol::AgentControlProgressStatus::Running
                    {
                        assert!(terminal_status.replace(agent_progress.status).is_none());
                    }
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    let expected_status = if completion.success() {
                        protocol::AgentControlProgressStatus::Completed
                    } else if matches!(&completion.outcome, ToolExecutionOutcome::Cancelled { .. })
                    {
                        protocol::AgentControlProgressStatus::Stopped
                    } else {
                        protocol::AgentControlProgressStatus::Failed
                    };
                    assert_eq!(terminal_status, Some(expected_status));
                    return completion;
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("agent-await failed before completion: {content}"),
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "agent-await did not complete on {stream}; trace:\n{}",
            trace.join("\n")
        )
    });
    assert_progress_terminal_is_stable(
        fixture,
        stream,
        tool_call_id,
        ProgressFamily::AgentControl,
        "agent-control terminal stability",
    )
    .await;
    completion
}

async fn expect_replayed_agent_await_request(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    tool_call_id: &str,
    expected_ids: &[protocol::AgentId],
) {
    let mut collector = BufferedEventCollector::new(&mut fixture.client);
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = collector.next("replayed agent-await request").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                collector.defer(envelope);
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .expect("parse replayed agent-await event")
            {
                ChatEvent::ToolRequest(request) if request.tool_call_id == tool_call_id => {
                    let ToolRequestType::TydeAwaitAgents { agent_ids } = request.tool_type else {
                        panic!("replayed await changed normalized tool type")
                    };
                    assert_eq!(agent_ids, expected_ids);
                    break;
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if completion.tool_call_id == tool_call_id =>
                {
                    panic!("await completed before its watched child changed: {completion:?}")
                }
                _ => collector.defer(envelope),
            }
        }
    })
    .await
    .expect("reconnect did not replay the pending agent-await request");
    collector.restore();
    assert_eq!(
        fixture
            .host
            .active_agent_control_await_request_count()
            .await,
        1,
        "reconnect duplicated or dropped the active agent-await request"
    );
}

fn assert_exact_agent_await_partition(
    completion: &ToolExecutionCompletedData,
    expected_ready: &[(protocol::AgentId, protocol::AgentControlStatus)],
    expected_still_thinking: &[(protocol::AgentId, protocol::AgentControlStatus)],
) {
    assert!(completion.success(), "agent-await failed: {completion:?}");
    let ToolExecutionResult::TydeAwaitAgents {
        ready,
        still_thinking,
    } = &completion.tool_result()
    else {
        panic!("agent-await completion was not normalized: {completion:?}")
    };
    let actual_ready = ready
        .iter()
        .map(|entry| (entry.agent_id.clone(), entry.status))
        .collect::<Vec<_>>();
    let actual_still_thinking = still_thinking
        .iter()
        .map(|entry| (entry.agent_id.clone(), entry.status))
        .collect::<Vec<_>>();
    assert_eq!(actual_ready, expected_ready);
    assert_eq!(actual_still_thinking, expected_still_thinking);
    let all_ids = ready
        .iter()
        .chain(still_thinking.iter())
        .map(|entry| entry.agent_id.clone())
        .collect::<Vec<_>>();
    assert_eq!(
        all_ids.iter().collect::<HashSet<_>>().len(),
        all_ids.len(),
        "agent-await partition duplicated a child: {completion:?}"
    );
}

async fn wait_for_agent_await_parent_idle(fixture: &mut RealBackendFixture, stream: &StreamPath) {
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, "agent-await parent idle").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .expect("parse agent-await post-completion event")
            {
                ChatEvent::TypingStatusChanged(false) => break,
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("agent-await parent failed after completion: {content}"),
                _ => {}
            }
        }
    })
    .await
    .expect("agent-await parent did not become idle after completion");
}

async fn assert_multi_agent_await_contract(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let pair = spawn_agent_control_pair(&mut fixture, backend_kind).await;
    let roots = fixture.workspace_roots();
    let third = spawn_agent_control_child(
        &mut fixture,
        backend_kind,
        roots,
        &pair.parent_id,
        "agent-control-third-child",
    )
    .await;

    let first_ids = vec![pair.child_id.clone(), third.id.clone()];
    let first_call = start_multi_agent_await_request(
        &mut fixture,
        backend_kind,
        &pair.parent_stream,
        &first_ids,
        true,
    )
    .await;
    assert!(
        fixture
            .host
            .force_agent_backend_shutdown_for_conformance(&pair.child_id)
            .await
    );
    let first = expect_agent_await_completion(&mut fixture, &pair.parent_stream, &first_call).await;
    assert_exact_agent_await_partition(
        &first,
        &[(pair.child_id.clone(), protocol::AgentControlStatus::Failed)],
        &[(third.id.clone(), protocol::AgentControlStatus::Thinking)],
    );
    wait_for_agent_await_parent_idle(&mut fixture, &pair.parent_stream).await;

    let roots = fixture.workspace_roots();
    let fourth = spawn_agent_control_child(
        &mut fixture,
        backend_kind,
        roots,
        &pair.parent_id,
        "agent-control-fourth-child",
    )
    .await;
    let pending_ids = vec![third.id.clone(), fourth.id.clone()];
    let second_call = start_multi_agent_await_request(
        &mut fixture,
        backend_kind,
        &pair.parent_stream,
        &pending_ids,
        true,
    )
    .await;
    let mut replacement = fixture.connect().await;
    replacement.inherit_live_trace_from(&fixture.client);
    std::mem::swap(&mut fixture.client, &mut replacement);
    drop(replacement);
    let reconnected_parent_stream = loop {
        let envelope =
            expect_next_event(&mut fixture.client, "multi-await reconnect bootstrap").await;
        if envelope.kind != FrameKind::HostBootstrap {
            continue;
        }
        let bootstrap: HostBootstrapPayload = envelope
            .parse_payload()
            .expect("parse multi-await reconnect bootstrap");
        break bootstrap
            .agents
            .into_iter()
            .find(|agent| agent.agent_id == pair.parent_id)
            .expect("multi-await reconnect omitted parent")
            .instance_stream;
    };
    expect_replayed_agent_await_request(
        &mut fixture,
        &reconnected_parent_stream,
        &second_call,
        &pending_ids,
    )
    .await;
    std::fs::write(&third.release, b"release").expect("release first running child");
    let second =
        expect_agent_await_completion(&mut fixture, &reconnected_parent_stream, &second_call).await;
    assert_exact_agent_await_partition(
        &second,
        &[(third.id.clone(), protocol::AgentControlStatus::Idle)],
        &[(fourth.id.clone(), protocol::AgentControlStatus::Thinking)],
    );
    wait_for_agent_await_parent_idle(&mut fixture, &reconnected_parent_stream).await;

    let idle_running_ids = vec![third.id.clone(), fourth.id.clone()];
    let third_call = start_multi_agent_await_request(
        &mut fixture,
        backend_kind,
        &reconnected_parent_stream,
        &idle_running_ids,
        false,
    )
    .await;
    let idle_running =
        expect_agent_await_completion(&mut fixture, &reconnected_parent_stream, &third_call).await;
    assert_exact_agent_await_partition(
        &idle_running,
        &[(third.id.clone(), protocol::AgentControlStatus::Idle)],
        &[(fourth.id.clone(), protocol::AgentControlStatus::Thinking)],
    );
    wait_for_agent_await_parent_idle(&mut fixture, &reconnected_parent_stream).await;

    let mixed_ids = vec![pair.child_id.clone(), third.id.clone(), fourth.id.clone()];
    let fourth_call = start_multi_agent_await_request(
        &mut fixture,
        backend_kind,
        &reconnected_parent_stream,
        &mixed_ids,
        false,
    )
    .await;
    let mixed =
        expect_agent_await_completion(&mut fixture, &reconnected_parent_stream, &fourth_call).await;
    assert_exact_agent_await_partition(
        &mixed,
        &[
            (pair.child_id.clone(), protocol::AgentControlStatus::Failed),
            (third.id.clone(), protocol::AgentControlStatus::Idle),
        ],
        &[(fourth.id.clone(), protocol::AgentControlStatus::Thinking)],
    );
    wait_for_agent_await_parent_idle(&mut fixture, &reconnected_parent_stream).await;

    let final_call = start_multi_agent_await_request(
        &mut fixture,
        backend_kind,
        &reconnected_parent_stream,
        std::slice::from_ref(&fourth.id),
        true,
    )
    .await;
    std::fs::write(&fourth.release, b"release").expect("release final running child");
    let final_completion =
        expect_agent_await_completion(&mut fixture, &reconnected_parent_stream, &final_call).await;
    assert_exact_agent_await_partition(
        &final_completion,
        &[(fourth.id.clone(), protocol::AgentControlStatus::Idle)],
        &[],
    );
    assert_eq!(
        [
            &first_call,
            &second_call,
            &third_call,
            &fourth_call,
            &final_call,
        ]
        .into_iter()
        .collect::<HashSet<_>>()
        .len(),
        5,
        "multi-agent await requests reused a tool-call ID"
    );
    close_agent_at_definitive_boundary(
        &mut fixture,
        &reconnected_parent_stream,
        &pair.parent_id,
        "close multi-agent await parent",
    )
    .await;
}

async fn expect_rejected_agent_control_call(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    stream: &StreamPath,
    tool: &str,
    agent_ids: &[String],
    message: Option<&str>,
    expected_error_fragment: &str,
) {
    let instruction = match (backend_kind, tool) {
        (BackendKind::Claude, "send") => "Call tyde_send_agent_message exactly once",
        (BackendKind::Claude, "await") => "Call tyde_await_agents exactly once",
        (BackendKind::Codex, "send") => {
            "Call tyde_send_agent_message from the connected Tyde agent-control MCP server exactly once"
        }
        (BackendKind::Codex, "await") => "Call the available tyde_await_agents tool exactly once",
        (_, "send") => "Use the Tyde agent-control send-message tool exactly once",
        (_, "await") => "Use the Tyde agent-control await-agents tool exactly once",
        _ => unreachable!(),
    };
    let prompt = if tool == "send" {
        format!(
            "{instruction} with agent_id `{}` and message `{}`. Do not correct, replace, or validate the ID. Do not call another tool. The call is expected to fail; after it returns, stop.",
            agent_ids.first().expect("send edge agent id"),
            message.expect("send edge message")
        )
    } else {
        let ids = agent_ids
            .iter()
            .map(|id| format!("`{id}`"))
            .collect::<Vec<_>>()
            .join(", ");
        format!(
            "{instruction} with agent_ids [{ids}] in exactly that order, including every duplicate. Do not correct, replace, deduplicate, or validate an ID. Do not call another tool. The call is expected to fail; after it returns, stop."
        )
    };
    fixture
        .client
        .send_message(stream, prompt)
        .await
        .expect("send invalid agent-control prompt");
    let mut request_id = None;
    let mut saw_completion = false;
    let mut trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "rejected agent-control call").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            let event = envelope
                .parse_payload::<ChatEvent>()
                .expect("parse rejected agent-control event");
            trace.push(format!("{event:?}"));
            match event {
                ChatEvent::ToolRequest(request) => {
                    match (&request.tool_type, tool) {
                        (
                            ToolRequestType::TydeSendAgentMessage {
                                agent_id,
                                message: actual,
                            },
                            "send",
                        ) => {
                            assert_eq!(agent_id.0, agent_ids[0]);
                            assert_eq!(actual, message.expect("send edge message"));
                        }
                        (ToolRequestType::TydeAwaitAgents { agent_ids: actual }, "await") => {
                            assert_eq!(
                                actual.iter().map(|id| id.0.clone()).collect::<Vec<_>>(),
                                agent_ids
                            );
                        }
                        _ => panic!(
                            "backend made the wrong agent-control call for invalid {tool} edge: {request:?}"
                        ),
                    }
                    request_id = Some(request.tool_call_id);
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if request_id.as_ref() == Some(&completion.tool_call_id) =>
                {
                    assert!(!completion.success(), "invalid call succeeded: {completion:?}");
                    let error = completion
                        .error()
                        .map(str::to_owned)
                        .unwrap_or_else(|| format!("{:?}", completion.tool_result()));
                    assert!(
                        error.to_ascii_lowercase().contains(expected_error_fragment),
                        "invalid call returned the wrong error: {completion:?}"
                    );
                    saw_completion = true;
                }
                ChatEvent::TypingStatusChanged(false) if saw_completion => break,
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) if request_id.is_none() => panic!(
                    "backend failed before making the requested invalid agent-control call: {content}"
                ),
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "invalid agent-control call did not fail visibly; trace:\n{}",
            trace.join("\n")
        )
    });
    assert_eq!(
        fixture
            .host
            .active_agent_control_await_request_count()
            .await,
        0,
        "rejected agent-control edge leaked an await request"
    );
    assert_eq!(
        fixture
            .host
            .active_agent_message_delivery_count_for_conformance()
            .await,
        0,
        "rejected agent-control edge leaked a send request"
    );
}

async fn assert_invalid_agent_control_edges(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let pair = spawn_agent_control_pair(&mut fixture, backend_kind).await;
    let missing = Uuid::new_v4().to_string();
    let parent = pair.parent_id.0.clone();

    for (tool, ids, expected) in [
        (
            "send",
            vec!["not-an-agent-id".to_owned()],
            "invalid agent_id",
        ),
        ("send", vec![pair.child_id.0.clone()], "message"),
        ("send", vec![missing.clone()], "authorization"),
        ("send", vec![parent.clone()], "authorization"),
        (
            "await",
            vec!["not-an-agent-id".to_owned()],
            "invalid agent_id",
        ),
        ("await", vec![missing], "authorization"),
        ("await", vec![parent], "authorization"),
        ("await", vec![], "agent"),
        (
            "await",
            vec![pair.child_id.0.clone(), pair.child_id.0.clone()],
            "duplicate agent_id",
        ),
    ] {
        expect_rejected_agent_control_call(
            &mut fixture,
            backend_kind,
            &pair.parent_stream,
            tool,
            &ids,
            if tool == "send" && ids == [pair.child_id.0.clone()] {
                Some("")
            } else {
                (tool == "send").then_some("INVALID_EDGE_MESSAGE")
            },
            expected,
        )
        .await;
    }

    assert!(
        fixture
            .host
            .force_agent_backend_shutdown_for_conformance(&pair.child_id)
            .await
    );
    expect_rejected_agent_control_call(
        &mut fixture,
        backend_kind,
        &pair.parent_stream,
        "send",
        std::slice::from_ref(&pair.child_id.0),
        Some("TERMINAL_CHILD_MESSAGE"),
        "agent",
    )
    .await;
    close_agent_at_definitive_boundary(
        &mut fixture,
        &pair.parent_stream,
        &pair.parent_id,
        "close invalid agent-control edge parent",
    )
    .await;
}

fn agent_control_coverage_cell(
    tool: SpecialToolContract,
    relation: AgentControlTargetRelation,
    authorization: AgentControlAuthorizationSet,
    multiplicity: AgentControlRequestMultiplicity,
    boundary_race: AgentControlBoundaryRace,
) -> AgentControlCoverageCell {
    AgentControlCoverageCell {
        tool,
        relation,
        authorization,
        multiplicity,
        boundary_race,
    }
}

async fn expect_successful_agent_control_call(
    fixture: &mut RealBackendFixture,
    backend_kind: BackendKind,
    stream: &StreamPath,
    tool: &str,
    target: &protocol::AgentId,
) -> String {
    let prompt = agent_control_tool_prompt(backend_kind, tool, target);
    fixture
        .client
        .send_message(stream, prompt.clone())
        .await
        .unwrap();
    let turn = expect_tool_turn_after_user_echo(&mut fixture.client, stream, &prompt).await;
    let request = turn
        .tool_requests
        .iter()
        .find(|request| match (&request.tool_type, tool) {
            (ToolRequestType::TydeSendAgentMessage { agent_id, .. }, "send") => agent_id == target,
            (ToolRequestType::TydeAwaitAgents { agent_ids }, "await") => {
                agent_ids == std::slice::from_ref(target)
            }
            _ => false,
        })
        .unwrap_or_else(|| panic!("missing successful {tool} request: {turn:?}"));
    let completion = turn
        .tool_completions
        .iter()
        .find(|completion| completion.tool_call_id == request.tool_call_id)
        .expect("successful control request did not terminalize");
    assert!(
        completion.success(),
        "successful {tool} failed: {completion:?}"
    );
    request.tool_call_id.clone()
}

async fn assert_agent_control_authorization_matrix(
    backend_kind: BackendKind,
) -> Vec<AgentControlCoverageCell> {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let (parent_stream, parent_id) =
        spawn_idle_agent_control_agent(&mut fixture, backend_kind, None, "AUTH_PARENT").await;
    let (child_stream, child_id) = spawn_idle_agent_control_agent(
        &mut fixture,
        backend_kind,
        Some(parent_id.clone()),
        "AUTH_CHILD",
    )
    .await;
    let (_, sibling_id) = spawn_idle_agent_control_agent(
        &mut fixture,
        backend_kind,
        Some(parent_id.clone()),
        "AUTH_SIBLING",
    )
    .await;
    let (_, grandchild_id) = spawn_idle_agent_control_agent(
        &mut fixture,
        backend_kind,
        Some(child_id.clone()),
        "AUTH_GRANDCHILD",
    )
    .await;
    let (_, unrelated_id) =
        spawn_idle_agent_control_agent(&mut fixture, backend_kind, None, "AUTH_UNRELATED").await;

    let mut witnessed = Vec::new();
    for (caller_stream, target, relation) in [
        (
            &child_stream,
            &parent_id,
            AgentControlTargetRelation::Parent,
        ),
        (
            &child_stream,
            &sibling_id,
            AgentControlTargetRelation::Sibling,
        ),
        (
            &parent_stream,
            &grandchild_id,
            AgentControlTargetRelation::Grandchild,
        ),
        (
            &parent_stream,
            &unrelated_id,
            AgentControlTargetRelation::UnrelatedRoot,
        ),
    ] {
        for (tool_name, tool) in [
            ("send", SpecialToolContract::SendAgentMessage),
            ("await", SpecialToolContract::AwaitAgents),
        ] {
            expect_rejected_agent_control_call(
                &mut fixture,
                backend_kind,
                caller_stream,
                tool_name,
                std::slice::from_ref(&target.0),
                (tool_name == "send").then_some("AUTHORIZATION_PROBE"),
                "authorization",
            )
            .await;
            witnessed.push(agent_control_coverage_cell(
                tool,
                relation,
                AgentControlAuthorizationSet::SingleUnauthorized,
                AgentControlRequestMultiplicity::Single,
                AgentControlBoundaryRace::None,
            ));
        }
    }

    for (authorization, ids) in [
        (
            AgentControlAuthorizationSet::MixedAuthorizedFirst,
            vec![grandchild_id.0.clone(), sibling_id.0.clone()],
        ),
        (
            AgentControlAuthorizationSet::MixedUnauthorizedFirst,
            vec![sibling_id.0.clone(), grandchild_id.0.clone()],
        ),
    ] {
        expect_rejected_agent_control_call(
            &mut fixture,
            backend_kind,
            &child_stream,
            "await",
            &ids,
            None,
            "authorization",
        )
        .await;
        witnessed.push(agent_control_coverage_cell(
            SpecialToolContract::AwaitAgents,
            AgentControlTargetRelation::Sibling,
            authorization,
            AgentControlRequestMultiplicity::Single,
            AgentControlBoundaryRace::None,
        ));
    }

    expect_successful_agent_control_call(
        &mut fixture,
        backend_kind,
        &child_stream,
        "await",
        &grandchild_id,
    )
    .await;
    witnessed.push(agent_control_coverage_cell(
        SpecialToolContract::AwaitAgents,
        AgentControlTargetRelation::DirectChild,
        AgentControlAuthorizationSet::SingleAuthorized,
        AgentControlRequestMultiplicity::Single,
        AgentControlBoundaryRace::None,
    ));
    expect_successful_agent_control_call(
        &mut fixture,
        backend_kind,
        &parent_stream,
        "send",
        &child_id,
    )
    .await;
    witnessed.push(agent_control_coverage_cell(
        SpecialToolContract::SendAgentMessage,
        AgentControlTargetRelation::DirectChild,
        AgentControlAuthorizationSet::SingleAuthorized,
        AgentControlRequestMultiplicity::Single,
        AgentControlBoundaryRace::None,
    ));

    let mut replacement = fixture.connect().await;
    replacement.inherit_live_trace_from(&fixture.client);
    std::mem::swap(&mut fixture.client, &mut replacement);
    drop(replacement);
    let (reconnected_parent, reconnected_child) =
        tokio::time::timeout(Duration::from_secs(30), async {
            loop {
                let envelope =
                    expect_next_event(&mut fixture.client, "ownership reconnect bootstrap").await;
                if envelope.kind != FrameKind::HostBootstrap {
                    continue;
                }
                let bootstrap: HostBootstrapPayload = envelope
                    .parse_payload()
                    .expect("parse ownership reconnect bootstrap");
                let parent = bootstrap
                    .agents
                    .iter()
                    .find(|agent| agent.agent_id == parent_id)
                    .map(|agent| agent.instance_stream.clone());
                let child = bootstrap
                    .agents
                    .iter()
                    .find(|agent| agent.agent_id == child_id)
                    .map(|agent| agent.instance_stream.clone());
                if let (Some(parent), Some(child)) = (parent, child) {
                    break (parent, child);
                }
            }
        })
        .await
        .expect("ownership reconnect omitted established topology");
    let (_, late_grandchild_id) = spawn_idle_agent_control_agent(
        &mut fixture,
        backend_kind,
        Some(child_id.clone()),
        "AUTH_LATE_GRANDCHILD",
    )
    .await;
    expect_successful_agent_control_call(
        &mut fixture,
        backend_kind,
        &reconnected_child,
        "await",
        &late_grandchild_id,
    )
    .await;
    expect_rejected_agent_control_call(
        &mut fixture,
        backend_kind,
        &reconnected_parent,
        "await",
        std::slice::from_ref(&late_grandchild_id.0),
        None,
        "authorization",
    )
    .await;
    let (_, late_sibling_id) = spawn_idle_agent_control_agent(
        &mut fixture,
        backend_kind,
        Some(parent_id.clone()),
        "AUTH_LATE_SIBLING",
    )
    .await;
    expect_rejected_agent_control_call(
        &mut fixture,
        backend_kind,
        &reconnected_child,
        "send",
        std::slice::from_ref(&late_sibling_id.0),
        Some("LATE_SIBLING_AUTHORIZATION_PROBE"),
        "authorization",
    )
    .await;
    witnessed
}

async fn wait_for_agent_control_child_echoes(
    fixture: &mut RealBackendFixture,
    stream: &StreamPath,
    expected: usize,
) {
    let mut echoes = 0usize;
    tokio::time::timeout(Duration::from_secs(180), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "repeated agent-message child").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::User,
                    content,
                    ..
                }) if content == "AGENT_CONTROL_MESSAGE_731" => echoes += 1,
                ChatEvent::TypingStatusChanged(false) if echoes == expected => break,
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("repeated agent-message child failed: {content}"),
                _ => {}
            }
        }
    })
    .await
    .expect("repeated agent messages were not consumed");
    assert_eq!(echoes, expected);
}

async fn wait_for_agent_control_child_idle(fixture: &mut RealBackendFixture, stream: &StreamPath) {
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, "agent-control child idle").await;
            if envelope.kind == FrameKind::ChatEvent
                && envelope.stream == *stream
                && matches!(
                    envelope.parse_payload::<ChatEvent>().unwrap(),
                    ChatEvent::TypingStatusChanged(false)
                )
            {
                break;
            }
        }
    })
    .await
    .expect("agent-control child did not become idle");
}

async fn assert_agent_message_multiplicity_matrix(
    backend_kind: BackendKind,
) -> Vec<AgentControlCoverageCell> {
    let mut witnessed = Vec::new();

    let mut active_fixture = RealBackendFixture::new(backend_kind).await;
    let active = spawn_agent_control_pair(&mut active_fixture, backend_kind).await;
    let first = expect_successful_agent_control_call(
        &mut active_fixture,
        backend_kind,
        &active.parent_stream,
        "send",
        &active.child_id,
    )
    .await;
    let second = expect_successful_agent_control_call(
        &mut active_fixture,
        backend_kind,
        &active.parent_stream,
        "send",
        &active.child_id,
    )
    .await;
    assert_ne!(first, second, "identical sends reused a tool-call ID");
    std::fs::write(&active.child_release, b"release").unwrap();
    wait_for_agent_control_child_echoes(&mut active_fixture, &active.child_stream, 2).await;
    witnessed.push(agent_control_coverage_cell(
        SpecialToolContract::SendAgentMessage,
        AgentControlTargetRelation::DirectChild,
        AgentControlAuthorizationSet::SingleAuthorized,
        AgentControlRequestMultiplicity::RepeatedWhileTargetActive,
        AgentControlBoundaryRace::None,
    ));

    let mut idle_fixture = RealBackendFixture::new(backend_kind).await;
    let idle = spawn_agent_control_pair(&mut idle_fixture, backend_kind).await;
    std::fs::write(&idle.child_release, b"release").unwrap();
    wait_for_agent_control_child_idle(&mut idle_fixture, &idle.child_stream).await;
    let first = expect_successful_agent_control_call(
        &mut idle_fixture,
        backend_kind,
        &idle.parent_stream,
        "send",
        &idle.child_id,
    )
    .await;
    wait_for_agent_control_child_echoes(&mut idle_fixture, &idle.child_stream, 1).await;
    let second = expect_successful_agent_control_call(
        &mut idle_fixture,
        backend_kind,
        &idle.parent_stream,
        "send",
        &idle.child_id,
    )
    .await;
    wait_for_agent_control_child_echoes(&mut idle_fixture, &idle.child_stream, 1).await;
    assert_ne!(
        first, second,
        "sequential identical sends reused a tool-call ID"
    );
    witnessed.push(agent_control_coverage_cell(
        SpecialToolContract::SendAgentMessage,
        AgentControlTargetRelation::DirectChild,
        AgentControlAuthorizationSet::SingleAuthorized,
        AgentControlRequestMultiplicity::RepeatedAfterTargetIdle,
        AgentControlBoundaryRace::None,
    ));
    witnessed
}

