async fn expect_tool_completion_for_id(
    client: &mut ValidatedConnection,
    stream: &StreamPath,
    tool_call_id: &str,
    context: &str,
) -> protocol::ToolExecutionCompletedData {
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = client
                .next_event()
                .await
                .unwrap_or_else(|error| panic!("read {context}: {error}"))
                .unwrap_or_else(|| panic!("connection closed while waiting for {context}"));
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            if let ChatEvent::ToolExecutionCompleted(completion) = envelope
                .parse_payload::<ChatEvent>()
                .expect("parse tool completion")
                && completion.tool_call_id == tool_call_id
            {
                return completion;
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("timed out waiting for {context}"))
}

async fn run_selected_certification_case(case: CertificationCase) {
    assert!(
        real_ai_tests_enabled(),
        "set {RUN_REAL_AI_TESTS_ENV}=1 to authorize paid backend qualification"
    );
    let _conformance_environment = REAL_CONFORMANCE_ENV_MUTEX.lock().await;
    let backends = selected_real_backends().expect("parse backend selection");
    let _claude_subagent_model_guard = backends.contains(&BackendKind::Claude).then(|| {
        EnvVarGuard::set(
            "CLAUDE_CODE_SUBAGENT_MODEL",
            UNIVERSAL_CLAUDE_MODEL.to_owned(),
        )
    });
    if let Some(reason) = intentional_registry_only_certification_case(case) {
        for backend_kind in &backends {
            let capabilities = server::backend::capabilities_for_backend_kind(*backend_kind);
            assert!(
                !backend_supports_certification_case(*backend_kind, &capabilities, case),
                "registry-only case {} became runnable on {}; remove its N/A exemption and implement its real conformance runner",
                case.id(),
                backend_label(*backend_kind)
            );
        }
        eprintln!("INTENTIONAL REGISTRY-ONLY N/A {}: {reason}", case.id());
        return;
    }
    let _hermes_python_guard = backends
        .contains(&BackendKind::Hermes)
        .then(|| {
            std::env::var("HERMES_PYTHON")
                .ok()
                .filter(|value| !value.trim().is_empty())
                .or_else(|| {
                    Path::new(DEFAULT_HERMES_TEST_PYTHON)
                        .exists()
                        .then(|| DEFAULT_HERMES_TEST_PYTHON.to_owned())
                })
        })
        .flatten()
        .map(|python| EnvVarGuard::set("HERMES_PYTHON", python));
    let mut failures = Vec::new();
    let mut executions = 0usize;
    for backend_kind in backends {
        if !backend_binary_available(backend_kind) || !backend_runtime_available(backend_kind) {
            failures.push(format!(
                "{}: selected backend is not runnable",
                backend_label(backend_kind)
            ));
            continue;
        }
        let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
        if !backend_supports_certification_case(backend_kind, &capabilities, case) {
            let reason = certification_case_exemption_reason(backend_kind, &capabilities, case);
            eprintln!(
                "SKIPPED {} {}: {reason}",
                backend_label(backend_kind),
                case.id()
            );
            continue;
        }
        executions += 1;
        eprintln!("RUNNING {} {}", backend_label(backend_kind), case.id());
        let handle = tokio::spawn(run_certification_case_for_backend(backend_kind, case));
        let result = handle.await;
        await_real_backend_cleanup().await;
        match result {
            Ok(witnesses)
                if certification_case_requires_witnesses(case) && witnesses.is_empty() =>
            {
                failures.push(format!(
                    "{} {}: executed no conformance matrix cells",
                    backend_label(backend_kind),
                    case.id()
                ));
            }
            Ok(_) => {}
            Err(error) => failures.push(format!(
                "{} {}: {error}",
                backend_label(backend_kind),
                case.id()
            )),
        }
    }
    assert!(executions > 0, "no selected backend ran {}", case.id());
    assert!(
        failures.is_empty(),
        "backend certification case {} failed:\n{}",
        case.id(),
        failures.join("\n")
    );
}

