fn assert_agent_projection_metadata(
    projected: &NewAgentPayload,
    started: &AgentStartPayload,
    context: &str,
) {
    assert_eq!(
        started.agent_id, projected.agent_id,
        "{context} changed agent id"
    );
    assert_eq!(
        started.name, projected.name,
        "{context} changed initial name"
    );
    assert_eq!(started.origin, projected.origin, "{context} changed origin");
    assert_eq!(
        started.backend_kind, projected.backend_kind,
        "{context} changed backend"
    );
    assert_eq!(
        started.launch_profile_id, projected.launch_profile_id,
        "{context} changed launch profile"
    );
    assert_eq!(
        started.workspace_roots, projected.workspace_roots,
        "{context} changed workspace roots"
    );
    assert_eq!(
        started.custom_agent_id, projected.custom_agent_id,
        "{context} changed custom-agent identity"
    );
    assert_eq!(started.team_id, projected.team_id, "{context} changed team");
    assert_eq!(
        started.team_member_id, projected.team_member_id,
        "{context} changed team member"
    );
    assert_eq!(
        started.project_id, projected.project_id,
        "{context} changed project"
    );
    assert_eq!(
        started.parent_agent_id, projected.parent_agent_id,
        "{context} changed parent"
    );
    if projected.session_id.is_some() {
        assert_eq!(
            started.session_id, projected.session_id,
            "{context} changed a session identity already known at publication"
        );
    }
    assert!(
        started.session_id.is_some(),
        "{context} AgentStart did not establish a backend session"
    );
    assert_eq!(
        started.workflow, projected.workflow,
        "{context} changed workflow metadata"
    );
    assert_eq!(
        started.created_at_ms, projected.created_at_ms,
        "{context} changed creation timestamp"
    );
}

