fn assert_completed_native_projection_replay(
    bootstrap: &AgentBootstrapPayload,
    tool_call_id: &str,
    child_id: &protocol::AgentId,
    expected_start_id: &protocol::AgentId,
    context: &str,
) {
    assert!(
        !bootstrap.turn_active,
        "{context} replayed a completed turn as active"
    );
    let starts: Vec<_> = bootstrap
        .events
        .iter()
        .filter_map(|event| match event {
            AgentBootstrapEvent::AgentStart(start) => Some(start),
            _ => None,
        })
        .collect();
    assert_eq!(starts.len(), 1, "{context} duplicated AgentStart");
    assert_eq!(
        &starts[0].agent_id, expected_start_id,
        "{context} leaked another agent's AgentStart"
    );

    let mut request_positions = Vec::new();
    let mut running_positions = Vec::new();
    let mut terminal_positions = Vec::new();
    let mut completion_positions = Vec::new();
    for (position, event) in bootstrap.events.iter().enumerate() {
        let AgentBootstrapEvent::ChatEvent(event) = event else {
            continue;
        };
        match event {
            ChatEvent::ToolRequest(ToolRequest {
                tool_call_id: replayed_id,
                tool_type: ToolRequestType::AgentSpawn { .. },
                ..
            }) if replayed_id == tool_call_id => request_positions.push(position),
            ChatEvent::ToolProgress(progress) if progress.tool_call_id == tool_call_id => {
                let protocol::ToolProgressUpdate::SubAgent(child) = &progress.update else {
                    panic!("{context} changed native projection progress type: {progress:?}");
                };
                assert_eq!(
                    &child.agent_id, child_id,
                    "{context} changed projected child identity"
                );
                if child.completed {
                    terminal_positions.push(position);
                } else {
                    running_positions.push(position);
                }
            }
            ChatEvent::ToolExecutionCompleted(completion)
                if completion.tool_call_id == tool_call_id =>
            {
                assert!(
                    completion.success(),
                    "{context} replayed child completion as failure"
                );
                completion_positions.push(position);
            }
            _ => {}
        }
    }
    assert_eq!(
        request_positions.len(),
        1,
        "{context} lost/duplicated spawn request"
    );
    assert!(
        !running_positions.is_empty(),
        "{context} lost the running child projection"
    );
    assert_eq!(
        terminal_positions.len(),
        1,
        "{context} lost/duplicated completed child projection"
    );
    assert_eq!(
        completion_positions.len(),
        1,
        "{context} lost/duplicated normalized spawn completion"
    );
    assert!(
        request_positions[0] < running_positions[0]
            && *running_positions.last().unwrap() < terminal_positions[0]
            && terminal_positions[0] < completion_positions[0],
        "{context} replayed native projection out of order"
    );
}

async fn completed_native_projection_run(backend_kind: BackendKind) -> NativeProjectionRun {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let workspace_roots = fixture.workspace_roots();
    let prompt = match backend_kind {
        BackendKind::Claude => {
            "Use the Agent tool exactly once to ask a general-purpose subagent to read README.txt and return its first line. Wait for it to finish, then reply exactly SUBAGENT_OK."
        }
        BackendKind::Codex => {
            "Spawn exactly one native subagent to read README.txt and return its first line. Wait for it to finish. Do not use any Tyde MCP agent-control tool. Then reply exactly SUBAGENT_OK."
        }
        BackendKind::Hermes => {
            "Delegate to exactly one native subagent: have it read README.txt and return its first line. Wait for it to finish, then reply exactly SUBAGENT_OK."
        }
        _ => {
            "Use exactly one native subagent to read README.txt and return its first line. Wait for it to finish, then reply exactly SUBAGENT_OK."
        }
    };

    fixture
        .client
        .spawn_agent(SpawnAgentPayload {
            name: Some("universal-native-subagent".to_owned()),
            custom_agent_id: None,
            parent_agent_id: None,
            project_id: None,
            params: SpawnAgentParams::New {
                workspace_roots: workspace_roots.clone(),
                prompt: prompt.to_owned(),
                images: None,
                backend_kind,
                launch_profile_id: None,
                cost_hint: cost_hint_for(backend_kind),
                access_mode: Default::default(),
                session_settings: None,
            },
        })
        .await
        .expect("spawn universal native-subagent parent");
    let env = expect_next_event_kind(
        &mut fixture.client,
        FrameKind::NewAgent,
        "native-subagent parent NewAgent",
    )
    .await;
    let parent: NewAgentPayload = env.parse_payload().expect("parse parent NewAgent");
    assert_eq!(parent.origin, AgentOrigin::User);
    assert_eq!(parent.backend_kind, backend_kind);
    assert_eq!(parent.workspace_roots, workspace_roots);
    let parent_start = expect_agent_start_on_stream(
        &mut fixture.client,
        &parent.instance_stream,
        "native-subagent parent AgentStart",
    )
    .await;
    assert_agent_projection_metadata(&parent, &parent_start, "native parent projection");

    let mut child = None;
    let mut child_start = None;
    let mut child_new_count = 0usize;
    let mut child_start_count = 0usize;
    let mut request_id = None;
    let mut request_position = None;
    let mut child_new_position = None;
    let mut child_start_position = None;
    let mut running_positions = Vec::new();
    let mut terminal_position = None;
    let mut completion_position = None;
    let mut completion_count = 0usize;
    let mut saw_parent_response = false;
    let mut position = 0usize;
    let mut trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(240), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "completed native projection").await;
            position += 1;
            trace.push(format!("{:?} {}", envelope.kind, envelope.stream));
            if envelope.kind == FrameKind::NewAgent {
                let projected: NewAgentPayload = envelope.parse_payload().unwrap();
                if projected.parent_agent_id.as_ref() == Some(&parent.agent_id) {
                    child_new_count += 1;
                    assert_eq!(
                        child_new_count, 1,
                        "duplicate backend-native child NewAgent"
                    );
                    assert_eq!(projected.origin, AgentOrigin::BackendNative);
                    assert_eq!(projected.backend_kind, backend_kind);
                    assert_eq!(projected.workspace_roots, workspace_roots);
                    assert_ne!(projected.agent_id, parent.agent_id);
                    assert_ne!(projected.instance_stream, parent.instance_stream);
                    assert!(
                        projected.session_id.is_some(),
                        "native child has no session identity"
                    );
                    assert_ne!(projected.session_id, parent.session_id);
                    assert_eq!(projected.project_id, parent.project_id);
                    assert_eq!(projected.custom_agent_id, parent.custom_agent_id);
                    assert_eq!(projected.launch_profile_id, parent.launch_profile_id);
                    assert!(projected.team_id.is_none());
                    assert!(projected.team_member_id.is_none());
                    assert!(projected.workflow.is_none());
                    child_new_position = Some(position);
                    child = Some(projected);
                }
                continue;
            }
            if envelope.kind == FrameKind::AgentBootstrap
                && child
                    .as_ref()
                    .is_some_and(|projected| envelope.stream == projected.instance_stream)
            {
                child_start_count += 1;
                assert_eq!(
                    child_start_count, 1,
                    "duplicate backend-native child AgentStart"
                );
                let projected_start =
                    agent_start_from_bootstrap(envelope, "backend-native child AgentBootstrap");
                assert_agent_projection_metadata(
                    child.as_ref().unwrap(),
                    &projected_start,
                    "native child projection",
                );
                child_start_position = Some(position);
                child_start = Some(projected_start);
                continue;
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != parent.instance_stream {
                continue;
            }
            match envelope.parse_payload::<ChatEvent>().unwrap() {
                ChatEvent::ToolRequest(ToolRequest {
                    tool_call_id,
                    tool_type: ToolRequestType::AgentSpawn { .. },
                    ..
                }) => {
                    assert!(
                        request_id.replace(tool_call_id).is_none(),
                        "duplicate spawn request"
                    );
                    request_position = Some(position);
                }
                ChatEvent::ToolProgress(progress) => {
                    let protocol::ToolProgressUpdate::SubAgent(projected) = progress.update else {
                        continue;
                    };
                    let request_id = request_id
                        .as_deref()
                        .expect("native child progress preceded normalized spawn request");
                    assert_eq!(request_id, progress.tool_call_id);
                    assert_eq!(
                        child.as_ref().map(|value| &value.agent_id),
                        Some(&projected.agent_id),
                        "tool card referenced an unprojected child"
                    );
                    if projected.completed {
                        assert!(
                            terminal_position.replace(position).is_none(),
                            "duplicate terminal child progress"
                        );
                    } else {
                        assert!(
                            terminal_position.is_none(),
                            "child progress regressed after completion"
                        );
                        running_positions.push(position);
                    }
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if request_id.as_deref() == Some(completion.tool_call_id.as_str()) =>
                {
                    completion_count += 1;
                    assert_eq!(completion_count, 1, "duplicate native spawn completion");
                    assert!(completion.success(), "native child failed: {completion:?}");
                    completion_position = Some(position);
                }
                ChatEvent::StreamEnd(end) if end.message.content.contains("SUBAGENT_OK") => {
                    saw_parent_response = true;
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("native projection failed: {content}"),
                ChatEvent::TypingStatusChanged(false)
                    if completion_position.is_some() && saw_parent_response =>
                {
                    break;
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "native projection did not complete; trace:\n{}",
            trace.join("\n")
        )
    });

    let child = child.expect("native child was never projected");
    let child_start = child_start.expect("native child never emitted AgentStart");
    let request_position = request_position.expect("parent emitted no AgentSpawn request");
    let child_new_position = child_new_position.unwrap();
    let child_start_position = child_start_position.unwrap();
    let terminal_position = terminal_position.expect("child never emitted completed progress");
    let completion_position = completion_position.expect("spawn never emitted a completion");
    assert!(
        !running_positions.is_empty(),
        "child never emitted running progress"
    );
    assert!(
        request_position < child_new_position
            && child_new_position < child_start_position
            && child_start_position < running_positions[0]
            && *running_positions.last().unwrap() < terminal_position
            && terminal_position < completion_position,
        "native child projection order was invalid: request={request_position}, child_new={child_new_position}, child_start={child_start_position}, running={running_positions:?}, terminal={terminal_position}, completion={completion_position}; trace:\n{}",
        trace.join("\n")
    );

    NativeProjectionRun {
        fixture,
        parent,
        parent_start,
        child,
        child_start,
        tool_call_id: request_id.unwrap(),
    }
}

async fn reconnect_native_projection(run: &mut NativeProjectionRun, context: &str) {
    let mut client = run.fixture.connect().await;
    let bootstrap = loop {
        let envelope = expect_next_unfiltered_event(&mut client, context).await;
        if envelope.kind == FrameKind::HostBootstrap {
            break envelope
                .parse_payload::<HostBootstrapPayload>()
                .expect("parse native projection HostBootstrap");
        }
    };
    let parents: Vec<_> = bootstrap
        .agents
        .iter()
        .filter(|agent| agent.agent_id == run.parent.agent_id)
        .collect();
    let children: Vec<_> = bootstrap
        .agents
        .iter()
        .filter(|agent| agent.agent_id == run.child.agent_id)
        .collect();
    let native_children: Vec<_> = bootstrap
        .agents
        .iter()
        .filter(|agent| agent.origin == AgentOrigin::BackendNative)
        .collect();
    assert_eq!(parents.len(), 1, "{context} lost/duplicated native parent");
    assert_eq!(children.len(), 1, "{context} lost/duplicated native child");
    assert_eq!(
        native_children.len(),
        1,
        "{context} duplicated or leaked a backend-native child"
    );
    assert_same_persisted_agent(parents[0], &run.parent, context);
    assert_same_persisted_agent(children[0], &run.child, context);

    let parent_stream = parents[0].instance_stream.clone();
    let child_stream = children[0].instance_stream.clone();
    assert_ne!(
        parent_stream, child_stream,
        "{context} aliased parent and child streams"
    );
    let mut parent_bootstrap = None;
    let mut child_bootstrap = None;
    while parent_bootstrap.is_none() || child_bootstrap.is_none() {
        let envelope = expect_next_unfiltered_event(&mut client, context).await;
        if envelope.kind == FrameKind::NewAgent {
            let duplicate: NewAgentPayload = envelope.parse_payload().unwrap();
            assert_ne!(
                duplicate.agent_id, run.child.agent_id,
                "{context} re-emitted the completed child as live NewAgent"
            );
        } else if envelope.kind == FrameKind::AgentBootstrap && envelope.stream == parent_stream {
            assert!(
                parent_bootstrap.is_none(),
                "{context} duplicated parent bootstrap"
            );
            parent_bootstrap = Some(envelope.parse_payload::<AgentBootstrapPayload>().unwrap());
        } else if envelope.kind == FrameKind::AgentBootstrap && envelope.stream == child_stream {
            assert!(
                child_bootstrap.is_none(),
                "{context} duplicated child bootstrap"
            );
            child_bootstrap = Some(envelope.parse_payload::<AgentBootstrapPayload>().unwrap());
        }
    }
    assert_completed_native_projection_replay(
        parent_bootstrap.as_ref().unwrap(),
        &run.tool_call_id,
        &run.child.agent_id,
        &run.parent.agent_id,
        context,
    );
    let child_bootstrap = child_bootstrap.unwrap();
    assert!(
        !child_bootstrap.turn_active,
        "{context} replayed completed child as active"
    );
    let starts: Vec<_> = child_bootstrap
        .events
        .iter()
        .filter_map(|event| match event {
            AgentBootstrapEvent::AgentStart(start) => Some(start),
            _ => None,
        })
        .collect();
    assert_eq!(starts.len(), 1, "{context} duplicated child AgentStart");
    assert_eq!(starts[0].agent_id, run.child.agent_id);
    assert!(
        child_bootstrap.events.iter().all(|event| !matches!(
            event,
            AgentBootstrapEvent::ChatEvent(ChatEvent::ToolRequest(request))
                if request.tool_call_id == run.tool_call_id
        )),
        "{context} leaked the parent's spawn request into the child transcript"
    );
}

async fn assert_backend_native_subagent_projection(
    backend_kind: BackendKind,
    case: CertificationCase,
) {
    let mut run = completed_native_projection_run(backend_kind).await;
    assert_eq!(run.parent_start.agent_id, run.parent.agent_id);
    assert_eq!(run.child_start.agent_id, run.child.agent_id);
    match case {
        CertificationCase::NativeSubagentProjected => {
            let parent_session = run
                .parent_start
                .session_id
                .as_ref()
                .expect("parent session id");
            let child_session = run
                .child_start
                .session_id
                .as_ref()
                .expect("child session id");
            let sessions = list_sessions_via_protocol(&mut run.fixture.client).await;
            let children: Vec<_> = sessions
                .sessions
                .iter()
                .filter(|session| &session.id == child_session)
                .collect();
            assert_eq!(
                children.len(),
                1,
                "session list lost/duplicated native child"
            );
            assert_eq!(children[0].parent_id.as_ref(), Some(parent_session));
            assert!(
                !children[0].resumable,
                "backend-native child became resumable"
            );
        }
        CertificationCase::NativeSubagentParentLinked => {
            reconnect_native_projection(&mut run, "native reconnect replay").await;
        }
        CertificationCase::NativeSubagentResumeReplay => {
            let session_id = run.parent.session_id.clone().expect("parent session id");
            run.fixture
                .client
                .spawn_agent(SpawnAgentPayload {
                    name: Some("native-projection-resume".to_owned()),
                    custom_agent_id: None,
                    parent_agent_id: None,
                    project_id: None,
                    params: SpawnAgentParams::Resume {
                        session_id,
                        prompt: None,
                    },
                })
                .await
                .expect("resume completed native projection");
            let resumed: NewAgentPayload = expect_next_event_kind(
                &mut run.fixture.client,
                FrameKind::NewAgent,
                "native projection resumed NewAgent",
            )
            .await
            .parse_payload()
            .unwrap();
            assert_ne!(resumed.agent_id, run.parent.agent_id);
            assert_eq!(resumed.origin, AgentOrigin::User);
            let replay = loop {
                let envelope = expect_next_unfiltered_event(
                    &mut run.fixture.client,
                    "native projection resume bootstrap",
                )
                .await;
                if envelope.kind == FrameKind::NewAgent {
                    let unexpected: NewAgentPayload = envelope.parse_payload().unwrap();
                    assert_ne!(
                        unexpected.agent_id, run.child.agent_id,
                        "resume duplicated child"
                    );
                } else if envelope.kind == FrameKind::AgentBootstrap
                    && envelope.stream == resumed.instance_stream
                {
                    break envelope.parse_payload::<AgentBootstrapPayload>().unwrap();
                }
            };
            assert_completed_native_projection_replay(
                &replay,
                &run.tool_call_id,
                &run.child.agent_id,
                &resumed.agent_id,
                "native resume replay",
            );
            reconnect_native_projection(&mut run, "native post-resume identity audit").await;
        }
        CertificationCase::NativeSubagentForkReplay => {
            let fork_prompt = "Do not use tools. Reply exactly NATIVE_FORK_OK.";
            run.fixture
                .client
                .spawn_agent(SpawnAgentPayload {
                    name: Some("native-projection-fork".to_owned()),
                    custom_agent_id: None,
                    parent_agent_id: Some(run.parent.agent_id.clone()),
                    project_id: None,
                    params: SpawnAgentParams::Fork {
                        from_session_id: run.parent.session_id.clone().expect("parent session id"),
                        prompt: fork_prompt.to_owned(),
                        images: None,
                        access_mode: None,
                    },
                })
                .await
                .expect("fork completed native projection");
            let forked: NewAgentPayload = expect_next_event_kind(
                &mut run.fixture.client,
                FrameKind::NewAgent,
                "native projection fork NewAgent",
            )
            .await
            .parse_payload()
            .unwrap();
            assert_eq!(forked.origin, AgentOrigin::SideQuestion);
            assert_eq!(forked.parent_agent_id.as_ref(), Some(&run.parent.agent_id));
            let replay = loop {
                let envelope = expect_next_unfiltered_event(
                    &mut run.fixture.client,
                    "native projection fork bootstrap",
                )
                .await;
                if envelope.kind == FrameKind::NewAgent {
                    let unexpected: NewAgentPayload = envelope.parse_payload().unwrap();
                    assert_ne!(
                        unexpected.agent_id, run.child.agent_id,
                        "fork duplicated child"
                    );
                } else if envelope.kind == FrameKind::AgentBootstrap
                    && envelope.stream == forked.instance_stream
                {
                    break envelope.parse_payload::<AgentBootstrapPayload>().unwrap();
                }
            };
            assert_completed_native_projection_replay(
                &replay,
                &run.tool_call_id,
                &run.child.agent_id,
                &forked.agent_id,
                "native fork replay",
            );
            let response = expect_assistant_turn_after_user_echo(
                &mut run.fixture.client,
                &forked.instance_stream,
                fork_prompt,
            )
            .await;
            assert!(response.final_text.contains("NATIVE_FORK_OK"));
            let mut audit = run.fixture.connect().await;
            let host_bootstrap = loop {
                let envelope =
                    expect_next_unfiltered_event(&mut audit, "native post-fork identity audit")
                        .await;
                if envelope.kind == FrameKind::HostBootstrap {
                    break envelope.parse_payload::<HostBootstrapPayload>().unwrap();
                }
            };
            let native_children: Vec<_> = host_bootstrap
                .agents
                .iter()
                .filter(|agent| agent.origin == AgentOrigin::BackendNative)
                .collect();
            assert_eq!(
                native_children.len(),
                1,
                "fork duplicated/leaked native child"
            );
            assert_eq!(native_children[0].agent_id, run.child.agent_id);
            assert_eq!(
                native_children[0].parent_agent_id.as_ref(),
                Some(&run.parent.agent_id)
            );
        }
        _ => unreachable!("not a native projection certification case"),
    }
}

async fn assert_background_completion_lifecycle(
    backend_kind: BackendKind,
    require_agent_initiated_turn: bool,
) {
    const COMPLETED: &str = "BACKGROUND_COMPLETED_637";
    const LAUNCHED: &str = "BACKGROUND_LAUNCHED_637";
    const RESUMED: &str = "BACKGROUND_RESUMED_637";
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let workspace_roots = fixture.workspace_roots();
    let completion_instruction = if require_agent_initiated_turn {
        format!(
            " When completion later wakes you in an agent-initiated turn, reply exactly {RESUMED}."
        )
    } else {
        String::new()
    };
    let prompt = match backend_kind {
        BackendKind::Claude => format!(
            "Use Bash exactly once with run_in_background=true to run `sleep 15; printf {COMPLETED}`. Do not call TaskOutput, TaskStop, or another tool. After Bash reports Running, end the initial foreground turn by replying exactly {LAUNCHED}; do not wait for the result.{completion_instruction}"
        ),
        BackendKind::Codex => format!(
            "Use command execution exactly once to run exactly `sleep 15; printf {COMPLETED}`, setting yield_time_ms to 1000 so it returns while still running. Do not add `&`, call write_stdin, wait, poll, or use another tool. After it reports Running, end the initial foreground turn by replying exactly {LAUNCHED}; do not wait for the result.{completion_instruction}"
        ),
        BackendKind::Hermes => format!(
            "Use terminal exactly once with background=true and notify_on_complete=true to run `sleep 15; printf {COMPLETED}`. Do not call the process tool, wait, poll, or use another tool. After it reports Running, end the initial foreground turn by replying exactly {LAUNCHED}; do not wait for the result.{completion_instruction}"
        ),
        _ => format!(
            "Start exactly one background command `sleep 15; printf {COMPLETED}`. Do not wait, poll, stop it, or use another tool. After it reports Running, end the initial foreground turn by replying exactly {LAUNCHED}; do not wait for the result.{completion_instruction}"
        ),
    };
    let stream = spawn_agent_via_protocol_with_options(
        &mut fixture.client,
        workspace_roots,
        backend_kind,
        "background-completion-lifecycle",
        &prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;

    let mut command_tool_call_id: Option<String> = None;
    let mut background_tool_call_id = None;
    let mut initial_turn_count = 0usize;
    let mut saw_launched = false;
    let mut saw_initial_idle = false;
    let mut completion_count = 0usize;
    let mut saw_resumed_typing = false;
    let mut resumed_turn_count = 0usize;
    let mut saw_resumed_result = false;
    let mut trace = Vec::new();
    tokio::time::timeout(Duration::from_secs(240), async {
        loop {
            let envelope = expect_next_event(
                &mut fixture.client,
                "generic background completion lifecycle",
            )
            .await;
            if envelope.kind == FrameKind::AgentError && envelope.stream == stream {
                let error: protocol::AgentErrorPayload = envelope
                    .parse_payload()
                    .expect("parse background completion AgentError");
                panic!("{backend_kind:?} background completion failed: {}", error.message);
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            let event: ChatEvent = envelope
                .parse_payload()
                .expect("parse background completion ChatEvent");
            trace.push(event.clone());
            match event {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{backend_kind:?} background completion failed: {content}"),
                ChatEvent::ToolRequest(ToolRequest {
                    tool_call_id,
                    tool_type: ToolRequestType::RunCommand { command, .. },
                    ..
                }) => {
                    assert!(
                        command.contains(COMPLETED),
                        "{backend_kind:?} ran the wrong background command: {command:?}"
                    );
                    assert!(
                        command_tool_call_id.replace(tool_call_id).is_none(),
                        "{backend_kind:?} issued more than one command request"
                    );
                }
                ChatEvent::ToolRequest(request) => panic!(
                    "{backend_kind:?} background lifecycle issued an unexpected tool request: {request:?}"
                ),
                ChatEvent::StreamEnd(end) => {
                    if completion_count == 0 && end.message.content.contains(LAUNCHED) {
                        initial_turn_count += 1;
                        assert_eq!(initial_turn_count, 1, "duplicate initial launch turn");
                        saw_launched = true;
                    } else if completion_count == 1 && end.message.content.contains(RESUMED) {
                        resumed_turn_count += 1;
                        assert_eq!(resumed_turn_count, 1, "duplicate resumed turn");
                        saw_resumed_result = true;
                    }
                }
                ChatEvent::ToolProgress(progress) => {
                    let Some(_task) = background_task_progress(&progress.update) else {
                        continue;
                    };
                    assert_eq!(
                        command_tool_call_id.as_deref(),
                        Some(progress.tool_call_id.as_str()),
                        "{backend_kind:?} background lifecycle was not correlated to its command request"
                    );
                    assert_eq!(
                        progress.execution_mode,
                        protocol::ToolExecutionMode::Background
                    );
                    assert_eq!(
                        completion_count, 0,
                        "{backend_kind:?} emitted progress after completion"
                    );
                    assert!(
                        background_tool_call_id
                            .as_ref()
                            .is_none_or(|known| known == &progress.tool_call_id),
                        "{backend_kind:?} changed background tool identity"
                    );
                    background_tool_call_id = Some(progress.tool_call_id);
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if background_tool_call_id.as_deref()
                        == Some(completion.tool_call_id.as_str()) =>
                {
                    assert!(
                        saw_initial_idle,
                        "{backend_kind:?} completed background work before initial idle"
                    );
                    assert!(completion.success(), "background command failed: {completion:?}");
                    let ToolExecutionResult::RunCommand {
                        exit_code, stdout, ..
                    } = &completion.tool_result()
                    else {
                        panic!("background command returned a non-command result: {completion:?}")
                    };
                    assert_eq!(*exit_code, 0);
                    assert!(
                        stdout.contains(COMPLETED),
                        "background result omitted {COMPLETED}: {stdout:?}"
                    );
                    completion_count += 1;
                    assert_eq!(completion_count, 1, "background tool completed more than once");
                }
                ChatEvent::ToolExecutionCompleted(completion) => panic!(
                    "{backend_kind:?} background lifecycle completed an unrequested tool: {completion:?}"
                ),
                ChatEvent::TypingStatusChanged(false)
                    if background_tool_call_id.is_some() && completion_count == 0 =>
                {
                    assert!(
                        saw_launched && initial_turn_count == 1,
                        "{backend_kind:?} became idle without one completed launch turn"
                    );
                    saw_initial_idle = true;
                }
                ChatEvent::TypingStatusChanged(true) if completion_count == 1 => {
                    saw_resumed_typing = true;
                }
                ChatEvent::TypingStatusChanged(false)
                    if require_agent_initiated_turn
                        && saw_resumed_typing
                        && saw_resumed_result
                        && resumed_turn_count == 1
                        && completion_count == 1 =>
                {
                    break;
                }
                _ if !require_agent_initiated_turn
                    && completion_count == 1 =>
                {
                    break;
                }
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "{backend_kind:?} did not satisfy the generic background completion lifecycle; trace:\n{trace:#?}"
        )
    });
    assert!(
        command_tool_call_id.is_some(),
        "{backend_kind:?} did not emit the normalized command request"
    );
    assert!(
        background_tool_call_id.is_some(),
        "{backend_kind:?} did not report background Running"
    );
    assert_eq!(initial_turn_count, 1);
    assert!(saw_launched);
    assert!(saw_initial_idle);
    assert_eq!(completion_count, 1);
    if require_agent_initiated_turn {
        assert!(saw_resumed_typing);
        assert_eq!(resumed_turn_count, 1);
        assert!(saw_resumed_result);
    }
    fixture.client.close_agent(&stream).await.ok();
}

async fn assert_background_completion_retires_tray_entry(backend_kind: BackendKind) {
    const DONE: &str = "BACKGROUND_TRAY_DONE_941";
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let workspace_roots = fixture.workspace_roots();
    let prompt = match backend_kind {
        BackendKind::Claude => {
            "Use the Bash tool exactly once to run `sleep 8; printf BACKGROUND_TRAY_DONE_941` with run_in_background=true. Do not call TaskOutput, TaskStop, or any other tool. After Bash reports that the command is running in the background, end the foreground turn by replying exactly BACKGROUND_TRAY_LAUNCHED; do not wait for its result."
        }
        BackendKind::Codex => {
            "Use command execution exactly once to run `sleep 8; printf BACKGROUND_TRAY_DONE_941`, setting the tool's `yield_time_ms` argument to `1000` so it returns while the process is still running. Do not add `&`, and do not call write_stdin, wait, poll, or any other tool afterward. As soon as the tool reports a running session, end the foreground turn by replying exactly BACKGROUND_TRAY_LAUNCHED; do not wait for its result."
        }
        BackendKind::Hermes => {
            "Use terminal exactly once with background=true and notify_on_complete=true to run `sleep 8; printf BACKGROUND_TRAY_DONE_941`. Do not call the process tool, wait, poll, stop it, or use another tool. After it reports Running, end the foreground turn by replying exactly BACKGROUND_TRAY_LAUNCHED; do not wait for its result."
        }
        BackendKind::Acp => {
            "Run `sleep 8; printf BACKGROUND_TRAY_DONE_941` exactly once as background work. Do not wait, poll, stop it, or use another tool. After it reports Running, end the foreground turn by replying exactly BACKGROUND_TRAY_LAUNCHED; do not wait for its result."
        }
        BackendKind::Tycode => {
            "Run `sleep 8; printf BACKGROUND_TRAY_DONE_941` exactly once as background work. Do not wait, poll, stop it, or use another tool. After it reports Running, end the foreground turn by replying exactly BACKGROUND_TRAY_LAUNCHED; do not wait for its result."
        }
        BackendKind::Antigravity => {
            "Run `sleep 8; printf BACKGROUND_TRAY_DONE_941` exactly once as background work. Do not wait, poll, stop it, or use another tool. After it reports Running, end the foreground turn by replying exactly BACKGROUND_TRAY_LAUNCHED; do not wait for its result."
        }
    };
    let stream = spawn_agent_via_protocol_with_options(
        &mut fixture.client,
        workspace_roots,
        backend_kind,
        "background-completion-retires-tray-entry",
        prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;

    let mut command_tool_call_id = None;
    let mut background_tool_call_id = None;
    let mut completions = HashMap::<String, (usize, bool)>::new();
    tokio::time::timeout(Duration::from_secs(120), async {
        loop {
            let envelope = fixture
                .client
                .next_event()
                .await
                .expect("read background tray lifecycle")
                .expect("background tray lifecycle stream closed");
            if envelope.kind == FrameKind::AgentError && envelope.stream == stream {
                let error: protocol::AgentErrorPayload = envelope
                    .parse_payload()
                    .expect("parse background tray AgentError");
                panic!("{backend_kind:?} background tray case failed: {}", error.message);
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            let event: ChatEvent = envelope
                .parse_payload()
                .expect("parse background tray lifecycle event");
            match event {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{backend_kind:?} background tray case failed: {content}"),
                ChatEvent::ToolRequest(request) => match request.tool_type {
                    ToolRequestType::RunCommand { command, .. } if command.contains(DONE) => {
                        assert!(
                            command_tool_call_id
                                .replace(request.tool_call_id)
                                .is_none(),
                            "{backend_kind:?} issued more than one background tray command"
                        );
                    }
                    other => panic!(
                        "{backend_kind:?} background tray case issued an unexpected tool request: {other:?}"
                    ),
                },
                ChatEvent::ToolProgress(progress) => {
                    let Some(task) = background_task_progress(&progress.update) else {
                        continue;
                    };
                    assert_eq!(
                        command_tool_call_id.as_deref(),
                        Some(progress.tool_call_id.as_str()),
                        "{backend_kind:?} background tray progress was not correlated to its command"
                    );
                    assert_eq!(
                        progress.execution_mode,
                        protocol::ToolExecutionMode::Background
                    );
                    assert!(
                        task.description
                            .as_deref()
                            .is_some_and(|description| description.contains(DONE)),
                        "{backend_kind:?} reported unrelated background work: {task:?}"
                    );
                    assert!(
                        background_tool_call_id
                            .as_ref()
                            .is_none_or(|known| known == &progress.tool_call_id),
                        "{backend_kind:?} changed background tool identity"
                    );
                    assert!(
                        !completions.contains_key(&progress.tool_call_id),
                        "{backend_kind:?} emitted progress after completion"
                    );
                    background_tool_call_id = Some(progress.tool_call_id);
                }
                ChatEvent::ToolExecutionCompleted(completion) => {
                    assert_eq!(
                        command_tool_call_id.as_deref(),
                        Some(completion.tool_call_id.as_str()),
                        "{backend_kind:?} background tray case completed an unrequested tool"
                    );
                    let (count, success) = completions
                        .entry(completion.tool_call_id.clone())
                        .or_insert((0, completion.success()));
                    *count += 1;
                    *success &= completion.success();
                    assert_eq!(
                        *count, 1,
                        "{backend_kind:?} completed one background command more than once"
                    );
                    if background_tool_call_id.as_deref()
                        == Some(completion.tool_call_id.as_str())
                    {
                        assert!(
                            completion.success(),
                            "{backend_kind:?} reported successful terminal progress but failed its tool: {completion:?}"
                        );
                    }
                }
                _ => {}
            }
            if background_tool_call_id.as_ref().is_some_and(|tool_call_id| {
                        completions.get(tool_call_id).map(|value| value.0) == Some(1)
                })
            {
                break;
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "{backend_kind:?} never completed the running background tray entry: tool_call_id={background_tool_call_id:?}"
        )
    });

    assert!(
        command_tool_call_id.is_some(),
        "{backend_kind:?} never emitted the normalized tray command request"
    );
    assert!(
        background_tool_call_id.is_some(),
        "{backend_kind:?} never reported the command as background work"
    );
    assert_eq!(
        completions
            .get(background_tool_call_id.as_ref().unwrap())
            .copied(),
        Some((1, true))
    );

    let duplicate = tokio::time::timeout(Duration::from_secs(2), async {
        loop {
            let envelope =
                expect_next_event(&mut fixture.client, "post-terminal background quiet window")
                    .await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .expect("parse post-terminal background event")
            {
                ChatEvent::ToolProgress(progress)
                    if background_tool_call_id.as_deref()
                        == Some(progress.tool_call_id.as_str()) =>
                {
                    return format!("progress {progress:?}");
                }
                ChatEvent::ToolExecutionCompleted(completion)
                    if background_tool_call_id.as_deref()
                        == Some(completion.tool_call_id.as_str()) =>
                {
                    return format!("completion {completion:?}");
                }
                _ => {}
            }
        }
    })
    .await;
    assert!(
        duplicate.is_err(),
        "{backend_kind:?} emitted an event after the command terminal: {duplicate:?}"
    );
    fixture
        .client
        .close_agent(&stream)
        .await
        .expect("close completed background tray case");
}

async fn assert_background_work_is_not_supervisor_stalled(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let prompt = match backend_kind {
        BackendKind::Claude => {
            "Use Bash exactly twice with run_in_background=true to start `sleep 300` and `sleep 301` as separate background commands. Do not poll or stop them. After both Bash calls report Running, end the foreground turn by replying exactly BACKGROUND_SUPERVISOR_READY."
        }
        BackendKind::Codex => {
            "Make exactly two distinct command-execution tool calls, never one combined call. In call 1 start only `sleep 300`; after it reports a running session, in call 2 start only `sleep 301`. Set `yield_time_ms` to `1000` on both calls. Do not poll or stop either session. After both report Running, end the foreground turn by replying exactly BACKGROUND_SUPERVISOR_READY."
        }
        BackendKind::Hermes => {
            "Use terminal exactly twice with background=true to start `sleep 300` and `sleep 301` as separate background commands. Do not poll or stop them. After both report Running, end the foreground turn by replying exactly BACKGROUND_SUPERVISOR_READY."
        }
        BackendKind::Acp | BackendKind::Tycode | BackendKind::Antigravity => {
            "Start `sleep 300` and `sleep 301` as exactly two separate background commands. Do not poll or stop them. After both report Running, end the foreground turn by replying exactly BACKGROUND_SUPERVISOR_READY."
        }
    };
    let roots = fixture.workspace_roots();
    let stream = spawn_agent_via_protocol_with_options(
        &mut fixture.client,
        roots,
        backend_kind,
        "background-work-not-supervisor-stalled",
        prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let mut running_tools = HashSet::new();
    let mut foreground_ended = false;
    let mut foreground_idle = false;
    let mut settings_armed = false;
    tokio::time::timeout(Duration::from_secs(120), async {
        while running_tools.len() < 2 || !foreground_ended || !foreground_idle {
            let envelope =
                expect_next_event(&mut fixture.client, "background supervisor setup").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .expect("parse background supervisor event")
            {
                ChatEvent::ToolProgress(progress) => {
                    if background_task_progress(&progress.update).is_some() {
                        running_tools.insert(progress.tool_call_id);
                    }
                }
                ChatEvent::StreamEnd(end) => {
                    foreground_ended |= end.message.content.contains("BACKGROUND_SUPERVISOR_READY");
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Assistant { .. },
                    content,
                    tool_calls,
                    ..
                }) if tool_calls.is_empty() && content.contains("BACKGROUND_SUPERVISOR_READY") => {
                    foreground_ended = true;
                }
                ChatEvent::TypingStatusChanged(false) => foreground_idle = true,
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => {
                    panic!("{backend_kind:?} background supervisor setup failed: {content}")
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Warning,
                    content,
                    ..
                }) if content.starts_with(protocol::SUPERVISOR_STALL_INTERRUPT_NOTICE_PREFIX) => {
                    panic!("{backend_kind:?} supervisor interrupted foreground work while detached background tasks were running: {content}")
                }
                ChatEvent::OperationCancelled(cancelled) => {
                    panic!("{backend_kind:?} foreground work was cancelled while detached background tasks were running: {}", cancelled.message)
                }
                _ => {}
            }
            if foreground_ended && !settings_armed {
                for (path, value, expected) in [
                    ("/supervisor/stall_timeout_seconds", serde_json::json!(1), serde_json::json!(1_800)),
                    ("/supervisor/stall_timeout_enabled", serde_json::json!(true), serde_json::json!(false)),
                    ("/supervisor/enabled", serde_json::json!(true), serde_json::json!(false)),
                ] {
                    fixture
                        .client
                        .inner
                        .replace_setting(path, value, expected)
                        .await
                        .expect("enable supervisor stall timeout");
                }
                settings_armed = true;
            }
        }
    })
    .await
    .expect("backend did not leave detached background work running");

    assert_eq!(running_tools.len(), 2, "expected two background tools");
    assert!(settings_armed, "supervisor settings were not armed");
    assert!(foreground_idle, "foreground never became idle");
    let interrupted = tokio::time::timeout(Duration::from_secs(3), async {
        loop {
            let envelope = expect_next_event(&mut fixture.client, "supervisor quiet window").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .expect("parse supervisor quiet event")
            {
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Warning,
                    content,
                    ..
                }) if content.starts_with(protocol::SUPERVISOR_STALL_INTERRUPT_NOTICE_PREFIX) => {
                    return Some(content);
                }
                ChatEvent::OperationCancelled(cancelled) => return Some(cancelled.message),
                ChatEvent::ToolProgress(progress)
                    if running_tools.contains(&progress.tool_call_id) =>
                {
                    assert!(background_task_progress(&progress.update).is_some());
                }
                _ => {}
            }
        }
    })
    .await;
    assert!(
        interrupted.is_err(),
        "supervisor treated legitimate detached background work as a stalled foreground turn: {interrupted:?}"
    );
    fixture
        .client
        .close_agent(&stream)
        .await
        .expect("close background supervisor case");
}

async fn assert_background_work_allows_foreground_idle(backend_kind: BackendKind) {
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let prompt = match backend_kind {
        BackendKind::Claude => {
            "Use Bash exactly once with run_in_background=true to run `sleep 300`. Do not poll or stop it. After Bash reports Running, end the foreground turn by replying exactly BACKGROUND_IDLE_READY."
        }
        BackendKind::Codex => {
            "Use command execution exactly once to run `sleep 300`, setting the tool's `yield_time_ms` argument to `1000` so it remains running. Do not poll or stop it. End the foreground turn by replying exactly BACKGROUND_IDLE_READY."
        }
        BackendKind::Hermes => {
            "Use terminal exactly once with background=true to run `sleep 300`. Do not poll or stop it. End the foreground turn by replying exactly BACKGROUND_IDLE_READY."
        }
        BackendKind::Acp | BackendKind::Tycode | BackendKind::Antigravity => {
            "Start `sleep 300` as background command work exactly once. Do not poll or stop it. End the foreground turn by replying exactly BACKGROUND_IDLE_READY."
        }
    };
    let roots = fixture.workspace_roots();
    let stream = spawn_agent_via_protocol_with_options(
        &mut fixture.client,
        roots,
        backend_kind,
        "background-work-allows-foreground-idle",
        prompt,
        None,
        None,
    )
    .await;
    let mut running_tool = None;
    let mut foreground_ended = false;
    let mut foreground_idle = false;
    tokio::time::timeout(Duration::from_secs(120), async {
        while running_tool.is_none() || !foreground_ended || !foreground_idle {
            let envelope = expect_next_event(&mut fixture.client, "background idle contract").await;
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != stream {
                continue;
            }
            match envelope
                .parse_payload::<ChatEvent>()
                .expect("parse background idle event")
            {
                ChatEvent::ToolProgress(progress) => {
                    let Some(_task) = background_task_progress(&progress.update) else {
                        continue;
                    };
                    running_tool = Some(progress.tool_call_id);
                }
                ChatEvent::StreamEnd(end)
                    if end.message.content.contains("BACKGROUND_IDLE_READY") =>
                {
                    foreground_ended = true;
                }
                ChatEvent::TypingStatusChanged(false) if foreground_ended => {
                    foreground_idle = true;
                }
                ChatEvent::OperationCancelled(cancelled) => {
                    panic!("{backend_kind:?} required an interrupt to finish foreground activity: {}", cancelled.message)
                }
                ChatEvent::MessageAdded(ChatMessage {
                    sender: MessageSender::Error,
                    content,
                    ..
                }) => panic!("{backend_kind:?} background idle setup failed: {content}"),
                _ => {}
            }
        }
    })
    .await
    .unwrap_or_else(|_| {
        panic!(
            "{backend_kind:?} kept foreground activity running after its response ended while detached background work remained: running_tool={running_tool:?} foreground_ended={foreground_ended} foreground_idle={foreground_idle}"
        )
    });

    let follow_up = "Reply exactly BACKGROUND_IDLE_FOLLOW_UP.";
    fixture
        .client
        .send_message(&stream, follow_up.to_owned())
        .await
        .expect("send follow-up over detached background work");
    let response =
        expect_assistant_turn_after_user_echo(&mut fixture.client, &stream, follow_up).await;
    assert!(
        response.final_text.contains("BACKGROUND_IDLE_FOLLOW_UP"),
        "{backend_kind:?} did not accept a follow-up while detached background work remained: {:?}",
        response.final_text
    );
    fixture
        .client
        .close_agent(&stream)
        .await
        .expect("close background idle case");
}

fn run_paid_backend_test_on_large_stack<F, Fut>(test: F)
where
    F: FnOnce() -> Fut + Send + 'static,
    Fut: std::future::Future<Output = ()> + 'static,
{
    let result = std::thread::Builder::new()
        .name("real-backend-conformance".to_owned())
        .stack_size(32 * 1024 * 1024)
        .spawn(move || {
            tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .expect("build real-backend conformance runtime")
                .block_on(test());
        })
        .expect("spawn real-backend conformance thread")
        .join();
    if let Err(panic) = result {
        std::panic::resume_unwind(panic);
    }
}

#[test]
#[ignore = "heavy paid backend qualification; use --ignored and TYDE_RUN_REAL_AI_TESTS=1"]
fn real_universal_backend_qualification_suite() {
    run_paid_backend_test_on_large_stack(real_universal_backend_qualification_suite_async);
}

async fn real_universal_backend_qualification_suite_async() {
    assert!(
        real_ai_tests_enabled(),
        "set {RUN_REAL_AI_TESTS_ENV}=1 to authorize paid backend qualification"
    );
    let _conformance_environment = REAL_CONFORMANCE_ENV_MUTEX.lock().await;
    let _targeted_filter_guards = remove_targeted_conformance_filters();
    let backends = ALL_SUPPORTED_REAL_BACKENDS.to_vec();
    let _claude_subagent_model_guard = EnvVarGuard::set(
        "CLAUDE_CODE_SUBAGENT_MODEL",
        UNIVERSAL_CLAUDE_MODEL.to_owned(),
    );
    let _hermes_python_guard = backends
        .contains(&BackendKind::Hermes)
        .then(|| {
            std::env::var("HERMES_PYTHON")
                .ok()
                .filter(|value| !value.trim().is_empty())
                .or_else(|| {
                    Path::new(DEFAULT_HERMES_TEST_PYTHON)
                        .exists()
                        .then(|| DEFAULT_HERMES_TEST_PYTHON.to_owned())
                })
        })
        .flatten()
        .map(|python| EnvVarGuard::set("HERMES_PYTHON", python));
    let mut failures = Vec::new();
    let mut case_executions = CertificationCase::ALL
        .into_iter()
        .map(|case| (case, 0usize))
        .collect::<HashMap<_, _>>();
    let mut case_exemptions = CertificationCase::ALL
        .into_iter()
        .map(|case| (case, Vec::<String>::new()))
        .collect::<HashMap<_, _>>();
    let mut case_blockers = CertificationCase::ALL
        .into_iter()
        .map(|case| (case, Vec::<String>::new()))
        .collect::<HashMap<_, _>>();

    for backend_kind in backends {
        if !backend_binary_available(backend_kind) {
            let reason = format!("{} binary is not installed", backend_label(backend_kind));
            failures.push(reason.clone());
            for case in CertificationCase::ALL {
                case_blockers.get_mut(&case).unwrap().push(reason.clone());
            }
            continue;
        }
        if !backend_runtime_available(backend_kind) {
            let reason = format!(
                "{} runtime prerequisites are unavailable",
                backend_label(backend_kind)
            );
            failures.push(reason.clone());
            for case in CertificationCase::ALL {
                case_blockers.get_mut(&case).unwrap().push(reason.clone());
            }
            continue;
        }

        let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
        let mut coverage = ConformanceCoverageLedger::for_capabilities(&capabilities);
        let mut successful_cases = HashSet::new();
        for case in CertificationCase::ALL {
            if !backend_supports_certification_case(backend_kind, &capabilities, case) {
                let reason = certification_case_exemption_reason(backend_kind, &capabilities, case);
                eprintln!(
                    "EXEMPT {} {}: {reason}",
                    backend_label(backend_kind),
                    case.id()
                );
                case_exemptions.get_mut(&case).unwrap().push(reason);
                continue;
            }
            *case_executions.get_mut(&case).unwrap() += 1;
            eprintln!("RUNNING {} {}", backend_label(backend_kind), case.id());
            let handle = tokio::spawn(run_certification_case_for_backend(backend_kind, case));
            let result = handle.await;
            await_real_backend_cleanup().await;
            match result {
                Ok(witnessed_coverage) => {
                    if certification_case_requires_witnesses(case) && witnessed_coverage.is_empty()
                    {
                        failures.push(format!(
                            "{} {}: executed no conformance matrix cells",
                            backend_label(backend_kind),
                            case.id()
                        ));
                    }
                    for cell in witnessed_coverage {
                        if let Err(error) = coverage.record(cell) {
                            failures.push(format!(
                                "{} {} coverage: {error}",
                                backend_label(backend_kind),
                                case.id()
                            ));
                        }
                    }
                    successful_cases.insert(case);
                }
                Err(error) => failures.push(format!(
                    "{} {}: {error}",
                    backend_label(backend_kind),
                    case.id()
                )),
            }
        }
        if let Err(error) = coverage.finish() {
            failures.push(format!(
                "{} exhaustive special-tool coverage: {error}",
                backend_label(backend_kind)
            ));
        }
        if let Err(error) = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            assert_declared_capabilities_have_live_witnesses(backend_kind, &successful_cases)
        })) {
            failures.push(format!(
                "{} declared capability witnesses: {}",
                backend_label(backend_kind),
                panic_payload_message(error)
            ));
        }
    }

    for case in CertificationCase::ALL {
        if case_executions[&case] > 0 {
            continue;
        }
        let exemptions = &case_exemptions[&case];
        let blockers = &case_blockers[&case];
        if !blockers.is_empty() {
            eprintln!(
                "BLOCKED {}: zero executions; {}",
                case.id(),
                blockers.join("; ")
            );
        } else if let Some(reason) = intentional_registry_only_certification_case(case) {
            eprintln!(
                "INTENTIONAL REGISTRY-ONLY N/A {}: {reason}; {}",
                case.id(),
                exemptions.join("; ")
            );
        } else {
            failures.push(format!(
                "{}: zero executions without an explicit intentional registry-only N/A; capability exemptions: {}",
                case.id(),
                exemptions.join("; ")
            ));
        }
    }

    assert!(
        failures.is_empty(),
        "universal paid backend qualification failures:\n{}",
        failures.join("\n")
    );
}

macro_rules! live_certification_tests {
    ($($name:ident => $case:ident),+ $(,)?) => {
        $(
            #[test]
            #[ignore = "paid backend certification; use --ignored and TYDE_RUN_REAL_AI_TESTS=1"]
            fn $name() {
                run_paid_backend_test_on_large_stack(|| async {
                    run_selected_certification_case(CertificationCase::$case).await;
                });
            }
        )+
    };
}

