#[derive(Debug, Clone, PartialEq)]
struct NormalizedToolMetadata {
    request: Value,
    completion: Value,
}

fn read_tool_prompt(backend_kind: BackendKind, path: &str, sentinel: &str) -> String {
    match backend_kind {
        BackendKind::Claude => format!(
            "Use the Read tool exactly once to read {path}. Do not use Bash or any other tool. Then reply exactly {sentinel}."
        ),
        BackendKind::Codex => format!(
            "Use run_command exactly once to run `cat -- '{path}'`. Do not use any other tool. Then reply exactly {sentinel}."
        ),
        BackendKind::Acp => format!(
            "Use the native file read tool exactly once to read {path}. Do not use a shell command or any other tool. Then reply exactly {sentinel}."
        ),
        BackendKind::Hermes => format!(
            "Use read_file exactly once to read {path}. Do not use the terminal or any other tool. Then reply exactly {sentinel}."
        ),
        BackendKind::Tycode => format!(
            "Use the bash tool exactly once to run `cat -- '{path}'`. Do not use any other tool. Then reply exactly {sentinel}."
        ),
        BackendKind::Antigravity => format!(
            "Use the native file-reading tool exactly once to read {path}. Do not use a terminal command or any other tool. Then reply exactly {sentinel}."
        ),
    }
}

async fn collect_tool_metadata_turn(
    client: &mut ValidatedConnection,
    stream: &StreamPath,
    expected_user: Option<&str>,
    context: &str,
) -> Vec<ChatEvent> {
    let mut events = Vec::new();
    let mut saw_expected_user = expected_user.is_none();
    let mut saw_completion = false;
    tokio::time::timeout(Duration::from_secs(180), async {
        loop {
            let envelope = expect_next_event(client, context).await;
            if envelope.kind == FrameKind::AgentError && envelope.stream == *stream {
                let error: protocol::AgentErrorPayload = envelope
                    .parse_payload()
                    .expect("parse tool-metadata AgentError");
                panic!("{context} failed: {}", error.message);
            }
            if envelope.kind != FrameKind::ChatEvent || envelope.stream != *stream {
                continue;
            }
            let event: ChatEvent = envelope
                .parse_payload()
                .expect("parse tool-metadata ChatEvent");
            if let ChatEvent::MessageAdded(message) = &event {
                if matches!(message.sender, MessageSender::User)
                    && expected_user.is_some_and(|expected| message.content == expected)
                {
                    saw_expected_user = true;
                }
                if matches!(message.sender, MessageSender::Error) {
                    panic!("{context} returned an error: {}", message.content);
                }
            }
            saw_completion |= matches!(event, ChatEvent::ToolExecutionCompleted(_));
            let terminal = matches!(event, ChatEvent::TypingStatusChanged(false))
                && saw_expected_user
                && saw_completion;
            events.push(event);
            if terminal {
                break;
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("timed out waiting for {context}: {events:?}"));
    events
}

fn normalized_tool_metadata_for_path(
    events: &[ChatEvent],
    path: &str,
    context: &str,
) -> NormalizedToolMetadata {
    let requests = events
        .iter()
        .filter_map(|event| match event {
            ChatEvent::ToolRequest(request) => {
                let value =
                    serde_json::to_value(request).expect("serialize normalized tool request");
                serde_json::to_string(&value)
                    .expect("render normalized tool request")
                    .contains(path)
                    .then_some((request, value))
            }
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(
        requests.len(),
        1,
        "{context} must expose the normalized request for {path} exactly once: {events:?}"
    );
    let (request, request_value) = &requests[0];
    let completions = events
        .iter()
        .filter_map(|event| match event {
            ChatEvent::ToolExecutionCompleted(completion)
                if completion.tool_call_id == request.tool_call_id =>
            {
                Some(completion)
            }
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(
        completions.len(),
        1,
        "{context} must expose exactly one correlated completion: {events:?}"
    );
    let completion = completions[0];
    assert!(
        completion.success(),
        "{context} read tool failed: {completion:?}"
    );
    assert_eq!(
        completion.normalization_failure(),
        None,
        "{context} did not produce fully normalized tool metadata"
    );
    NormalizedToolMetadata {
        request: request_value.clone(),
        completion: serde_json::to_value(completion).expect("serialize normalized tool completion"),
    }
}

fn assert_tool_path_absent(events: &[ChatEvent], path: &str, context: &str) {
    let encoded = serde_json::to_string(events).expect("serialize tool replay for isolation");
    assert!(
        !encoded.contains(path),
        "{context} leaked isolated tool metadata for {path}: {events:?}"
    );
}

async fn replayed_agent_events_by_id(
    client: &mut ValidatedConnection,
    agent_id: &protocol::AgentId,
    context: &str,
) -> (StreamPath, Vec<ChatEvent>) {
    while !client.bootstrap_agent_streams.contains_key(agent_id) {
        expect_next_event(client, context).await;
    }
    let agent_stream = client
        .bootstrap_agent_streams
        .get(agent_id)
        .expect("bootstrap stream was observed")
        .clone();
    while !client.replayed_agent_events.contains_key(&agent_stream) {
        expect_next_event(client, context).await;
    }
    client.pending_bootstrap_events.clear();
    let events = client
        .replayed_agent_events
        .remove(&agent_stream)
        .expect("bootstrap events were observed");
    (agent_stream, events)
}

async fn assert_tool_metadata_survives_reconnect_resume(backend_kind: BackendKind) {
    const CONTENT: &str = "TOOL_METADATA_SENTINEL_20260813\nline-two-pi";
    let capabilities = server::backend::capabilities_for_backend_kind(backend_kind);
    let mut fixture = RealBackendFixture::new(backend_kind).await;
    let roots = fixture.workspace_roots();

    let first_path = fixture
        .workspace_dir
        .path()
        .join(format!("metadata-first-{}.txt", Uuid::new_v4()))
        .to_string_lossy()
        .to_string();
    std::fs::write(&first_path, CONTENT).expect("write first tool-metadata file");
    let first_prompt = read_tool_prompt(backend_kind, &first_path, "FIRST_READ_DONE");
    let (source_stream, source_start) = spawn_agent_via_protocol_with_start(
        &mut fixture.client,
        roots,
        backend_kind,
        "tool-metadata-resume-source",
        &first_prompt,
        None,
        cost_hint_for(backend_kind),
    )
    .await;
    let source_session = source_start
        .session_id
        .clone()
        .expect("tool-metadata source AgentStart needs session id");
    let first_live_events = collect_tool_metadata_turn(
        &mut fixture.client,
        &source_stream,
        Some(&first_prompt),
        "first live tool turn",
    )
    .await;
    let first_metadata =
        normalized_tool_metadata_for_path(&first_live_events, &first_path, "first live tool turn");

    fixture = fixture.reconnect_after_zero_clients().await;
    let (_reconnected_source_stream, reconnected_events) = replayed_agent_events_by_id(
        &mut fixture.client,
        &source_start.agent_id,
        "zero-client source reconnect",
    )
    .await;
    assert_eq!(
        normalized_tool_metadata_for_path(
            &reconnected_events,
            &first_path,
            "zero-client source reconnect",
        ),
        first_metadata,
        "zero-client reconnect changed normalized tool metadata"
    );
    let (resumed_stream, resumed_start) = resume_agent_without_prompt_via_protocol_with_start(
        &mut fixture.client,
        "tool-metadata-native-resume",
        source_session,
    )
    .await;
    let native_replay_events = collect_tool_metadata_turn(
        &mut fixture.client,
        &resumed_stream,
        None,
        "native resume replay",
    )
    .await;
    assert_eq!(
        normalized_tool_metadata_for_path(
            &native_replay_events,
            &first_path,
            "native resume replay",
        ),
        first_metadata,
        "native resume changed normalized tool metadata"
    );

    let second_path = fixture
        .workspace_dir
        .path()
        .join(format!("metadata-second-{}.txt", Uuid::new_v4()))
        .to_string_lossy()
        .to_string();
    std::fs::write(&second_path, CONTENT).expect("write second tool-metadata file");
    let second_prompt = read_tool_prompt(backend_kind, &second_path, "SECOND_READ_DONE");
    fixture
        .client
        .send_message(&resumed_stream, second_prompt.clone())
        .await
        .expect("send post-resume tool turn");
    let second_live_events = collect_tool_metadata_turn(
        &mut fixture.client,
        &resumed_stream,
        Some(&second_prompt),
        "post-resume second tool turn",
    )
    .await;
    let second_metadata = normalized_tool_metadata_for_path(
        &second_live_events,
        &second_path,
        "post-resume second tool turn",
    );

    let mut fork_state = None;
    if capabilities.contains(tyde_agent_adapter::BackendCapability::ForkSession) {
        let fork_path = fixture
            .workspace_dir
            .path()
            .join(format!("metadata-fork-{}.txt", Uuid::new_v4()))
            .to_string_lossy()
            .to_string();
        std::fs::write(&fork_path, CONTENT).expect("write fork tool-metadata file");
        let fork_prompt = read_tool_prompt(backend_kind, &fork_path, "FORK_READ_DONE");
        let (fork_stream, fork_start) = fork_agent_via_protocol_with_start(
            &mut fixture.client,
            "tool-metadata-fork",
            resumed_start.agent_id.clone(),
            resumed_start
                .session_id
                .clone()
                .expect("resumed AgentStart needs session id"),
            &fork_prompt,
        )
        .await;
        let fork_live_events = collect_tool_metadata_turn(
            &mut fixture.client,
            &fork_stream,
            Some(&fork_prompt),
            "fork tool turn",
        )
        .await;
        let fork_metadata =
            normalized_tool_metadata_for_path(&fork_live_events, &fork_path, "fork tool turn");

        let source_after_fork_path = fixture
            .workspace_dir
            .path()
            .join(format!("metadata-source-after-fork-{}.txt", Uuid::new_v4()))
            .to_string_lossy()
            .to_string();
        std::fs::write(&source_after_fork_path, CONTENT)
            .expect("write source-after-fork tool-metadata file");
        let source_after_fork_prompt = read_tool_prompt(
            backend_kind,
            &source_after_fork_path,
            "SOURCE_AFTER_FORK_READ_DONE",
        );
        fixture
            .client
            .send_message(&resumed_stream, source_after_fork_prompt.clone())
            .await
            .expect("send source-after-fork tool turn");
        let source_after_fork_events = collect_tool_metadata_turn(
            &mut fixture.client,
            &resumed_stream,
            Some(&source_after_fork_prompt),
            "source-after-fork tool turn",
        )
        .await;
        let source_after_fork_metadata = normalized_tool_metadata_for_path(
            &source_after_fork_events,
            &source_after_fork_path,
            "source-after-fork tool turn",
        );
        fork_state = Some((
            fork_stream,
            fork_start,
            fork_path,
            fork_metadata,
            source_after_fork_path,
            source_after_fork_metadata,
        ));
    }

    fixture = fixture.reconnect_after_zero_clients().await;
    let (replayed_source_stream, replayed_source_events) = replayed_agent_events_by_id(
        &mut fixture.client,
        &resumed_start.agent_id,
        "final source reconnect",
    )
    .await;
    assert_eq!(
        normalized_tool_metadata_for_path(
            &replayed_source_events,
            &first_path,
            "final source first replay",
        ),
        first_metadata,
    );
    assert_eq!(
        normalized_tool_metadata_for_path(
            &replayed_source_events,
            &second_path,
            "final source second replay",
        ),
        second_metadata,
    );

    if let Some((
        _fork_stream,
        fork_start,
        fork_path,
        fork_metadata,
        source_after_fork_path,
        source_after_fork_metadata,
    )) = fork_state
    {
        assert_eq!(
            normalized_tool_metadata_for_path(
                &replayed_source_events,
                &source_after_fork_path,
                "final source post-fork replay",
            ),
            source_after_fork_metadata,
        );
        assert_tool_path_absent(
            &replayed_source_events,
            &fork_path,
            "source replay after fork",
        );
        let (replayed_fork_stream, replayed_fork_events) = replayed_agent_events_by_id(
            &mut fixture.client,
            &fork_start.agent_id,
            "final fork reconnect",
        )
        .await;
        assert_eq!(
            normalized_tool_metadata_for_path(
                &replayed_fork_events,
                &fork_path,
                "final fork replay",
            ),
            fork_metadata,
        );
        assert_tool_path_absent(
            &replayed_fork_events,
            &source_after_fork_path,
            "fork replay after source continued",
        );
        fixture
            .client
            .close_agent(&replayed_fork_stream)
            .await
            .expect("close replayed fork agent");
    }
    fixture
        .client
        .close_agent(&replayed_source_stream)
        .await
        .expect("close replayed source agent");
}
